Object.assign(window.OTPU_CODE,{"tools/offload/sessions/emdef2.sh": "#!/bin/bash\n# Session emdef2 (docs/offload.md 13.16): expert-major from EM_ROWS new rows a call (Qwen3.5 48, Gemma 4 24), before\n# its host swap, and the crossover it rests on. emdef (13.15) ran expert-major on every call and the 35B's short turns\n# lost (24 / 31 tokens +0.50 / +0.39 s TTFT, each with the 4-row call after its snapshot). Trees: the candidate\n# deploy's host, ~/otpu-build/deploy_em_91a9c2d3/host (T: the commit with the threshold, EM_ROWS in\n# opentpu/host/streamed.py and --em-rows in tools/qual/chatmoe.py, or it stops); production's host for the P arm,\n# read-only, no bytecode written (PH: deploy_mt4_91a9c2d3/host, main 23b68089). Card: production deploy_mt4_91a9c2d3\n# as loaded (EXPECT 91a9c2d3, register map 4). One otpu-lock:\n# 1. selftest (T); the device configuration must be production's qual/cfg.pkl;\n# 2. the production qual's chatmoe step from T: tools/qual/chatmoe.sh, RUNS=\"qwen35-35b gemma4-26b\" (two greedy turns\n#    each, the second continuing the context), token-exact against the ISA references (O/chatmoe-<model>.json);\n# 3. otpu-chat by name from T, one greedy answer each (qual_run.sh's), its reply against production's mt4 chat-<model>.txt;\n# 4. per model three arms, each a chatmoe.py chat of five turns continuing one context, about 24, 31, 49, 80 and 163\n#    new tokens on the 35B (TURNS' two, a question, a request, lmtime's passage with a question; each turn is a\n#    call up to the snapshot at the reply's start and a 4-row call after it, both models holding state):\n#      P  production's host (every call layer-major),\n#      N  T as it would ship (expert-major from the family's EM_ROWS rows a call),\n#      X  T with --em-rows 8 (every call but the 4-row ones expert-major: the crossover);\n#    a discarded warm-up (N), then P N X X N P. Every run's tokens must equal the warm-up's, and its first two\n#    turns the ISA references'. N1 and X1 write each call's runs and the server's timeline (--trace);\n# 5. selftest; then the summary: per model and turn the arms' TTFT, the pairs N - P and X - P, and N's and X's calls\n#    (rows, expert-major or not, wall and device s, needs, parts, holds, misses).\n# The swap's rule (the lead's): N no worse than P at every turn and faster on the long ones; X - P per call length is\n# where EM_ROWS belongs.\n# A build other than EXPECT, a failed selftest, another configuration, a FAIL, a failed or timed-out run or a mismatch\n# stops it (then the final selftest). About 40 min.\n# Run (no pipe): setsid nohup ~/.local/bin/otpu-lock --wait 600 -- bash $T/tools/offload/sessions/emdef2.sh\n#   > ~/otpu-build/moe-ab/emdef2.launch.log 2>&1 < /dev/null &\nset -u\nfor v in $(env | grep -o '^OTPU_[A-Z0-9_]*' | grep -vE '^OTPU_LOCK_(HELD|PID|WAIT)$'); do unset $v; done\nexport OTPU_IMG_CACHE_GB=30 OTPU_IMG_CACHE_FREE_GB=6      # (the card host's, from its ~/.bashrc)\nMA=${MA:-$HOME/otpu-build/moe-ab}\nT=${T:-$HOME/otpu-build/deploy_em_91a9c2d3/host}\nPH=${PH:-$HOME/otpu-build/deploy_mt4_91a9c2d3/host}\nR=${R:-$MA/emdef2}\nsource $T/tools/offload/sessions/env.sh       # (O: card2; OTPU_QUIET claimed, removed at exit)\nexec > >(tee -a $R/session.log) 2>&1\nEXPECT=${EXPECT:-91a9c2d3}\nXROWS=${XROWS:-8}                             # (X: every call of more rows than the 4 after a snapshot)\nPD=$HOME/otpu-build/deploy_mt4_91a9c2d3        # (production's qual/cfg.pkl and chat-<model>.txt)\nDROPOTHER=$HOME/openTPU/models:$O:$HOME/otpu-build/offload/g26it\nT1=\"What is the capital of France? Answer in one sentence.\"\nT2=\"And what is it famous for? Two sentences.\"\nT3=\"Which three museums in Paris should a first-time visitor see, and how long does each take?\"\nT4=\"I will be in Paris for four days in late spring with two teenagers who like history, art and food. Suggest a simple plan for each day, with one museum, one walk and one place to eat, and keep the whole plan short.\"\nT5=\"$(python -c 'import json, sys; print(json.load(open(sys.argv[1]))[\"prompt\"])' \\\n      $HOME/otpu-build/moepf/lmtime/q35w-hf.json) Summarize this passage in one sentence.\"\ndeclare -A M=([q]=\"qwen35-35b Qwen3.5-35B-A3B pool-q35-fp4.split.bin\"\n              [g]=\"gemma4-26b gemma-4-26B-A4B-it ../g26it/pool-g26it-fp4.split.bin\")\nfail=0\necho \"emdef2 start $(date +%T) T $T ($(cat $T/COMMIT)) PH $PH ($(cat $PH/COMMIT)) mem $(mem) GB, /home $(df -BG --output=avail /home | tail -1 | tr -d ' ') free; $(uptime)\"\ngrep -q \"^EM_ROWS = \" $T/opentpu/host/streamed.py && grep -q -- \"--em-rows\" $T/tools/qual/chatmoe.py \\\n  || { echo \"STOP: T has no EM_ROWS / chatmoe --em-rows (not the threshold's commit)\"; exit 2; }\necho \"  T's EM_ROWS: $(grep '^EM_ROWS = ' $T/opentpu/host/streamed.py)\"\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"build $EXPECT\" || { echo \"STOP: the card's build is not $EXPECT\"; exit 2; }\necho \"$st\" | grep -q \"register map 4\" || { echo \"STOP: not register map 4\"; exit 2; }\necho \"$st\" | grep -q \"ALL PASS\" || { echo \"STOP: selftest\"; exit 2; }\ntimeout 300 python tools/qual/refs.py cfg $R/cfg-dev.pkl > /dev/null 2>&1; echo \"cfg exit $?\"\npython - $R/cfg-dev.pkl $PD/qual/cfg.pkl <<'PY' || { echo \"STOP: the device configuration\"; exit 2; }\nimport dataclasses, pickle, sys\na, b = (pickle.load(open(f, \"rb\")) for f in sys.argv[1:])\nd = {f.name: (getattr(a, f.name), getattr(b, f.name)) for f in dataclasses.fields(a)\n     if getattr(a, f.name) != getattr(b, f.name)}\nprint(\"  cfg: production's (qual/cfg.pkl)\" if not d else f\"  cfg DIFFERS from production's: {d}\")\nsys.exit(1 if d else 0)\nPY\nwarm() {   # checkpoint, pool (in O): every other big file out of the page cache, the pool read into it\n  python - $O/$1 $O/$2 $DROPOTHER <<'PY'\nimport os, sys                      # every other file of 100 MB or more out of the page cache\nkeep = {os.path.realpath(sys.argv[1]), os.path.realpath(sys.argv[2])}  # (card_moe.sh's DROPOTHER)\nours = tuple(os.path.realpath(os.path.expanduser(d)) + os.sep for d in (\"~/openTPU\", \"~/otpu-build\"))\ngb = n = 0\nseen = set()\nfor d in sys.argv[3].split(\":\"):\n    for root, _, files in os.walk(os.path.expanduser(d)):\n        for f in files:\n            r = os.path.realpath(os.path.join(root, f))\n            if r in seen or not r.startswith(ours) or not os.path.isfile(r) \\\n                    or os.path.getsize(r) < 100 << 20 or r in keep or os.path.dirname(r) in keep:\n                continue\n            seen.add(r)\n            fd = os.open(r, os.O_RDONLY)\n            os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n            os.close(fd)\n            gb, n = gb + os.path.getsize(r) / 1e9, n + 1\nprint(f\"  dropped from the page cache: {n} other files of {gb:.1f} GB\")\nPY\n  local t0=$SECONDS; cat $O/$2 > /dev/null; echo \"  pool read in $((SECONDS - t0)) s, mem $(mem) GB\"\n}\n# 2. the production qual's chatmoe step, from T\necho \"=== chatmoe.sh $(date +%T)\"\nenv RUNS=\"qwen35-35b gemma4-26b\" SESSION=chatmoe R=$R/chatmoe timeout 3600 bash $T/tools/qual/chatmoe.sh \\\n  > $R/chatmoe.log 2>&1\necho \"  CHATMOE EXIT $? $(date +%T)\"\ngrep -E \"\\[(PASS|FAIL|SKIP)\\] [^ ]+ against|  turn [0-9]|    call: |Error|Traceback\" $R/chatmoe.log | cut -c1-260\n[ \"$(grep -c \"turns' tokens the same\" $R/chatmoe.log)\" = 2 ] && ! grep -q \"\\[FAIL\\]\" $R/chatmoe.log \\\n  || { echo \"STOP: chatmoe\"; fail=1; }\n# 3. otpu-chat by name, from T\nfor m in q g; do\n  [ $fail = 0 ] || break\n  read -r name md pool <<< \"${M[$m]}\"\n  echo \"=== otpu-chat $name $(date +%T)\"\n  warm $md $pool\n  (cd /tmp && timeout 1200 python -m opentpu.host.chat --backend board --model $name --greedy --max-new 24 \\\n     --prompt \"$T1\" > $R/chat-$name.txt 2>&1)\n  echo \"  CHAT $name EXIT $? $(date +%T)\"\n  python - $R/chat-$name.txt $PD/chat-$name.txt <<'PY' || { echo \"STOP: otpu-chat $name\"; fail=1; }\nimport sys\ndef part(f):\n    ln = [x for x in open(f).read().splitlines() if x.strip()]\n    reply = [x for x in ln if not x.startswith((\"loading \", \"experts:\", \"weights:\", \"loaded in\", \"[TTFT\"))]\n    return reply, [x for x in ln if x.startswith((\"loaded in\", \"[TTFT\"))]\n(a, sa), (b, sb) = part(sys.argv[1]), part(sys.argv[2])\nprint(f\"  [{'PASS' if a == b and a else 'FAIL'}] reply {a!r} {'=' if a == b else '!='} production's (mt4)\")\nfor x, y in zip(sa, sb):\n    print(f\"    {x[:200]}\\n    (mt4) {y[:200]}\")\nsys.exit(0 if a == b and a else 1)\nPY\ndone\n# 4. P (production's host), N (T), X (T, --em-rows XROWS), per model: W, then P N X X N P\nfor m in q g; do\n  [ $fail = 0 ] || break\n  read -r name md pool <<< \"${M[$m]}\"\n  for x in W P1 N1 X1 X2 N2 P2; do\n    tree=$T; [ ${x:0:1} = P ] && tree=$PH\n    extra=(); [ ${x:0:1} = X ] && extra=(--em-rows $XROWS)\n    case $x in N1|X1) extra+=(--trace $R/$m$x.trace.json);; esac\n    echo \"=== $m$x $(date +%T) ($name, host $(cat $tree/COMMIT)${extra[*]:+, ${extra[*]}})\"\n    warm $md $pool\n    (cd $tree && env PYTHONPATH=$tree PYTHONDONTWRITEBYTECODE=1 timeout 1500 python tools/qual/chatmoe.py \\\n       $O/$md --pool $O/$pool --backend board --cfg $R/cfg-dev.pkl --turn \"$T1\" --turn \"$T2\" --turn \"$T3\" \\\n       --turn \"$T4\" --turn \"$T5\" \"${extra[@]}\" --out $R/$m$x.json > $R/$m$x.log 2>&1)\n    rc=$?; echo \"  exit $rc $(date +%T)\"; grep -E \"Error|Traceback\" $R/$m$x.log | tail -3\n    [ $rc = 0 ] && [ -f $R/$m$x.json ] || { echo \"STOP: $m$x\"; fail=1; break; }\n    python - $R/$m$x.json $R/${m}W.json $RF/chatmoe-$name.json <<'PY' || { echo \"STOP: $m$x differs\"; fail=1; break; }\nimport json, sys\nd, w, ref = (json.load(open(f)) for f in sys.argv[1:])\ntok = [t[\"tokens\"] for t in d[\"turns\"]]\nok_w = tok == [t[\"tokens\"] for t in w[\"turns\"]]\nok_r = tok[:2] == [t[\"tokens\"] for t in ref[\"turns\"][:2]]     # (the references: TURNS' two)\nprint(f\"  [{'PASS' if ok_w and ok_r else 'FAIL'}] tokens {'=' if ok_w else '!='} W's, first two turns \"\n      f\"{'=' if ok_r else '!='} the ISA reference's; layer-major {d['layer_major']}, em_rows \"\n      f\"{d.get('em_rows', '-')}, load {d['load_s']} s\")\nfor i, t in enumerate(d[\"turns\"]):\n    print(f\"  turn {i + 1}: prompt {t['prompt_tokens']} (reused {t['reused']}) TTFT {t['ttft_s']} s, prefill \"\n          f\"{t['prefill_tok_s']} tok/s (device {t['prefill_dev_tok_s']}), {t['prefill_misses']} misses; decode \"\n          f\"{t['gen_tokens']} at {t['decode_tok_s']} tok/s (device {t['decode_dev_tok_s']}); end {t['end']}\")\n    for c in t.get(\"calls\", []):\n        print(f\"    call {c['rows']} rows {'EM' if c['em'] else 'LM'}: {c['s']} s (device {c['device_s']}), \"\n              f\"{c['runs']} runs, misses {c['misses']}, needs {c['needs_queued']} (hits {c['need_hits']}), \"\n              f\"parts {c['prefetched']}, holds {c['holds']}\")\nsys.exit(0 if ok_w and ok_r else 1)\nPY\n  done\ndone\necho \"=== final selftest $(date +%T)\"\ntimeout 600 python -m opentpu.host.selftest 2>&1 | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"emdef2 end $(date +%T) fail $fail\"\npython - $R <<'PY'\nimport json, os, sys\nr = sys.argv[1]\ndef get(run):\n    f = f\"{r}/{run}.json\"\n    return json.load(open(f)) if os.path.exists(f) else None\nfor name, m in ((\"35B\", \"q\"), (\"26B\", \"g\")):\n    a = {x: get(m + x) for x in (\"P1\", \"N1\", \"X1\", \"X2\", \"N2\", \"P2\")}\n    if None in a.values():\n        print(f\"  {name}: incomplete\"); continue\n    for i in range(len(a[\"P1\"][\"turns\"])):\n        v = lambda x, k=\"ttft_s\": a[x][\"turns\"][i][k] or 0.0     # noqa: E731\n        mean = lambda p: (v(p + \"1\") + v(p + \"2\")) / 2           # noqa: E731\n        calls = lambda x: \" + \".join(f\"{c['rows']}{'E' if c['em'] else 'L'}\"     # noqa: E731\n                                     for c in a[x][\"turns\"][i].get(\"calls\", []))\n        print(f\"  {name} turn {i + 1} ({a['P1']['turns'][i]['prompt_tokens']} tokens; N {calls('N1')}, X \"\n              f\"{calls('X1')}) TTFT: P {mean('P'):.3f}, N {mean('N'):.3f}, X {mean('X'):.3f}; N-P \"\n              f\"{v('N1') - v('P1'):+.3f} {v('N2') - v('P2'):+.3f} mean {mean('N') - mean('P'):+.3f}; X-P \"\n              f\"{v('X1') - v('P1'):+.3f} {v('X2') - v('P2'):+.3f} mean {mean('X') - mean('P'):+.3f}\")\n        for k in (\"decode_tok_s\", \"prefill_dev_tok_s\"):\n            m2 = lambda p: (v(p + \"1\", k) + v(p + \"2\", k)) / 2   # noqa: E731\n            print(f\"      {k}: P {m2('P'):.3f}, N {m2('N'):.3f}, X {m2('X'):.3f}\")\nPY\ndate > $R/DONE\necho \"EMDEF2 EXIT $fail $(date +%T)\"\n", "tools/offload/sessions/emdef3.sh": "#!/bin/bash\n# Session emdef3 (docs/offload.md 13.16): the expert-major threshold again, after emdef2. There every run was\n# token-exact and the 35B's expert-major calls gained from 45 rows on (X - P: 27 rows +0.27 s, 45 rows -0.21 s), but\n# N's 27-row layer-major call (turn 2) took +0.40 / +0.52 s against P's. On the ISA simulator N's layer-major calls run\n# production's programs, requests, slots, snapshots and tokens exactly (the gate changes nothing below EM_ROWS); in\n# N1's trace that call's requests were served about 8% slower a miss than its turn 3's, all along the call: the host's\n# time, which emdef2 measured for N and X only. So here:\n# - P runs T's chatmoe.py on production's opentpu (PYTHONPATH=PH: production's engine, server and settings; the tool\n#   only records): each P call has the same counts as N's and X's, and its requests' host time;\n# - every run but W writes its trace (each call's runs and the server's timeline);\n# - before each run the host's load and its busiest processes are logged (the headless 1Password / Hyprland spin);\n# - EM_ROWS from emdef2's X - P: Qwen3.5 44, Gemma 4 24.\n# Trees: the candidate deploy's host, ~/otpu-build/deploy_em_91a9c2d3/host (T: the commit with EM_ROWS 44 and\n# chatmoe.py's serve_s, or it stops); production's host (PH: deploy_mt4_91a9c2d3/host, main 23b68089), read-only, no\n# bytecode written. Card: production deploy_mt4_91a9c2d3 as loaded (EXPECT 91a9c2d3, register map 4). One otpu-lock:\n# 1. selftest (T); the device configuration must be production's qual/cfg.pkl;\n# 2. the production qual's chatmoe step from T (RUNS=\"qwen35-35b gemma4-26b\"), token-exact against the ISA references;\n# 3. otpu-chat by name from T, one greedy answer each, its reply against production's mt4 chat-<model>.txt;\n# 4. per model emdef2's five turns (about 24, 31, 49, 80 and 163 new tokens on the 35B, each a call up to the snapshot\n#    at the reply's start and a 4-row call after it), arms P (production's opentpu), N (T: EM_ROWS), X (T,\n#    --em-rows 8: every call but the 4-row ones expert-major); a discarded warm-up (N), then P N X X N P. Every run's\n#    tokens must equal the warm-up's, and its first two turns the ISA references';\n# 5. selftest; the summary: per model and turn the arms' TTFT, N - P and X - P per pair, the calls, and each arm's\n#    layer-major calls' host time a miss (serve_s / misses: a gap the host's, not the card's).\n# The swap's rule (the lead's): N no worse than P at every turn and faster on the long ones, token-exact.\n# A build other than EXPECT, a failed selftest, another configuration, a FAIL, a failed or timed-out run or a mismatch\n# stops it (then the final selftest). About 40 min.\n# Run (no pipe): setsid nohup ~/.local/bin/otpu-lock --wait 600 -- bash $T/tools/offload/sessions/emdef3.sh\n#   > ~/otpu-build/moe-ab/emdef3.launch.log 2>&1 < /dev/null &\nset -u\nfor v in $(env | grep -o '^OTPU_[A-Z0-9_]*' | grep -vE '^OTPU_LOCK_(HELD|PID|WAIT)$'); do unset $v; done\nexport OTPU_IMG_CACHE_GB=30 OTPU_IMG_CACHE_FREE_GB=6      # (the card host's, from its ~/.bashrc)\nMA=${MA:-$HOME/otpu-build/moe-ab}\nT=${T:-$HOME/otpu-build/deploy_em_91a9c2d3/host}\nPH=${PH:-$HOME/otpu-build/deploy_mt4_91a9c2d3/host}\nR=${R:-$MA/emdef3}\nsource $T/tools/offload/sessions/env.sh       # (O: card2; OTPU_QUIET claimed, removed at exit)\nexec > >(tee -a $R/session.log) 2>&1\nEXPECT=${EXPECT:-91a9c2d3}\nXROWS=${XROWS:-8}                             # (X: every call of more rows than the 4 after a snapshot)\nPD=$HOME/otpu-build/deploy_mt4_91a9c2d3        # (production's qual/cfg.pkl and chat-<model>.txt)\nDROPOTHER=$HOME/openTPU/models:$O:$HOME/otpu-build/offload/g26it\nT1=\"What is the capital of France? Answer in one sentence.\"\nT2=\"And what is it famous for? Two sentences.\"\nT3=\"Which three museums in Paris should a first-time visitor see, and how long does each take?\"\nT4=\"I will be in Paris for four days in late spring with two teenagers who like history, art and food. Suggest a simple plan for each day, with one museum, one walk and one place to eat, and keep the whole plan short.\"\nT5=\"$(python -c 'import json, sys; print(json.load(open(sys.argv[1]))[\"prompt\"])' \\\n      $HOME/otpu-build/moepf/lmtime/q35w-hf.json) Summarize this passage in one sentence.\"\ndeclare -A M=([q]=\"qwen35-35b Qwen3.5-35B-A3B pool-q35-fp4.split.bin\"\n              [g]=\"gemma4-26b gemma-4-26B-A4B-it ../g26it/pool-g26it-fp4.split.bin\")\nfail=0\necho \"emdef3 start $(date +%T) T $T ($(cat $T/COMMIT)) PH $PH ($(cat $PH/COMMIT)) mem $(mem) GB, /home $(df -BG --output=avail /home | tail -1 | tr -d ' ') free; $(uptime)\"\ngrep -q '^EM_ROWS = {\"qwen35\": 44' $T/opentpu/host/streamed.py && grep -q \"serve_s\" $T/tools/qual/chatmoe.py \\\n  || { echo \"STOP: T is not the commit with EM_ROWS 44 and chatmoe.py's serve_s\"; exit 2; }\necho \"  T's EM_ROWS: $(grep '^EM_ROWS = ' $T/opentpu/host/streamed.py)\"\necho \"  P's opentpu: $(cd /tmp && PYTHONPATH=$PH PYTHONDONTWRITEBYTECODE=1 python -c 'import opentpu; print(opentpu.__file__)')\"\nbusy() { echo \"  host: $(cut -d' ' -f1-3 /proc/loadavg); $(ps -eo pcpu,comm --sort=-pcpu | sed -n 2,4p | tr -s ' ' | tr '\\n' ';')\"; }\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"build $EXPECT\" || { echo \"STOP: the card's build is not $EXPECT\"; exit 2; }\necho \"$st\" | grep -q \"register map 4\" || { echo \"STOP: not register map 4\"; exit 2; }\necho \"$st\" | grep -q \"ALL PASS\" || { echo \"STOP: selftest\"; exit 2; }\ntimeout 300 python tools/qual/refs.py cfg $R/cfg-dev.pkl > /dev/null 2>&1; echo \"cfg exit $?\"\npython - $R/cfg-dev.pkl $PD/qual/cfg.pkl <<'PY' || { echo \"STOP: the device configuration\"; exit 2; }\nimport dataclasses, pickle, sys\na, b = (pickle.load(open(f, \"rb\")) for f in sys.argv[1:])\nd = {f.name: (getattr(a, f.name), getattr(b, f.name)) for f in dataclasses.fields(a)\n     if getattr(a, f.name) != getattr(b, f.name)}\nprint(\"  cfg: production's (qual/cfg.pkl)\" if not d else f\"  cfg DIFFERS from production's: {d}\")\nsys.exit(1 if d else 0)\nPY\nwarm() {   # checkpoint, pool (in O): every other big file out of the page cache, the pool read into it\n  python - $O/$1 $O/$2 $DROPOTHER <<'PY'\nimport os, sys                      # every other file of 100 MB or more out of the page cache\nkeep = {os.path.realpath(sys.argv[1]), os.path.realpath(sys.argv[2])}  # (card_moe.sh's DROPOTHER)\nours = tuple(os.path.realpath(os.path.expanduser(d)) + os.sep for d in (\"~/openTPU\", \"~/otpu-build\"))\ngb = n = 0\nseen = set()\nfor d in sys.argv[3].split(\":\"):\n    for root, _, files in os.walk(os.path.expanduser(d)):\n        for f in files:\n            r = os.path.realpath(os.path.join(root, f))\n            if r in seen or not r.startswith(ours) or not os.path.isfile(r) \\\n                    or os.path.getsize(r) < 100 << 20 or r in keep or os.path.dirname(r) in keep:\n                continue\n            seen.add(r)\n            fd = os.open(r, os.O_RDONLY)\n            os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n            os.close(fd)\n            gb, n = gb + os.path.getsize(r) / 1e9, n + 1\nprint(f\"  dropped from the page cache: {n} other files of {gb:.1f} GB\")\nPY\n  local t0=$SECONDS; cat $O/$2 > /dev/null; echo \"  pool read in $((SECONDS - t0)) s, mem $(mem) GB\"\n}\n# 2. the production qual's chatmoe step, from T\necho \"=== chatmoe.sh $(date +%T)\"\nenv RUNS=\"qwen35-35b gemma4-26b\" SESSION=chatmoe R=$R/chatmoe timeout 3600 bash $T/tools/qual/chatmoe.sh \\\n  > $R/chatmoe.log 2>&1\necho \"  CHATMOE EXIT $? $(date +%T)\"\ngrep -E \"\\[(PASS|FAIL|SKIP)\\] [^ ]+ against|  turn [0-9]|    call: |Error|Traceback\" $R/chatmoe.log | cut -c1-260\n[ \"$(grep -c \"turns' tokens the same\" $R/chatmoe.log)\" = 2 ] && ! grep -q \"\\[FAIL\\]\" $R/chatmoe.log \\\n  || { echo \"STOP: chatmoe\"; fail=1; }\n# 3. otpu-chat by name, from T\nfor m in q g; do\n  [ $fail = 0 ] || break\n  read -r name md pool <<< \"${M[$m]}\"\n  echo \"=== otpu-chat $name $(date +%T)\"\n  warm $md $pool\n  (cd /tmp && timeout 1200 python -m opentpu.host.chat --backend board --model $name --greedy --max-new 24 \\\n     --prompt \"$T1\" > $R/chat-$name.txt 2>&1)\n  echo \"  CHAT $name EXIT $? $(date +%T)\"\n  python - $R/chat-$name.txt $PD/chat-$name.txt <<'PY' || { echo \"STOP: otpu-chat $name\"; fail=1; }\nimport sys\ndef part(f):\n    ln = [x for x in open(f).read().splitlines() if x.strip()]\n    reply = [x for x in ln if not x.startswith((\"loading \", \"experts:\", \"weights:\", \"loaded in\", \"[TTFT\"))]\n    return reply, [x for x in ln if x.startswith((\"loaded in\", \"[TTFT\"))]\n(a, sa), (b, sb) = part(sys.argv[1]), part(sys.argv[2])\nprint(f\"  [{'PASS' if a == b and a else 'FAIL'}] reply {a!r} {'=' if a == b else '!='} production's (mt4)\")\nfor x, y in zip(sa, sb):\n    print(f\"    {x[:200]}\\n    (mt4) {y[:200]}\")\nsys.exit(0 if a == b and a else 1)\nPY\ndone\n# 4. P (production's host), N (T), X (T, --em-rows XROWS), per model: W, then P N X X N P\nfor m in q g; do\n  [ $fail = 0 ] || break\n  read -r name md pool <<< \"${M[$m]}\"\n  for x in W P1 N1 X1 X2 N2 P2; do\n    tree=$T; [ ${x:0:1} = P ] && tree=$PH          # (the opentpu it runs; the tool is T's)\n    extra=(); [ ${x:0:1} = X ] && extra=(--em-rows $XROWS)\n    [ $x = W ] || extra+=(--trace $R/$m$x.trace.json)\n    echo \"=== $m$x $(date +%T) ($name, opentpu $(cat $tree/COMMIT)${extra[*]:+, ${extra[*]}})\"\n    warm $md $pool\n    busy\n    (cd $T && env PYTHONPATH=$tree PYTHONDONTWRITEBYTECODE=1 timeout 1500 python $T/tools/qual/chatmoe.py \\\n       $O/$md --pool $O/$pool --backend board --cfg $R/cfg-dev.pkl --turn \"$T1\" --turn \"$T2\" --turn \"$T3\" \\\n       --turn \"$T4\" --turn \"$T5\" \"${extra[@]}\" --out $R/$m$x.json > $R/$m$x.log 2>&1)\n    rc=$?; echo \"  exit $rc $(date +%T)\"; grep -E \"Error|Traceback\" $R/$m$x.log | tail -3\n    [ $rc = 0 ] && [ -f $R/$m$x.json ] || { echo \"STOP: $m$x\"; fail=1; break; }\n    python - $R/$m$x.json $R/${m}W.json $RF/chatmoe-$name.json <<'PY' || { echo \"STOP: $m$x differs\"; fail=1; break; }\nimport json, sys\nd, w, ref = (json.load(open(f)) for f in sys.argv[1:])\ntok = [t[\"tokens\"] for t in d[\"turns\"]]\nok_w = tok == [t[\"tokens\"] for t in w[\"turns\"]]\nok_r = tok[:2] == [t[\"tokens\"] for t in ref[\"turns\"][:2]]     # (the references: TURNS' two)\nprint(f\"  [{'PASS' if ok_w and ok_r else 'FAIL'}] tokens {'=' if ok_w else '!='} W's, first two turns \"\n      f\"{'=' if ok_r else '!='} the ISA reference's; layer-major {d['layer_major']}, em_rows \"\n      f\"{d.get('em_rows', '-')}, load {d['load_s']} s\")\nfor i, t in enumerate(d[\"turns\"]):\n    print(f\"  turn {i + 1}: prompt {t['prompt_tokens']} (reused {t['reused']}) TTFT {t['ttft_s']} s, prefill \"\n          f\"{t['prefill_tok_s']} tok/s (device {t['prefill_dev_tok_s']}), {t['prefill_misses']} misses; decode \"\n          f\"{t['gen_tokens']} at {t['decode_tok_s']} tok/s (device {t['decode_dev_tok_s']}); end {t['end']}\")\n    for c in t.get(\"calls\", []):\n        print(f\"    call {c['rows']} rows {'EM' if c['em'] else 'LM'}: {c['s']} s (device {c['device_s']}), \"\n              f\"{c['runs']} runs, misses {c['misses']} ({c['requests']} requests, served in {c['serve_s']} s), \"\n              f\"needs {c['needs_queued']} (hits {c['need_hits']}), parts {c['prefetched']} ({c['parts_s']} s), \"\n              f\"holds {c['holds']}\")\nsys.exit(0 if ok_w and ok_r else 1)\nPY\n  done\ndone\necho \"=== final selftest $(date +%T)\"\ntimeout 600 python -m opentpu.host.selftest 2>&1 | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"emdef3 end $(date +%T) fail $fail\"\npython - $R <<'PY'\nimport json, os, sys\nr = sys.argv[1]\ndef get(run):\n    f = f\"{r}/{run}.json\"\n    return json.load(open(f)) if os.path.exists(f) else None\nfor name, m in ((\"35B\", \"q\"), (\"26B\", \"g\")):\n    a = {x: get(m + x) for x in (\"P1\", \"N1\", \"X1\", \"X2\", \"N2\", \"P2\")}\n    if None in a.values():\n        print(f\"  {name}: incomplete\"); continue\n    for i in range(len(a[\"P1\"][\"turns\"])):\n        v = lambda x, k=\"ttft_s\": a[x][\"turns\"][i][k] or 0.0     # noqa: E731\n        mean = lambda p: (v(p + \"1\") + v(p + \"2\")) / 2           # noqa: E731\n        calls = lambda x: \" + \".join(f\"{c['rows']}{'E' if c['em'] else 'L'}\"     # noqa: E731\n                                     for c in a[x][\"turns\"][i].get(\"calls\", []))\n        print(f\"  {name} turn {i + 1} ({a['P1']['turns'][i]['prompt_tokens']} tokens; N {calls('N1')}, X \"\n              f\"{calls('X1')}) TTFT: P {mean('P'):.3f}, N {mean('N'):.3f}, X {mean('X'):.3f}; N-P \"\n              f\"{v('N1') - v('P1'):+.3f} {v('N2') - v('P2'):+.3f} mean {mean('N') - mean('P'):+.3f}; X-P \"\n              f\"{v('X1') - v('P1'):+.3f} {v('X2') - v('P2'):+.3f} mean {mean('X') - mean('P'):+.3f}\")\n        for k in (\"decode_tok_s\", \"prefill_dev_tok_s\"):\n            m2 = lambda p: (v(p + \"1\", k) + v(p + \"2\", k)) / 2   # noqa: E731\n            print(f\"      {k}: P {m2('P'):.3f}, N {m2('N'):.3f}, X {m2('X'):.3f}\")\n        def lm(x):          # the layer-major calls' host time a miss, ms\n            cs = [c for c in a[x][\"turns\"][i].get(\"calls\", []) if not c[\"em\"] and c[\"misses\"]]\n            m = sum(c[\"misses\"] for c in cs)\n            return f\"{1e3 * sum(c['serve_s'] for c in cs) / m:.3f}\" if m else \"-\"\n        print(\"      layer-major calls' host ms a miss: \" + \", \".join(f\"{x} {lm(x)}\" for x in a))\nPY\ndate > $R/DONE\necho \"EMDEF3 EXIT $fail $(date +%T)\"\n", "tools/offload/sessions/emdef4.sh": "#!/bin/bash\n# Session emdef4 (docs/offload.md 13.16): the expert-major threshold's swap check, short. emdef3 was token-exact and\n# the 35B passed; the 26B's first turn (21 rows, layer-major in both arms) took +0.20 / +0.14 s against P, with the\n# same requests (the host served them 3-8% slower in N; on the ISA simulator N's and P's layer-major calls run the\n# same programs, requests and slots, and their host time a request is the same). Gemma 4's EM_ROWS is now 20: its\n# 21-row call expert-major (X - P over four pairs -0.086 s TTFT, -0.18 to -0.56 s device). Qwen3.5's stays 44.\n# Trees: the candidate deploy's host, ~/otpu-build/deploy_em_91a9c2d3/host (T: the commit with EM_ROWS 44 / 20, or it\n# stops); production's host (PH: deploy_mt4_91a9c2d3/host, main 23b68089), read-only, no bytecode written. Card:\n# production deploy_mt4_91a9c2d3 as loaded (EXPECT 91a9c2d3, register map 4). One otpu-lock:\n# 1. selftest (T); the device configuration must be production's qual/cfg.pkl;\n# 2. the production qual's chatmoe step from T (RUNS=\"qwen35-35b gemma4-26b\"), token-exact against the ISA references\n#    (the 26B's two turns now expert-major: 21 and 27 rows);\n# 3. otpu-chat by name from T, one greedy answer each, its reply against production's mt4 chat-<model>.txt;\n# 4. per model emdef2's first three turns (about 24, 31 and 49 new tokens on the 35B: calls of 20, 27 and 45 rows,\n#    each with a 4-row call after it; the 26B's 21, 27 and 46), arms P (T's chatmoe.py on production's opentpu) and\n#    N (T), every run traced: a discarded warm-up (N), then ORDER (default P1 N1 N2 P2; for more pairs, balanced:\n#    ORDER=\"P1 N1 N2 P2 N3 P3 P4 N4\", about 8 min more). Every run's tokens must equal the warm-up's, and its first\n#    two turns the ISA references';\n# 5. selftest; the summary: per model and turn each run's TTFT and device s, N - P per pair (Nk - Pk) and of the\n#    means, the calls, and each arm's layer-major calls' host ms a miss.\n# The swap's rule (the lead's): N no worse than P at every turn, token-exact.\n# A build other than EXPECT, a failed selftest, another configuration, a FAIL, a failed or timed-out run or a mismatch\n# stops it (then the final selftest). About 20 min.\n# Run (no pipe): setsid nohup ~/.local/bin/otpu-lock --wait 600 -- bash $T/tools/offload/sessions/emdef4.sh\n#   > ~/otpu-build/moe-ab/emdef4.launch.log 2>&1 < /dev/null &\nset -u\nfor v in $(env | grep -o '^OTPU_[A-Z0-9_]*' | grep -vE '^OTPU_LOCK_(HELD|PID|WAIT)$'); do unset $v; done\nexport OTPU_IMG_CACHE_GB=30 OTPU_IMG_CACHE_FREE_GB=6      # (the card host's, from its ~/.bashrc)\nMA=${MA:-$HOME/otpu-build/moe-ab}\nT=${T:-$HOME/otpu-build/deploy_em_91a9c2d3/host}\nPH=${PH:-$HOME/otpu-build/deploy_mt4_91a9c2d3/host}\nR=${R:-$MA/emdef4}\nsource $T/tools/offload/sessions/env.sh       # (O: card2; OTPU_QUIET claimed, removed at exit)\nexec > >(tee -a $R/session.log) 2>&1\nEXPECT=${EXPECT:-91a9c2d3}\nORDER=${ORDER:-P1 N1 N2 P2}                    # (after the warm-up W)\nPD=$HOME/otpu-build/deploy_mt4_91a9c2d3        # (production's qual/cfg.pkl and chat-<model>.txt)\nDROPOTHER=$HOME/openTPU/models:$O:$HOME/otpu-build/offload/g26it\nT1=\"What is the capital of France? Answer in one sentence.\"\nT2=\"And what is it famous for? Two sentences.\"\nT3=\"Which three museums in Paris should a first-time visitor see, and how long does each take?\"\ndeclare -A M=([q]=\"qwen35-35b Qwen3.5-35B-A3B pool-q35-fp4.split.bin\"\n              [g]=\"gemma4-26b gemma-4-26B-A4B-it ../g26it/pool-g26it-fp4.split.bin\")\nfail=0\necho \"emdef4 start $(date +%T) T $T ($(cat $T/COMMIT)) PH $PH ($(cat $PH/COMMIT)) mem $(mem) GB, /home $(df -BG --output=avail /home | tail -1 | tr -d ' ') free; $(uptime)\"\ngrep -q '^EM_ROWS = {\"qwen35\": 44, \"gemma4\": 20}' $T/opentpu/host/streamed.py \\\n  && grep -q \"serve_s\" $T/tools/qual/chatmoe.py \\\n  || { echo \"STOP: T is not the commit with EM_ROWS 44 / 20 and chatmoe.py's serve_s\"; exit 2; }\necho \"  T's EM_ROWS: $(grep '^EM_ROWS = ' $T/opentpu/host/streamed.py)\"\necho \"  P's opentpu: $(cd /tmp && PYTHONPATH=$PH PYTHONDONTWRITEBYTECODE=1 python -c 'import opentpu; print(opentpu.__file__)')\"\nbusy() { echo \"  host: $(cut -d' ' -f1-3 /proc/loadavg); $(ps -eo pcpu,comm --sort=-pcpu | sed -n 2,4p | tr -s ' ' | tr '\\n' ';')\"; }\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"build $EXPECT\" || { echo \"STOP: the card's build is not $EXPECT\"; exit 2; }\necho \"$st\" | grep -q \"register map 4\" || { echo \"STOP: not register map 4\"; exit 2; }\necho \"$st\" | grep -q \"ALL PASS\" || { echo \"STOP: selftest\"; exit 2; }\ntimeout 300 python tools/qual/refs.py cfg $R/cfg-dev.pkl > /dev/null 2>&1; echo \"cfg exit $?\"\npython - $R/cfg-dev.pkl $PD/qual/cfg.pkl <<'PY' || { echo \"STOP: the device configuration\"; exit 2; }\nimport dataclasses, pickle, sys\na, b = (pickle.load(open(f, \"rb\")) for f in sys.argv[1:])\nd = {f.name: (getattr(a, f.name), getattr(b, f.name)) for f in dataclasses.fields(a)\n     if getattr(a, f.name) != getattr(b, f.name)}\nprint(\"  cfg: production's (qual/cfg.pkl)\" if not d else f\"  cfg DIFFERS from production's: {d}\")\nsys.exit(1 if d else 0)\nPY\nwarm() {   # checkpoint, pool (in O): every other big file out of the page cache, the pool read into it\n  python - $O/$1 $O/$2 $DROPOTHER <<'PY'\nimport os, sys                      # every other file of 100 MB or more out of the page cache\nkeep = {os.path.realpath(sys.argv[1]), os.path.realpath(sys.argv[2])}  # (card_moe.sh's DROPOTHER)\nours = tuple(os.path.realpath(os.path.expanduser(d)) + os.sep for d in (\"~/openTPU\", \"~/otpu-build\"))\ngb = n = 0\nseen = set()\nfor d in sys.argv[3].split(\":\"):\n    for root, _, files in os.walk(os.path.expanduser(d)):\n        for f in files:\n            r = os.path.realpath(os.path.join(root, f))\n            if r in seen or not r.startswith(ours) or not os.path.isfile(r) \\\n                    or os.path.getsize(r) < 100 << 20 or r in keep or os.path.dirname(r) in keep:\n                continue\n            seen.add(r)\n            fd = os.open(r, os.O_RDONLY)\n            os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n            os.close(fd)\n            gb, n = gb + os.path.getsize(r) / 1e9, n + 1\nprint(f\"  dropped from the page cache: {n} other files of {gb:.1f} GB\")\nPY\n  local t0=$SECONDS; cat $O/$2 > /dev/null; echo \"  pool read in $((SECONDS - t0)) s, mem $(mem) GB\"\n}\n# 2. the production qual's chatmoe step, from T\necho \"=== chatmoe.sh $(date +%T)\"\nenv RUNS=\"qwen35-35b gemma4-26b\" SESSION=chatmoe R=$R/chatmoe timeout 3600 bash $T/tools/qual/chatmoe.sh \\\n  > $R/chatmoe.log 2>&1\necho \"  CHATMOE EXIT $? $(date +%T)\"\ngrep -E \"\\[(PASS|FAIL|SKIP)\\] [^ ]+ against|  turn [0-9]|    call: |Error|Traceback\" $R/chatmoe.log | cut -c1-260\n[ \"$(grep -c \"turns' tokens the same\" $R/chatmoe.log)\" = 2 ] && ! grep -q \"\\[FAIL\\]\" $R/chatmoe.log \\\n  || { echo \"STOP: chatmoe\"; fail=1; }\n# 3. otpu-chat by name, from T\nfor m in q g; do\n  [ $fail = 0 ] || break\n  read -r name md pool <<< \"${M[$m]}\"\n  echo \"=== otpu-chat $name $(date +%T)\"\n  warm $md $pool\n  (cd /tmp && timeout 1200 python -m opentpu.host.chat --backend board --model $name --greedy --max-new 24 \\\n     --prompt \"$T1\" > $R/chat-$name.txt 2>&1)\n  echo \"  CHAT $name EXIT $? $(date +%T)\"\n  python - $R/chat-$name.txt $PD/chat-$name.txt <<'PY' || { echo \"STOP: otpu-chat $name\"; fail=1; }\nimport sys\ndef part(f):\n    ln = [x for x in open(f).read().splitlines() if x.strip()]\n    reply = [x for x in ln if not x.startswith((\"loading \", \"experts:\", \"weights:\", \"loaded in\", \"[TTFT\"))]\n    return reply, [x for x in ln if x.startswith((\"loaded in\", \"[TTFT\"))]\n(a, sa), (b, sb) = part(sys.argv[1]), part(sys.argv[2])\nprint(f\"  [{'PASS' if a == b and a else 'FAIL'}] reply {a!r} {'=' if a == b else '!='} production's (mt4)\")\nfor x, y in zip(sa, sb):\n    print(f\"    {x[:200]}\\n    (mt4) {y[:200]}\")\nsys.exit(0 if a == b and a else 1)\nPY\ndone\n# 4. P (production's opentpu, T's tool) and N (T), per model: W, then ORDER\nfor m in q g; do\n  [ $fail = 0 ] || break\n  read -r name md pool <<< \"${M[$m]}\"\n  for x in W $ORDER; do\n    tree=$T; [ ${x:0:1} = P ] && tree=$PH          # (the opentpu it runs; the tool is T's)\n    extra=(); [ $x = W ] || extra+=(--trace $R/$m$x.trace.json)\n    echo \"=== $m$x $(date +%T) ($name, opentpu $(cat $tree/COMMIT)${extra[*]:+, ${extra[*]}})\"\n    warm $md $pool\n    busy\n    (cd $T && env PYTHONPATH=$tree PYTHONDONTWRITEBYTECODE=1 timeout 1500 python $T/tools/qual/chatmoe.py \\\n       $O/$md --pool $O/$pool --backend board --cfg $R/cfg-dev.pkl --turn \"$T1\" --turn \"$T2\" --turn \"$T3\" \\\n       \"${extra[@]}\" --out $R/$m$x.json > $R/$m$x.log 2>&1)\n    rc=$?; echo \"  exit $rc $(date +%T)\"; grep -E \"Error|Traceback\" $R/$m$x.log | tail -3\n    [ $rc = 0 ] && [ -f $R/$m$x.json ] || { echo \"STOP: $m$x\"; fail=1; break; }\n    python - $R/$m$x.json $R/${m}W.json $RF/chatmoe-$name.json <<'PY' || { echo \"STOP: $m$x differs\"; fail=1; break; }\nimport json, sys\nd, w, ref = (json.load(open(f)) for f in sys.argv[1:])\ntok = [t[\"tokens\"] for t in d[\"turns\"]]\nok_w = tok == [t[\"tokens\"] for t in w[\"turns\"]]\nok_r = tok[:2] == [t[\"tokens\"] for t in ref[\"turns\"][:2]]     # (the references: TURNS' two)\nprint(f\"  [{'PASS' if ok_w and ok_r else 'FAIL'}] tokens {'=' if ok_w else '!='} W's, first two turns \"\n      f\"{'=' if ok_r else '!='} the ISA reference's; layer-major {d['layer_major']}, em_rows \"\n      f\"{d.get('em_rows', '-')}, load {d['load_s']} s\")\nfor i, t in enumerate(d[\"turns\"]):\n    print(f\"  turn {i + 1}: prompt {t['prompt_tokens']} (reused {t['reused']}) TTFT {t['ttft_s']} s, prefill \"\n          f\"{t['prefill_tok_s']} tok/s (device {t['prefill_dev_tok_s']}), {t['prefill_misses']} misses; decode \"\n          f\"{t['gen_tokens']} at {t['decode_tok_s']} tok/s (device {t['decode_dev_tok_s']}); end {t['end']}\")\n    for c in t.get(\"calls\", []):\n        print(f\"    call {c['rows']} rows {'EM' if c['em'] else 'LM'}: {c['s']} s (device {c['device_s']}), \"\n              f\"{c['runs']} runs, misses {c['misses']} ({c['requests']} requests, served in {c['serve_s']} s), \"\n              f\"needs {c['needs_queued']} (hits {c['need_hits']}), parts {c['prefetched']} ({c['parts_s']} s), \"\n              f\"holds {c['holds']}\")\nsys.exit(0 if ok_w and ok_r else 1)\nPY\n  done\ndone\necho \"=== final selftest $(date +%T)\"\ntimeout 600 python -m opentpu.host.selftest 2>&1 | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"emdef4 end $(date +%T) fail $fail\"\npython - $R \"$ORDER\" <<'PY'\nimport json, os, sys\nr, order = sys.argv[1], sys.argv[2].split()\ndef get(run):\n    f = f\"{r}/{run}.json\"\n    return json.load(open(f)) if os.path.exists(f) else None\nfor name, m in ((\"35B\", \"q\"), (\"26B\", \"g\")):\n    a = {x: get(m + x) for x in order}\n    if None in a.values():\n        print(f\"  {name}: incomplete\"); continue\n    P, N = [x for x in order if x[0] == \"P\"], [x for x in order if x[0] == \"N\"]\n    pairs = [(n, \"P\" + n[1:]) for n in N if \"P\" + n[1:] in a]\n    for i in range(len(a[P[0]][\"turns\"])):\n        def v(x, k=\"ttft_s\"):\n            return a[x][\"turns\"][i][k] or 0.0\n        def dev(x):\n            t = a[x][\"turns\"][i]\n            return t[\"prompt_tokens\"] / t[\"prefill_dev_tok_s\"]\n        def mean(xs, f=v):\n            return sum(f(x) for x in xs) / len(xs)\n        def lm(x):          # the layer-major calls' host time a miss, ms\n            cs = [c for c in a[x][\"turns\"][i].get(\"calls\", []) if not c[\"em\"] and c[\"misses\"]]\n            m_ = sum(c[\"misses\"] for c in cs)\n            return f\"{1e3 * sum(c['serve_s'] for c in cs) / m_:.3f}\" if m_ else \"-\"\n        calls = \" + \".join(f\"{c['rows']}{'E' if c['em'] else 'L'}\" for c in a[N[0]][\"turns\"][i].get(\"calls\", []))\n        print(f\"  {name} turn {i + 1} ({a[P[0]]['turns'][i]['prompt_tokens']} tokens; N {calls}): TTFT N - P \"\n              + \" \".join(f\"{v(n) - v(p):+.3f}\" for n, p in pairs) + f\", of the means {mean(N) - mean(P):+.3f}; \"\n              f\"device N - P of the means {mean(N, dev) - mean(P, dev):+.3f}\")\n        print(\"      TTFT \" + \", \".join(f\"{x} {v(x):.3f}\" for x in order) + \"; device \"\n              + \", \".join(f\"{x} {dev(x):.3f}\" for x in order))\n        print(\"      layer-major calls' host ms a miss: \" + \", \".join(f\"{x} {lm(x)}\" for x in order))\nPY\ndate > $R/DONE\necho \"EMDEF4 EXIT $fail $(date +%T)\"\n", "tools/offload/sessions/emdefault.sh": "#!/bin/bash\n# Session emdef (docs/offload.md 13.15): the expert-major default on the card, before its host swap.\n# Trees: the candidate deploy's host, ~/otpu-build/deploy_em_91a9c2d3/host (T: main ee8f118d + pfB b6cfa9db + the\n# default e42f5eb2); production's host for the A arm, read-only, no bytecode written (PH: deploy_mt4_91a9c2d3/host,\n# main 23b68089). Card: production deploy_mt4_91a9c2d3 as loaded (EXPECT 91a9c2d3, register map 4). One otpu-lock:\n# 1. selftest (T); the device configuration must be production's qual/cfg.pkl;\n# 2. the production qual's chatmoe step from T: tools/qual/chatmoe.sh, RUNS=\"qwen35-35b gemma4-26b\" (two greedy turns\n#    each, the second continuing the context), token-exact against the ISA references (O/chatmoe-<model>.json);\n# 3. otpu-chat by name from T, one greedy answer each (qual_run.sh's), its reply against production's mt4 chat-<model>.txt;\n# 4. per model, production's host (P) against T (N): a discarded warm-up run (N), then P N N P, each a chatmoe.py chat of\n#    three turns: TURNS' two, then a long passage (lmtime's text and a question, about 150 tokens continuing the\n#    context). Every run's tokens must equal the warm-up's, and its first two turns the ISA references';\n# 5. selftest.\n# A build other than EXPECT, a failed selftest, another configuration, a FAIL, a failed or timed-out run or a mismatch\n# stops it (then the final selftest). About 30 min.\n# Run (no pipe): setsid nohup ~/.local/bin/otpu-lock --wait 600 -- bash $T/tools/offload/sessions/emdefault.sh\n#   > ~/otpu-build/moe-ab/emdef.launch.log 2>&1 < /dev/null &\nset -u\nfor v in $(env | grep -o '^OTPU_[A-Z0-9_]*' | grep -vE '^OTPU_LOCK_(HELD|PID|WAIT)$'); do unset $v; done\nexport OTPU_IMG_CACHE_GB=30 OTPU_IMG_CACHE_FREE_GB=6      # (the card host's, from its ~/.bashrc)\nMA=${MA:-$HOME/otpu-build/moe-ab}\nT=${T:-$HOME/otpu-build/deploy_em_91a9c2d3/host}\nPH=${PH:-$HOME/otpu-build/deploy_mt4_91a9c2d3/host}\nR=${R:-$MA/emdef}\nsource $T/tools/offload/sessions/env.sh       # (O: card2; OTPU_QUIET claimed, removed at exit)\nexec > >(tee -a $R/session.log) 2>&1\nEXPECT=${EXPECT:-91a9c2d3}\nPD=$HOME/otpu-build/deploy_mt4_91a9c2d3        # (production's qual/cfg.pkl and chat-<model>.txt)\nDROPOTHER=$HOME/openTPU/models:$O:$HOME/otpu-build/offload/g26it\nT1=\"What is the capital of France? Answer in one sentence.\"\nT2=\"And what is it famous for? Two sentences.\"\nT3=\"$(python -c 'import json, sys; print(json.load(open(sys.argv[1]))[\"prompt\"])' \\\n      $HOME/otpu-build/moepf/lmtime/q35w-hf.json) Summarize this passage in one sentence.\"\ndeclare -A M=([q]=\"qwen35-35b Qwen3.5-35B-A3B pool-q35-fp4.split.bin\"\n              [g]=\"gemma4-26b gemma-4-26B-A4B-it ../g26it/pool-g26it-fp4.split.bin\")\nfail=0\necho \"emdef start $(date +%T) T $T ($(cat $T/COMMIT)) PH $PH ($(cat $PH/COMMIT)) mem $(mem) GB, /home $(df -BG --output=avail /home | tail -1 | tr -d ' ') free; $(uptime)\"\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"build $EXPECT\" || { echo \"STOP: the card's build is not $EXPECT\"; exit 2; }\necho \"$st\" | grep -q \"register map 4\" || { echo \"STOP: not register map 4\"; exit 2; }\necho \"$st\" | grep -q \"ALL PASS\" || { echo \"STOP: selftest\"; exit 2; }\ntimeout 300 python tools/qual/refs.py cfg $R/cfg-dev.pkl > /dev/null 2>&1; echo \"cfg exit $?\"\npython - $R/cfg-dev.pkl $PD/qual/cfg.pkl <<'PY' || { echo \"STOP: the device configuration\"; exit 2; }\nimport dataclasses, pickle, sys\na, b = (pickle.load(open(f, \"rb\")) for f in sys.argv[1:])\nd = {f.name: (getattr(a, f.name), getattr(b, f.name)) for f in dataclasses.fields(a)\n     if getattr(a, f.name) != getattr(b, f.name)}\nprint(\"  cfg: production's (qual/cfg.pkl)\" if not d else f\"  cfg DIFFERS from production's: {d}\")\nsys.exit(1 if d else 0)\nPY\nwarm() {   # checkpoint, pool (in O): every other big file out of the page cache, the pool read into it\n  python - $O/$1 $O/$2 $DROPOTHER <<'PY'\nimport os, sys                      # every other file of 100 MB or more out of the page cache\nkeep = {os.path.realpath(sys.argv[1]), os.path.realpath(sys.argv[2])}  # (card_moe.sh's DROPOTHER)\nours = tuple(os.path.realpath(os.path.expanduser(d)) + os.sep for d in (\"~/openTPU\", \"~/otpu-build\"))\ngb = n = 0\nseen = set()\nfor d in sys.argv[3].split(\":\"):\n    for root, _, files in os.walk(os.path.expanduser(d)):\n        for f in files:\n            r = os.path.realpath(os.path.join(root, f))\n            if r in seen or not r.startswith(ours) or not os.path.isfile(r) \\\n                    or os.path.getsize(r) < 100 << 20 or r in keep or os.path.dirname(r) in keep:\n                continue\n            seen.add(r)\n            fd = os.open(r, os.O_RDONLY)\n            os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n            os.close(fd)\n            gb, n = gb + os.path.getsize(r) / 1e9, n + 1\nprint(f\"  dropped from the page cache: {n} other files of {gb:.1f} GB\")\nPY\n  local t0=$SECONDS; cat $O/$2 > /dev/null; echo \"  pool read in $((SECONDS - t0)) s, mem $(mem) GB\"\n}\n# 2. the production qual's chatmoe step, from T\necho \"=== chatmoe.sh $(date +%T)\"\nenv RUNS=\"qwen35-35b gemma4-26b\" SESSION=chatmoe R=$R/chatmoe timeout 3600 bash $T/tools/qual/chatmoe.sh \\\n  > $R/chatmoe.log 2>&1\necho \"  CHATMOE EXIT $? $(date +%T)\"\ngrep -E \"\\[(PASS|FAIL|SKIP)\\] [^ ]+ against|  turn [0-9]|Error|Traceback\" $R/chatmoe.log | cut -c1-260\n[ \"$(grep -c \"turns' tokens the same\" $R/chatmoe.log)\" = 2 ] && ! grep -q \"\\[FAIL\\]\" $R/chatmoe.log \\\n  || { echo \"STOP: chatmoe\"; fail=1; }\n# 3. otpu-chat by name, from T\nfor m in q g; do\n  [ $fail = 0 ] || break\n  read -r name md pool <<< \"${M[$m]}\"\n  echo \"=== otpu-chat $name $(date +%T)\"\n  warm $md $pool\n  (cd /tmp && timeout 1200 python -m opentpu.host.chat --backend board --model $name --greedy --max-new 24 \\\n     --prompt \"$T1\" > $R/chat-$name.txt 2>&1)\n  echo \"  CHAT $name EXIT $? $(date +%T)\"\n  python - $R/chat-$name.txt $PD/chat-$name.txt <<'PY' || { echo \"STOP: otpu-chat $name\"; fail=1; }\nimport sys\ndef part(f):\n    ln = [x for x in open(f).read().splitlines() if x.strip()]\n    reply = [x for x in ln if not x.startswith((\"loading \", \"experts:\", \"weights:\", \"loaded in\", \"[TTFT\"))]\n    return reply, [x for x in ln if x.startswith((\"loaded in\", \"[TTFT\"))]\n(a, sa), (b, sb) = part(sys.argv[1]), part(sys.argv[2])\nprint(f\"  [{'PASS' if a == b and a else 'FAIL'}] reply {a!r} {'=' if a == b else '!='} production's (mt4)\")\nfor x, y in zip(sa, sb):\n    print(f\"    {x[:200]}\\n    (mt4) {y[:200]}\")\nsys.exit(0 if a == b and a else 1)\nPY\ndone\n# 4. production's host (P) against T (N), per model: W, then P N N P\nfor m in q g; do\n  [ $fail = 0 ] || break\n  read -r name md pool <<< \"${M[$m]}\"\n  for x in W P1 N1 N2 P2; do\n    tree=$T; [ ${x:0:1} = P ] && tree=$PH\n    echo \"=== $m$x $(date +%T) ($name, host $(cat $tree/COMMIT))\"\n    warm $md $pool\n    (cd $tree && env PYTHONPATH=$tree PYTHONDONTWRITEBYTECODE=1 timeout 1200 python tools/qual/chatmoe.py \\\n       $O/$md --pool $O/$pool --backend board --cfg $R/cfg-dev.pkl --turn \"$T1\" --turn \"$T2\" --turn \"$T3\" \\\n       --out $R/$m$x.json > $R/$m$x.log 2>&1)\n    rc=$?; echo \"  exit $rc $(date +%T)\"; grep -E \"Error|Traceback\" $R/$m$x.log | tail -3\n    [ $rc = 0 ] && [ -f $R/$m$x.json ] || { echo \"STOP: $m$x\"; fail=1; break; }\n    python - $R/$m$x.json $R/${m}W.json $RF/chatmoe-$name.json <<'PY' || { echo \"STOP: $m$x differs\"; fail=1; break; }\nimport json, sys\nd, w, ref = (json.load(open(f)) for f in sys.argv[1:])\ntok = [t[\"tokens\"] for t in d[\"turns\"]]\nok_w = tok == [t[\"tokens\"] for t in w[\"turns\"]]\nok_r = tok[:2] == [t[\"tokens\"] for t in ref[\"turns\"]]\nprint(f\"  [{'PASS' if ok_w and ok_r else 'FAIL'}] tokens {'=' if ok_w else '!='} W's, first two turns \"\n      f\"{'=' if ok_r else '!='} the ISA reference's; layer-major {d['layer_major']}, load {d['load_s']} s\")\nfor i, t in enumerate(d[\"turns\"]):\n    print(f\"  turn {i + 1}: prompt {t['prompt_tokens']} (reused {t['reused']}) TTFT {t['ttft_s']} s, prefill \"\n          f\"{t['prefill_tok_s']} tok/s (device {t['prefill_dev_tok_s']}), {t['prefill_misses']} misses; decode \"\n          f\"{t['gen_tokens']} at {t['decode_tok_s']} tok/s (device {t['decode_dev_tok_s']}); end {t['end']}\")\nsys.exit(0 if ok_w and ok_r else 1)\nPY\n  done\ndone\necho \"=== final selftest $(date +%T)\"\ntimeout 600 python -m opentpu.host.selftest 2>&1 | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"emdef end $(date +%T) fail $fail\"\npython - $R <<'PY'\nimport json, os, sys\nr = sys.argv[1]\ndef get(run):\n    f = f\"{r}/{run}.json\"\n    return json.load(open(f)) if os.path.exists(f) else None\nfor name, m in ((\"35B\", \"q\"), (\"26B\", \"g\")):\n    p1, n1, n2, p2 = (get(m + x) for x in (\"P1\", \"N1\", \"N2\", \"P2\"))\n    if None in (p1, n1, n2, p2):\n        print(f\"  {name}: incomplete\"); continue\n    for i in range(len(p1[\"turns\"])):\n        for key in (\"ttft_s\", \"decode_tok_s\", \"prefill_dev_tok_s\"):\n            v = lambda c: c[\"turns\"][i][key] or 0.0     # noqa: E731\n            d1, d2 = v(n1) - v(p1), v(n2) - v(p2)\n            mp, mn = (v(p1) + v(p2)) / 2, (v(n1) + v(n2)) / 2\n            print(f\"  {name} turn {i + 1} ({p1['turns'][i]['prompt_tokens']} tokens) {key}: P {v(p1):.3f} {v(p2):.3f}, \"\n                  f\"N {v(n1):.3f} {v(n2):.3f}; pairs N-P {d1:+.3f} {d2:+.3f}; mean N-P {mn - mp:+.3f}\")\nPY\ndate > $R/DONE\necho \"EMDEF EXIT $fail $(date +%T)\"\n", "tools/offload/sessions/emprol.sh": "#!/bin/bash\n# Session emprol (docs/tiled_prefill.md 14.3): em-prologue's card A/B. A tile's MoE prologue takes its rows at once and\n# posts its need lines between the shared expert's passes (each post waits for the host to serve the one before: the\n# co-simulation serves at once, so what the host's poll costs is the card's to show), and a tiled MoE image's DeltaNet\n# rows run a tile's at a time where MCOLS takes them. Co-simulated (T = 8, position 256): MiniCPM-V's mixer -6.3% a row\n# on m4 (-1.15 s of the 488-row image prompt), -13.3% on m8 (-2.25 s); qwen35-35b's -2.2% / -7.1%.\n# Arms: A = the release's host (A, default the r2.1 deploy's host: batch3), B = em-prologue's (B), each its own\n# opentpu on PYTHONPATH and its own tools/qual/chatmoe.py, read only (no bytecode written). Card: production as\n# loaded (EXPECT, MAP), the configuration of REFCFG. Models and prompts (chatmoe.py, --pool-calls):\n#   mcpv  MiniCPM-V 4.7: doc.png at 9 slices, one turn of 32 tokens (the image request: 488 prompt rows)\n#   q35   qwen35-35b: a ~260-token text prompt (the em-tile references' q35turn), 16 tokens\n# Per model: the pool into the page cache (every other file of 100 MB or more out of it), a warm-up run in each arm\n# (WA, WB: each tree's images and programs built and cached, discarded; WA's tokens the reference), then ORDER (default\n# A1 B1 B2 A2; ORDER=\"A1 B1 B2 A2 B3 A3 A4 B4\" for more pairs). Every run's tokens must equal WA's (the same bits).\n# Summary per model: each run's TTFT, prefill and device seconds, B - A per pair and of the means, the expert-major\n# call's runs and its host time. The rule (the lead's): B no worse than A on either model, token-exact.\n# A build other than EXPECT, a failed selftest, another configuration, a missing file, a failed run or a token\n# mismatch stops it (then the final selftest). About 45 min (the warm-ups ~10 min each model with first builds).\n# Stage (from the Mac): B's tree (git archive of em-prologue's commit) to ~/otpu-build/emprol/host with COMMIT;\n#   A defaults to the r2.1 deploy's host (its COMMIT is printed). Run (no pipe; the lead's GO), e.g.:\n#   EXPECT=039b34d5 A=$HOME/otpu-build/production/host \\\n#   REFCFG=$HOME/otpu-build/production/refcache/configs/cfg_E3.pkl setsid -f ~/.local/bin/otpu-lock --wait 3600 -- \\\n#     bash ~/otpu-build/emprol/host/tools/offload/sessions/emprol.sh > ~/otpu-build/emprol/session.log 2>&1 < /dev/null\n# (No apostrophe inside a ${...:?...} / ${...:-...} word: bash takes it as an open quote, to the next one.)\nset -u\n[ -n \"${OTPU_LOCK_HELD:-}\" ] || { echo \"run under otpu-lock\"; exit 1; }\nfor v in $(env | grep -o '^OTPU_[A-Z0-9_]*' | grep -vE '^OTPU_LOCK_(HELD|PID|WAIT)$'); do unset $v; done\nexport OTPU_IMG_CACHE_GB=30 OTPU_IMG_CACHE_FREE_GB=6      # (the card host's, from its ~/.bashrc)\nE=${E:-$HOME/otpu-build/emprol}\nA=${A:-$HOME/otpu-build/deploy_rel21_039b34d5/host}\nB=${B:-$E/host}\nEXPECT=${EXPECT:?the card build to expect, e.g. 039b34d5}\nMAP=${MAP:-register map 5}\nREFCFG=${REFCFG:?the configuration the arms run on, e.g. the deploy refcache/configs/cfg_E3.pkl}\nORDER=${ORDER:-A1 B1 B2 A2}\nP=$HOME/otpu-venv/bin/python\nMO=/data/otpu/minicpmv; C2=$HOME/otpu-build/offload/card2\nPYLIB=${PYLIB:-$MO/pylib}                       # (MiniCPM-V's tower: torchvision, pillow, transformers)\nR=$E/run-$(date +%m%d-%H%M); mkdir -p $R\nexec > >(tee -a $R/session.log) 2>&1\nQ=$HOME/otpu-build/QUIET          # the whole session is quiet: no prebuilds or OOC jobs on the host\nq=$(cat $Q 2>/dev/null); if [ -z \"$q\" ] || ! kill -0 \"$q\" 2>/dev/null; then echo $$ > $Q; trap '[ \"$(cat $Q 2>/dev/null)\" = $$ ] && rm -f $Q' EXIT; fi\nmem() { awk '/MemAvailable/ {print int($2/1048576)}' /proc/meminfo; }\ndeclare -A MD=([mcpv]=\"$MO/MiniCPM-V-4.7-35B-A3B $MO/pool-mcpv35-mx.split.bin\"\n               [q35]=\"$C2/Qwen3.5-35B-A3B $C2/pool-q35-mx.split.bin\")\ncat > $R/q35turn.txt <<'TXT'\nSummarize the following text in two sentences.\n\nThe printing press with movable type changed how knowledge travelled across Europe. Before it, books were copied by hand, a slow and costly process that kept most texts in the libraries of monasteries, universities and wealthy families. A single scribe might spend months on one volume, and every copy could introduce new errors. Around 1450, Johannes Gutenberg combined several existing technologies into a practical system: metal type cast in a hand mould, an oil-based ink that stuck to metal, and a screw press adapted from those used to make wine and paper. Within fifty years, presses were running in more than two hundred cities, and millions of books had been printed. Prices fell, literacy spread beyond the clergy and the nobility, and scholars in distant cities could work from identical texts, which made it easier to compare results and correct mistakes. Pamphlets and broadsheets carried news and arguments quickly, and the Reformation, the scientific revolution and the growth of national languages all drew on this new capacity to reproduce words cheaply and accurately. At the same time, authorities worried about what could now be spread so easily, and many states introduced licences and censorship to control the presses.\nTXT\ndeclare -A ARGS=([mcpv]=\"--image 1:$MO/img/doc.png --turn 'What does this document say? Two sentences.' --max-new 32\"\n                 [q35]=\"--turn \\\"\\$(cat $R/q35turn.txt)\\\" --max-new 16\")\nfail=0\necho \"emprol start $(date +%T): A $A ($(cat $A/COMMIT 2>/dev/null)), B $B ($(cat $B/COMMIT 2>/dev/null)); mem $(mem) GB; $(uptime)\"\ngrep -q \"def need_rows\" $B/opentpu/llm/moe.py && grep -q \"each=None\" $B/opentpu/kernels/mlp.py \\\n  || { echo \"STOP: B is not em-prologue's tree (moe.need_rows, swiglu_down(each=))\"; exit 2; }\n! grep -q \"def need_rows\" $A/opentpu/llm/moe.py || { echo \"STOP: A already has em-prologue\"; exit 2; }\nfor m in mcpv q35; do\n  read -r md pool <<< \"${MD[$m]}\"\n  [ -f $md/config.json ] && [ -f $pool ] && [ -f $pool.key ] || { echo \"STOP: $md or $pool missing\"; exit 2; }\ndone\n[ -f $MO/img/doc.png ] && [ -f $REFCFG ] || { echo \"STOP: $MO/img/doc.png or $REFCFG missing\"; exit 2; }\nfor t in $A $B; do\n  echo \"  $t: $(cd /tmp && PYTHONPATH=$t PYTHONDONTWRITEBYTECODE=1 $P -c 'import opentpu, opentpu.progcache as p; print(opentpu.__file__, p.source())')\"\ndone\nst=$(cd /tmp && PYTHONPATH=$A timeout 600 $P -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"build $EXPECT\" || { echo \"STOP: the card's build is not $EXPECT\"; exit 2; }\necho \"$st\" | grep -q \"$MAP\" || { echo \"STOP: not $MAP\"; exit 2; }\necho \"$st\" | grep -q \"ALL PASS\" || { echo \"STOP: selftest\"; exit 2; }\n(cd $A && PYTHONPATH=$A PYTHONDONTWRITEBYTECODE=1 timeout 300 $P tools/qual/refs.py cfg $R/cfg-dev.pkl > /dev/null 2>&1)\n$P - $R/cfg-dev.pkl $REFCFG <<'PY' || { echo \"STOP: the device configuration is not REFCFG's\"; exit 2; }\nimport dataclasses, pickle, sys\na, b = (pickle.load(open(f, \"rb\")) for f in sys.argv[1:])\nd = {f.name: (getattr(a, f.name), getattr(b, f.name)) for f in dataclasses.fields(a)\n     if getattr(a, f.name) != getattr(b, f.name)}\nprint(\"  cfg: REFCFG's\" if not d else f\"  cfg DIFFERS (device, REFCFG): {d}\")\nsys.exit(1 if d else 0)\nPY\nwarm() {      # $1 checkpoint, $2 pool: every other file of 100 MB or more out of the page cache, the pool into it\n  $P - $1 $2 $MO:$C2:$HOME/openTPU/models:$HOME/otpu-build/offload <<'PY'\nimport os, sys\nkeep = {os.path.realpath(sys.argv[1]), os.path.realpath(sys.argv[2])}\nours = tuple(os.path.realpath(os.path.expanduser(d)) + os.sep\n             for d in (\"~/openTPU\", \"~/otpu-build\", \"/data/otpu\"))\ngb = n = 0\nseen = set()\nfor d in sys.argv[3].split(\":\"):\n    for root, _, files in os.walk(d):\n        for f in files:\n            r = os.path.realpath(os.path.join(root, f))\n            if r in seen or not r.startswith(ours) or not os.path.isfile(r) or \\\n                    os.path.getsize(r) < 100 << 20 or r in keep or os.path.dirname(r) in keep:\n                seen.add(r)\n                continue\n            seen.add(r)\n            fd = os.open(r, os.O_RDONLY)\n            os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n            os.close(fd)\n            gb, n = gb + os.path.getsize(r) / 1e9, n + 1\nprint(f\"  dropped from the page cache: {n} other files of {gb:.1f} GB\")\nPY\n  local t0=$SECONDS\n  dd if=$2 of=/dev/null bs=16M status=none\n  echo \"  (pool read in $((SECONDS - t0)) s, mem $(mem) GB)\"\n}\nrun() {       # $1 model, $2 run name (WA, WB, A1, B2, ...): its arm's tree and chatmoe.py; WA's tokens the reference\n  local m=$1 n=$2 t; read -r md pool <<< \"${MD[$m]}\"\n  case $n in WA|A*) t=$A ;; *) t=$B ;; esac\n  case $n in WA) chk=\"\" ;; *) chk=\"--check $R/$m-WA.json\" ;; esac\n  eval \"(cd $t && env PYTHONPATH=$t:$PYLIB PYTHONDONTWRITEBYTECODE=1 timeout 3600 $P tools/qual/chatmoe.py $md \\\n    --pool $pool --backend board --cfg $R/cfg-dev.pkl --pool-calls $chk --out $R/$m-$n.json ${ARGS[$m]})\" \\\n    > $R/$m-$n.log 2>&1\n  local rc=$?\n  echo \"  $m $n ($t) exit $rc $(date +%T); $(grep -E \"\\[(PASS|FAIL)\\]|Error|Traceback\" $R/$m-$n.log | tail -2 | cut -c1-200)\"\n  [ $rc = 0 ] && { [ $n = WA ] || grep -q \"\\[PASS\\]\" $R/$m-$n.log; } || { echo \"STOP: $m $n\"; fail=1; }\n}\nfor m in mcpv q35; do\n  [ $fail = 0 ] || break\n  read -r md pool <<< \"${MD[$m]}\"\n  echo \"=== $m $(date +%T)\"\n  warm $md $pool\n  for n in WA WB $ORDER; do\n    [ $fail = 0 ] || break\n    run $m $n\n  done\ndone\necho \"=== summary $(date +%T)\"\n$P - $R \"$ORDER\" <<'PY'\nimport json, sys\nfrom pathlib import Path\nR, order = Path(sys.argv[1]), sys.argv[2].split()\nfor m in (\"mcpv\", \"q35\"):\n    rows = {}\n    for n in order:\n        f = R / f\"{m}-{n}.json\"\n        if not f.exists():\n            continue\n        t = json.load(open(f))[\"turns\"][0]\n        dev = t[\"prompt_tokens\"] / t[\"prefill_dev_tok_s\"] if t.get(\"prefill_dev_tok_s\") else None\n        rows[n] = (t[\"ttft_s\"], t[\"prefill_s\"], dev, t.get(\"calls\"))\n        print(f\"  {m} {n}: TTFT {t['ttft_s']} s, prefill {t['prefill_s']} s ({t['prompt_tokens']} tokens), device \"\n              f\"{dev and round(dev, 2)} s, decode {t['decode_tok_s']} tok/s\")\n    pairs = sorted({n[1:] for n in rows})\n    d = [(rows[\"B\" + k][0] - rows[\"A\" + k][0], rows[\"B\" + k][1] - rows[\"A\" + k][1])\n         for k in pairs if \"A\" + k in rows and \"B\" + k in rows]\n    for k, (dt, dp) in zip(pairs, d):\n        print(f\"  {m} pair {k}: B - A TTFT {dt:+.2f} s, prefill {dp:+.2f} s\")\n    if d:\n        print(f\"  {m} mean B - A: TTFT {sum(x for x, _ in d) / len(d):+.2f} s, prefill \"\n              f\"{sum(y for _, y in d) / len(d):+.2f} s over {len(d)} pairs \"\n              f\"({'B no worse' if all(x <= 0.05 for x, _ in d) else 'B WORSE in a pair'})\")\nPY\nst=$(cd /tmp && PYTHONPATH=$A timeout 600 $P -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"ALL|stopped|FAIL\" | tail -3\necho \"EMPROL SESSION END $(date +%T) fail=$fail\"\n", "tools/offload/sessions/env.sh": "# Sourced by the card session scripts beside it (docs/offload.md 10, 11.5). Each path can be set\n# from outside:\n#   T           the openTPU checkout a session runs (default: the one holding this file; a\n#               session's own tree is named in its header: git worktree add DIR SHA, then T=DIR)\n#   O           the session directory: the checkpoints (or links to them), the pools, the HF\n#               references (hf_reference.sh), the ISA simulator's (reference.sh) and the card's\n#               configuration they were made with (REFCFG)\n#   R           where the runs write: O/SESSION (a session script's SESSION, e.g. s8), or O\n#   RF          the ISA simulator's references (default O): a tree's own, its programs' sums\n#   OTPU_VENV   the Python environment (default ~/otpu-venv)\n#   OTPU_QUIET  the host's quiet file (docs/host.md 8): no prebuild on the host while a session\n#               runs; an outer script's claim stays\nhere=$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\nT=${T:-$(cd \"$here/../../..\" && pwd)}\nO=${O:-$HOME/otpu-build/offload/card2}\nR=${R:-$O${SESSION:+/$SESSION}}\nRF=${RF:-$O}\nREFCFG=${REFCFG:-$O/cfg-c2830d6a.pkl}\nOTPU_QUIET=${OTPU_QUIET:-$HOME/otpu-build/QUIET}\nexport T O R RF REFCFG OTPU_QUIET PATH=${OTPU_VENV:-$HOME/otpu-venv}/bin:$PATH PYTHONPATH=$T\nmkdir -p \"$R\"\nq=$(cat \"$OTPU_QUIET\" 2>/dev/null)\n[ -n \"$q\" ] && kill -0 \"$q\" 2>/dev/null || echo $$ > \"$OTPU_QUIET\"\ntrap '[ \"$(cat \"$OTPU_QUIET\" 2>/dev/null)\" = $$ ] && rm -f \"$OTPU_QUIET\"' EXIT\ncd \"$T\" || exit 1\nrev=$(cat COMMIT 2>/dev/null || git rev-parse --short HEAD)\nmem() { awk '/MemAvailable/ {print int($2/1048576)}' /proc/meminfo; }\n", "tools/offload/sessions/g2check.sh": "#!/bin/bash\n# offload: the Gen2 x8 check (docs/offload.md 10.9) on production g2fix 0885d436, no reload:\n# session 13 tree (b40fc6f, d29bfe9 programs, refs-d29bfe9), q35e128s x2 then g26s, with traces.\n# About 6 min (2026-10-02 00:31-00:37; results: docs/offload.md 10.9). It stops at a mismatch,\n# a timeout or an error.\n# Run: otpu-lock --wait 3600 -- tools/offload/sessions/g2check.sh   (log: O/g2c/session.log)\nset -u\nSESSION=${SESSION:-g2c}; RF=${RF:-${O:-$HOME/otpu-build/offload/card2}/refs-d29bfe9}\nsource \"$(dirname \"$0\")/env.sh\"\nexec > >(tee -a $R/session.log) 2>&1\necho \"g2check start $(date +%T) tree $rev mem $(mem) GB\"\nbad() { sleep 1; grep -c -E \"\\[FAIL\\]|exit 124|Traceback|STOP\" $R/session.log; }\nb0=$(bad)\nstop() { [ $(bad) -gt $b0 ] && { echo \"STOP $(date +%T): a mismatch, a timeout or an error\"; return 0; }; return 1; }\nrun() { echo \"--- $1: $2\"; env T=$T RF=$RF R=$R/$1 RUNS=\"$2\" bash \"$here/card_moe.sh\"; }\nfor x in \"N1 q35e128s\" \"N2 q35e128s\" \"gN1 g26s\"; do\n  run $x\n  stop && break\ndone\necho \"g2check end $(date +%T)\"\npython - $R <<'PY'\nimport glob, json, sys\nr = sys.argv[1]\nfor f in sorted(glob.glob(f\"{r}/*/*.json\")):\n    if \".trace.\" in f:\n        continue\n    c = json.load(open(f))\n    h, d = c.get(\"host_decode_s\") or {}, c.get(\"device_counters\") or {}\n    g = {k: round(d.get(k, 0) / 1e9, 3) for k in (\"RUNNING\", \"MXU_STARVE\", \"DMA_BUSY\", \"DRAM_WAIT\")}\n    print(f\"  {f[len(r) + 1:]}: tok/s {c['tok_s_wall']} (device {c['tok_s_device']}), poll \"\n          f\"{h.get('poll')}, dma {h.get('dma_s')} ({h.get('dma_gbs')} GB/s), polls \"\n          f\"{h.get('polls_reads')}, G {g}, match {c.get('match')} sha {c.get('prefill_logits_sha')}\")\nPY\ndate > $R/DONE\n", "tools/offload/sessions/gen2.sh": "#!/bin/bash\n# offload: Qwen3.5-35B-A3B's streaming on a PCIe Gen2 image (ld-memch's session, the image as\n# loaded: no reload; docs/offload.md 6). slot_bench (the 35B's split pool warm: ms an expert,\n# the DMA thread's GB/s), then session 7's runs in its order: 128 tokens, decayed use, slots\n# filling the DRAM, the first 16 tokens against q35ref16: q35e128a/b (the embedding table on the\n# host, 42 slots a layer) and q35c128a/b (on the card, 34), against session 7's Gen1 (O/s7).\n# Needs a tree at or after main 2a0b962 (the DMA guard). About 10 min.\n# Run: otpu-lock --wait 10800 -- tools/offload/sessions/gen2.sh   (log: O/gen2/session.log)\nset -u\nSESSION=gen2; source \"$(dirname \"$0\")/env.sh\"\nexec > >(tee -a $R/session.log) 2>&1\necho \"gen2 start $(date +%T) tree $rev mem $(mem) GB\"\necho \"--- card: the 35B's split pool, warm\"\ntimeout 600 python tools/offload/slot_bench.py --reqs 40 --sizes q35 --pool $O/pool-q35-fp4.split.bin --warm 2>&1 | tail -1\nRUNS=\"${RUNS:-q35e128a q35c128a q35e128b q35c128b}\" bash \"$here/card_moe.sh\"\necho \"gen2 end $(date +%T)\"\ndate > $R/DONE\n", "tools/offload/sessions/hf_reference.sh": "#!/bin/bash\n# Hugging Face's greedy tokens for card runs (bf16 on the CPU, moe_card --hf): the prompt and the\n# 8 best logits a step, on a host with the whole checkpoint (the 26B's: omarchy, 8 GiB of weights\n# in RAM and the rest from disk). A checkpoint without a chat template takes the prompt as plain\n# text (the 26B's download is the base model).\n#   hf_reference.sh MODEL OUT.json N [PROMPT_FILE]    (MODEL a checkpoint directory; OUT in O;\n#   no PROMPT_FILE: moe_card's question, as the 35B's and LFM2.5's references)\n# e.g. session 8's: hf_reference.sh ~/openTPU/models/gemma-4-26B-A4B q26-hf.json 16 \\\n#   tools/offload/sessions/wiki1.txt   (the first paragraph of the router traces' wiki text)\n# MAXMEM of weights in RAM (default 8GiB), under a MEMMAX memory limit (default 12G) at nice 19; killed, not frozen, on two 15 s samples\n# under MEMFLOOR GB of MemAvailable (default 6) or DISKFLOOR GB free (default 41); the\n# accelerate offload folder removed after.\nset -u\nhere=$(cd \"$(dirname \"$0\")\" && pwd)\nT=${T:-$(cd \"$here/../../..\" && pwd)}; O=${O:-$HOME/otpu-build/offload/card2}\nmodel=$1 out=$2 n=$3 prompt=${4:-}\ncd \"$T\" || exit 1\nexport PATH=${OTPU_VENV:-$HOME/otpu-venv}/bin:$PATH PYTHONPATH=$T OMP_NUM_THREADS=4 MKL_NUM_THREADS=4\nmem() { awk '/MemAvailable/ {print int($2/1048576)}' /proc/meminfo; }\ndisk() { df -BG --output=avail ~ | tail -1 | tr -dc 0-9; }\necho \"hf_reference start $(date +%T) mem $(mem) GB disk $(disk) GB\"\nlim=()\ncommand -v systemd-run > /dev/null && lim=(systemd-run --user --scope -p MemoryMax=${MEMMAX:-12G} -p MemorySwapMax=0 --quiet)\n\"${lim[@]}\" nice -n 19 python tools/offload/moe_card.py $model --hf $O/$out -n $n \\\n  --max-memory ${MAXMEM:-8GiB} ${prompt:+--prompt \"$(cat $prompt)\"} &\npid=$!; low=0\nwhile kill -0 $pid 2>/dev/null; do\n  m=$(mem); d=$(disk)\n  if [ \"$m\" -lt ${MEMFLOOR:-6} ] || [ \"$d\" -lt ${DISKFLOOR:-41} ]; then low=$((low+1)); else low=0; fi\n  if [ $low -ge 2 ]; then pkill -P $pid; kill $pid; echo \"KILLED $(date +%T) mem $m GB disk $d GB\"; break; fi\n  sleep 15\ndone\nwait $pid; echo \"hf_reference exit $? $(date +%T)\"\nrm -rf \"$(dirname $model)/.offload-moe-card\"\n", "tools/offload/sessions/hostr21.sh": "#!/bin/bash\n# Session hostr21: the host release batch host-r21 (MiniCPM-V, the pool's warm gate, S = the shared expert beside the\n# request, chatmoe's pool residency, qual.sh's ECC_EACH) qualified on production's bitstream b10245f5 as loaded (no JTAG\n# load, LOAD=0; production stays on the card), under ONE otpu-lock. Its deploy directory D\n# (~/otpu-build/deploy_hostr21_b10245f5): otpu.bit -> production's, host/ (this tree, COMMIT, models -> ~/openTPU/models),\n# refcache/ (tools/qual/refs.py's references for this tree's keys, computed on hwe-bench on production's configuration,\n# configs/deploy_hostr21_b10245f5.pkl), chatmoe/ (the streamed MoE models' references: qwen35-35b recomputed on this\n# tree, lfm2-8b and gemma4-26b production's, whose programs S does not change).\n# PART (env): A = qual.sh fast (ECC_EACH=1) + E2B-it + otpu-chat on eight models against production's replies;\n#             B = chatmoe.sh (lfm2-8b qwen35-35b gemma4-26b, POOL_CALLS=1) + the warm gate on otpu-serve (qwen35-35b);\n#             C = MiniCPM-V (mcpv3.sh RUNS=\"warmup sliced thumb text\", POOL_CALLS=1, its references in /data);\n#             all (default) = A, B, C. Selftest first (build b10245f5, register map 5, MCOLS 4 at 133.333 MHz: else\n#             no session), an ECC check after each part and at the end, scrub, selftest.\n# The warm gate (PART B): qwen35-35b's pool (production's file, read only) dropped from the page cache, otpu-serve\n#   opened on it: /health polled every 2 s (each change of answer logged: 503 \"warming\" with its progress, then 200),\n#   the server's \"pool warm:\" lines, serve_bench's check part through the warming 503 (wait_up); then the pool read\n#   back into the page cache. PASS: a 503 \"warming\" seen, then 200 within the cap, \"pool warm: done\", serve_bench's\n#   check passed.\n# Every line that says FAIL, NOT CLEAN or EXIT <non-zero> is the lead's to read; the last line: HOSTR21 SESSION END.\n# About 2.5 h (A ~70 min with the images' first builds for this tree, B ~45, C ~40).\n# Stage (from the Mac): see the deploy directory's README. Run (no pipe; the lead's GO):\n#   setsid -f ~/.local/bin/otpu-lock --wait 3600 -- bash ~/otpu-build/deploy_hostr21_b10245f5/host/tools/offload/\\\n#     sessions/hostr21.sh > ~/otpu-build/deploy_hostr21_b10245f5/session.log 2>&1 < /dev/null\nset -u\nPART=${PART:-all}\nD=${D:-$HOME/otpu-build/deploy_hostr21_b10245f5}; H=$D/host\nP=$HOME/otpu-venv/bin/python; RC=$D/refcache\nPD=${PD:-$HOME/otpu-build/deploy_r2m4_b10245f5}        # production (its chat-*.txt, qual/cfg.pkl)\nC2=$HOME/otpu-build/offload/card2\n[ -n \"${OTPU_LOCK_HELD:-}\" ] || { echo \"run under otpu-lock\"; exit 1; }\nfor v in $(env | grep -o '^OTPU_[A-Z0-9_]*' | grep -vE '^OTPU_LOCK_(HELD|PID|WAIT)$'); do unset $v; done\nexport OTPU_IMG_CACHE_GB=30 OTPU_IMG_CACHE_FREE_GB=6      # (the card host's, from its ~/.bashrc)\nQ=$HOME/otpu-build/QUIET          # the whole session is quiet: no prebuilds or OOC jobs on the host\nq=$(cat $Q 2>/dev/null); if [ -z \"$q\" ] || ! kill -0 \"$q\" 2>/dev/null; then echo $$ > $Q; trap '[ \"$(cat $Q 2>/dev/null)\" = $$ ] && rm -f $Q' EXIT; fi\ncs() { echo \"  img cache $(du -sm $HOME/otpu-build/qcache/img 2>/dev/null | cut -f1) MB, disk $(df -BG --output=avail /home | tail -1 | tr -d ' ') free, mem $(awk '/MemAvailable/ {print int($2/1048576)}' /proc/meminfo) GB\"; }\necc() {   # $1 = label: selftest's ECC counts since the last scrub; any error = NOT CLEAN\n  echo \"=== ECC check: $1 $(date +%T)\"; cd /tmp && env PYTHONPATH=$H timeout 900 $P -m opentpu.host.selftest > $D/selftest_ecc_$1.log 2>&1\n  grep -qE \"\\[PASS\\] ecc .*channel 0: 0 corrected, 0 uncorrectable, channel 1: 0 corrected, 0 uncorrectable\" $D/selftest_ecc_$1.log \\\n    && echo \"ECC CLEAN ($1)\" || echo \"ECC NOT CLEAN ($1): $(grep -E \" ecc \" $D/selftest_ecc_$1.log | cut -c1-200)\"\n}\ntree() { local x; for x in \"$@\"; do echo $x; tree $(pgrep -P $x); done; }    # these PIDs and all under them\nlive() { local x; for x in \"$@\"; do kill -0 $x 2> /dev/null && echo $x; done; }  # those of them alive\nstop_tree() {   # $1: a background job's PID, timeout's (exec'd), the leader of the server's process group: TERM to the\n  local p=$1 g w all left   # group (uutils' timeout passes a TERM to its child only, not to the child's children: a\n  g=$(ps -o pgid= -p $p | tr -d ' ')   # compile worker would outlive it), up to 30 s for all of it; then KILL\n  [ \"$g\" = \"$p\" ] || g=\"\"              # (not its own group's leader: its tree instead)\n  all=$(tree $p | tr '\\n' ' ')\n  if [ -n \"$g\" ]; then kill -- -$g 2> /dev/null; else kill $all 2> /dev/null; fi\n  for w in $(seq 1 30); do\n    left=$( { [ -n \"$g\" ] && pgrep -g $g; live $all; } | sort -u | tr '\\n' ' ')\n    [ -z \"${left// }\" ] && break; sleep 1; done\n  if [ -n \"${left// }\" ]; then echo \"  stop_tree: $left still alive after 30 s: KILL\"\n    [ -n \"$g\" ] && kill -9 -- -$g 2> /dev/null; kill -9 $left 2> /dev/null; sleep 2; fi\n  wait $p 2> /dev/null\n}\nxdma_free() {   # the card's device files closed by every process of this user (60 s at most)\n  local w u\n  for w in $(seq 1 60); do u=$(lsof -t /dev/xdma0_* 2> /dev/null | tr '\\n' ' '); [ -z \"$u\" ] && return 0; sleep 1; done\n  echo \"  /dev/xdma0 still open by pids $u: FAIL\"; return 1\n}\necho \"HOSTR21 SESSION START $(date +%T) PART $PART host $(cat $H/COMMIT) up since $(uptime -s)\"\nfor f in $D/otpu.bit $H/models $RC/configs/$(basename $D).pkl $D/chatmoe/chatmoe-qwen35-35b.json; do\n  [ -e $f ] || { echo \"STOP: no $f\"; exit 2; }; done\necho \"=== selftest $(date +%T)\"; cd /tmp && env PYTHONPATH=$H timeout 900 $P -m opentpu.host.selftest 2>&1 | tee $D/selftest$PART.log | grep -E \"config|bandwidth|ALL|FAIL|ecc\"\ngrep -q \"build b10245f5 \" $D/selftest$PART.log || { echo \"BUILD MISMATCH: the card is not build b10245f5: no session\"; exit 3; }\ngrep -q \"register map 5\" $D/selftest$PART.log || { echo \"REGMAP 5 MISSING: no session\"; exit 3; }\ngrep -qE \"MCOLS=4 .*core 133.333 MHz\" $D/selftest$PART.log || { echo \"CONFIG NOT m4 133.33: no session\"; exit 3; }\ngrep -q \"ALL PASS\" $D/selftest$PART.log || { echo \"SELFTEST FAIL: no session\"; exit 3; }\ncase $PART in all|A)\n  cs; cd $H && env -u RUNS LOAD=0 ECC_EACH=1 OUT=$D/qual REFCACHE=$RC timeout 5400 bash $H/tools/qual/qual.sh $D fast > $D/qual_fast.log 2>&1\n  echo \"QUAL EXIT $? $(date +%T)\"; tail -2 $D/qual_fast.log; grep -F \"[FAIL]\" $D/qual/checks.txt | head -8 | cut -c1-220\n  grep -E \"NOTE|DRAM turnarounds, ECC|ecc \" $D/qual/checks.txt | head -6 | cut -c1-220; cs\n  echo \"=== qual E2B-it gemma4:int8:- $(date +%T)\"\n  cd $H && env -u RUNS RUNS=\"gemma4:int8:-\" LONG=\"\" LOAD=0 SOAK=60 ECC_EACH=1 OUT=$D/qual_e2b REFCACHE=$RC timeout 3600 bash $H/tools/qual/qual.sh $D fast > $D/qual_e2b.log 2>&1\n  echo \"QUAL E2B EXIT $? $(date +%T)\"; tail -2 $D/qual_e2b.log; grep -F \"[FAIL]\" $D/qual_e2b/checks.txt 2>/dev/null | head -8 | cut -c1-220; cs\n  Qn=\"What is the capital of France? Answer in one sentence.\"\n  for m in gemma4-e4b gemma4 qwen35-4b lfm2-2.6b qwen35 lfm2-8b qwen35-35b gemma4-26b; do\n    echo \"=== otpu-chat $m $(date +%T)\"\n    cd /tmp && env PYTHONPATH=$H timeout 2400 $P -m opentpu.host.chat --backend board --model $m --greedy --max-new 24 --prompt \"$Qn\" > $D/chat-$m.txt 2>&1\n    echo \"CHAT $m EXIT $? $(date +%T)\"; grep -vE \"^\\s*$\" $D/chat-$m.txt | cut -c1-220 | tail -3\n    echo \"  hostr21: $(grep -oE \"\\(device [0-9.]+\\) tok/s|[0-9.]+ Mcycles/token\" $D/chat-$m.txt | tr \"\\n\" \" \")\"\n    echo \"  prod:    $(grep -oE \"\\(device [0-9.]+\\) tok/s|[0-9.]+ Mcycles/token\" $PD/chat-$m.txt 2>/dev/null | tr \"\\n\" \" \")\"\n  done; cs\n  ecc after-A ;;\nesac\ncase $PART in all|B)\n  CF=$(ls $D/chatmoe/*.pkl | head -1)\n  echo \"=== chatmoe lfm2-8b qwen35-35b gemma4-26b $(date +%T) (refcfg $CF, POOL_CALLS=1)\"\n  cd $H && env RUNS=\"lfm2-8b qwen35-35b gemma4-26b\" RF=$D/chatmoe REFCFG=$CF POOL_CALLS=1 SESSION=chatmoe-hostr21-$(date +%H%M) \\\n    timeout 7200 bash tools/qual/chatmoe.sh > $D/chatmoe.log 2>&1\n  echo \"CHATMOE EXIT $? $(date +%T)\"; grep -E \"\\[(PASS|FAIL|SKIP)\\]|Error|cfg|COLD|load\" $D/chatmoe.log | cut -c1-240\n  echo \"=== warm gate: otpu-serve qwen35-35b, its pool dropped from the page cache $(date +%T)\"\n  POOL=$C2/pool-q35-mx.split.bin; before=$(stat -c '%s %Y' $POOL; sha256sum $POOL.packed $POOL.key | cut -c1-16 | tr '\\n' ' ')\n  env PYTHONPATH=$H $P - $POOL <<'PY'\nimport os, sys\nfd = os.open(sys.argv[1], os.O_RDONLY)          # (read only: its pages out of the page cache)\nos.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\nos.close(fd)\nfrom opentpu.host.offload import PoolFile\np, n = sys.argv[1], os.path.getsize(sys.argv[1] + \".packed\")\nprint(f\"  pool: {PoolFile(p, os.path.getsize(p) // n, True, False).resident(range(n)) / 1e9:.2f} of \"\n      f\"{os.path.getsize(p) / 1e9:.2f} GB in the page cache\")\nPY\n  # (exec: $! is timeout's own PID, the leader of the server's process group; `cd ... && env ... &` gave a subshell's,\n  # and killing it left the server holding /dev/xdma0: session hostr21, 2026-10-14)\n  (cd /tmp && exec env PYTHONPATH=$H timeout 2400 $P -m opentpu.serve.api --model $C2/Qwen3.5-35B-A3B --backend board \\\n    --pool $POOL --port 8019 --kv-ram-gb 2 --kv-dir $D/kv) > $D/serve.log 2>&1 &\n  sp=$!\n  env PYTHONPATH=$H $P - <<'PY' > $D/serve-health.log 2>&1\nimport http.client, json, time\nt0, last = time.time(), None\nwhile time.time() - t0 < 1800:\n    try:\n        c = http.client.HTTPConnection(\"127.0.0.1\", 8019, timeout=10)\n        c.request(\"GET\", \"/health\")\n        r = c.getresponse()\n        st, body = r.status, json.loads(r.read() or b\"null\")\n    except (OSError, ValueError):\n        st, body = None, None\n    b = body if isinstance(body, dict) else {}\n    k = (st, b.get(\"status\"), b.get(\"warm\"), round(b.get(\"progress\") or 0, 1))\n    if k != last:\n        print(f\"{time.time() - t0:7.1f} s: {st} {body}\", flush=True)\n        last = k\n    if st == 200:\n        break\n    time.sleep(2)\nPY\n  cat $D/serve-health.log\n  cd $H && env PYTHONPATH=$H timeout 1800 $P tools/serve_bench.py --port 8019 --skip throughput,conversation,users,arrivals \\\n    --check-prompts 2 --check-tokens 16 --out $D/serve-bench.json > $D/serve-bench.log 2>&1\n  rb=$?; echo \"SERVE_BENCH EXIT $rb $(date +%T)\"; grep -E \"warming|check:|did not come up\" $D/serve-bench.log | cut -c1-200\n  sleep 1; stop_tree $sp; xdma_free || ok_dev=0\n  grep -E \"^pool warm|^otpu-serve|Error|Traceback\" $D/serve.log | cut -c1-220\n  ok=${ok_dev:-1}\n  grep -q ' 503 .*warming' $D/serve-health.log || { ok=0; echo \"  warm gate: no 503 warming seen\"; }\n  grep -q ' 200 ' $D/serve-health.log || { ok=0; echo \"  warm gate: no 200 after it\"; }\n  grep -q '^pool warm: done' $D/serve.log || { ok=0; echo \"  warm gate: the warm did not end done\"; }\n  [ $rb = 0 ] && grep -q \"check: PASS\" $D/serve-bench.log || { ok=0; echo \"  warm gate: serve_bench's check did not pass\"; }\n  echo \"WARM GATE $([ $ok = 1 ] && echo PASS || echo FAIL) $(date +%T)\"\n  after=$(stat -c '%s %Y' $POOL; sha256sum $POOL.packed $POOL.key | cut -c1-16 | tr '\\n' ' ')\n  [ \"$before\" = \"$after\" ] && echo \"  q35 pool unchanged: $after\" || echo \"  q35 pool CHANGED: $before -> $after (FAIL)\"\n  t0=$SECONDS; cat $POOL > /dev/null; echo \"  q35 pool read back into the page cache in $((SECONDS - t0)) s\"; cs\n  ecc after-B ;;\nesac\ncase $PART in all|C)\n  echo \"=== MiniCPM-V (mcpv3.sh warmup sliced thumb text, POOL_CALLS=1) $(date +%T)\"\n  cd $H && env RUNS=\"warmup sliced thumb text\" POOL_CALLS=1 SESSION=mcpv-hostr21 timeout 5400 \\\n    bash $H/tools/offload/sessions/mcpv3.sh > $D/mcpv.log 2>&1\n  echo \"MCPV EXIT $? $(date +%T)\"; grep -E \"^===|\\[(PASS|FAIL)\\]|STOP|MCPV3|turn 1:\" $D/mcpv.log | cut -c1-220; cs\n  ecc after-C ;;\nesac\necc end-$PART\ncd $H && env PYTHONPATH=$H timeout 600 $P $PD/scrub.py > $D/scrub$PART.log 2>&1; echo \"SCRUB EXIT $? $(date +%T)\"; tail -3 $D/scrub$PART.log\necho \"=== selftest $(date +%T)\"; cd /tmp && env PYTHONPATH=$H timeout 900 $P -m opentpu.host.selftest 2>&1 | tee $D/selftest2$PART.log | grep -E \"config|bandwidth|ALL|FAIL\"\necho \"HOSTR21 SESSION END (PART $PART) $(date +%T)\"\n", "tools/offload/sessions/layer_major.sh": "#!/bin/bash\n# Layer-major prefill on the card (production build B, Gen1, no reload; docs/offload.md 13):\n# 16 tokens of gemma-4-26B-A4B as session 8's g26a (int8 layers, fp4 experts and head, 18 slots\n# a layer by decayed use, wiki.txt's first paragraph) and of Qwen3.5-35B-A3B as q35e (the\n# table on the host, no hints), each prompt token by token (g26t16, q35t16) or layer by layer\n# in runs of 1 or 2 rows (g26lm1/2, q35lm1/2: each layer's own slots; g26lmp2, q35lmp2: R = 2\n# with the slots pooled). RUNS picks the runs (default: the 35B's three and the 26B's R = 2\n# with per-layer slots, then the pooled ones last, so that a pooled failure costs only its own\n# runs; the 26B's must give O/lm's 90e6b6e06e19da99).\n# A model's runs must give the same prefill logits and tokens (layer-major is bit-exact with\n# token by token on the ISA simulator, pooled or not); each is also checked against the ISA\n# simulator's reference (reference.sh; RF, default O/refs-d29bfe9: q35ref16 88225ff781699291,\n# after moe-pair's expert sum order) and HF's; and against the runs of an earlier session in\n# O/lm (678b976: g26t16 / lm1 / lm2, per-layer slots). prefill_s: the prompt's time.\n# Run: otpu-lock --wait 10800 -- tools/offload/sessions/layer_major.sh   (log: O/lm2/session.log)\nset -u\nSESSION=${SESSION:-lm2}; RF=${RF:-${O:-$HOME/otpu-build/offload/card2}/refs-d29bfe9}\nsource \"$(dirname \"$0\")/env.sh\"             # (its RF defaults to O, whose q35ref16 is 7d879e6's)\nexec > >(tee -a $R/session.log) 2>&1\n[ -e $O/gemma-4-26B-A4B ] || ln -s ${G26:-$HOME/openTPU/models/gemma-4-26B-A4B} $O/gemma-4-26B-A4B\necho \"layer_major start $(date +%T) tree $rev mem $(mem) GB\"\ncheck() {      # the model's runs so far (and O/lm's) agree, and this run wrote its result\n  python - $R $1 <<'PY'\nimport glob, json, sys\no, run = sys.argv[1:]\nm = run[:3]\nfs = glob.glob(f\"{o}/{m}card16*.json\") + glob.glob(f\"{o}/../lm/{m}card16*.json\")\nn = len(glob.glob(f\"{o}/{m}card16*.json\"))\nsame = len({(json.load(open(f))[\"prefill_logits_sha\"], tuple(json.load(open(f))[\"tokens\"]))\n            for f in fs}) == 1\nsys.exit(0 if same and n else 1)\nPY\n}\nfor run in ${RUNS:-q35t16 q35lm1 q35lm2 g26lm2 q35lmp2 g26lmp2}; do   # one at a time: stop at the\n  n0=$(ls $R/${run:0:3}card16*.json 2>/dev/null | wc -l)        # first failed or differing run\n  RUNS=$run bash \"$here/card_moe.sh\"\n  n1=$(ls $R/${run:0:3}card16*.json 2>/dev/null | wc -l)\n  if [ \"$n1\" -le \"$n0\" ] || ! check $run; then echo \"STOP after $run: no result, or it differs\"; break; fi\ndone\necho \"layer_major end $(date +%T)\"\npython - $R <<'PY'\nimport glob, json, os, sys\no = sys.argv[1]\nfor m in (\"g26\", \"q35\"):\n    r = {(d + \" \" if d else \"\") + (os.path.basename(f)[len(m) + 6:-5] or \"t16\"): json.load(open(f))\n         for d in (\"\", \"lm\") for f in sorted(glob.glob(f\"{o}/{'../' + d + '/' if d else ''}\"\n                                                       f\"{m}card16*.json\"))\n         if d != \"lm\" or os.path.realpath(f\"{o}/../lm\") != os.path.realpath(o)}\n    if not r:\n        continue\n    same = len({(x[\"prefill_logits_sha\"], tuple(x[\"tokens\"])) for x in r.values()}) == 1\n    print(f\"  [{'PASS' if same else 'FAIL'}] {m}: {len(r)} runs, prefill logits and tokens the \"\n          f\"same: {same}\")\n    for n, x in r.items():\n        print(f\"  {m} {n}: prefill {x['prefill_s']} s, sha {x['prefill_logits_sha']}, pooled \"\n              f\"{x.get('pooled')}, layer-major requests {x.get('prefill_requests')} misses \"\n              f\"{x.get('prefill_misses')}, decode {x['tok_s_wall']} tok/s\")\nPY\ndate > $R/DONE\n", "tools/offload/sessions/les1.sh": "#!/bin/bash\n# Session les1 (docs/offload.md 15.4): what LES gives the card, production's host against les's on production's\n# bitstream. les = release-2's r2 (4ead4e53) + two host changes, both bit for bit:\n#   S  the shared expert beside the request (moe.moe_ffn / moe_ffn_rows): Qwen3.5-MoE only, its programs change;\n#   O  an expert-major need line counts as a request, and the finished layer's experts go to the pooled order's end\n#      by their last need line (docs/offload.md 13.18, ExpertServer.need / _at): the slots after an EM prompt.\n# Arms: A = production's host tree (PD/host, d8fe2c15), B = les's (TB, its COMMIT). Both models, five turns of\n# --max-new 32: emc1's four (the 35B's turns 3-4 expert-major, 45 / ~157 rows; the 26B's 1-4) and a short fifth.\n# Predicted (tools/offload/lesim.py on session 16's card fit; docs/offload.md 15): S, the 35B's decode about -2.5% a\n# token (F less 0.136 ms on every request with misses; ~-5 ms a token at the chat's ~120 misses), its layer-major\n# prompts a little shorter (~0.14 ms a request with misses); the 26B nothing (no shared expert). O, the decode after\n# an expert-major prompt: emc1's 35B turn 4 lost 0.035 hits / 18.9 MB a token against layer-major; em_slotsim bounds\n# the fix at 177.0 -> 166.7 MB (16 decode rows); the hit rates and MB a token are deterministic per arm (emc1: equal\n# in every run of an arm), so B - A on them is O's effect alone; its time is the rest of a later turn's decode\n# change beyond S's per-token change in turns 1-2.\n# Card: production deploy_r2m4_b10245f5 as loaded (EXPECT b10245f5, register map 5); its qual/cfg.pkl; the MX pools;\n# the ISA references: PD/chatmoe (TURNS' two, production's tree: RF) and les's five-turn ones (RL: chatmoe5-*.json,\n# computed on hwe-bench from TB on deploy_r2m4_d352e53d.pkl = r2's configuration). One otpu-lock:\n# 1. selftest; the device configuration must be production's qual/cfg.pkl;\n# 2. per model (the 35B, then the 26B): a discarded warm-up of each arm (WA, WB: each tree builds its own images),\n#    then ORDER (default ABBA x 2: \"A1 B1 B2 A2 A3 B3 B4 A4\"), each run after the pool's read; every run's tokens\n#    must equal RL's in all five turns and RF's first two (RF's at --max-new 16: turn 1's eos, turn 2's 16 first);\n# 3. selftest; the summary per model and turn: B - A per pair and of the means (TTFT, prefill device s, decode\n#    device ms a token, decode hit rate, MB a token), then the split: S = the 35B's decode ms a token B - A over\n#    the turns before its first expert-major prompt (1-2), O = each later turn's hits and MB a token B - A, and its\n#    ms a token beyond S's (the 26B: no S, all of B - A is O's).\n# A build other than EXPECT, a failed selftest, another configuration, a failed or timed-out run or a token mismatch\n# stops it (then the final selftest). About 40 min (20 runs of 60-90 s, each after a pool read of ~40 s; W builds).\n# Stage (from the Mac, before the session; no host work while a session runs):\n#   git archive <les sha> | ssh opentpu 'D=~/otpu-build/les/les1/host; mkdir -p $D && tar -x -C $D'\n#   ssh opentpu 'echo <les sha, full> > ~/otpu-build/les/les1/host/COMMIT'\n#   scp chatmoe5-qwen35-35b.json chatmoe5-gemma4-26b.json opentpu:otpu-build/les/les1/refs/\n# Run (no pipe): setsid nohup ~/.local/bin/otpu-lock --wait 600 -- bash ~/otpu-build/les/les1/host/tools/offload/sessions/les1.sh\n#   > ~/otpu-build/les/les1.launch.log 2>&1 < /dev/null &\nset -u\nfor v in $(env | grep -o '^OTPU_[A-Z0-9_]*' | grep -vE '^OTPU_LOCK_(HELD|PID|WAIT)$'); do unset $v; done\nexport OTPU_IMG_CACHE_GB=30 OTPU_IMG_CACHE_FREE_GB=6      # (the card host's, from its ~/.bashrc)\nLS=${LS:-$HOME/otpu-build/les/les1}\nPD=${PD:-$HOME/otpu-build/deploy_r2m4_b10245f5}  # (production: host/, qual/cfg.pkl, chatmoe/)\nTA=${TA:-$PD/host}\nTB=${TB:-$LS/host}\nRF=${RF:-$PD/chatmoe}\nRL=${RL:-$LS/refs}\nR=${R:-$LS/runs}\nT=$TB\nsource $TB/tools/offload/sessions/env.sh       # (O: card2; OTPU_QUIET claimed, removed at exit)\nexec > >(tee -a $R/session.log) 2>&1\nEXPECT=${EXPECT:-b10245f5}\nMAP=${MAP:-register map 5}\nORDER=${ORDER:-A1 B1 B2 A2 A3 B3 B4 A4}       # (after the warm-ups WA, WB)\nMAXNEW=${MAXNEW:-32}\nDROPOTHER=$HOME/openTPU/models:$O:$HOME/otpu-build/offload/g26it\nT1=\"What is the capital of France? Answer in one sentence.\"\nT2=\"And what is it famous for? Two sentences.\"\nT3=\"Which three museums in Paris should a first-time visitor see, and how long does each take?\"\nT4=\"Sum this up in one sentence: $(cat $TB/tools/offload/sessions/wiki1.txt)\"\nT5=\"Name two emperors of that period.\"\ndeclare -A M=([q]=\"qwen35-35b Qwen3.5-35B-A3B pool-q35-mx.split.bin\"\n              [g]=\"gemma4-26b gemma-4-26B-A4B-it ../g26it/pool-g26it-mx.split.bin\")\nfail=0\necho \"les1 start $(date +%T) A $TA ($(cat $TA/COMMIT)) B $TB ($(cat $TB/COMMIT)) PD $PD RF $RF RL $RL mem $(mem) GB,\" \\\n  \"/home $(df -BG --output=avail /home | tail -1 | tr -d ' ') free; $(uptime)\"\ngrep -q 'sh = swiglu_down(xs, lw.wg, lw.wu, lw.wd)' $TB/opentpu/llm/moe.py && grep -q 'def _count' $TB/opentpu/host/offload.py \\\n  || { echo \"STOP: TB is not les (the shared expert beside the request, need's count)\"; exit 2; }\ngrep -q 'def _count' $TA/opentpu/host/offload.py && { echo \"STOP: TA already has les's server\"; exit 2; }\nfor m in q g; do\n  read -r name md pool <<< \"${M[$m]}\"\n  [ -f $O/$pool ] && [ -f $RF/chatmoe-$name.json ] && [ -f $RL/chatmoe5-$name.json ] \\\n    || { echo \"STOP: $O/$pool, $RF/chatmoe-$name.json or $RL/chatmoe5-$name.json missing\"; exit 2; }\ndone\nbusy() { echo \"  host: $(cut -d' ' -f1-3 /proc/loadavg); $(ps -eo pcpu,comm --sort=-pcpu | sed -n 2,4p | tr -s ' ' | tr '\\n' ';')\"; }\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"build $EXPECT\" || { echo \"STOP: the card's build is not $EXPECT\"; exit 2; }\necho \"$st\" | grep -q \"$MAP\" || { echo \"STOP: not $MAP\"; exit 2; }\necho \"$st\" | grep -q \"ALL PASS\" || { echo \"STOP: selftest\"; exit 2; }\ntimeout 300 python tools/qual/refs.py cfg $R/cfg-dev.pkl > /dev/null 2>&1; echo \"cfg exit $?\"\npython - $R/cfg-dev.pkl $PD/qual/cfg.pkl <<'PY' || { echo \"STOP: the device configuration\"; exit 2; }\nimport dataclasses, pickle, sys\na, b = (pickle.load(open(f, \"rb\")) for f in sys.argv[1:])\nd = {f.name: (getattr(a, f.name), getattr(b, f.name)) for f in dataclasses.fields(a)\n     if getattr(a, f.name) != getattr(b, f.name)}\nprint(\"  cfg: production's (qual/cfg.pkl)\" if not d else f\"  cfg DIFFERS from production's: {d}\")\nsys.exit(1 if d else 0)\nPY\nwarm() {   # checkpoint, pool (in O): every other big file out of the page cache, the pool read into it\n  python - $O/$1 $O/$2 $DROPOTHER <<'PY'\nimport os, sys                      # every other file of 100 MB or more out of the page cache\nkeep = {os.path.realpath(sys.argv[1]), os.path.realpath(sys.argv[2])}  # (card_moe.sh's DROPOTHER)\nours = tuple(os.path.realpath(os.path.expanduser(d)) + os.sep for d in (\"~/openTPU\", \"~/otpu-build\"))\ngb = n = 0\nseen = set()\nfor d in sys.argv[3].split(\":\"):\n    for root, _, files in os.walk(os.path.expanduser(d)):\n        for f in files:\n            r = os.path.realpath(os.path.join(root, f))\n            if r in seen or not r.startswith(ours) or not os.path.isfile(r) \\\n                    or os.path.getsize(r) < 100 << 20 or r in keep or os.path.dirname(r) in keep:\n                continue\n            seen.add(r)\n            fd = os.open(r, os.O_RDONLY)\n            os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n            os.close(fd)\n            gb, n = gb + os.path.getsize(r) / 1e9, n + 1\nprint(f\"  dropped from the page cache: {n} other files of {gb:.1f} GB\")\nPY\n  local t0=$SECONDS; cat $O/$2 > /dev/null; echo \"  pool read in $((SECONDS - t0)) s, mem $(mem) GB\"\n}\n# 2. per model: WA, WB, then ORDER; A from TA, B from TB, each its own PYTHONPATH\nfor m in q g; do\n  [ $fail = 0 ] || break\n  read -r name md pool <<< \"${M[$m]}\"\n  for x in WA WB $ORDER; do\n    case $x in WA|A*) tr=$TA;; *) tr=$TB;; esac\n    echo \"=== $m$x $(date +%T) ($name, $(basename $(dirname $tr))/$(basename $tr) $(cut -c1-8 $tr/COMMIT))\"\n    warm $md $pool\n    busy\n    (cd $tr && PYTHONPATH=$tr timeout 1800 python $tr/tools/qual/chatmoe.py $O/$md --pool $O/$pool --backend board \\\n       --cfg $R/cfg-dev.pkl --turn \"$T1\" --turn \"$T2\" --turn \"$T3\" --turn \"$T4\" --turn \"$T5\" --max-new $MAXNEW \\\n       --out $R/$m$x.json > $R/$m$x.log 2>&1)\n    rc=$?; echo \"  exit $rc $(date +%T)\"; grep -E \"Error|Traceback\" $R/$m$x.log | tail -3\n    [ $rc = 0 ] && [ -f $R/$m$x.json ] || { echo \"STOP: $m$x\"; fail=1; break; }\n    python - $R/$m$x.json $RL/chatmoe5-$name.json $RF/chatmoe-$name.json <<'PY' || { echo \"STOP: $m$x differs\"; fail=1; break; }\nimport json, sys\nd, rl, rf = (json.load(open(f)) for f in sys.argv[1:])\ntok = [t[\"tokens\"] for t in d[\"turns\"]]\nok_l = tok == [t[\"tokens\"] for t in rl[\"turns\"]]\nok_f = all(x == t[\"tokens\"] if t[\"end\"] == \"eos\" else x[:len(t[\"tokens\"])] == t[\"tokens\"]   # (RF's at --max-new 16:\n           for x, t in zip(tok, rf[\"turns\"][:2]))                                         #  turn 2 a prefix)\nprint(f\"  [{'PASS' if ok_l and ok_f else 'FAIL'}] tokens {'=' if ok_l else '!='} les's five-turn ISA reference, \"\n      f\"first two {'=' if ok_f else '!='} production's; em_rows {d.get('em_rows', '-')}, load {d['load_s']} s\")\nfor i, t in enumerate(d[\"turns\"]):\n    print(f\"  turn {i + 1}: prompt {t['prompt_tokens']} (reused {t['reused']}) TTFT {t['ttft_s']} s, prefill \"\n          f\"{t['prefill_tok_s']} tok/s (device {t['prefill_dev_tok_s']}), {t['prefill_misses']} misses; decode \"\n          f\"{t['gen_tokens']} at {t['decode_tok_s']} tok/s (device {t['decode_dev_tok_s']}), hits {t['hit_rate']}, \"\n          f\"{t['mb_per_token']} MB/token; end {t['end']}\")\n    for c in t.get(\"calls\", []):\n        print(f\"    call {c['rows']} rows {'EM' if c['em'] else 'LM'}: {c['s']} s (device {c['device_s']}), \"\n              f\"{c['runs']} runs, misses {c['misses']} ({c['requests']} requests, served in {c['serve_s']} s), \"\n              f\"needs {c['needs_queued']} (hits {c['need_hits']}), holds {c['holds']}\")\nsys.exit(0 if ok_l and ok_f else 1)\nPY\n  done\ndone\necho \"=== final selftest $(date +%T)\"\ntimeout 600 python -m opentpu.host.selftest 2>&1 | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"les1 end $(date +%T) fail $fail\"\npython - $R \"$ORDER\" <<'PY'\nimport json, os, sys\nr, order = sys.argv[1], sys.argv[2].split()\ndef get(run):\n    f = f\"{r}/{run}.json\"\n    return json.load(open(f)) if os.path.exists(f) else None\nfor name, m in ((\"35B\", \"q\"), (\"26B\", \"g\")):\n    a = {x: get(m + x) for x in order}\n    if None in a.values():\n        print(f\"  {name}: incomplete\"); continue\n    A, B = ([x for x in order if x[0] == c] for c in \"AB\")\n    pairs = [(b, \"A\" + b[1:]) for b in B if \"A\" + b[1:] in a]\n    n = len(a[B[0]][\"turns\"])\n    def tv(x, i, k):\n        t = a[x][\"turns\"][i]\n        if k == \"dev_s\":                    # the prompt's device seconds\n            return t[\"prompt_tokens\"] / t[\"prefill_dev_tok_s\"] if t[\"prefill_dev_tok_s\"] else 0.0\n        if k == \"ms_tok\":                   # the decode's device ms a token\n            return 1000.0 / t[\"decode_dev_tok_s\"] if t[\"decode_dev_tok_s\"] else 0.0\n        return t[k] or 0.0\n    def mean(xs, i, k):\n        return sum(tv(x, i, k) for x in xs) / len(xs)\n    split = {}\n    for i in range(n):\n        calls = \" + \".join(f\"{c['rows']}{'E' if c['em'] else 'L'}\" for c in a[B[0]][\"turns\"][i].get(\"calls\", []))\n        print(f\"  {name} turn {i + 1} ({a[B[0]]['turns'][i]['prompt_tokens']} tokens; {calls}):\")\n        for k, lab, fmt in ((\"ttft_s\", \"TTFT s\", \"+.3f\"), (\"dev_s\", \"prompt device s\", \"+.3f\"),\n                            (\"ms_tok\", \"decode device ms/token\", \"+.2f\"), (\"hit_rate\", \"decode hits\", \"+.4f\"),\n                            (\"mb_per_token\", \"decode MB/token\", \"+.2f\")):\n            d = mean(B, i, k) - mean(A, i, k)\n            split[(i, k)] = (d, mean(A, i, k))\n            print(f\"      {lab}: B - A \" + \" \".join(f\"{tv(b, i, k) - tv(p, i, k):{fmt}}\" for b, p in pairs)\n                  + f\", of the means {d:{fmt}}; \" + \", \".join(f\"{x} {tv(x, i, k):{fmt[1:]}}\" for x in order))\n    em = [i for i in range(n) if any(c[\"em\"] for c in a[B[0]][\"turns\"][i].get(\"calls\", []))]\n    clean = [i for i in range(n) if not em or i < em[0]]    # (decodes no expert-major prompt came before)\n    s_rel = 0.0\n    if m == \"q\" and clean:              # S: the 35B's decode before any expert-major prompt (O can't act there)\n        s = sum(split[(i, \"ms_tok\")][0] for i in clean) / len(clean)\n        s_rel = sum(split[(i, \"ms_tok\")][0] / split[(i, \"ms_tok\")][1] for i in clean) / len(clean)\n        print(f\"  {name} split: S (the shared expert) = decode B - A over turns {[i + 1 for i in clean]}: \"\n              f\"{s:+.2f} ms a token ({s_rel * 100:+.2f}%)\")\n    else:                               # (the 26B: no shared expert, byte-identical programs)\n        print(f\"  {name} split: no S (no shared expert): B - A is O's alone, and the noise in turns \"\n              f\"{[i + 1 for i in clean]}\")\n    for i in range(n):\n        if i not in clean:\n            d, base = split[(i, \"ms_tok\")]\n            print(f\"  {name} split: turn {i + 1}: O (the slots after an expert-major prompt) hits \"\n                  f\"{split[(i, 'hit_rate')][0]:+.4f}, MB/token {split[(i, 'mb_per_token')][0]:+.2f}; decode \"\n                  f\"{d:+.2f} ms a token, beyond S {d - s_rel * base:+.2f}\")\nPY\ndate > $R/DONE\necho \"LES1 EXIT $fail $(date +%T)\"\n", "tools/offload/sessions/mcpv1.sh": "#!/bin/bash\n# Session mcpv1 (docs/minicpmv.md 6): MiniCPM-V 4.7 (35B-A3B) on the card for the first time, through otpu-chat's\n# engine and Chat (tools/qual/chatmoe.py): the language model's experts streamed from the MX pool, the vision tower\n# resident in int8 (Spec.vision_staged False), MiniCPM-V's formats (streamed.FORMATS[\"minicpmv\"]: fp4 experts,\n# DeltaNet int8 in layers 0-19, the shared expert int8, the rest nvfp4, head int8). Runs, each token-exact against\n# the ISA simulator's reference (REF=1, below):\n#   text    chatmoe.py's two text turns (TURNS, --max-new 16): the language model alone\n#   thumb   cats.jpg at --max-slices 1 (its thumbnail: one crop), two turns\n#   sliced  doc.png at the processor's 9 slices (7 crops), one turn of --max-new 32\n#   serve   otpu-serve on the card, tools/serve_bench.py's images part (docs/serve.md Images) at max_slices 1: cats.jpg\n#           with thumb's first question (its reply must be thumb's reference's first turn's), again (the context\n#           reused past the image), its next turn, doc.png with the same question (no context past it reused), a\n#           text-only question; each request's cached tokens and TTFT (no reference of its own)\n# Each chatmoe.py turn reports its images and their crops' seconds through the card's tower (vision_s), TTFT, prefill\n# and decode tok/s (wall and device) and the slots' hits.\n# Card: production deploy_r2m4_b10245f5 as loaded (EXPECT b10245f5, register map 5); its qual/cfg.pkl.\n# O (/data/otpu/minicpmv) holds MiniCPM-V-4.7-35B-A3B/ (the slim checkpoint), pool-mcpv35-mx.split.bin (+ .packed,\n# .format, .key), img/ (cats.jpg, doc.png), refs/minicpmv-<run>.json and pylib/ (PYLIB: hwe-bench's ~/mcpv/tf518,\n# torchvision 0.29.1+cpu, pillow 12.3.0 and transformers 5.18.0 over the venv's torch 2.14.0: the image's decode and\n# resize as HF's processor, the packages the references ran with; without torchvision the resize differs).\n# One otpu-lock:\n# 1. selftest; the device configuration must be production's qual/cfg.pkl;\n# 2. per run (RUNS, default \"text thumb sliced serve\"): every other file of 100 MB or more under O, ~/openTPU/models\n#    and ~/otpu-build/offload out of the page cache, the pool read into it, then chatmoe.py --check its reference\n#    (serve: otpu-serve on PORT, default 8017, and serve_bench.py against it, then the server stopped);\n# 3. selftest; the summary per run and turn.\n# A build other than EXPECT, a failed selftest, another configuration or a missing file stops it; a failed run or a\n# token mismatch is reported and the next run goes on. The last line: MCPV1 PASS or MCPV1 FAIL. About 35 min (the\n# image's first build on the card host ~5 min, otpu-serve's ~5 min more, the pool's read ~40 s a run).\n# References (REF=1: the same runs on the ISA simulator with REFCFG, no card, no selftest), on hwe-bench from this\n# tree, one run a call (each in a slot of its own), into RF (serve has none: thumb's):\n#   REF=1 O=~/mcpv PYLIB=~/mcpv/tf518 REFCFG=~/mcpv/cfg-b10245f5.pkl RUNS=thumb bash tools/offload/sessions/mcpv1.sh\n#   (O there: MiniCPM-V-4.7-35B-A3B -> slim/MiniCPM-V-4.7-35B-A3B, the pool, img/; RF default O/refs)\n# Stage (from the Mac, before the session; no host work while a session runs):\n#   git archive <sha> | ssh opentpu 'D=~/otpu-build/minicpmv/mcpv1/host; mkdir -p $D && tar -x -C $D'\n#   ssh opentpu 'echo <sha> > ~/otpu-build/minicpmv/mcpv1/host/COMMIT'\n#   ssh hwe-bench 'tar -C ~/mcpv -cf - tf518 img refs' | ssh opentpu 'cd /data/otpu/minicpmv && tar -xf - && \\\n#     rm -rf pylib && mv tf518 pylib'\n# Run (no pipe): setsid nohup ~/.local/bin/otpu-lock --wait 600 -- bash \\\n#   ~/otpu-build/minicpmv/mcpv1/host/tools/offload/sessions/mcpv1.sh > ~/otpu-build/minicpmv/mcpv1.launch.log 2>&1 \\\n#   < /dev/null &\nset -u\nREF=${REF:-0}\nif [ $REF = 1 ]; then\n  OTPU_QUIET=${OTPU_QUIET:-/dev/null}               # (no card host: nothing to keep quiet)\n  SESSION=${SESSION:-mcpv1-ref}\nelse\n  for v in $(env | grep -o '^OTPU_[A-Z0-9_]*' | grep -vE '^OTPU_LOCK_(HELD|PID|WAIT)$'); do unset $v; done\n  export OTPU_IMG_CACHE_GB=30 OTPU_IMG_CACHE_FREE_GB=6      # (the card host's, from its ~/.bashrc)\n  SESSION=${SESSION:-mcpv1}\nfi\nO=${O:-/data/otpu/minicpmv}\nRF=${RF:-$O/refs}\nPD=${PD:-$HOME/otpu-build/deploy_r2m4_b10245f5}        # (production: qual/cfg.pkl)\nREFCFG=${REFCFG:-$PD/qual/cfg.pkl}\nPYLIB=${PYLIB:-$O/pylib}\nsource \"$(dirname \"${BASH_SOURCE[0]}\")/env.sh\"       # (T: this tree; R = O/SESSION; OTPU_QUIET claimed)\nexport PYTHONPATH=$T:$PYLIB\nexec > >(tee -a $R/session.log) 2>&1\nEXPECT=${EXPECT:-b10245f5}\nMAP=${MAP:-register map 5}\nMD=MiniCPM-V-4.7-35B-A3B\nPOOL=pool-mcpv35-mx.split.bin\nRUNS=${RUNS:-text thumb sliced serve}\nPORT=${PORT:-8017}\ndeclare -A RUN=(        # chatmoe.py's options\n  [text]=\"\"\n  [thumb]=\"--image 1:$O/img/cats.jpg --max-slices 1 --turn 'Describe this image in one sentence.' --turn 'What colors stand out? One sentence.'\"\n  [sliced]=\"--image 1:$O/img/doc.png --turn 'What does this document say? Two sentences.' --max-new 32\")\nfail=0\necho \"mcpv1 start $(date +%T) REF $REF T $T ($rev) O $O RF $RF REFCFG $REFCFG mem $(mem) GB; $(uptime)\"\ngrep -q '\"minicpmv\": (\"fp4\", \"int8\", \"delta@0-19=int8,attn=nvfp4,delta=nvfp4,mlp=int8\")' \\\n  $T/opentpu/host/streamed.py && grep -q \"def place\" $T/opentpu/host/offload.py \\\n  || { echo \"STOP: T is not the minicpmv branch (MiniCPM-V's formats, the expert server's place)\"; exit 2; }\npython -c \"import torchvision, PIL, transformers; print('  python:', torchvision.__version__, PIL.__version__,\n  transformers.__version__)\" || { echo \"STOP: no torchvision / pillow / transformers under PYLIB $PYLIB\"; exit 2; }\n[ -f $O/$MD/config.json ] && [ -f $O/$POOL ] && [ -f $O/$POOL.key ] && [ -f $O/img/cats.jpg ] && \\\n  [ -f $O/img/doc.png ] && [ -f $REFCFG ] || { echo \"STOP: $O/$MD, $O/$POOL, its key, img/ or $REFCFG missing\"; exit 2; }\nif [ $REF = 1 ]; then\n  mkdir -p $RF\n  for m in ${RUNS/serve/}; do\n    echo \"=== ref $m $(date +%T)\"\n    t0=$SECONDS\n    eval \"python tools/qual/chatmoe.py $O/$MD --pool $O/$POOL --backend isa --cfg $REFCFG \\\n      --out $RF/minicpmv-$m.json ${RUN[$m]}\" > $R/ref-$m.log 2>&1\n    echo \"  exit $? in $((SECONDS - t0)) s $(date +%T)\"; grep -E \"^turn|Error|Traceback\" $R/ref-$m.log | tail -6\n  done\n  echo \"MCPV1 REF DONE $(date +%T)\"\n  exit 0\nfi\nfor m in $RUNS; do\n  [ $m = serve ] && m=thumb\n  [ -f $RF/minicpmv-$m.json ] || { echo \"STOP: no reference $RF/minicpmv-$m.json\"; exit 2; }\ndone\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"build $EXPECT\" || { echo \"STOP: the card's build is not $EXPECT\"; exit 2; }\necho \"$st\" | grep -q \"$MAP\" || { echo \"STOP: not $MAP\"; exit 2; }\necho \"$st\" | grep -q \"ALL PASS\" || { echo \"STOP: selftest\"; exit 2; }\ntimeout 300 python tools/qual/refs.py cfg $R/cfg-dev.pkl > /dev/null 2>&1; echo \"cfg exit $?\"\npython - $R/cfg-dev.pkl $REFCFG <<'PY' || { echo \"STOP: the device configuration is not the references'\"; exit 2; }\nimport dataclasses, pickle, sys\na, b = (pickle.load(open(f, \"rb\")) for f in sys.argv[1:])\nd = {f.name: (getattr(a, f.name), getattr(b, f.name)) for f in dataclasses.fields(a)\n     if getattr(a, f.name) != getattr(b, f.name)}\nprint(\"  cfg: the references' configuration\" if not d else f\"  cfg DIFFERS (device, ref): {d}\")\nsys.exit(1 if d else 0)\nPY\nfor m in $RUNS; do\n  echo \"=== $m $(date +%T)\"\n  python - $O/$MD $O/$POOL $O:$HOME/openTPU/models:$HOME/otpu-build/offload <<'PY'\nimport os, sys                                # every other file of 100 MB or more out of the\nkeep = {os.path.realpath(sys.argv[1]), os.path.realpath(sys.argv[2])}    # page cache\nours = tuple(os.path.realpath(os.path.expanduser(d)) + os.sep\n             for d in (\"~/openTPU\", \"~/otpu-build\", \"/data/otpu\"))\ngb = n = 0\nseen = set()\nfor d in sys.argv[3].split(\":\"):\n    for root, _, files in os.walk(d):\n        for f in files:\n            r = os.path.realpath(os.path.join(root, f))\n            if r in seen or not r.startswith(ours) or not os.path.isfile(r) or \\\n                    os.path.getsize(r) < 100 << 20 or r in keep or os.path.dirname(r) in keep:\n                seen.add(r)\n                continue\n            seen.add(r)\n            fd = os.open(r, os.O_RDONLY)\n            os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n            os.close(fd)\n            gb, n = gb + os.path.getsize(r) / 1e9, n + 1\nprint(f\"  dropped from the page cache: {n} other files of {gb:.1f} GB\")\nPY\n  t0=$SECONDS; cat $O/$POOL > /dev/null       # the pool in the page cache (the RAM tier)\n  echo \"  (pool read in $((SECONDS - t0)) s, mem $(mem) GB)\"\n  if [ $m = serve ]; then\n    timeout 3600 python -m opentpu.serve.api --model $O/$MD --backend board --pool $O/$POOL --port $PORT \\\n      --kv-ram-gb 2 --kv-dir $R/kv > $R/serve.log 2>&1 &\n    sp=$!\n    timeout 2400 python tools/serve_bench.py --port $PORT --skip check,throughput,conversation,users,arrivals \\\n      --image $O/img/cats.jpg --image $O/img/doc.png --image-slices 1 --image-tokens 16 \\\n      --image-ref $RF/minicpmv-thumb.json --wait 1200 --out $R/serve-bench.json > $R/serve-bench.log 2>&1\n    rc=$?\n    kill $sp 2>/dev/null; wait $sp 2>/dev/null\n    echo \"  exit $rc $(date +%T); server: $(grep -E \"^weights|Error|Traceback\" $R/serve.log | tail -2 | tr '\\n' ' ')\"\n    [ $rc = 0 ] || fail=1\n    python - $R/serve-bench.json <<'PY'\nimport json, sys\ntry:\n    r = json.load(open(sys.argv[1]))[\"images\"]\nexcept (OSError, KeyError, ValueError) as e:\n    sys.exit(f\"  no images part: {e!r}\")\nprint(f\"  images {'PASS' if r['pass'] else 'FAIL'}: thumb's reply {r.get('ref_equal')}, again equal \"\n      f\"{r['again_equal']}\")\nfor k in (\"first\", \"again\", \"turn2\", \"others\", \"text\"):\n    for x in (r[k] if k == \"others\" else [r[k]]):\n        print(f\"  {k}: prompt {x['prompt_tokens']}, cached {x['cached']}, TTFT {x['ttft_s']} s, \"\n              f\"{x['finish']}: {x['text']!r}\")\nPY\n    continue\n  fi\n  eval \"timeout 3600 python tools/qual/chatmoe.py $O/$MD --pool $O/$POOL --backend board \\\n    --cfg $R/cfg-dev.pkl --check $RF/minicpmv-$m.json --out $R/minicpmv-$m.json ${RUN[$m]}\" \\\n    > $R/minicpmv-$m.log 2>&1\n  rc=$?\n  echo \"  exit $rc $(date +%T)\"; grep -E \"\\[(PASS|FAIL)\\]|Error|Traceback\" $R/minicpmv-$m.log | tail -3\n  [ $rc = 0 ] && grep -q \"\\[PASS\\]\" $R/minicpmv-$m.log || fail=1\n  [ -f $R/minicpmv-$m.json ] || continue\n  python - $R/minicpmv-$m.json <<'PY'\nimport json, sys\nr = json.load(open(sys.argv[1]))\nprint(f\"  {r['weights']}; {r['experts']}; layer-major {r['layer_major']}, loop on the card \"\n      f\"{r['on_card']}, load {r['load_s']} s, host {r['host_mem']}\")\nfor i, t in enumerate(r[\"turns\"]):\n    print(f\"  turn {i + 1}: {t.get('images', 0)} images (vision {t.get('vision_s')} s); prompt \"\n          f\"{t['prompt_tokens']} tokens (reused {t['reused']}\"\n          f\"{', restarted' if t['restarted'] else ''}) in {t['prefill_s']} s \"\n          f\"({t['prefill_tok_s']} tok/s, device {t['prefill_dev_tok_s']}), {t['prefill_misses']} \"\n          f\"misses; TTFT {t['ttft_s']} s; decode {t['gen_tokens']} tokens at {t['decode_tok_s']} \"\n          f\"tok/s (device {t['decode_dev_tok_s']}), hits {t['hit_rate']}, \"\n          f\"{t['mb_per_token']} MB/token; end {t['end']}\\n    {t['reply']!r}\")\nPY\ndone\necho \"=== final selftest $(date +%T)\"\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"ALL PASS\" || fail=1\necho \"MCPV1 $([ $fail = 0 ] && echo PASS || echo FAIL) $(date +%T)\"\nexit $fail\n", "tools/offload/sessions/mcpv2.sh": "#!/bin/bash\n# Session mcpv2 (docs/minicpmv.md 6): MiniCPM-V 4.7 (35B-A3B) on the card, where the time goes and the staged vision.\n# mcpv1 passed (text, thumb, serve token-exact) with thumb's one crop at 30.3 s of vision, otpu-serve's image TTFTs at\n# 16.6 / 15.5 s and text's first turns cold (its image's first build, 200.8 s at a 28.4 GB peak of the host's 31 GB,\n# took the pool out of the page cache: the pool is on /data, a 7200 rpm disk). Runs (RUNS, default\n# \"tower text sliced staged stower\"), each after every other file of 100 MB or more under O, ~/openTPU/models and\n# ~/otpu-build/offload leaves the page cache and the pool is read into it:\n#   tower    tools/minicpmv_tower.py time: cats.jpg at max-slices 1 (one crop), then doc.png at 9 slices (7 crops),\n#            each step timed (host preprocessing, the programs' build, host rows, their writes, each run's start and\n#            wait against its device time by phase, the rows' read), then minicpmv.Vision.encode twice as a whole\n#   text     chatmoe.py's two text turns again, the image built already (mcpv1's were cold): the warm decode\n#   sliced   doc.png at 9 slices, one turn of 32 tokens, token-exact against its reference\n#   staged   cats.jpg at max-slices 1, two turns, the tower's weights staged through the expert slots\n#            (chatmoe.py --vision-staged): a warm-up (its image's first build; the pool grows by the 446 vision\n#            entries, packed on first use), the pool read again, then the run, token-exact against thumb's reference\n#            (staged rows are the resident tower's bit for bit): its slots a layer, decode tok/s and hits against\n#            mcpv1's thumb (resident)\n#   stower   tools/minicpmv_tower.py time --vision-staged on cats.jpg (max-slices 1) and doc.png: the placement's\n#            seconds (Vision.stage) beside the crops'\n# Card: production deploy_r2m4_b10245f5 as loaded (EXPECT b10245f5, register map 5); its qual/cfg.pkl. O\n# (/data/otpu/minicpmv): as mcpv1 (the slim checkpoint, the pool, img/, refs/, pylib/). The staged runs grow the pool\n# file in place by 763.6 MB (its key's \"vision\"; the experts unchanged: SUMS-pool's sum no longer holds for the file).\n# One otpu-lock: selftest (the configuration must be production's), the runs, selftest. A build other than EXPECT, a\n# failed selftest, another configuration or a missing file stops it; a failed run or a token mismatch is reported and\n# the next run goes on. The last line: MCPV2 PASS or MCPV2 FAIL. About 30 min (the staged image's first build ~4 min).\n# Stage (from the Mac, before the session; no host work while a session runs):\n#   git archive <sha> | ssh opentpu 'D=~/otpu-build/minicpmv/mcpv2/host; mkdir -p $D && tar -x -C $D'\n#   ssh opentpu 'echo <sha> > ~/otpu-build/minicpmv/mcpv2/host/COMMIT'\n# Run (no pipe): setsid nohup ~/.local/bin/otpu-lock --wait 600 -- bash \\\n#   ~/otpu-build/minicpmv/mcpv2/host/tools/offload/sessions/mcpv2.sh > ~/otpu-build/minicpmv/mcpv2.launch.log 2>&1 \\\n#   < /dev/null &\nset -u\nfor v in $(env | grep -o '^OTPU_[A-Z0-9_]*' | grep -vE '^OTPU_LOCK_(HELD|PID|WAIT)$'); do unset $v; done\nexport OTPU_IMG_CACHE_GB=30 OTPU_IMG_CACHE_FREE_GB=6      # (the card host's, from its ~/.bashrc)\nSESSION=${SESSION:-mcpv2}\nO=${O:-/data/otpu/minicpmv}\nRF=${RF:-$O/refs}\nPD=${PD:-$HOME/otpu-build/deploy_r2m4_b10245f5}        # (production: qual/cfg.pkl)\nREFCFG=${REFCFG:-$PD/qual/cfg.pkl}\nPYLIB=${PYLIB:-$O/pylib}\nsource \"$(dirname \"${BASH_SOURCE[0]}\")/env.sh\"       # (T: this tree; R = O/SESSION; OTPU_QUIET claimed)\nexport PYTHONPATH=$T:$PYLIB\nexec > >(tee -a $R/session.log) 2>&1\nEXPECT=${EXPECT:-b10245f5}\nMAP=${MAP:-register map 5}\nMD=MiniCPM-V-4.7-35B-A3B\nPOOL=pool-mcpv35-mx.split.bin\nRUNS=${RUNS:-tower text sliced staged stower}\nTHUMB=\"--image 1:$O/img/cats.jpg --max-slices 1 --turn 'Describe this image in one sentence.' --turn 'What colors stand out? One sentence.'\"\ndeclare -A RUN=(        # chatmoe.py's options\n  [text]=\"\"\n  [sliced]=\"--image 1:$O/img/doc.png --turn 'What does this document say? Two sentences.' --max-new 32\"\n  [staged]=\"--vision-staged $THUMB\")\ndeclare -A REFOF=([text]=text [sliced]=sliced [staged]=thumb)\nfail=0\necho \"mcpv2 start $(date +%T) T $T ($rev) O $O RF $RF mem $(mem) GB, /data $(df -BG --output=avail /data | tail -1 | tr -d ' ') free; $(uptime)\"\ngrep -q 'vision_staged: bool | None = None' $T/opentpu/host/streamed.py && [ -f $T/tools/minicpmv_tower.py ] \\\n  || { echo \"STOP: T is not the minicpmv branch with minicpmv_tower.py and streamed.engine(vision_staged=)\"; exit 2; }\npython -c \"import torchvision, PIL, transformers; print('  python:', torchvision.__version__, PIL.__version__,\n  transformers.__version__)\" || { echo \"STOP: no torchvision / pillow / transformers under PYLIB $PYLIB\"; exit 2; }\n[ -f $O/$MD/config.json ] && [ -f $O/$POOL ] && [ -f $O/$POOL.key ] && [ -f $O/img/cats.jpg ] && \\\n  [ -f $O/img/doc.png ] && [ -f $REFCFG ] || { echo \"STOP: $O/$MD, $O/$POOL, its key, img/ or $REFCFG missing\"; exit 2; }\nfor m in $RUNS; do\n  [ -n \"${REFOF[$m]:-}\" ] || continue\n  [ -f $RF/minicpmv-${REFOF[$m]}.json ] || { echo \"STOP: no reference $RF/minicpmv-${REFOF[$m]}.json\"; exit 2; }\ndone\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"build $EXPECT\" || { echo \"STOP: the card's build is not $EXPECT\"; exit 2; }\necho \"$st\" | grep -q \"$MAP\" || { echo \"STOP: not $MAP\"; exit 2; }\necho \"$st\" | grep -q \"ALL PASS\" || { echo \"STOP: selftest\"; exit 2; }\ntimeout 300 python tools/qual/refs.py cfg $R/cfg-dev.pkl > /dev/null 2>&1; echo \"cfg exit $?\"\npython - $R/cfg-dev.pkl $REFCFG <<'PY' || { echo \"STOP: the device configuration is not the references'\"; exit 2; }\nimport dataclasses, pickle, sys\na, b = (pickle.load(open(f, \"rb\")) for f in sys.argv[1:])\nd = {f.name: (getattr(a, f.name), getattr(b, f.name)) for f in dataclasses.fields(a)\n     if getattr(a, f.name) != getattr(b, f.name)}\nprint(\"  cfg: the references' configuration\" if not d else f\"  cfg DIFFERS (device, ref): {d}\")\nsys.exit(1 if d else 0)\nPY\nwarm() {      # every other file of 100 MB or more out of the page cache, then the pool into it\n  python - $O/$MD $O/$POOL $O:$HOME/openTPU/models:$HOME/otpu-build/offload <<'PY'\nimport os, sys\nkeep = {os.path.realpath(sys.argv[1]), os.path.realpath(sys.argv[2])}\nours = tuple(os.path.realpath(os.path.expanduser(d)) + os.sep\n             for d in (\"~/openTPU\", \"~/otpu-build\", \"/data/otpu\"))\ngb = n = 0\nseen = set()\nfor d in sys.argv[3].split(\":\"):\n    for root, _, files in os.walk(d):\n        for f in files:\n            r = os.path.realpath(os.path.join(root, f))\n            if r in seen or not r.startswith(ours) or not os.path.isfile(r) or \\\n                    os.path.getsize(r) < 100 << 20 or r in keep or os.path.dirname(r) in keep:\n                seen.add(r)\n                continue\n            seen.add(r)\n            fd = os.open(r, os.O_RDONLY)\n            os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n            os.close(fd)\n            gb, n = gb + os.path.getsize(r) / 1e9, n + 1\nprint(f\"  dropped from the page cache: {n} other files of {gb:.1f} GB\")\nPY\n  local t0=$SECONDS\n  dd if=$O/$POOL of=/dev/null bs=16M status=none      # (every block read)\n  echo \"  (pool read in $((SECONDS - t0)) s, mem $(mem) GB, cached $(awk '/^Cached:/ {print int($2/1048576)}' /proc/meminfo) GB)\"\n}\nsummary() {   # a chatmoe.py JSON's lines\n  python - $1 <<'PY'\nimport json, sys\nr = json.load(open(sys.argv[1]))\nprint(f\"  {r['weights']}; {r['experts']}; staged vision {r.get('vision_staged')}; load {r['load_s']} s, \"\n      f\"host {r['host_mem']}\")\nfor i, t in enumerate(r[\"turns\"]):\n    print(f\"  turn {i + 1}: {t.get('images', 0)} images (vision {t.get('vision_s')} s); prompt \"\n          f\"{t['prompt_tokens']} tokens (reused {t['reused']}) in {t['prefill_s']} s ({t['prefill_tok_s']} \"\n          f\"tok/s, device {t['prefill_dev_tok_s']}), {t['prefill_misses']} misses; TTFT {t['ttft_s']} s; decode \"\n          f\"{t['gen_tokens']} tokens at {t['decode_tok_s']} tok/s (device {t['decode_dev_tok_s']}), hits \"\n          f\"{t['hit_rate']}, {t['mb_per_token']} MB/token; end {t['end']}\\n    {t['reply']!r}\")\nPY\n}\nchat() {      # chatmoe.py run $1 (RUN's options), checked against REFOF's reference; $2: the output's name\n  eval \"timeout 3600 python tools/qual/chatmoe.py $O/$MD --pool $O/$POOL --backend board --cfg $R/cfg-dev.pkl \\\n    --check $RF/minicpmv-${REFOF[$1]}.json --out $R/minicpmv-$2.json ${RUN[$1]}\" > $R/minicpmv-$2.log 2>&1\n  local rc=$?\n  echo \"  exit $rc $(date +%T)\"; grep -E \"\\[(PASS|FAIL)\\]|Error|Traceback\" $R/minicpmv-$2.log | tail -3\n  [ $rc = 0 ] && grep -q \"\\[PASS\\]\" $R/minicpmv-$2.log || fail=1\n  [ -f $R/minicpmv-$2.json ] && summary $R/minicpmv-$2.json\n}\ntower() {     # minicpmv_tower.py time, $1 its output's name, the rest its options\n  local n=$1; shift\n  timeout 2400 python tools/minicpmv_tower.py time $O/$MD --backend board --cfg $R/cfg-dev.pkl --pool $O/$POOL \\\n    --image $O/img/cats.jpg:1 --image $O/img/doc.png --reps 2 --out $R/$n.json \"$@\" > $R/$n.log 2>&1\n  local rc=$?\n  echo \"  exit $rc $(date +%T)\"; grep -vE \"^\\[transformers\" $R/$n.log | grep -vE \"^    \" | tail -14\n  [ $rc = 0 ] || fail=1\n}\nfor m in $RUNS; do\n  echo \"=== $m $(date +%T)\"\n  case $m in\n    tower) warm; tower tower ;;\n    stower) warm; tower stower --vision-staged ;;\n    staged)\n      echo \"  warm-up (the staged image's first build, the pieces packed into the pool)\"\n      chat staged staged-w\n      warm; chat staged staged ;;\n    *) warm; chat $m $m ;;\n  esac\ndone\necho \"=== final selftest $(date +%T)\"\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"ALL PASS\" || fail=1\nls -la $O/$POOL $O/$POOL.key\necho \"MCPV2 $([ $fail = 0 ] && echo PASS || echo FAIL) $(date +%T)\"\nexit $fail\n", "tools/offload/sessions/mcpv3.sh": "#!/bin/bash\n# Session mcpv3 (docs/minicpmv.md 6): MiniCPM-V 4.7 (35B-A3B) on the card with this tree's defaults:\n# the staged vision, the tower's wait entries computed ahead (opentpu/host/vision_warm.py) and the\n# faster wait analysis (waits._MemoPass). Also the sliced reference's first run, and what the pool's\n# disk costs (/data is a 7200 rpm disk). Runs (RUNS, default \"warmup sliced thumb text tower pooldisk\"):\n#   warmup    chatmoe.py's text turns, unmeasured: the image's first build for this tree (its keys\n#             are new: ~100-200 s, ~28 GB at its peak, which takes the pool out of the page cache);\n#             the engine's vision_warm process starts\n#   sliced    doc.png at 9 slices (7 crops of 1,008 and 1,024 patches), one turn of 32 tokens,\n#             token-exact against its reference; its vision_s against mcpv2's ~41 s plus ~23 s for\n#             a patch count's first crop\n#   thumb     cats.jpg at max-slices 1, two turns, token-exact against thumb's reference (staged,\n#             the default now)\n#   text      chatmoe.py's two text turns, token-exact\n#   tower     tools/minicpmv_tower.py time on cats.jpg (one crop) and doc.png: each crop's start\n#             seconds (a first crop's ~23 s of wait entries computed at its start, before\n#             vision_warm), and the odd-stride residual's gain (vit_out_mlp, docs/minicpmv.md 6):\n#             out, out2 and last's device time a run against the co-simulation's expected\n#             (3.27 ms a 16-row group; mcpv2's 4.57) and each crop's against mcpv2's ~5.77 s\n#   pooldisk  tools/offload/pool_disk.py: one warm process, the same text turn with the pool in the\n#             page cache and dropped from it (ABBA): decode tok/s and a miss's read time from the\n#             disk against the page cache\n# Each measured run follows the reset of mcpv2: every other file of 100 MB or more under O,\n# ~/openTPU/models and ~/otpu-build/offload leaves the page cache and the pool is read into it.\n# Card: production deploy_r2m4_b10245f5 as loaded (EXPECT b10245f5, register map 5); its\n# qual/cfg.pkl. O (/data/otpu/minicpmv): the slim checkpoint, the pool (its 446 vision entries\n# packed by mcpv2), img/, refs/ (minicpmv-text/thumb/sliced.json), pylib/.\n# POOL_CALLS=1: chatmoe.py --pool-calls (the pool's page cache around each call too).\n# One otpu-lock: selftest (the configuration must be production's), the runs, selftest. A build\n# other than EXPECT, a failed selftest, another configuration or a missing file stops it; a failed\n# run or a token mismatch is reported and the next run goes on. The last line: MCPV3 PASS or\n# MCPV3 FAIL. About 25 min.\n# Stage (from the Mac, before the session; no host work while a session runs):\n#   git archive <sha> | ssh opentpu 'D=~/otpu-build/minicpmv/mcpv3/host; mkdir -p $D && tar -x -C $D'\n#   ssh opentpu 'echo <sha> > ~/otpu-build/minicpmv/mcpv3/host/COMMIT'\n# Run (no pipe): setsid nohup ~/.local/bin/otpu-lock --wait 600 -- bash \\\n#   ~/otpu-build/minicpmv/mcpv3/host/tools/offload/sessions/mcpv3.sh > ~/otpu-build/minicpmv/mcpv3.launch.log 2>&1 \\\n#   < /dev/null &\nset -u\nfor v in $(env | grep -o '^OTPU_[A-Z0-9_]*' | grep -vE '^OTPU_LOCK_(HELD|PID|WAIT)$'); do unset $v; done\nexport OTPU_IMG_CACHE_GB=30 OTPU_IMG_CACHE_FREE_GB=6      # (the card host's, from its ~/.bashrc)\nSESSION=${SESSION:-mcpv3}\nO=${O:-/data/otpu/minicpmv}\nRF=${RF:-$O/refs}\nPD=${PD:-$HOME/otpu-build/deploy_r2m4_b10245f5}        # (production: qual/cfg.pkl)\nREFCFG=${REFCFG:-$PD/qual/cfg.pkl}\nPYLIB=${PYLIB:-$O/pylib}\nsource \"$(dirname \"${BASH_SOURCE[0]}\")/env.sh\"       # (T: this tree; R = O/SESSION; OTPU_QUIET claimed)\nexport PYTHONPATH=$T:$PYLIB\nexec > >(tee -a $R/session.log) 2>&1\nEXPECT=${EXPECT:-b10245f5}\nMAP=${MAP:-register map 5}\nMD=MiniCPM-V-4.7-35B-A3B\nPOOL=pool-mcpv35-mx.split.bin\nRUNS=${RUNS:-warmup sliced thumb text tower pooldisk}\nTHUMB=\"--image 1:$O/img/cats.jpg --max-slices 1 --turn 'Describe this image in one sentence.' --turn 'What colors stand out? One sentence.'\"\ndeclare -A RUN=(        # chatmoe.py's options\n  [warmup]=\"\"\n  [text]=\"\"\n  [sliced]=\"--image 1:$O/img/doc.png --turn 'What does this document say? Two sentences.' --max-new 32\"\n  [thumb]=\"$THUMB\")\ndeclare -A REFOF=([warmup]=text [text]=text [sliced]=sliced [thumb]=thumb)\nfail=0\necho \"mcpv3 start $(date +%T) T $T ($rev) O $O RF $RF mem $(mem) GB, /data $(df -BG --output=avail /data | tail -1 | tr -d ' ') free; $(uptime)\"\n[ -f $T/opentpu/host/vision_warm.py ] && grep -q '_MemoPass' $T/opentpu/waits.py \\\n  && grep -q 'vision_staged: bool = True' $T/opentpu/llm/minicpmv.py \\\n  && grep -q 'odd: bool = True' $T/opentpu/kernels/vit.py \\\n  || { echo \"STOP: T is not the minicpmv tree with vision_warm, waits._MemoPass, staged by default and the odd-stride residual\"; exit 2; }\npython -c \"import torchvision, PIL, transformers; print('  python:', torchvision.__version__, PIL.__version__,\n  transformers.__version__)\" || { echo \"STOP: no torchvision / pillow / transformers under PYLIB $PYLIB\"; exit 2; }\n[ -f $O/$MD/config.json ] && [ -f $O/$POOL ] && [ -f $O/$POOL.key ] && [ -f $O/img/cats.jpg ] && \\\n  [ -f $O/img/doc.png ] && [ -f $REFCFG ] || { echo \"STOP: $O/$MD, $O/$POOL, its key, img/ or $REFCFG missing\"; exit 2; }\ngrep -q '\"vision\"' $O/$POOL.key || { echo \"STOP: the pool's key has no vision entries (mcpv2's staged run packs them)\"; exit 2; }\nfor m in $RUNS; do\n  [ -n \"${REFOF[$m]:-}\" ] || continue\n  [ -f $RF/minicpmv-${REFOF[$m]}.json ] || { echo \"STOP: no reference $RF/minicpmv-${REFOF[$m]}.json\"; exit 2; }\ndone\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"build $EXPECT\" || { echo \"STOP: the card's build is not $EXPECT\"; exit 2; }\necho \"$st\" | grep -q \"$MAP\" || { echo \"STOP: not $MAP\"; exit 2; }\necho \"$st\" | grep -q \"ALL PASS\" || { echo \"STOP: selftest\"; exit 2; }\ntimeout 300 python tools/qual/refs.py cfg $R/cfg-dev.pkl > /dev/null 2>&1; echo \"cfg exit $?\"\npython - $R/cfg-dev.pkl $REFCFG <<'PY' || { echo \"STOP: the device configuration is not the references'\"; exit 2; }\nimport dataclasses, pickle, sys\na, b = (pickle.load(open(f, \"rb\")) for f in sys.argv[1:])\nd = {f.name: (getattr(a, f.name), getattr(b, f.name)) for f in dataclasses.fields(a)\n     if getattr(a, f.name) != getattr(b, f.name)}\nprint(\"  cfg: the references' configuration\" if not d else f\"  cfg DIFFERS (device, ref): {d}\")\nsys.exit(1 if d else 0)\nPY\nwarm() {      # every other file of 100 MB or more out of the page cache, then the pool into it\n  python - $O/$MD $O/$POOL $O:$HOME/openTPU/models:$HOME/otpu-build/offload <<'PY'\nimport os, sys\nkeep = {os.path.realpath(sys.argv[1]), os.path.realpath(sys.argv[2])}\nours = tuple(os.path.realpath(os.path.expanduser(d)) + os.sep\n             for d in (\"~/openTPU\", \"~/otpu-build\", \"/data/otpu\"))\ngb = n = 0\nseen = set()\nfor d in sys.argv[3].split(\":\"):\n    for root, _, files in os.walk(d):\n        for f in files:\n            r = os.path.realpath(os.path.join(root, f))\n            if r in seen or not r.startswith(ours) or not os.path.isfile(r) or \\\n                    os.path.getsize(r) < 100 << 20 or r in keep or os.path.dirname(r) in keep:\n                seen.add(r)\n                continue\n            seen.add(r)\n            fd = os.open(r, os.O_RDONLY)\n            os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n            os.close(fd)\n            gb, n = gb + os.path.getsize(r) / 1e9, n + 1\nprint(f\"  dropped from the page cache: {n} other files of {gb:.1f} GB\")\nPY\n  local t0=$SECONDS\n  dd if=$O/$POOL of=/dev/null bs=16M status=none      # (every block read)\n  echo \"  (pool read in $((SECONDS - t0)) s, mem $(mem) GB, cached $(awk '/^Cached:/ {print int($2/1048576)}' /proc/meminfo) GB)\"\n}\nsummary() {   # a chatmoe.py JSON's lines\n  python - $1 <<'PY'\nimport json, sys\nr = json.load(open(sys.argv[1]))\nprint(f\"  {r['weights']}; {r['experts']}; staged vision {r.get('vision_staged')}; load {r['load_s']} s, \"\n      f\"host {r['host_mem']}\")\nfor i, t in enumerate(r[\"turns\"]):\n    print(f\"  turn {i + 1}: {t.get('images', 0)} images (vision {t.get('vision_s')} s); prompt \"\n          f\"{t['prompt_tokens']} tokens (reused {t['reused']}) in {t['prefill_s']} s ({t['prefill_tok_s']} \"\n          f\"tok/s, device {t['prefill_dev_tok_s']}), {t['prefill_misses']} misses; TTFT {t['ttft_s']} s; decode \"\n          f\"{t['gen_tokens']} tokens at {t['decode_tok_s']} tok/s (device {t['decode_dev_tok_s']}), hits \"\n          f\"{t['hit_rate']}, {t['mb_per_token']} MB/token; end {t['end']}\\n    {t['reply']!r}\")\nPY\n}\nchat() {      # chatmoe.py run $1 (RUN's options), checked against REFOF's reference\n  eval \"timeout 3600 python tools/qual/chatmoe.py $O/$MD --pool $O/$POOL --backend board --cfg $R/cfg-dev.pkl \\\n    --check $RF/minicpmv-${REFOF[$1]}.json --out $R/minicpmv-$1.json ${POOL_CALLS:+--pool-calls} ${RUN[$1]}\" \\\n    > $R/minicpmv-$1.log 2>&1\n  local rc=$?\n  echo \"  exit $rc $(date +%T)\"; grep -E \"\\[(PASS|FAIL)\\]|Error|Traceback\" $R/minicpmv-$1.log | tail -3\n  [ $rc = 0 ] && grep -q \"\\[PASS\\]\" $R/minicpmv-$1.log || fail=1\n  [ -f $R/minicpmv-$1.json ] && summary $R/minicpmv-$1.json\n}\nfor m in $RUNS; do\n  echo \"=== $m $(date +%T)\"\n  case $m in\n    warmup) chat warmup ;;\n    tower)\n      warm\n      timeout 2400 python tools/minicpmv_tower.py time $O/$MD --backend board --cfg $R/cfg-dev.pkl \\\n        --pool $O/$POOL --image $O/img/cats.jpg:1 --image $O/img/doc.png --reps 1 --out $R/tower.json \\\n        > $R/tower.log 2>&1\n      rc=$?; echo \"  exit $rc $(date +%T)\"; grep -vE \"^\\[transformers\" $R/tower.log | grep -vE \"^    \" | tail -12\n      [ $rc = 0 ] || fail=1\n      [ -f $R/tower.json ] && python - $R/tower.json <<'PY'\nimport json, math, sys\nG, G0 = 3.27e-3, 4.57e-3    # s a 16-row group of vit_out_mlp with the MLP: co-sim after the fix, mcpv2's card\nfor im in json.load(open(sys.argv[1]))[\"images\"]:\n    for c in im[\"crops\"]:\n        h, w = c[\"size\"]\n        g = {\"out\": math.ceil(h * w / 16), \"out2\": math.ceil(h * w / 64), \"last\": math.ceil(h * w / 64)}\n        ph = \" \".join(f\"{k} {1e3 * x['device_s'] / x['runs']:.1f} ms a run (expected {1e3 * g[k] * G:.1f}, \"\n                      f\"mcpv2 ~{1e3 * g[k] * G0:.1f})\" for k, x in c[\"phases\"].items() if k in g)\n        print(f\"  crop {h}x{w}: device {c['device_s']:.3f} s (mcpv2 ~5.77 at 1,008-1,024 patches, expected ~4.8); {ph}\")\nPY\n      ;;\n    pooldisk)\n      timeout 2400 python tools/offload/pool_disk.py $O/$MD --pool $O/$POOL --backend board \\\n        --cfg $R/cfg-dev.pkl --out $R/pooldisk.json > $R/pooldisk.log 2>&1\n      rc=$?; echo \"  exit $rc $(date +%T)\"; grep -vE \"^\\[transformers\" $R/pooldisk.log | tail -6\n      [ $rc = 0 ] || fail=1 ;;\n    *) warm; chat $m ;;\n  esac\ndone\necho \"=== MiniCPM-V's pool and checkpoint out of the page cache $(date +%T)\"   # (the card host's 31 GB hold\npython - $O/$POOL $O/$MD <<'PY'           # one 35B pool: after session hostr21 this one's 18 GB stayed, and the next\nimport os, sys                            # session's warm held 63% of production's 35B pool)\ngb = n = 0\nfor a in sys.argv[1:]:\n    fs = [os.path.join(r, f) for r, _, fl in os.walk(a) for f in fl] if os.path.isdir(a) else [a]\n    for f in fs:\n        if os.path.isfile(f):\n            fd = os.open(f, os.O_RDONLY)\n            os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n            os.close(fd)\n            gb, n = gb + os.path.getsize(f) / 1e9, n + 1\nprint(f\"  dropped from the page cache: {n} files of {gb:.1f} GB\")\nPY\necho \"  mem $(mem) GB, cached $(awk '/^Cached:/ {print int($2/1048576)}' /proc/meminfo) GB\"\necho \"=== final selftest $(date +%T)\"\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"ALL PASS\" || fail=1\necho \"MCPV3 $([ $fail = 0 ] && echo PASS || echo FAIL) $(date +%T)\"\nexit $fail\n", "tools/offload/sessions/mtp1.sh": "#!/bin/bash\n# Session mtp1 (docs/offload.md 15.6): the MoE MTP loop on the card, production's host against les-mtp's with --mtp on\n# production's bitstream. les-mtp = release-2's r2 (4ead4e53) + S (the shared expert beside the request, les1: -4.09 ms a\n# token) + the MTP drafter on the streamed 35B: each decode iteration one verify run of the token and its draft\n# through every layer (both rows' experts one request a layer), then the MTP layer's draft (its MoE one more layer\n# of the pool's), the loop on the device (opentpu/llm/mtp.py); greedy, its tokens plain decode's bit for bit.\n# Arms: A = production's host tree (PD/host, d8fe2c15), plain decode from production's pool; B = les-mtp's (TB, its\n# COMMIT), chatmoe --mtp from the MTP pool (QM: the production pool's experts, the MTP layer's 256 after them;\n# pack_pool.py extend + recv). The 35B only (the 26B has no MTP layer). Five turns of --max-new 32: les1's.\n# Predicted (tools/offload/mtp_bound.py on session 16's fit, the co-simulated verify and draft, 38 slots a layer for\n# the MTP image against 41): see docs/offload.md 15.6; acceptance ~0.78 (greedy, base 35B's head, fp4 32K ids).\n# Card: production deploy_r2m4_b10245f5 as loaded (EXPECT b10245f5, register map 5); its qual/cfg.pkl; the ISA\n# references: PD/chatmoe (TURNS' two, production's tree: RF) and les's five-turn ones (RL: chatmoe5-qwen35-35b.json,\n# hwe-bench, r2's configuration; les-mtp's --mtp run on the ISA simulator gave the same tokens). One otpu-lock:\n# 1. selftest; the device configuration must be production's qual/cfg.pkl;\n# 2. a discarded warm-up of each arm (WA, WB: each tree builds its own image; B's the MTP image), then ORDER\n#    (default ABBA x 2), each run after its pool's read (A and B read different pool files: each one wholly in the\n#    page cache before its run, fincore, else STOP; its share after the run reported, so a run whose image read\n#    evicted pool pages shows); every run's tokens must equal RL's in all five turns and RF's first two;\n# 3. selftest; the summary per turn: B - A per pair and of the means (TTFT, prompt device s, decode device ms a\n#    token, hits, MB a token), B's MTP acceptance and decode speedup (A's ms a token / B's), and MTP's share beyond S\n#    (les1's -4.09 ms a token, the 35B's turns 1-2).\n# A build other than EXPECT, a failed selftest, another configuration, a failed or timed-out run or a token mismatch\n# stops it (then the final selftest). About 45 min: 10 runs of 70-120 s, W's builds, and the pools' reads. The two\n# pools (17.5 GB, the MTP one 18.0) do not fit the card host's page cache (31 GB) together: each switch of arm reads\n# the next arm's from the SSD again (~130 s; 7 of the 10 runs), the others' read is from the page cache. Before each\n# read every other file of 100 MB or more under ~/openTPU, ~/otpu-build and /data/otpu leaves the page cache (the\n# image cache's entries too: each run reads its image from the SSD).\n# Stage (from the Mac, before the session, with the lead's go; no host work while a session runs):\n#   git archive <les-mtp sha> | ssh opentpu 'D=~/otpu-build/les/mtp1/host; mkdir -p $D && tar -x -C $D'\n#   ssh opentpu 'echo <les-mtp sha, full> > ~/otpu-build/les/mtp1/host/COMMIT'\n#   scp chatmoe5-qwen35-35b.json opentpu:otpu-build/les/mtp1/refs/\n#   the MTP pool (QM: its disk the lead's choice; opentpu's /data is a 7200 rpm disk): on opentpu at nice / ionice idle, pack_pool.py $O/Qwen3.5-35B-A3B $QM extend\n#   $O/pool-q35-mx.split.bin (card2's verified pool, only read; sha256 before and after), then recv the MTP layer's 256\n#   experts (pack_pool.py ... send --mtp on hwe-bench, ~438 MB relayed through the Mac, sha256 on both sides);\n#   info --mtp: 10496 of 10496 packed, the same key; B's checkpoint (MDB): card2's Qwen3.5-35B-A3B files linked, beside\n#   them mtp.safetensors (the MTP head but its experts, 0.1 GiB: strip_experts.py BASE DIR --mtp --only mtp. --out\n#   mtp.safetensors on hwe-bench, relayed; card2's checkpoint has no mtp.* and is not changed)\n# Run (no pipe; QM the MTP pool's path): QM=... setsid nohup ~/.local/bin/otpu-lock --wait 600 -- bash\n#   ~/otpu-build/les/mtp1/host/tools/offload/sessions/mtp1.sh > ~/otpu-build/les/mtp1.launch.log 2>&1 < /dev/null &\nset -u\nfor v in $(env | grep -o '^OTPU_[A-Z0-9_]*' | grep -vE '^OTPU_LOCK_(HELD|PID|WAIT)$'); do unset $v; done\nexport OTPU_IMG_CACHE_GB=30 OTPU_IMG_CACHE_FREE_GB=6      # (the card host's, from its ~/.bashrc)\nLS=${LS:-$HOME/otpu-build/les/mtp1}\nPD=${PD:-$HOME/otpu-build/deploy_r2m4_b10245f5}  # (production: host/, qual/cfg.pkl, chatmoe/)\nTA=${TA:-$PD/host}\nTB=${TB:-$LS/host}\nRF=${RF:-$PD/chatmoe}\nRL=${RL:-$LS/refs}\nR=${R:-$LS/runs}\nT=$TB\nsource $TB/tools/offload/sessions/env.sh       # (O: card2; OTPU_QUIET claimed, removed at exit)\nexec > >(tee -a $R/session.log) 2>&1\nEXPECT=${EXPECT:-b10245f5}\nMAP=${MAP:-register map 5}\nORDER=${ORDER:-A1 B1 B2 A2 A3 B3 B4 A4}       # (after the warm-ups WA, WB)\nMAXNEW=${MAXNEW:-32}\nS_MS=${S_MS:--4.09}                             # (les1: S, the 35B's decode B - A, ms a token)\nMD=Qwen3.5-35B-A3B\nMDB=${MDB:-$LS/$MD-mtp}                         # (B's checkpoint: card2's files linked, and mtp.safetensors)\nQA=${QA:-pool-q35-mx.split.bin}                 # (in O)\nQM=${QM:?the MTP pool (the lead chooses its disk: beside QA on /home, or on /data and kept warm)}\nDROPOTHER=${DROPOTHER:-$HOME/openTPU:$HOME/otpu-build:/data/otpu}   # (all of ours: mtp1b, 2026-10-14, stopped\n                                # before its first run, MiniCPM-V's pool on /data/otpu cached since session hostr21)\nT1=\"What is the capital of France? Answer in one sentence.\"\nT2=\"And what is it famous for? Two sentences.\"\nT3=\"Which three museums in Paris should a first-time visitor see, and how long does each take?\"\nT4=\"Sum this up in one sentence: $(cat $TB/tools/offload/sessions/wiki1.txt)\"\nT5=\"Name two emperors of that period.\"\nname=qwen35-35b\nfail=0\necho \"mtp1 start $(date +%T) A $TA ($(cat $TA/COMMIT)) B $TB ($(cat $TB/COMMIT)) PD $PD RF $RF RL $RL QM $QM\" \\\n  \"mem $(mem) GB, /home $(df -BG --output=avail /home | tail -1 | tr -d ' ') free; $(uptime)\"\ngrep -q 'mtp_from' $TB/opentpu/host/streamed.py && grep -q '\"--mtp\"' $TB/tools/qual/chatmoe.py \\\n  || { echo \"STOP: TB is not les-mtp (streamed.engine's mtp, chatmoe --mtp)\"; exit 2; }\ngrep -q 'mtp_from' $TA/opentpu/host/streamed.py && { echo \"STOP: TA already has les-mtp's engine\"; exit 2; }\n[ -f $O/$QA ] && [ -f $QM ] && [ -f $RF/chatmoe-$name.json ] && [ -f $RL/chatmoe5-$name.json ] \\\n  || { echo \"STOP: $O/$QA, $QM, $RF/chatmoe-$name.json or $RL/chatmoe5-$name.json missing\"; exit 2; }\n[ -f $MDB/mtp.safetensors ] && [ -f $MDB/config.json ] || { echo \"STOP: $MDB is not B's checkpoint\"; exit 2; }\n(cd $TB && PYTHONPATH=$TB python tools/offload/pack_pool.py $MDB $QM info --mtp) 2>&1 | tail -3 > $R/qm-info.txt\ncat $R/qm-info.txt\ngrep -q \"10496 of 10496 experts packed\" $R/qm-info.txt && grep -q \"the same key\" $R/qm-info.txt \\\n  || { echo \"STOP: the MTP pool is not whole or not this image's\"; exit 2; }\nbusy() { echo \"  host: $(cut -d' ' -f1-3 /proc/loadavg); $(ps -eo pcpu,comm --sort=-pcpu | sed -n 2,4p | tr -s ' ' | tr '\\n' ';')\"; }\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"build $EXPECT\" || { echo \"STOP: the card's build is not $EXPECT\"; exit 2; }\necho \"$st\" | grep -q \"$MAP\" || { echo \"STOP: not $MAP\"; exit 2; }\necho \"$st\" | grep -q \"ALL PASS\" || { echo \"STOP: selftest\"; exit 2; }\ntimeout 300 python tools/qual/refs.py cfg $R/cfg-dev.pkl > /dev/null 2>&1; echo \"cfg exit $?\"\npython - $R/cfg-dev.pkl $PD/qual/cfg.pkl <<'PY' || { echo \"STOP: the device configuration\"; exit 2; }\nimport dataclasses, pickle, sys\na, b = (pickle.load(open(f, \"rb\")) for f in sys.argv[1:])\nd = {f.name: (getattr(a, f.name), getattr(b, f.name)) for f in dataclasses.fields(a)\n     if getattr(a, f.name) != getattr(b, f.name)}\nprint(\"  cfg: production's (qual/cfg.pkl)\" if not d else f\"  cfg DIFFERS from production's: {d}\")\nsys.exit(1 if d else 0)\nPY\nwarm() {   # checkpoint, pool: every other big file out of the page cache, the pool read into it\n  python - $1 $2 $DROPOTHER <<'PY'\nimport os, sys                      # every other file of 100 MB or more out of the page cache\nkeep = {os.path.realpath(sys.argv[1]), os.path.realpath(sys.argv[2])}  # (card_moe.sh's DROPOTHER)\nkeep |= {os.path.realpath(os.path.join(sys.argv[1], f)) for f in os.listdir(sys.argv[1])}  # (B's links)\nours = tuple(os.path.realpath(os.path.expanduser(d)) + os.sep for d in (\"~/openTPU\", \"~/otpu-build\", \"/data/otpu\"))\ngb = n = 0\nseen = set()\nfor d in sys.argv[3].split(\":\"):\n    for root, _, files in os.walk(os.path.expanduser(d)):\n        for f in files:\n            r = os.path.realpath(os.path.join(root, f))\n            if r in seen or not r.startswith(ours) or not os.path.isfile(r) \\\n                    or os.path.getsize(r) < 100 << 20 or r in keep or os.path.dirname(r) in keep:\n                continue\n            seen.add(r)\n            fd = os.open(r, os.O_RDONLY)\n            os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n            os.close(fd)\n            gb, n = gb + os.path.getsize(r) / 1e9, n + 1\nprint(f\"  dropped from the page cache: {n} other files of {gb:.1f} GB\")\nPY\n  local t0=$SECONDS k\n  for k in 1 2; do                      # (every block read; a second read if pages were dropped)\n    dd if=$2 of=/dev/null bs=16M status=none\n    [ \"$(res $2)\" -ge 99 ] && break\n  done\n  echo \"  pool read in $((SECONDS - t0)) s, $(res $2)% of it in the page cache, mem $(mem) GB, cached\" \\\n    \"$(awk '/^Cached:/ {print int($2/1048576)}' /proc/meminfo) GB\"\n  [ \"$(res $2)\" -ge 99 ]\n}\nres() {    # the percentage of a file in the page cache (util-linux fincore)\n  local r=$(fincore -b -n -o RES \"$1\" 2>/dev/null | tr -d ' ')\n  echo $(( ${r:-0} * 100 / $(stat -c %s \"$1\") ))\n}\n# 2. WA, WB, then ORDER; A from TA (plain, production's pool), B from TB (--mtp, the MTP pool)\nfor x in WA WB $ORDER; do\n  case $x in WA|A*) tr=$TA; md=$O/$MD; pool=$O/$QA; extra=\"\";; *) tr=$TB; md=$MDB; pool=$QM; extra=\"--mtp\";; esac\n  echo \"=== q$x $(date +%T) ($name, $(basename $(dirname $tr))/$(basename $tr) $(cut -c1-8 $tr/COMMIT) $extra)\"\n  warm $md $pool || { echo \"STOP: $pool not wholly in the page cache (both arms' pools must be warm)\"; fail=1; break; }\n  busy\n  (cd $tr && PYTHONPATH=$tr timeout 1800 python $tr/tools/qual/chatmoe.py $md --pool $pool --backend board \\\n     --cfg $R/cfg-dev.pkl --turn \"$T1\" --turn \"$T2\" --turn \"$T3\" --turn \"$T4\" --turn \"$T5\" --max-new $MAXNEW \\\n     $extra --out $R/q$x.json > $R/q$x.log 2>&1)\n  rc=$?; echo \"  exit $rc $(date +%T); after it $(res $pool)% of its pool in the page cache\"\n  grep -E \"Error|Traceback\" $R/q$x.log | tail -3\n  [ $rc = 0 ] && [ -f $R/q$x.json ] || { echo \"STOP: q$x\"; fail=1; break; }\n  python - $R/q$x.json $RL/chatmoe5-$name.json $RF/chatmoe-$name.json <<'PY' || { echo \"STOP: q$x differs\"; fail=1; break; }\nimport json, sys\nd, rl, rf = (json.load(open(f)) for f in sys.argv[1:])\ntok = [t[\"tokens\"] for t in d[\"turns\"]]\nok_l = tok == [t[\"tokens\"] for t in rl[\"turns\"]]\nok_f = all(x == t[\"tokens\"] if t[\"end\"] == \"eos\" else x[:len(t[\"tokens\"])] == t[\"tokens\"]   # (RF's at --max-new 16:\n           for x, t in zip(tok, rf[\"turns\"][:2]))                                         #  turn 2 a prefix)\nprint(f\"  [{'PASS' if ok_l and ok_f else 'FAIL'}] tokens {'=' if ok_l else '!='} les's five-turn ISA reference, \"\n      f\"first two {'=' if ok_f else '!='} production's; mtp {d.get('mtp', False)}, {d['experts']}, load {d['load_s']} s\")\nfor i, t in enumerate(d[\"turns\"]):\n    acc = f\", MTP {t['mtp_accepted']} of {t['mtp_iters']} drafts\" if t.get(\"mtp_iters\") else \"\"\n    print(f\"  turn {i + 1}: prompt {t['prompt_tokens']} (reused {t['reused']}) TTFT {t['ttft_s']} s, prefill \"\n          f\"{t['prefill_tok_s']} tok/s (device {t['prefill_dev_tok_s']}), {t['prefill_misses']} misses; decode \"\n          f\"{t['gen_tokens']} at {t['decode_tok_s']} tok/s (device {t['decode_dev_tok_s']}), hits {t['hit_rate']}, \"\n          f\"{t['mb_per_token']} MB/token{acc}; end {t['end']}\")\n    for c in t.get(\"calls\", []):\n        print(f\"    call {c['rows']} rows {'EM' if c['em'] else 'LM'}: {c['s']} s (device {c['device_s']}), \"\n              f\"{c['runs']} runs, misses {c['misses']} ({c['requests']} requests, served in {c['serve_s']} s), \"\n              f\"needs {c['needs_queued']} (hits {c['need_hits']}), holds {c['holds']}\")\nsys.exit(0 if ok_l and ok_f else 1)\nPY\ndone\necho \"=== final selftest $(date +%T)\"\ntimeout 600 python -m opentpu.host.selftest 2>&1 | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"mtp1 end $(date +%T) fail $fail\"\npython - $R \"$ORDER\" \"$S_MS\" <<'PY'\nimport json, os, sys\nr, order, s_ms = sys.argv[1], sys.argv[2].split(), float(sys.argv[3])\na = {x: json.load(open(f\"{r}/q{x}.json\")) if os.path.exists(f\"{r}/q{x}.json\") else None for x in order}\nif None in a.values():\n    print(\"  35B: incomplete\"); sys.exit(0)\nA, B = ([x for x in order if x[0] == c] for c in \"AB\")\npairs = [(b, \"A\" + b[1:]) for b in B if \"A\" + b[1:] in a]\nn = len(a[B[0]][\"turns\"])\ndef tv(x, i, k):\n    t = a[x][\"turns\"][i]\n    if k == \"dev_s\":                    # the prompt's device seconds\n        return t[\"prompt_tokens\"] / t[\"prefill_dev_tok_s\"] if t[\"prefill_dev_tok_s\"] else 0.0\n    if k == \"ms_tok\":                   # the decode's device ms a token\n        return 1000.0 / t[\"decode_dev_tok_s\"] if t[\"decode_dev_tok_s\"] else 0.0\n    return t.get(k) or 0.0\ndef mean(xs, i, k):\n    return sum(tv(x, i, k) for x in xs) / len(xs)\ntot = {\"A\": [0.0, 0], \"B\": [0.0, 0]}\nfor i in range(n):\n    calls = \" + \".join(f\"{c['rows']}{'E' if c['em'] else 'L'}\" for c in a[B[0]][\"turns\"][i].get(\"calls\", []))\n    print(f\"  35B turn {i + 1} ({a[B[0]]['turns'][i]['prompt_tokens']} tokens; {calls}):\")\n    for k, lab, fmt in ((\"ttft_s\", \"TTFT s\", \"+.3f\"), (\"dev_s\", \"prompt device s\", \"+.3f\"),\n                        (\"ms_tok\", \"decode device ms/token\", \"+.2f\"), (\"hit_rate\", \"decode hits\", \"+.4f\"),\n                        (\"mb_per_token\", \"decode MB/token\", \"+.2f\")):\n        d = mean(B, i, k) - mean(A, i, k)\n        print(f\"      {lab}: B - A \" + \" \".join(f\"{tv(b, i, k) - tv(p, i, k):{fmt}}\" for b, p in pairs)\n              + f\", of the means {d:{fmt}}; \" + \", \".join(f\"{x} {tv(x, i, k):{fmt[1:]}}\" for x in order))\n    it = sum(a[x][\"turns\"][i].get(\"mtp_iters\", 0) for x in B)\n    ac = sum(a[x][\"turns\"][i].get(\"mtp_accepted\", 0) for x in B)\n    ma, mb = mean(A, i, \"ms_tok\"), mean(B, i, \"ms_tok\")\n    g = a[B[0]][\"turns\"][i][\"gen_tokens\"]\n    for c, m in ((\"A\", ma), (\"B\", mb)):\n        tot[c][0] += m * g\n        tot[c][1] += g\n    print(f\"      MTP: acceptance {ac / max(1, it):.3f} ({ac} of {it}); decode {ma / mb if mb else 0:.3f}x \"\n          f\"(A {ma:.1f}, B {mb:.1f} ms a token); beyond S ({s_ms:+.2f} ms) {ma / (mb - s_ms) if mb else 0:.3f}x\")\nma, mb = (tot[c][0] / max(1, tot[c][1]) for c in \"AB\")\nprint(f\"  35B decode over the turns (token-weighted): A {ma:.1f}, B {mb:.1f} ms a token: {ma / mb:.3f}x; MTP alone \"\n      f\"(B less S's {s_ms:+.2f}) {ma / (mb - s_ms):.3f}x\")\nPY\ndate > $R/DONE\necho \"MTP1 EXIT $fail $(date +%T)\"\n", "tools/offload/sessions/mtp2.sh": "#!/bin/bash\n# Session mtp2 (docs/offload.md 15.6): mtp1c's A / B again with the two TTFT fixes, and a traced pair. A = production's\n# host tree (PD/host: deploy_hostr21_b10245f5, d966c3df, with S), plain decode from production's pool; B = mcpv-mtp\n# (TB, its COMMIT: les-mtp's MoE MTP drafter with MiniCPM-V on main, and F1b: the loop's first run drafts the prompt's\n# last row; F2: the chat's snapshot at the reply's start holds the row before it), chatmoe --mtp from the MTP pool (QM,\n# mtp1's). The 35B's five les1 turns of --max-new 32. Predicted TTFT B - A from mtp1c's parts with F1b and F2\n# (MODEL, turns 1-5): -0.31 +0.06 +0.33 +0.33 +0.59 s (docs/offload.md 15.6); decode as mtp1c's (1.127x).\n# Card: production deploy_hostr21_b10245f5 as loaded (EXPECT b10245f5, register map 5); its qual/cfg.pkl; the ISA\n# references: PD/chatmoe (TURNS' two: RF) and les's five-turn ones (RL: chatmoe5-qwen35-35b.json in mtp1's refs/).\n# One otpu-lock:\n# 1. selftest; the device configuration must be production's qual/cfg.pkl;\n# 2. a discarded warm-up of each arm (WA, WB: each tree builds its own image), then ORDER (default ABBA x 2), then\n#    TRACE (default AT BT: one run of each arm with chatmoe --trace, each call's runs and the expert server's\n#    timeline; outside the timed runs), each run after its pool's read (both pools wholly in the page cache before\n#    their runs, fincore, else STOP); every run's tokens must equal RL's in all five turns and RF's first two;\n# 3. selftest; the summary per turn as mtp1's, B - A's TTFT against MODEL, and from the traced pair the expert-major\n#    calls (turns 3-5) by run kind: device ms, wall ms, the gaps between runs, the server's parts and requests.\n# A build other than EXPECT, a failed selftest, another configuration, a failed or timed-out run or a token mismatch\n# stops it (then the final selftest). About 50 min: 12 runs of 70-120 s, W's builds, the pools' reads (~130 s from\n# the SSD at each switch of arm: the two pools do not fit the card host's page cache together).\n# Stage (from the Mac, with the lead's go; no host work while a session runs; mtp1's pool, checkpoint and refs as\n# they are in ~/otpu-build/les/mtp1, only read):\n#   git archive <mcpv-mtp sha> | ssh opentpu 'D=~/otpu-build/les/mtp2/host; mkdir -p $D && tar -x -C $D'\n#   ssh opentpu 'echo <mcpv-mtp sha, full> > ~/otpu-build/les/mtp2/host/COMMIT; mkdir -p ~/otpu-build/les/mtp2/runs'\n# Run (no pipe): QM=$HOME/otpu-build/les/mtp1/pool-q35-mx-mtp.split.bin setsid nohup ~/.local/bin/otpu-lock --wait 600 --\n#   bash ~/otpu-build/les/mtp2/host/tools/offload/sessions/mtp2.sh > ~/otpu-build/les/mtp2.launch.log 2>&1 < /dev/null &\nset -u\nfor v in $(env | grep -o '^OTPU_[A-Z0-9_]*' | grep -vE '^OTPU_LOCK_(HELD|PID|WAIT)$'); do unset $v; done\nexport OTPU_IMG_CACHE_GB=30 OTPU_IMG_CACHE_FREE_GB=6      # (the card host's, from its ~/.bashrc)\nLS=${LS:-$HOME/otpu-build/les/mtp2}\nM1=${M1:-$HOME/otpu-build/les/mtp1}               # (mtp1's MTP checkpoint and refs)\nPD=${PD:-$HOME/otpu-build/deploy_hostr21_b10245f5}  # (production: host/, qual/cfg.pkl, chatmoe/)\nTA=${TA:-$PD/host}\nTB=${TB:-$LS/host}\nRF=${RF:-$PD/chatmoe}\nRL=${RL:-$M1/refs}\nR=${R:-$LS/runs}\nT=$TB\nsource $TB/tools/offload/sessions/env.sh       # (O: card2; OTPU_QUIET claimed, removed at exit)\nexec > >(tee -a $R/session.log) 2>&1\nEXPECT=${EXPECT:-b10245f5}\nMAP=${MAP:-register map 5}\nORDER=${ORDER:-A1 B1 B2 A2 A3 B3 B4 A4}       # (after the warm-ups WA, WB)\nTRACE=${TRACE-AT BT}                            # (after ORDER: --trace; empty: none)\nMODEL=${MODEL:--0.31 0.06 0.33 0.33 0.59}       # (TTFT B - A predicted, turns 1-5, s)\nMAXNEW=${MAXNEW:-32}\nS_MS=${S_MS:-0}                                 # (A has S: B - A is MTP alone)\nMD=Qwen3.5-35B-A3B\nMDB=${MDB:-$M1/$MD-mtp}                         # (B's checkpoint: card2's files linked, and mtp.safetensors)\nQA=${QA:-pool-q35-mx.split.bin}                 # (in O)\nQM=${QM:?the MTP pool (the lead chooses its disk: beside QA on /home, or on /data and kept warm)}\nDROPOTHER=${DROPOTHER:-$HOME/openTPU:$HOME/otpu-build:/data/otpu}   # (all of ours: mtp1b, 2026-10-14, stopped\n                                # before its first run, MiniCPM-V's pool on /data/otpu cached since session hostr21)\nT1=\"What is the capital of France? Answer in one sentence.\"\nT2=\"And what is it famous for? Two sentences.\"\nT3=\"Which three museums in Paris should a first-time visitor see, and how long does each take?\"\nT4=\"Sum this up in one sentence: $(cat $TB/tools/offload/sessions/wiki1.txt)\"\nT5=\"Name two emperors of that period.\"\nname=qwen35-35b\nfail=0\necho \"mtp2 start $(date +%T) A $TA ($(cat $TA/COMMIT)) B $TB ($(cat $TB/COMMIT)) PD $PD RF $RF RL $RL QM $QM\" \\\n  \"mem $(mem) GB, /home $(df -BG --output=avail /home | tail -1 | tr -d ' ') free; $(uptime)\"\ngrep -q 'mtp_from' $TB/opentpu/host/streamed.py && grep -q '\"--mtp\"' $TB/tools/qual/chatmoe.py \\\n  && grep -q 'def _settle' $TB/opentpu/llm/mtp.py && grep -q 'def holds' $TB/opentpu/llm/mtp.py \\\n  || { echo \"STOP: TB is not mcpv-mtp with F1b and F2 (streamed.engine's mtp, chatmoe --mtp, MTPDecoder._settle, holds)\"; exit 2; }\ngrep -q 'mtp_from' $TA/opentpu/host/streamed.py && { echo \"STOP: TA already has les-mtp's engine\"; exit 2; }\n[ -f $O/$QA ] && [ -f $QM ] && [ -f $RF/chatmoe-$name.json ] && [ -f $RL/chatmoe5-$name.json ] \\\n  || { echo \"STOP: $O/$QA, $QM, $RF/chatmoe-$name.json or $RL/chatmoe5-$name.json missing\"; exit 2; }\n[ -f $MDB/mtp.safetensors ] && [ -f $MDB/config.json ] || { echo \"STOP: $MDB is not B's checkpoint\"; exit 2; }\n(cd $TB && PYTHONPATH=$TB python tools/offload/pack_pool.py $MDB $QM info --mtp) 2>&1 | tail -3 > $R/qm-info.txt\ncat $R/qm-info.txt\ngrep -q \"10496 of 10496 experts packed\" $R/qm-info.txt && grep -q \"the same key\" $R/qm-info.txt \\\n  || { echo \"STOP: the MTP pool is not whole or not this image's\"; exit 2; }\nbusy() { echo \"  host: $(cut -d' ' -f1-3 /proc/loadavg); $(ps -eo pcpu,comm --sort=-pcpu | sed -n 2,4p | tr -s ' ' | tr '\\n' ';')\"; }\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"build $EXPECT\" || { echo \"STOP: the card's build is not $EXPECT\"; exit 2; }\necho \"$st\" | grep -q \"$MAP\" || { echo \"STOP: not $MAP\"; exit 2; }\necho \"$st\" | grep -q \"ALL PASS\" || { echo \"STOP: selftest\"; exit 2; }\ntimeout 300 python tools/qual/refs.py cfg $R/cfg-dev.pkl > /dev/null 2>&1; echo \"cfg exit $?\"\npython - $R/cfg-dev.pkl $PD/qual/cfg.pkl <<'PY' || { echo \"STOP: the device configuration\"; exit 2; }\nimport dataclasses, pickle, sys\na, b = (pickle.load(open(f, \"rb\")) for f in sys.argv[1:])\nd = {f.name: (getattr(a, f.name), getattr(b, f.name)) for f in dataclasses.fields(a)\n     if getattr(a, f.name) != getattr(b, f.name)}\nprint(\"  cfg: production's (qual/cfg.pkl)\" if not d else f\"  cfg DIFFERS from production's: {d}\")\nsys.exit(1 if d else 0)\nPY\nwarm() {   # checkpoint, pool: every other big file out of the page cache, the pool read into it\n  python - $1 $2 $DROPOTHER <<'PY'\nimport os, sys                      # every other file of 100 MB or more out of the page cache\nkeep = {os.path.realpath(sys.argv[1]), os.path.realpath(sys.argv[2])}  # (card_moe.sh's DROPOTHER)\nkeep |= {os.path.realpath(os.path.join(sys.argv[1], f)) for f in os.listdir(sys.argv[1])}  # (B's links)\nours = tuple(os.path.realpath(os.path.expanduser(d)) + os.sep for d in (\"~/openTPU\", \"~/otpu-build\", \"/data/otpu\"))\ngb = n = 0\nseen = set()\nfor d in sys.argv[3].split(\":\"):\n    for root, _, files in os.walk(os.path.expanduser(d)):\n        for f in files:\n            r = os.path.realpath(os.path.join(root, f))\n            if r in seen or not r.startswith(ours) or not os.path.isfile(r) \\\n                    or os.path.getsize(r) < 100 << 20 or r in keep or os.path.dirname(r) in keep:\n                continue\n            seen.add(r)\n            fd = os.open(r, os.O_RDONLY)\n            os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n            os.close(fd)\n            gb, n = gb + os.path.getsize(r) / 1e9, n + 1\nprint(f\"  dropped from the page cache: {n} other files of {gb:.1f} GB\")\nPY\n  local t0=$SECONDS k\n  for k in 1 2; do                      # (every block read; a second read if pages were dropped)\n    dd if=$2 of=/dev/null bs=16M status=none\n    [ \"$(res $2)\" -ge 99 ] && break\n  done\n  echo \"  pool read in $((SECONDS - t0)) s, $(res $2)% of it in the page cache, mem $(mem) GB, cached\" \\\n    \"$(awk '/^Cached:/ {print int($2/1048576)}' /proc/meminfo) GB\"\n  [ \"$(res $2)\" -ge 99 ]\n}\nres() {    # the percentage of a file in the page cache (util-linux fincore)\n  local r=$(fincore -b -n -o RES \"$1\" 2>/dev/null | tr -d ' ')\n  echo $(( ${r:-0} * 100 / $(stat -c %s \"$1\") ))\n}\n# 2. WA, WB, then ORDER; A from TA (plain, production's pool), B from TB (--mtp, the MTP pool)\nfor x in WA WB $ORDER $TRACE; do\n  case $x in WA|A*) tr=$TA; md=$O/$MD; pool=$O/$QA; extra=\"\";; *) tr=$TB; md=$MDB; pool=$QM; extra=\"--mtp\";; esac\n  echo \"=== q$x $(date +%T) ($name, $(basename $(dirname $tr))/$(basename $tr) $(cut -c1-8 $tr/COMMIT) $extra)\"\n  warm $md $pool || { echo \"STOP: $pool not wholly in the page cache (both arms' pools must be warm)\"; fail=1; break; }\n  case $x in ?T) extra=\"$extra --trace $R/q$x.trace.json\";; esac   # (TRACE's: outside ORDER's timing)\n  busy\n  (cd $tr && PYTHONPATH=$tr timeout 1800 python $tr/tools/qual/chatmoe.py $md --pool $pool --backend board \\\n     --cfg $R/cfg-dev.pkl --turn \"$T1\" --turn \"$T2\" --turn \"$T3\" --turn \"$T4\" --turn \"$T5\" --max-new $MAXNEW \\\n     $extra --out $R/q$x.json > $R/q$x.log 2>&1)\n  rc=$?; echo \"  exit $rc $(date +%T); after it $(res $pool)% of its pool in the page cache\"\n  grep -E \"Error|Traceback\" $R/q$x.log | tail -3\n  [ $rc = 0 ] && [ -f $R/q$x.json ] || { echo \"STOP: q$x\"; fail=1; break; }\n  python - $R/q$x.json $RL/chatmoe5-$name.json $RF/chatmoe-$name.json <<'PY' || { echo \"STOP: q$x differs\"; fail=1; break; }\nimport json, sys\nd, rl, rf = (json.load(open(f)) for f in sys.argv[1:])\ntok = [t[\"tokens\"] for t in d[\"turns\"]]\nok_l = tok == [t[\"tokens\"] for t in rl[\"turns\"]]\nok_f = all(x == t[\"tokens\"] if t[\"end\"] == \"eos\" else x[:len(t[\"tokens\"])] == t[\"tokens\"]   # (RF's at --max-new 16:\n           for x, t in zip(tok, rf[\"turns\"][:2]))                                         #  turn 2 a prefix)\nprint(f\"  [{'PASS' if ok_l and ok_f else 'FAIL'}] tokens {'=' if ok_l else '!='} les's five-turn ISA reference, \"\n      f\"first two {'=' if ok_f else '!='} production's; mtp {d.get('mtp', False)}, {d['experts']}, load {d['load_s']} s\")\nfor i, t in enumerate(d[\"turns\"]):\n    acc = f\", MTP {t['mtp_accepted']} of {t['mtp_iters']} drafts\" if t.get(\"mtp_iters\") else \"\"\n    print(f\"  turn {i + 1}: prompt {t['prompt_tokens']} (reused {t['reused']}) TTFT {t['ttft_s']} s, prefill \"\n          f\"{t['prefill_tok_s']} tok/s (device {t['prefill_dev_tok_s']}), {t['prefill_misses']} misses; decode \"\n          f\"{t['gen_tokens']} at {t['decode_tok_s']} tok/s (device {t['decode_dev_tok_s']}), hits {t['hit_rate']}, \"\n          f\"{t['mb_per_token']} MB/token{acc}; end {t['end']}\")\n    for c in t.get(\"calls\", []):\n        print(f\"    call {c['rows']} rows {'EM' if c['em'] else 'LM'}: {c['s']} s (device {c['device_s']}), \"\n              f\"{c['runs']} runs, misses {c['misses']} ({c['requests']} requests, served in {c['serve_s']} s), \"\n              f\"needs {c['needs_queued']} (hits {c['need_hits']}), holds {c['holds']}\")\nsys.exit(0 if ok_l and ok_f else 1)\nPY\ndone\necho \"=== final selftest $(date +%T)\"\ntimeout 600 python -m opentpu.host.selftest 2>&1 | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"mtp2 end $(date +%T) fail $fail\"\npython - $R \"$ORDER\" \"$S_MS\" \"$MODEL\" <<'PY'\nimport json, os, sys\nr, order, s_ms = sys.argv[1], sys.argv[2].split(), float(sys.argv[3])\nmodel = [float(x) for x in sys.argv[4].split()]\na = {x: json.load(open(f\"{r}/q{x}.json\")) if os.path.exists(f\"{r}/q{x}.json\") else None for x in order}\nif None in a.values():\n    print(\"  35B: incomplete\"); sys.exit(0)\nA, B = ([x for x in order if x[0] == c] for c in \"AB\")\npairs = [(b, \"A\" + b[1:]) for b in B if \"A\" + b[1:] in a]\nn = len(a[B[0]][\"turns\"])\ndef tv(x, i, k):\n    t = a[x][\"turns\"][i]\n    if k == \"dev_s\":                    # the prompt's device seconds\n        return t[\"prompt_tokens\"] / t[\"prefill_dev_tok_s\"] if t[\"prefill_dev_tok_s\"] else 0.0\n    if k == \"ms_tok\":                   # the decode's device ms a token\n        return 1000.0 / t[\"decode_dev_tok_s\"] if t[\"decode_dev_tok_s\"] else 0.0\n    return t.get(k) or 0.0\ndef mean(xs, i, k):\n    return sum(tv(x, i, k) for x in xs) / len(xs)\ntot = {\"A\": [0.0, 0], \"B\": [0.0, 0]}\nfor i in range(n):\n    calls = \" + \".join(f\"{c['rows']}{'E' if c['em'] else 'L'}\" for c in a[B[0]][\"turns\"][i].get(\"calls\", []))\n    print(f\"  35B turn {i + 1} ({a[B[0]]['turns'][i]['prompt_tokens']} tokens; {calls}):\")\n    for k, lab, fmt in ((\"ttft_s\", \"TTFT s\", \"+.3f\"), (\"dev_s\", \"prompt device s\", \"+.3f\"),\n                        (\"ms_tok\", \"decode device ms/token\", \"+.2f\"), (\"hit_rate\", \"decode hits\", \"+.4f\"),\n                        (\"mb_per_token\", \"decode MB/token\", \"+.2f\")):\n        d = mean(B, i, k) - mean(A, i, k)\n        print(f\"      {lab}: B - A \" + \" \".join(f\"{tv(b, i, k) - tv(p, i, k):{fmt}}\" for b, p in pairs)\n              + f\", of the means {d:{fmt}}; \" + \", \".join(f\"{x} {tv(x, i, k):{fmt[1:]}}\" for x in order))\n    it = sum(a[x][\"turns\"][i].get(\"mtp_iters\", 0) for x in B)\n    ac = sum(a[x][\"turns\"][i].get(\"mtp_accepted\", 0) for x in B)\n    ma, mb = mean(A, i, \"ms_tok\"), mean(B, i, \"ms_tok\")\n    g = a[B[0]][\"turns\"][i][\"gen_tokens\"]\n    for c, m in ((\"A\", ma), (\"B\", mb)):\n        tot[c][0] += m * g\n        tot[c][1] += g\n    print(f\"      TTFT B - A of the means {mean(B, i, 'ttft_s') - mean(A, i, 'ttft_s'):+.3f} s against the \"\n          f\"model's {model[i]:+.2f} (mtp1c's parts less F1b's and F2's)\" if i < len(model) else \"\")\n    print(f\"      MTP: acceptance {ac / max(1, it):.3f} ({ac} of {it}); decode {ma / mb if mb else 0:.3f}x \"\n          f\"(A {ma:.1f}, B {mb:.1f} ms a token); beyond S ({s_ms:+.2f} ms) {ma / (mb - s_ms) if mb else 0:.3f}x\")\nma, mb = (tot[c][0] / max(1, tot[c][1]) for c in \"AB\")\nprint(f\"  35B decode over the turns (token-weighted): A {ma:.1f}, B {mb:.1f} ms a token: {ma / mb:.3f}x; MTP alone \"\n      f\"(B less S's {s_ms:+.2f}) {ma / (mb - s_ms):.3f}x\")\nPY\n[ -f $R/qAT.trace.json ] && [ -f $R/qBT.trace.json ] && python - $R <<'PY'\nimport json, sys                # the traced pair's prompt calls in turns 3-5 (expert-major's), by run kind\nr = sys.argv[1]\ntr = {x: json.load(open(f\"{r}/q{x}.trace.json\"))[\"calls\"] for x in (\"AT\", \"BT\")}\njs = {x: json.load(open(f\"{r}/q{x}.json\")) for x in (\"AT\", \"BT\")}\ndef kind(k):                    # (qwen3.layer_programs' keys)\n    if not isinstance(k, list):\n        return str(k)\n    return {\"x\": \"expert\", \"m\": \"mtp kv\", \"v\": \"vis\", -1: \"embed\"}.get(k[0], \"layer\")\nfor i in (2, 3, 4):\n    out = {}\n    for x in (\"AT\", \"BT\"):\n        n0 = sum(len(t[\"calls\"]) for t in js[x][\"turns\"][:i])\n        cs = js[x][\"turns\"][i][\"calls\"]\n        k, rows, parts, req = {}, [], 0.0, 0.0\n        for c, cj in zip(tr[x][n0:n0 + len(cs)], cs):\n            cyc = sum(run[3] or 0 for run in c[\"runs\"] if len(run) >= 4)\n            khz = cyc / (cj[\"device_s\"] * 1e3) if cj.get(\"device_s\") else 133333.0\n            rows.append(f\"{c['rows']} {'EM' if c['em'] else 'LM'}\")\n            prev = None\n            for run in c[\"runs\"]:\n                if len(run) < 4:\n                    continue\n                key, t0, t1, cy = run[:4]\n                d = k.setdefault(kind(key), [0, 0.0, 0.0, 0.0])\n                d[0] += 1\n                d[1] += (cy or 0) / khz\n                d[2] += 1e3 * (t1 - t0)\n                d[3] += 0.0 if prev is None else 1e3 * max(0.0, t0 - prev)\n                prev = t1\n            parts += sum(e[1] - e[0] for e in c[\"events\"] if e[2] == \"p\")\n            req += sum(e[1] - e[0] for e in c[\"events\"] if e[2] == \"d\")\n        out[x] = (rows, k, parts, req, js[x][\"turns\"][i][\"ttft_s\"])\n    print(f\"  turn {i + 1}: TTFT {out['AT'][4]} / {out['BT'][4]} s (AT / BT); calls \" +\n          \"; \".join(f\"{x} {', '.join(o[0])}\" for x, o in out.items()))\n    tot = [[0.0] * 3 for _ in range(2)]\n    for kd in sorted(set(out[\"AT\"][1]) | set(out[\"BT\"][1])):\n        a, b = (out[x][1].get(kd, [0, 0.0, 0.0, 0.0]) for x in (\"AT\", \"BT\"))\n        for t, v in zip(tot, (a, b)):\n            t[0] += v[1]; t[1] += v[2]; t[2] += v[3]\n        print(f\"    {kd:7s} runs {a[0]:5d} / {b[0]:5d}; device ms {a[1]:8.1f} / {b[1]:8.1f} ({b[1] - a[1]:+7.1f}); \"\n              f\"wall ms {a[2]:8.1f} / {b[2]:8.1f} ({b[2] - a[2]:+7.1f}); gaps before ms {a[3]:7.1f} / {b[3]:7.1f} \"\n              f\"({b[3] - a[3]:+7.1f})\")\n    a, b = tot\n    print(f\"    all     device ms {a[0]:.1f} / {b[0]:.1f} ({b[0] - a[0]:+.1f}); wall ms {a[1]:.1f} / {b[1]:.1f} \"\n          f\"({b[1] - a[1]:+.1f}); gaps ms {a[2]:.1f} / {b[2]:.1f} ({b[2] - a[2]:+.1f}); server parts \"\n          f\"{out['AT'][2]:.3f} / {out['BT'][2]:.3f} s, requests {out['AT'][3]:.3f} / {out['BT'][3]:.3f} s\")\nPY\ndate > $R/DONE\necho \"MTP2 EXIT $fail $(date +%T)\"\n", "tools/offload/sessions/mtps.sh": "#!/bin/bash\n# Session mtps (docs/offload.md 15.6): otpu-serve with and without --mtp on the streamed 35B, for MTP by default in the\n# server. Both arms from this tree (T: serve-mtp), so only --mtp differs: A = otpu-serve from production's pool (O/QA,\n# card2's checkpoint), B = otpu-serve --mtp from the MTP pool (QM, mtp1's checkpoint MDB). Each run: the arm's pool read\n# into the page cache (~130 s at a switch of arm: the two pools do not fit the page cache together), the server up\n# (/health 200), tools/serve_bench.py: its check part (each prompt alone, then all at once, a repeat: the same replies),\n# throughput at 1, 2 and 4 clients greedy and 4 sampled (the model's sampling, seeded), a three-turn conversation and\n# four arrivals one every 1.5 s, --max-tokens MAXTOK; then the server's /v1/stats (the context switches: restores,\n# restore_s, save_s; MTP's iterations and accepted drafts) and its stop. Order: a warm-up of each arm (WA, WB: the check\n# part alone; this tree's images' first builds), then ORDER (A1 B1 B2 A2).\n# Checks: every serve_bench check part PASS; B's check replies A's (greedy: MTP's loop is plain decode's bit for bit).\n# Default-on rule, B against A (the means of the arm's runs): aggregate tok/s >= A's at 1, 2 and 4 clients and >= 1.05x\n# A's at 4; the TTFT medians (throughput levels, conversation turns, arrivals) at most 0.3 s more; the arrivals' gap p99\n# at most 1.2x A's; and the checks. The summary prints each measure per run, B - A or B / A, the restore ms a context\n# switch (restore_s / restores) of each arm, and the rule's verdict (MTPS DEFAULT-ON: YES / NO, and why).\n# ADDON=1: the same on the dense Qwen3.5-4B (its own mtp.* layer; A plain, B --mtp; no pools), W4A W4B A41 B41 after\n# the 35B, reported apart (not in the rule).\n# On a tree whose tiled expert-major runs take the states' slot 0 only (before mtp-slot-fix), both arms run untiled\n# (OTPU_TILE=0).\n# A build other than EXPECT, a failed selftest, a server that does not come up, a failed check or a run past its timeout\n# stops it (then the final selftest). About 70 min at MAXTOK 128 (6 runs of the 35B, ~8-10 min each with the pool reads;\n# the add-on ~20 min more).\n# Stage (from the Mac; no host work while a session runs):\n#   git archive <serve-mtp sha> | ssh opentpu 'D=~/otpu-build/les/mtps/host; mkdir -p $D && tar -x -C $D'\n#   ssh opentpu 'echo <serve-mtp sha, full> > ~/otpu-build/les/mtps/host/COMMIT; mkdir -p ~/otpu-build/les/mtps/runs'\n# Run (no pipe), inside a held session (OTPU_LOCK_HELD set) directly, else under otpu-lock:\n#   EXPECT=<build> setsid -f ~/.local/bin/otpu-lock --wait 600 -- bash ~/otpu-build/les/mtps/host/tools/offload/\\\n#     sessions/mtps.sh > ~/otpu-build/les/mtps.launch.log 2>&1 < /dev/null\nset -u\n[ -n \"${OTPU_LOCK_HELD:-}\" ] || { echo \"run under otpu-lock\"; exit 1; }\nfor v in $(env | grep -o '^OTPU_[A-Z0-9_]*' | grep -vE '^OTPU_LOCK_(HELD|PID|WAIT)$'); do unset $v; done\nexport OTPU_IMG_CACHE_GB=30 OTPU_IMG_CACHE_FREE_GB=6      # (the card host's, from its ~/.bashrc)\nLS=${LS:-$HOME/otpu-build/les/mtps}\nM1=${M1:-$HOME/otpu-build/les/mtp1}               # (mtp1's MTP checkpoint and pool)\nR=${R:-$LS/runs}\nsource $(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)/env.sh   # (T: this tree; O: card2; OTPU_QUIET claimed)\nexec > >(tee -a $R/session.log) 2>&1\nEXPECT=${EXPECT:?the card build as the selftest prints it, e.g. 039b34d5}\nORDER=${ORDER:-A1 B1 B2 A2}                     # (after the warm-ups WA, WB)\nMAXTOK=${MAXTOK:-128}\nADDON=${ADDON:-0}\nPORT=${PORT:-8021}\nMD=Qwen3.5-35B-A3B\nMDB=${MDB:-$M1/$MD-mtp}                         # (B's checkpoint: card2's files linked, and mtp.safetensors)\nQA=${QA:-pool-q35-mx.split.bin}                 # (in O, read only)\nQM=${QM:-$M1/pool-q35-mx-mtp.split.bin}\nM4=${M4:-qwen35-4b}                             # (the add-on's model: a name or a checkpoint directory)\nDROPOTHER=${DROPOTHER:-$HOME/openTPU:$HOME/otpu-build:/data/otpu}\nfail=0\necho \"mtps start $(date +%T) T $T ($rev) O $O QM $QM MDB $MDB ORDER $ORDER MAXTOK $MAXTOK ADDON $ADDON mem $(mem) GB;\" \\\n  \"$(uptime)\"\ngrep -q '\"--mtp\"' $T/opentpu/serve/api.py && grep -q 'def _decode_mtp' $T/opentpu/serve/scheduler.py \\\n  || { echo \"STOP: T has no otpu-serve --mtp\"; exit 2; }\n[ -f $O/$QA ] && [ -f $QM ] && [ -f $MDB/mtp.safetensors ] && [ -d $O/$MD ] \\\n  || { echo \"STOP: $O/$QA, $QM, $MDB/mtp.safetensors or $O/$MD missing\"; exit 2; }\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"build $EXPECT\" || { echo \"STOP: the card's build is not $EXPECT\"; exit 2; }\necho \"$st\" | grep -q \"ALL PASS\" || { echo \"STOP: selftest\"; exit 2; }\nif grep -q \"a tiled layer run takes the states' slot 0\" $T/opentpu/llm/qwen3.py; then\n  export OTPU_TILE=0      # (this tree's tiled expert-major runs take the states' slot 0 only: MTP's slot 1 raises)\n  echo \"  OTPU_TILE=0 for both arms: no tiled runs in MTP's slot 1 on this tree (mtp-slot-fix)\"\nfi\nfor p in \"$O/$MD $O/$QA\" \"$MDB $QM --mtp\"; do\n  set -- $p\n  (python tools/offload/pack_pool.py $1 $2 info ${3:-}) 2>&1 | tail -3 > $R/info-$(basename $2).txt\n  cat $R/info-$(basename $2).txt\n  grep -q \"the same key\" $R/info-$(basename $2).txt && grep -qE \"([0-9]+) of \\1 experts packed\" $R/info-$(basename $2).txt \\\n    || { echo \"STOP: $2 is not whole or not this image's\"; exit 2; }\ndone\ntree() { local x; for x in \"$@\"; do echo $x; tree $(pgrep -P $x); done; }\nlive() { local x; for x in \"$@\"; do kill -0 $x 2> /dev/null && echo $x; done; }\nstop_tree() {   # hostr21.sh's: TERM to the server's process group (timeout's), 30 s, then KILL\n  local p=$1 g w all left\n  g=$(ps -o pgid= -p $p | tr -d ' ')\n  [ \"$g\" = \"$p\" ] || g=\"\"\n  all=$(tree $p | tr '\\n' ' ')\n  if [ -n \"$g\" ]; then kill -- -$g 2> /dev/null; else kill $all 2> /dev/null; fi\n  for w in $(seq 1 30); do\n    left=$( { [ -n \"$g\" ] && pgrep -g $g; live $all; } | sort -u | tr '\\n' ' ')\n    [ -z \"${left// }\" ] && break; sleep 1; done\n  if [ -n \"${left// }\" ]; then echo \"  stop_tree: $left still alive after 30 s: KILL\"\n    [ -n \"$g\" ] && kill -9 -- -$g 2> /dev/null; kill -9 $left 2> /dev/null; sleep 2; fi\n  wait $p 2> /dev/null\n}\nxdma_free() {\n  local w u\n  for w in $(seq 1 60); do u=$(lsof -t /dev/xdma0_* 2> /dev/null | tr '\\n' ' '); [ -z \"$u\" ] && return 0; sleep 1; done\n  echo \"  /dev/xdma0 still open by pids $u: FAIL\"; return 1\n}\nwarm() {   # checkpoint, pool: every other big file out of the page cache, the pool read into it (mtp2.sh's)\n  python - $1 $2 $DROPOTHER <<'PY'\nimport os, sys\nkeep = {os.path.realpath(sys.argv[1]), os.path.realpath(sys.argv[2])}\nkeep |= {os.path.realpath(os.path.join(sys.argv[1], f)) for f in os.listdir(sys.argv[1])}  # (B's links)\nours = tuple(os.path.realpath(os.path.expanduser(d)) + os.sep for d in (\"~/openTPU\", \"~/otpu-build\", \"/data/otpu\"))\ngb = n = 0\nseen = set()\nfor d in sys.argv[3].split(\":\"):\n    for root, _, files in os.walk(os.path.expanduser(d)):\n        for f in files:\n            r = os.path.realpath(os.path.join(root, f))\n            if r in seen or not r.startswith(ours) or not os.path.isfile(r) \\\n                    or os.path.getsize(r) < 100 << 20 or r in keep or os.path.dirname(r) in keep:\n                continue\n            seen.add(r)\n            fd = os.open(r, os.O_RDONLY)\n            os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n            os.close(fd)\n            gb, n = gb + os.path.getsize(r) / 1e9, n + 1\nprint(f\"  dropped from the page cache: {n} other files of {gb:.1f} GB\")\nPY\n  local t0=$SECONDS k\n  for k in 1 2; do\n    dd if=$2 of=/dev/null bs=16M status=none\n    [ \"$(res $2)\" -ge 99 ] && break\n  done\n  echo \"  pool read in $((SECONDS - t0)) s, $(res $2)% of it in the page cache, mem $(mem) GB\"\n  [ \"$(res $2)\" -ge 99 ]\n}\nres() {\n  local r=$(fincore -b -n -o RES \"$1\" 2>/dev/null | tr -d ' ')\n  echo $(( ${r:-0} * 100 / $(stat -c %s \"$1\") ))\n}\none() {   # run name, model, pool or \"\", extra server flags, serve_bench flags\n  local x=$1 md=$2 pool=$3 flags=$4 bench=$5 sp rb\n  echo \"=== $x $(date +%T) ($md $flags)\"\n  if [ -n \"$pool\" ] && [ \"$(res $pool)\" -lt 99 ]; then warm $md $pool || { echo \"STOP: $pool not in the page cache\"; return 1; }; fi\n  rm -rf $R/kv-$x\n  (cd /tmp && exec env PYTHONPATH=$T timeout 3000 python -m opentpu.serve.api --model $md --backend board \\\n     ${pool:+--pool $pool} $flags --port $PORT --kv-ram-gb 2 --kv-dir $R/kv-$x) > $R/$x.serve.log 2>&1 &\n  sp=$!\n  (cd $T && timeout 2700 python tools/serve_bench.py --port $PORT --max-tokens $MAXTOK $bench --out $R/$x.json \\\n     > $R/$x.bench.log 2>&1)\n  rb=$?\n  echo \"  serve_bench exit $rb $(date +%T)\"; grep -E \"check:|throughput:|^turn |arrivals:|did not come up\" $R/$x.bench.log \\\n    | cut -c1-260\n  stop_tree $sp; xdma_free || rb=1\n  grep -E \"Error|Traceback\" $R/$x.serve.log | tail -3\n  [ $rb = 0 ] && grep -q \"check: PASS\" $R/$x.bench.log\n}\nWARM=\"--skip throughput,conversation,users,arrivals --check-prompts 2 --check-tokens 16\"\nFULL=\"--levels 1,2,4 --sampled-levels 4 --turns 3 --arrivals 4 --users 0\"\nfor x in WA WB $ORDER; do\n  case $x in A*|WA) md=$O/$MD; pool=$O/$QA; flags=\"\";; *) md=$MDB; pool=$QM; flags=\"--mtp\";; esac\n  case $x in W?) bench=$WARM;; *) bench=$FULL;; esac\n  one q$x $md $pool \"$flags\" \"$bench\" || { echo \"STOP: q$x\"; fail=1; break; }\ndone\nif [ $fail = 0 ] && [ \"$ADDON\" = 1 ]; then\n  for x in W4A W4B A41 B41; do\n    case $x in *A*) flags=\"\";; *) flags=\"--mtp\";; esac\n    case $x in W*) bench=$WARM;; *) bench=$FULL;; esac\n    one q$x $M4 \"\" \"$flags\" \"$bench\" || { echo \"STOP: q$x (the add-on)\"; fail=1; break; }\n  done\nfi\necho \"=== final selftest $(date +%T)\"\ntimeout 600 python -m opentpu.host.selftest 2>&1 | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\n[ $fail = 0 ] && python - $R \"$ORDER\" $ADDON <<'PY' || fail=1\nimport json, os, statistics as S, sys\nr, order, addon = sys.argv[1], sys.argv[2].split(), sys.argv[3] == \"1\"\ndef load(x):\n    return json.load(open(f\"{r}/q{x}.json\"))\ndef measures(d):\n    m = {}\n    for t in d.get(\"throughput\", []):\n        k = f\"{t['clients']}{'s' if t['sampled'] else ''}\"\n        m[f\"tok/s {k}\"] = t[\"aggregate_tok_s\"]\n        m[f\"TTFT {k}\"] = t[\"ttft_s\"][\"median\"]\n    conv = d.get(\"conversation\", [])\n    if conv:\n        m[\"TTFT conv\"] = S.median(c[\"ttft_s\"] for c in conv)\n    a = d.get(\"arrivals\")\n    if a:\n        m[\"TTFT arrivals\"] = S.median(a[\"ttft_s\"])\n        m[\"gap p99 ms\"] = a[\"gap_ms\"][\"p99\"]\n    st = d.get(\"stats\", {})\n    m[\"restore ms\"] = round(1e3 * st[\"restore_s\"] / st[\"restores\"], 1) if st.get(\"restores\") else None\n    m[\"save ms\"] = round(1e3 * st[\"save_s\"] / st[\"saves\"], 1) if st.get(\"saves\") else None\n    if st.get(\"mtp_iters\"):\n        m[\"acceptance\"] = round(st[\"mtp_accepted\"] / st[\"mtp_iters\"], 3)\n    return m\ndef pair(As, Bs, label):\n    a, b = [load(x) for x in As], [load(x) for x in Bs]\n    ok = all(x[\"check\"][\"pass\"] for x in a + b)\n    same = all(x[\"check\"][\"solo\"] == a[0][\"check\"][\"solo\"] for x in a + b)\n    print(f\"  [{'PASS' if ok and same else 'FAIL'}] {label}: check parts {'PASS' if ok else 'FAIL'}, B's replies \"\n          f\"{'=' if same else '!='} A's\")\n    ma, mb = ([measures(x) for x in xs] for xs in (a, b))\n    keys = [k for k in ma[0] if all(k in m and m[k] is not None for m in ma + mb)]\n    mean = {c: {k: S.mean(m[k] for m in ms) for k in keys} for c, ms in ((\"A\", ma), (\"B\", mb))}\n    for k in keys:\n        rel = f\"B / A {mean['B'][k] / mean['A'][k]:.3f}\" if mean[\"A\"][k] else \"\"\n        print(f\"    {k:14s} \" + \"  \".join(f\"{x} {m[k]}\" for x, m in zip(As + Bs, ma + mb)) +\n              f\"  | A {mean['A'][k]:.3f} B {mean['B'][k]:.3f}  B - A {mean['B'][k] - mean['A'][k]:+.3f}  {rel}\")\n    return ok and same, mean\nok, mean = pair([x for x in order if x[0] == \"A\"], [x for x in order if x[0] == \"B\"], \"35B\")\nA, B = mean[\"A\"], mean[\"B\"]\nwhy = []\nfor c in (\"1\", \"2\", \"4\"):\n    k = f\"tok/s {c}\"\n    if k in A and B[k] < A[k]:\n        why.append(f\"{k} {B[k]:.2f} < A's {A[k]:.2f}\")\nif \"tok/s 4\" in A and B[\"tok/s 4\"] < 1.05 * A[\"tok/s 4\"]:\n    why.append(f\"tok/s 4 {B['tok/s 4']:.2f} under 1.05x A's {A['tok/s 4']:.2f}\")\nfor k in [k for k in A if k.startswith(\"TTFT\")]:\n    if B[k] > A[k] + 0.3:\n        why.append(f\"{k} {B[k]:.3f} s, A's + {B[k] - A[k]:.3f}\")\nif \"gap p99 ms\" in A and B[\"gap p99 ms\"] > 1.2 * A[\"gap p99 ms\"]:\n    why.append(f\"gap p99 {B['gap p99 ms']:.1f} ms over 1.2x A's {A['gap p99 ms']:.1f}\")\nif not ok:\n    why.append(\"a check failed\")\nprint(f\"MTPS DEFAULT-ON: {'YES' if not why else 'NO'}\" + (\"\" if not why else \" (\" + \"; \".join(why) + \")\"))\nif addon and all(os.path.exists(f\"{r}/q{x}.json\") for x in (\"A41\", \"B41\")):\n    ok4, _ = pair([\"A41\"], [\"B41\"], \"4B add-on (not in the rule)\")\n    ok = ok and ok4\nsys.exit(0 if ok else 1)\nPY\ndate > $R/DONE\necho \"MTPS EXIT $fail $(date +%T)\"\n", "tools/offload/sessions/mtpt.sh": "#!/bin/bash\n# Session step mtpt (docs/offload.md 15.6): mtp2's TTFT left +0.10..0.13 s of B - A outside the prompt's calls in turns\n# 2-5 (mtp1c +0.13..0.16); one traced run of each arm with chatmoe --trace's host phases (tools/qual/chatmoe.py\n# _Phases: rollback, each prefill_layers and its end_prefill, the snapshot and MTP's held row's read, MTP's own prefill,\n# a0, the device runs outside the calls) puts each turn's TTFT in its parts. Both arms from this tree (T: the stamps\n# branch), so only MTP differs: A = plain decode from production's pool (O/QA, card2's checkpoint), B = --mtp from the\n# MTP pool (QM, mtp1's checkpoint MDB). The 35B's five les1 turns of --max-new 32, as mtp2.\n# Self-contained, ~10 min, on whatever bitstream the card has (EXPECT: its build, as selftest prints it): selftest,\n# the device's configuration (refs.py cfg), both pools' keys against this tree's image (pack_pool.py info); then per\n# arm its pool read into the page cache (~70 s at a switch), a warm-up run (the image's first build for this tree and\n# configuration, one turn, untimed) and the traced run; selftest. Tokens: A's and B's the same in every turn (MTP's\n# greedy loop is plain decode's bit for bit), and with REF (a five-turn chatmoe JSON on this configuration, e.g. mtp1's\n# refs/chatmoe5-qwen35-35b.json on production's m4) each arm's equal to it. A build other than EXPECT, a failed\n# selftest, a pool not this image's, a failed run or another token stops it (then the final selftest).\n# On a tree whose tiled expert-major runs take the states' slot 0 only (before mtp-slot-fix: MTP's slot 1 raises\n# at the first expert-major prompt after a loop that ended there), both arms run untiled (OTPU_TILE=0).\n# Output: R/q{WA,AT,WB,BT}.{log,json}, R/q{AT,BT}.trace.json, and per turn A's and B's TTFT, the calls, each phase's\n# seconds and the rest of the TTFT outside them, B - A; the last line MTPT EXIT <fails>.\n# Stage (from the Mac; no host work while a session runs):\n#   git archive <stamps sha> | ssh opentpu 'D=~/otpu-build/les/mtpt/host; mkdir -p $D && tar -x -C $D'\n#   ssh opentpu 'echo <stamps sha, full> > ~/otpu-build/les/mtpt/host/COMMIT; mkdir -p ~/otpu-build/les/mtpt/runs'\n# Run (no pipe), inside a held session (OTPU_LOCK_HELD set) directly, else under otpu-lock:\n#   EXPECT=<build> setsid -f ~/.local/bin/otpu-lock --wait 600 -- bash ~/otpu-build/les/mtpt/host/tools/offload/\\\n#     sessions/mtpt.sh > ~/otpu-build/les/mtpt.launch.log 2>&1 < /dev/null\nset -u\n[ -n \"${OTPU_LOCK_HELD:-}\" ] || { echo \"run under otpu-lock\"; exit 1; }\nfor v in $(env | grep -o '^OTPU_[A-Z0-9_]*' | grep -vE '^OTPU_LOCK_(HELD|PID|WAIT)$'); do unset $v; done\nexport OTPU_IMG_CACHE_GB=30 OTPU_IMG_CACHE_FREE_GB=6      # (the card host's, from its ~/.bashrc)\nLS=${LS:-$HOME/otpu-build/les/mtpt}\nM1=${M1:-$HOME/otpu-build/les/mtp1}               # (mtp1's MTP checkpoint and pool)\nR=${R:-$LS/runs}\nsource $(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)/env.sh   # (T: this tree; O: card2; OTPU_QUIET claimed)\nexec > >(tee -a $R/session.log) 2>&1\nEXPECT=${EXPECT:?the card build as the selftest prints it, e.g. 039b34d5}\nREF=${REF:-}                                    # (a five-turn reference on this configuration; empty: A = B only)\nMAXNEW=${MAXNEW:-32}\nMD=Qwen3.5-35B-A3B\nMDB=${MDB:-$M1/$MD-mtp}                         # (B's checkpoint: card2's files linked, and mtp.safetensors)\nQA=${QA:-pool-q35-mx.split.bin}                 # (in O, read only)\nQM=${QM:-$M1/pool-q35-mx-mtp.split.bin}\nDROPOTHER=${DROPOTHER:-$HOME/openTPU:$HOME/otpu-build:/data/otpu}\nT1=\"What is the capital of France? Answer in one sentence.\"\nT2=\"And what is it famous for? Two sentences.\"\nT3=\"Which three museums in Paris should a first-time visitor see, and how long does each take?\"\nT4=\"Sum this up in one sentence: $(cat $T/tools/offload/sessions/wiki1.txt)\"\nT5=\"Name two emperors of that period.\"\nfail=0\necho \"mtpt start $(date +%T) T $T ($rev) O $O QM $QM MDB $MDB REF ${REF:-none} mem $(mem) GB; $(uptime)\"\ngrep -q 'class _Phases' $T/tools/qual/chatmoe.py && grep -q 'def holds' $T/opentpu/llm/mtp.py \\\n  || { echo \"STOP: T has no chatmoe phases or no MTP held rows\"; exit 2; }\n[ -f $O/$QA ] && [ -f $QM ] && [ -f $MDB/mtp.safetensors ] && [ -d $O/$MD ] && { [ -z \"$REF\" ] || [ -f \"$REF\" ]; } \\\n  || { echo \"STOP: $O/$QA, $QM, $MDB/mtp.safetensors, $O/$MD or REF missing\"; exit 2; }\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"build $EXPECT\" || { echo \"STOP: the card's build is not $EXPECT\"; exit 2; }\necho \"$st\" | grep -q \"ALL PASS\" || { echo \"STOP: selftest\"; exit 2; }\nif grep -q \"a tiled layer run takes the states' slot 0\" $T/opentpu/llm/qwen3.py; then\n  export OTPU_TILE=0      # (this tree's tiled expert-major runs take the states' slot 0 only: MTP's slot 1 raises)\n  echo \"  OTPU_TILE=0 for both arms: no tiled runs in MTP's slot 1 on this tree (mtp-slot-fix)\"\nfi\ntimeout 300 python tools/qual/refs.py cfg $R/cfg-dev.pkl > /dev/null 2>&1; echo \"cfg exit $?\"\n[ -f $R/cfg-dev.pkl ] || { echo \"STOP: no device configuration\"; exit 2; }\npython - $R/cfg-dev.pkl <<'PY'\nimport pickle, sys\nc = pickle.load(open(sys.argv[1], \"rb\"))\nprint(f\"  cfg: MCOLS {c.MCOLS}, S {c.S}, DRAM {c.DRAM_BYTES >> 20} MiB\")\nPY\nfor p in \"$O/$MD $O/$QA\" \"$MDB $QM --mtp\"; do\n  set -- $p\n  (python tools/offload/pack_pool.py $1 $2 info ${3:-}) 2>&1 | tail -3 > $R/info-$(basename $2).txt\n  cat $R/info-$(basename $2).txt\n  grep -q \"the same key\" $R/info-$(basename $2).txt && grep -qE \"([0-9]+) of \\1 experts packed\" $R/info-$(basename $2).txt \\\n    || { echo \"STOP: $2 is not whole or not this image's\"; exit 2; }\ndone\nwarm() {   # checkpoint, pool: every other big file out of the page cache, the pool read into it (mtp2.sh's)\n  python - $1 $2 $DROPOTHER <<'PY'\nimport os, sys\nkeep = {os.path.realpath(sys.argv[1]), os.path.realpath(sys.argv[2])}\nkeep |= {os.path.realpath(os.path.join(sys.argv[1], f)) for f in os.listdir(sys.argv[1])}  # (B's links)\nours = tuple(os.path.realpath(os.path.expanduser(d)) + os.sep for d in (\"~/openTPU\", \"~/otpu-build\", \"/data/otpu\"))\ngb = n = 0\nseen = set()\nfor d in sys.argv[3].split(\":\"):\n    for root, _, files in os.walk(os.path.expanduser(d)):\n        for f in files:\n            r = os.path.realpath(os.path.join(root, f))\n            if r in seen or not r.startswith(ours) or not os.path.isfile(r) \\\n                    or os.path.getsize(r) < 100 << 20 or r in keep or os.path.dirname(r) in keep:\n                continue\n            seen.add(r)\n            fd = os.open(r, os.O_RDONLY)\n            os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n            os.close(fd)\n            gb, n = gb + os.path.getsize(r) / 1e9, n + 1\nprint(f\"  dropped from the page cache: {n} other files of {gb:.1f} GB\")\nPY\n  local t0=$SECONDS k\n  for k in 1 2; do\n    dd if=$2 of=/dev/null bs=16M status=none\n    [ \"$(res $2)\" -ge 99 ] && break\n  done\n  echo \"  pool read in $((SECONDS - t0)) s, $(res $2)% of it in the page cache, mem $(mem) GB\"\n  [ \"$(res $2)\" -ge 99 ]\n}\nres() {    # the percentage of a file in the page cache (util-linux fincore)\n  local r=$(fincore -b -n -o RES \"$1\" 2>/dev/null | tr -d ' ')\n  echo $(( ${r:-0} * 100 / $(stat -c %s \"$1\") ))\n}\nfor x in WA AT WB BT; do\n  case $x in ?A|A?) md=$O/$MD; pool=$O/$QA; extra=\"\";; *) md=$MDB; pool=$QM; extra=\"--mtp\";; esac\n  case $x in W?) turns=(--turn \"$T1\"); mx=8;;\n             *) turns=(--turn \"$T1\" --turn \"$T2\" --turn \"$T3\" --turn \"$T4\" --turn \"$T5\"); mx=$MAXNEW\n                extra=\"$extra --trace $R/q$x.trace.json\";; esac\n  echo \"=== q$x $(date +%T) ($extra)\"\n  case $x in W?) warm $md $pool || { echo \"STOP: $pool not wholly in the page cache\"; fail=1; break; };; esac\n  (timeout 1200 python tools/qual/chatmoe.py $md --pool $pool --backend board --cfg $R/cfg-dev.pkl \"${turns[@]}\" \\\n     --max-new $mx $extra --out $R/q$x.json > $R/q$x.log 2>&1)\n  rc=$?; echo \"  exit $rc $(date +%T); after it $(res $pool)% of its pool in the page cache\"\n  grep -E \"Error|Traceback\" $R/q$x.log | tail -3\n  [ $rc = 0 ] && [ -f $R/q$x.json ] || { echo \"STOP: q$x\"; fail=1; break; }\n  grep -E \"^turn |phases:\" $R/q$x.log | cut -c1-400\n  if [ -n \"$REF\" ] && [ $x != WA ] && [ $x != WB ]; then\n    python - $R/q$x.json $REF <<'PY' || { echo \"STOP: q$x differs from REF\"; fail=1; break; }\nimport json, sys\nd, ref = (json.load(open(f)) for f in sys.argv[1:])\nok = [t[\"tokens\"] for t in d[\"turns\"]] == [t[\"tokens\"] for t in ref[\"turns\"]]\nprint(f\"  [{'PASS' if ok else 'FAIL'}] tokens {'=' if ok else '!='} REF's five turns\")\nsys.exit(0 if ok else 1)\nPY\n  fi\ndone\necho \"=== final selftest $(date +%T)\"\ntimeout 600 python -m opentpu.host.selftest 2>&1 | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\n[ $fail = 0 ] && python - $R <<'PY' || fail=1\nimport json, sys                # each turn: A's and B's TTFT in phases (chatmoe _Phases), B - A\nr = sys.argv[1]\nPH = (\"template\", \"rollback\", \"mtp prefill\", \"prefill_layers\", \"end_prefill\", \"mtp snapshot\", \"snapshot\", \"a0\",\n      \"run\")\nHOLD = (\"mtp prefill\", \"mtp snapshot\")\njs = {x: json.load(open(f\"{r}/q{x}.json\")) for x in (\"AT\", \"BT\")}\ntr = {x: json.load(open(f\"{r}/q{x}.trace.json\"))[\"turns\"] for x in (\"AT\", \"BT\")}\nok = [t[\"tokens\"] for t in js[\"AT\"][\"turns\"]] == [t[\"tokens\"] for t in js[\"BT\"][\"turns\"]]\nprint(f\"  [{'PASS' if ok else 'FAIL'}] tokens: A's and B's the same in all {len(js['AT']['turns'])} turns\")\ndef parts(t):\n    tot, spans = {}, []\n    for p, a, b, _ in t[\"phases\"]:\n        n, s = tot.get(p, (0, 0.0))\n        tot[p] = (n + 1, s + b - a)\n        if p not in HOLD:\n            spans.append((a, b))\n    cov, end = 0.0, 0.0\n    for a, b in sorted(spans):\n        cov += max(0.0, b - max(a, end))\n        end = max(end, b)\n    tot[\"rest\"] = (1, max(0.0, (t[\"ttft_s\"] or 0.0) - cov))\n    return tot\nfor i, (ta, tb) in enumerate(zip(tr[\"AT\"], tr[\"BT\"])):\n    pa, pb = parts(ta), parts(tb)\n    ca, cb = (\" + \".join(f\"{c['rows']}{'E' if c['em'] else 'L'} {c['s']}\" for c in js[x][\"turns\"][i][\"calls\"])\n              for x in (\"AT\", \"BT\"))\n    print(f\"  turn {i + 1}: TTFT A {ta['ttft_s']:.3f} B {tb['ttft_s']:.3f} ({tb['ttft_s'] - ta['ttft_s']:+.3f}) s; \"\n          f\"calls A {ca}; B {cb}\")\n    for p in PH + (\"rest\",):\n        if p in pa or p in pb:\n            (na, sa), (nb, sb) = pa.get(p, (0, 0.0)), pb.get(p, (0, 0.0))\n            print(f\"      {p:15s} A {sa:7.3f} ({na}) B {sb:7.3f} ({nb})  B - A {sb - sa:+.3f}\")\n    ra = [q for q in ta[\"phases\"] if q[0] == \"run\"]\n    rb = [q for q in tb[\"phases\"] if q[0] == \"run\"]\n    print(f\"      runs outside the calls: A {len(ra)} ({sum(q[3] or 0 for q in ra)} cycles), \"\n          f\"B {len(rb)} ({sum(q[3] or 0 for q in rb)} cycles)\")\nsys.exit(0 if ok else 1)\nPY\ndate > $R/DONE\necho \"MTPT EXIT $fail $(date +%T)\"\n", "tools/offload/sessions/pfB.sh": "#!/bin/bash\n# Session pfB (docs/offload.md 13.11, 13.13, 13.14, 13.15): expert-major MoE in the layer-major prefill\n# on the card, A/B against today's default. Run 2026-10-12 on opentpu.\n# Tree: GitHub main ee8f118d plus this script (its opentpu/ the same as production's host/, 23b68089),\n# a git archive at ~/otpu-build/moe-ab/tree-ee8f118d (T). Card: production deploy_mt4_91a9c2d3 as\n# loaded (EXPECT 91a9c2d3, register map 4); no bitstream change.\n# Arms (every one: R = 2, pooled slots, --idle-parts v2 --ahead-part 4096, slots filling the DRAM, lfu):\n#   A = today's default (no layer-ahead), B = --expert-major, C = --layer-ahead hint (C=0: none).\n# Per model a discarded warm-up run W (B: a failure of B stops the session before a measured run),\n# then A B C C B A (A B B A without C); each pair's difference in the summary:\n#   35B: Qwen3.5-35B-A3B, lmtime's 134-token prompt (moepf/lmtime/q35w-hf.json), 16 tokens;\n#   26B: gemma-4-26B-A4B-it (the -it checkpoint and its pool g26it/, since 2026-10-09), q26-hf.json's\n#        124 rows, 16 tokens.\n# Pass: every run bit for bit (its prefill logits' sha and its 16 tokens) with its model's W. The\n# 2026-10-02 keys (35B 95426ebacc3b40a9, the base 26B's q26ref16) predate fix-math (2026-10-08) and the\n# 26B's -it checkpoint, so they are printed for information only. A build other than EXPECT, a\n# failed selftest, a device configuration other than production's, a failed or timed-out run or a\n# mismatch stops it; no retries.\n# The images go to a cache of this session's own (IMG, removed after each model: none hits\n# production's ~/otpu-build/qcache/img, whose key holds chat's KV capacity), so each model builds\n# once (W). The programs compile in each run's process (no disk program cache: as every session).\n# About 25 min under the lock.\n# Run (no pipe): setsid nohup ~/.local/bin/otpu-lock --wait 600 -- bash $T/tools/offload/sessions/pfB.sh\n#   > ~/otpu-build/moe-ab/launch.log 2>&1 < /dev/null &\nset -u\nfor v in $(env | grep -o '^OTPU_[A-Z0-9_]*' | grep -vE '^OTPU_LOCK_(HELD|PID|WAIT)$'); do unset $v; done\nMA=${MA:-$HOME/otpu-build/moe-ab}\nT=${T:-$MA/tree-ee8f118d}\nR=${R:-$MA/pfB}\nIMG=${IMG:-$MA/img}\nC=${C:-1}\nexport OTPU_IMG_CACHE=$IMG OTPU_IMG_CACHE_GB=8 OTPU_IMG_CACHE_FREE_GB=6\nsource $T/tools/offload/sessions/env.sh       # (O: card2; OTPU_QUIET claimed, removed at exit)\nexec > >(tee -a $R/session.log) 2>&1\nEXPECT=${EXPECT:-91a9c2d3}\nPRODCFG=${PRODCFG:-$HOME/otpu-build/deploy_mt4_91a9c2d3/qual/cfg.pkl}\nG26IT=$HOME/otpu-build/offload/g26it\nDROPOTHER=$HOME/openTPU/models:$O:$G26IT:$HOME/otpu-build/qcache/img\nQ35=\"Qwen3.5-35B-A3B pool-q35-fp4.split.bin $HOME/otpu-build/moepf/lmtime/q35w-hf.json\"\nG26=\"gemma-4-26B-A4B-it ../g26it/pool-g26it-fp4.split.bin $O/q26-hf.json\"\nQO=\"--embed-table host --hints off\"\nGO=\"--wformat int8 --formats experts=fp4 --head-format fp4\"\nALL=\"--layer-major 2 --idle-parts v2 --ahead-part 4096\"\ndeclare -A ARM=([A]=\"\" [B]=\"--expert-major\" [C]=\"--layer-ahead hint\")\n# the 2026-10-02 card runs' (pfv2 pA1, before fix-math): information only\nOLD35='{\"sha\": \"95426ebacc3b40a9\", \"tokens\": [8160, 579, 264, 7047, 1817, 421, 11177, 310, 279, 11488, 2468, 25, 271, 16, 13, 220]}'\nfail=0\necho \"pfB start $(date +%T) tree $rev T $T mem $(mem) GB, /home $(df -BG --output=avail /home | tail -1 | tr -d ' ') free; $(uptime)\"\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"build $EXPECT\" || { echo \"STOP: the card's build is not $EXPECT\"; exit 2; }\necho \"$st\" | grep -q \"register map 4\" || { echo \"STOP: not register map 4\"; exit 2; }\necho \"$st\" | grep -q \"ALL PASS\" || { echo \"STOP: selftest\"; exit 2; }\ntimeout 300 python tools/qual/refs.py cfg $R/cfg-dev.pkl > /dev/null 2>&1; echo \"cfg exit $?\"\npython - $R/cfg-dev.pkl $PRODCFG <<'PY' || { echo \"STOP: the device configuration\"; exit 2; }\nimport dataclasses, pickle, sys\na, b = (pickle.load(open(f, \"rb\")) for f in sys.argv[1:])\nd = {f.name: (getattr(a, f.name), getattr(b, f.name)) for f in dataclasses.fields(a)\n     if getattr(a, f.name) != getattr(b, f.name)}\nprint(\"  cfg: production's (qual/cfg.pkl)\" if not d else f\"  cfg DIFFERS from production's: {d}\")\nsys.exit(1 if d else 0)\nPY\nrun() {   # model (q|g), run name, arm, timeout\n  local m=$1 run=$2 arm=$3 to=$4 md pool hf extra\n  if [ $m = q ]; then read -r md pool hf <<< \"$Q35\"; extra=\"$QO\"; else read -r md pool hf <<< \"$G26\"; extra=\"$GO\"; fi\n  extra=\"$extra $ALL ${ARM[$arm]}\"\n  echo \"=== $run ($arm) $(date +%T): $extra\"\n  python - $O/$md $O/$pool $DROPOTHER <<'PY'\nimport os, sys                      # every other file of 100 MB or more out of the page cache\nkeep = {os.path.realpath(sys.argv[1]), os.path.realpath(sys.argv[2])}  # (card_moe.sh's DROPOTHER)\nours = tuple(os.path.realpath(os.path.expanduser(d)) + os.sep for d in (\"~/openTPU\", \"~/otpu-build\"))\ngb = n = 0\nseen = set()\nfor d in sys.argv[3].split(\":\"):\n    for root, _, files in os.walk(os.path.expanduser(d)):\n        for f in files:\n            r = os.path.realpath(os.path.join(root, f))\n            if r in seen or not r.startswith(ours) or not os.path.isfile(r) \\\n                    or os.path.getsize(r) < 100 << 20 or r in keep or os.path.dirname(r) in keep:\n                continue\n            seen.add(r)\n            fd = os.open(r, os.O_RDONLY)\n            os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n            os.close(fd)\n            gb, n = gb + os.path.getsize(r) / 1e9, n + 1\nprint(f\"  dropped from the page cache: {n} other files of {gb:.1f} GB\")\nPY\n  local t0=$SECONDS; cat $O/$pool > /dev/null; echo \"  pool read in $((SECONDS - t0)) s, mem $(mem) GB\"\n  timeout $to python tools/offload/moe_card.py $O/$md --check $hf -n 16 --pool $O/$pool \\\n    --cfg $R/cfg-dev.pkl --experts 0 --card --policy lfu $extra --prefill-trace $R/$run.trace.json \\\n    --out $R/$run.json > $R/$run.log 2>&1\n  local rc=$?; echo \"  exit $rc $(date +%T)\"; grep -E \"Error|Traceback|timed out\" $R/$run.log | tail -3\n  [ $rc -eq 0 ] && [ -f $R/$run.json ] || { echo \"STOP: $run (exit $rc)\"; return 1; }\n  python - $R/$run.json $R/${m}W.json \"$OLD35\" $m <<'PY' || { echo \"STOP: $run differs from ${m}W\"; return 1; }\nimport json, sys\nd, w = json.load(open(sys.argv[1])), json.load(open(sys.argv[2]))\nok = d[\"prefill_logits_sha\"] == w[\"prefill_logits_sha\"] and d[\"tokens\"] == w[\"tokens\"]\npt = d[\"prefill_time\"]\nprint(f\"  [{'PASS' if ok else 'FAIL'}] prefill sha {d['prefill_logits_sha']} tokens \"\n      f\"{'same as' if d['tokens'] == w['tokens'] else 'DIFFER from'} W's ({w['prefill_logits_sha']}); \"\n      f\"prefill wall {pt['wall_s']} s (device {pt['device_s']}, halted {pt['halted_s']}, between \"\n      f\"{pt['between_s']}, serve {pt['serve_s']}), requests {d.get('prefill_requests')} misses \"\n      f\"{d.get('prefill_misses')}; load {d['load_s']} s; decode {d['tok_s_wall']} tok/s\")\nprint(f\"  need {json.dumps(pt.get('need'))} ahead {json.dumps(pt.get('ahead'))} idle_parts \"\n      f\"{json.dumps(d.get('idle_parts'))}\")\nif sys.argv[1] == sys.argv[2]:      # (W: the 2026-10-02 runs', information only)\n    if sys.argv[4] == \"q\":\n        o = json.loads(sys.argv[3])\n        print(f\"  (info) vs 2026-10-02 (pfv2, before fix-math): sha {'same' if o['sha'] == d['prefill_logits_sha'] else 'differs'}\"\n              f\" ({o['sha']}), tokens {'same' if o['tokens'] == d['tokens'] else 'DIFFER'}\")\n    else:\n        print(f\"  (info) vs the base 26B's HF tokens (q26-hf.json): first diff {d['first_diff']}\")\n    print(f\"  tokens {d['tokens']}\")\nsys.exit(0 if ok else 1)\nPY\n}\norder=\"W A1 B1 C1 C2 B2 A2\"; [ \"$C\" = 1 ] || order=\"W A1 B1 B2 A2\"\nfor m in q g; do\n  for x in $order; do\n    arm=${x:0:1}; [ $x = W ] && arm=B\n    to=600; [ $x = W ] && to=1500\n    run $m $m$x $arm $to || { fail=1; break 2; }\n  done\n  echo \"  image cache: $(du -sh $IMG 2>/dev/null | cut -f1); removed\"; rm -rf $IMG\ndone\necho \"=== final selftest $(date +%T)\"\ntimeout 600 python -m opentpu.host.selftest 2>&1 | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\nrm -rf $IMG\necho \"pfB end $(date +%T) fail $fail\"\npython - $R <<'PY'\nimport json, os, sys\nr = sys.argv[1]\ndef get(run):\n    f = f\"{r}/{run}.json\"\n    return json.load(open(f)) if os.path.exists(f) else None\nfor name, m in ((\"35B prefill\", \"q\"), (\"26B prefill\", \"g\")):\n    a1, a2 = get(m + \"A1\"), get(m + \"A2\")\n    for x in (\"B\", \"C\"):\n        x1, x2 = get(m + x + \"1\"), get(m + x + \"2\")\n        if None in (a1, a2, x1, x2):\n            print(f\"  {name} {x}: incomplete\"); continue\n        for key in (\"wall_s\", \"device_s\", \"halted_s\", \"between_s\", \"serve_s\"):\n            v = lambda c: c[\"prefill_time\"][key] or 0.0     # noqa: E731\n            d1, d2 = v(x1) - v(a1), v(x2) - v(a2)\n            ma, mx = (v(a1) + v(a2)) / 2, (v(x1) + v(x2)) / 2\n            print(f\"  {name} {key}: A {v(a1):.3f} {v(a2):.3f}, {x} {v(x1):.3f} {v(x2):.3f}; pairs \"\n                  f\"{x}-A {d1:+.3f} {d2:+.3f}; mean {x}-A {mx - ma:+.3f}\")\n        for y, c in ((x + \"1\", x1), (x + \"2\", x2)):\n            pt = c[\"prefill_time\"]\n            print(f\"    {y} runs {pt['runs']} requests {c.get('prefill_requests')} misses \"\n                  f\"{c.get('prefill_misses')} need {json.dumps(pt.get('need'))} idle_parts \"\n                  f\"{json.dumps(c.get('idle_parts'))}\")\nPY\ndate > $R/DONE\necho \"PFB EXIT $fail $(date +%T)\"\n", "tools/offload/sessions/pooldisk.sh": "#!/bin/bash\n# Session pooldisk (docs/minicpmv.md 6): what an expert pool's disk costs a warm process, on the card host's two disks.\n# mcpv3b's dropped arms were invalid (the engine maps the pool: posix_fadvise DONTNEED left it cached); pool_disk.py now\n# releases those maps first and checks every arm with mincore. Pools (each its model's engine, otpu-chat's):\n#   mcpv  MiniCPM-V 4.7's, /data (sdb, a 7200 rpm disk)\n#   q35   qwen35-35b's, production's file on /home (sda, the SATA SSD): read only (its .packed and .key's sums and the\n#         pool's size and mtime are checked before and after)\n# Per pool: a warm-up process (pool_disk.py --arms \"\": the engine's open, which builds the image into the image cache\n# if this tree's keys are new, and the warm-up turn; unmeasured), then the measured one: --arms cached,dropped,dropped,cached, the same turn\n# greedy. The arms' tok/s, misses and reads by where they came from (page cache or disk): a miss's service time per\n# disk. One otpu-lock: selftest (production's build and configuration), the pools, selftest. A failed run, an INVALID\n# arm or a changed q35 file is a FAIL; the last line: POOLDISK PASS or POOLDISK FAIL. About 20 min.\n# Stage (from the Mac): git archive <sha> | ssh opentpu 'D=~/otpu-build/minicpmv/pooldisk/host; mkdir -p $D &&\n#   tar -x -C $D'; ssh opentpu 'echo <sha> > ~/otpu-build/minicpmv/pooldisk/host/COMMIT'\n# Run (no pipe): setsid nohup ~/.local/bin/otpu-lock --wait 600 -- bash \\\n#   ~/otpu-build/minicpmv/pooldisk/host/tools/offload/sessions/pooldisk.sh > ~/otpu-build/minicpmv/pooldisk.launch.log \\\n#   2>&1 < /dev/null &\nset -u\nfor v in $(env | grep -o '^OTPU_[A-Z0-9_]*' | grep -vE '^OTPU_LOCK_(HELD|PID|WAIT)$'); do unset $v; done\nexport OTPU_IMG_CACHE_GB=30 OTPU_IMG_CACHE_FREE_GB=6      # (the card host's, from its ~/.bashrc)\nSESSION=${SESSION:-pooldisk}\nO=${O:-/data/otpu/minicpmv}\nC2=${C2:-$HOME/otpu-build/offload/card2}\nPD=${PD:-$HOME/otpu-build/deploy_r2m4_b10245f5}        # (production: qual/cfg.pkl)\nREFCFG=${REFCFG:-$PD/qual/cfg.pkl}\nPYLIB=${PYLIB:-$O/pylib}\nsource \"$(dirname \"${BASH_SOURCE[0]}\")/env.sh\"       # (T: this tree; R = O/SESSION; OTPU_QUIET claimed)\nexport PYTHONPATH=$T:$PYLIB\nexec > >(tee -a $R/session.log) 2>&1\nEXPECT=${EXPECT:-b10245f5}\nMAP=${MAP:-register map 5}\nPOOLS=${POOLS:-mcpv q35}\ndeclare -A MODEL=([mcpv]=$O/MiniCPM-V-4.7-35B-A3B [q35]=$C2/Qwen3.5-35B-A3B)\ndeclare -A POOL=([mcpv]=$O/pool-mcpv35-mx.split.bin [q35]=$C2/pool-q35-mx.split.bin)\nfail=0\necho \"pooldisk start $(date +%T) T $T ($rev) R $R mem $(mem) GB; $(uptime)\"\ngrep -q 'MADV_DONTNEED' $T/tools/offload/pool_disk.py && grep -q '\"valid\"\\|valid=valid' $T/tools/offload/pool_disk.py \\\n  || { echo \"STOP: T's pool_disk.py does not release the engine's maps or check its arms\"; exit 2; }\nfor p in $POOLS; do\n  [ -f ${MODEL[$p]}/config.json ] && [ -f ${POOL[$p]} ] && [ -f ${POOL[$p]}.key ] && [ -f ${POOL[$p]}.packed ] \\\n    || { echo \"STOP: $p's ${MODEL[$p]} or ${POOL[$p]} (.key, .packed) missing\"; exit 2; }\ndone\n[ -f $REFCFG ] || { echo \"STOP: no $REFCFG\"; exit 2; }\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"build $EXPECT\" || { echo \"STOP: the card's build is not $EXPECT\"; exit 2; }\necho \"$st\" | grep -q \"$MAP\" || { echo \"STOP: not $MAP\"; exit 2; }\necho \"$st\" | grep -q \"ALL PASS\" || { echo \"STOP: selftest\"; exit 2; }\ntimeout 300 python tools/qual/refs.py cfg $R/cfg-dev.pkl > /dev/null 2>&1; echo \"cfg exit $?\"\npython - $R/cfg-dev.pkl $REFCFG <<'PY' || { echo \"STOP: the device configuration is not production's\"; exit 2; }\nimport dataclasses, pickle, sys\na, b = (pickle.load(open(f, \"rb\")) for f in sys.argv[1:])\nd = {f.name: (getattr(a, f.name), getattr(b, f.name)) for f in dataclasses.fields(a)\n     if getattr(a, f.name) != getattr(b, f.name)}\nprint(\"  cfg: production's configuration\" if not d else f\"  cfg DIFFERS (device, production): {d}\")\nsys.exit(1 if d else 0)\nPY\nmark() {      # a pool's files as they are: size and mtime of the pool, sums of its .packed and .key\n  echo \"$(stat -c '%s %Y' $1) $(sha256sum $1.packed $1.key | cut -c1-16 | tr '\\n' ' ')\"\n}\nfor p in $POOLS; do\n  echo \"=== $p $(date +%T): ${POOL[$p]} on $(df --output=source ${POOL[$p]} | tail -1)\"\n  before=$(mark ${POOL[$p]})\n  timeout 1200 python tools/offload/pool_disk.py ${MODEL[$p]} --pool ${POOL[$p]} --backend board \\\n    --cfg $R/cfg-dev.pkl --arms \"\" --out $R/pooldisk-$p-warmup.json > $R/pooldisk-$p-warmup.log 2>&1\n  rc=$?; echo \"  warm-up exit $rc $(date +%T)\"; grep -vE \"^\\[transformers\" $R/pooldisk-$p-warmup.log | tail -3\n  [ $rc = 0 ] || { fail=1; continue; }\n  timeout 1500 python tools/offload/pool_disk.py ${MODEL[$p]} --pool ${POOL[$p]} --backend board \\\n    --cfg $R/cfg-dev.pkl --out $R/pooldisk-$p.json > $R/pooldisk-$p.log 2>&1\n  rc=$?; echo \"  exit $rc $(date +%T)\"; grep -vE \"^\\[transformers\" $R/pooldisk-$p.log | tail -6\n  [ $rc = 0 ] || fail=1\n  python - $R/pooldisk-$p.json <<'PY' || fail=1\nimport json, sys\nr = json.load(open(sys.argv[1]))\nbad = [a[\"arm\"] for a in r[\"arms\"] if not a.get(\"valid\")]\nprint(f\"  arms valid: {len(r['arms']) - len(bad)} of {len(r['arms'])}\" + (f\" (INVALID: {bad})\" if bad else \"\"))\nsys.exit(1 if bad or len(r[\"arms\"]) != 4 else 0)\nPY\n  after=$(mark ${POOL[$p]})\n  [ \"$before\" = \"$after\" ] && echo \"  pool files unchanged: $after\" || { echo \"  POOL FILES CHANGED: $before -> $after\"; fail=1; }\ndone\necho \"=== final selftest $(date +%T)\"\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|stopped\" | tail -14\necho \"$st\" | grep -q \"ALL PASS\" || fail=1\necho \"POOLDISK $([ $fail = 0 ] && echo PASS || echo FAIL) $(date +%T)\"\nexit $fail\n", "tools/offload/sessions/reference.sh": "#!/bin/bash\n# The ISA simulator's reference for card runs (docs/offload.md 10): moe_card on the simulator with\n# the card's generate loop, slots and configuration (REFCFG: tools/qual/refs.py cfg on the card's\n# host), on a host with the whole pool (the 26B's: 77 min on omarchy; its prefill steps a token at\n# a time). Its prefill logits' sha256 and its tokens are what card_moe.sh checks a run against.\n#   reference.sh MODEL POOL HF.json N OUT.json [moe_card options]\n# e.g. session 8's: reference.sh gemma-4-26B-A4B ../g26/pool-g26-fp4.split.bin q26-hf.json 16 \\\n#   q26ref16.json --wformat int8 --formats experts=fp4 --head-format fp4   (paths in O)\n# Started at MEMSTART GB of MemAvailable (default 16), under a MEMMAX memory limit (default 14G,\n# systemd-run --user --scope where there is one) at nice 19; killed, not frozen, on two 30 s\n# samples under MEMFLOOR GB (default 6). Log: O/OUT.log.\nset -u\nhere=$(cd \"$(dirname \"$0\")\" && pwd)\nT=${T:-$(cd \"$here/../../..\" && pwd)}; O=${O:-$HOME/otpu-build/offload/card2}\nREFCFG=${REFCFG:-$O/cfg-c2830d6a.pkl}\nmodel=$1 pool=$2 hf=$3 n=$4 out=$5; shift 5\ncd \"$T\" || exit 1\nexport PATH=${OTPU_VENV:-$HOME/otpu-venv}/bin:$PATH PYTHONPATH=$T OMP_NUM_THREADS=4 MKL_NUM_THREADS=4\nmem() { awk '/MemAvailable/ {print int($2/1048576)}' /proc/meminfo; }\nexec > >(tee -a $O/$out.log) 2>&1\nwhile [ $(mem) -lt ${MEMSTART:-16} ]; do sleep 60; done\necho \"reference start $(date +%T) mem $(mem) GB: $model $out\"\nlim=()\ncommand -v systemd-run > /dev/null && lim=(systemd-run --user --scope -p MemoryMax=${MEMMAX:-14G} -p MemorySwapMax=0 --quiet)\n\"${lim[@]}\" nice -n 19 python tools/offload/moe_card.py $O/$model --check $O/$hf -n $n \\\n  --pool $O/$pool --cfg $REFCFG --experts 0 \"$@\" --out $O/$out &\npid=$!; low=0\nwhile kill -0 $pid 2>/dev/null; do\n  m=$(mem)\n  if [ \"$m\" -lt ${MEMFLOOR:-6} ]; then low=$((low+1)); else low=0; fi\n  if [ $low -ge 2 ]; then pkill -P $pid; kill $pid; echo \"KILLED $(date +%T) mem $m GB\"; break; fi\n  sleep 30\ndone\nwait $pid; echo \"reference exit $? $(date +%T)\"\n", "tools/offload/sessions/session10.sh": "#!/bin/bash\n# offload card session 10 (2026-10-01, production build 72256074, no reload): where the 35B's\n# host staging goes (docs/offload.md 10.6; results there). Session 9's 35B lost 48 ms a token to\n# staging on main 7d879e6 and 117-210 ms on d29bfe9, at the same misses and DMA. Its tree: main\n# d29bfe9 with offload-relmem's host code (its programs d29bfe9's: program_sha.py --cfg 35B\n# 2fa1b39f, 26B 48151736, so RF = session 9's refs-d29bfe9). Rounds (ROUNDS, comma-separated):\n#   s10:  q35e128t q35e128r q35e128rw g26a g26r (DROPOTHER off; RF then fell to O's, 7d879e6's:\n#         its FAILs were the references', the prefill sha d29bfe9's; the 2nd round never ran)\n#   s10b: q35e128t q35e128r g26a g26r, the other checkpoints out of the page cache (DROPOTHER)\n#   then: q35e128t as session 9's q35e128a with each request's window (--hint-trace),\n#   q35e128r + --release-weights, q35e128rw + --willneed, g26r g26a + --release-weights. Since,\n#   moe_card releases and queues by default: q35e128k is the old q35e128t (--keep-weights\n#   --no-willneed), and card_moe.sh drops the other files unless DROPOTHER=\"\".\n# It stops at a mismatch, a timeout or an error (a FAIL, a selftest's).\n# Run: SESSION=s10b ROUNDS=\"...\" otpu-lock --wait 10800 -- tools/offload/sessions/session10.sh\nset -u\nSESSION=${SESSION:-s10}; RF=${RF:-${O:-$HOME/otpu-build/offload/card2}/refs-d29bfe9}\nsource \"$(dirname \"$0\")/env.sh\"             # (its RF defaults to O: set before)\nexec > >(tee -a $R/session.log) 2>&1\necho \"session10 start $(date +%T) tree $rev mem $(mem) GB\"\nbad() { sleep 1; grep -c -E \"\\[FAIL\\]|exit 124|Traceback|STOP\" $R/session.log; }\nb0=$(bad)\nk=0\nIFS=, read -r -a rounds <<< \"${ROUNDS:-q35e128t q35e128r q35e128rw g26a g26r,q35e128r q35e128t g26r g26a}\"\nfor runs in \"${rounds[@]}\"; do\n  k=$((k + 1))\n  echo \"--- round $k: $runs\"\n  RF=$RF R=$R/r$k RUNS=\"$runs\" bash \"$here/card_moe.sh\"\n  [ $(bad) -gt $b0 ] && { echo \"STOP $(date +%T): a mismatch, a timeout or an error\"; break; }\ndone\necho \"session10 end $(date +%T)\"\npython - $R <<'PY'\nimport glob, json, sys\nr = sys.argv[1]\nfor f in sorted(glob.glob(f\"{r}/r[0-9]/*.json\")):\n    if f.endswith(\".trace.json\"):\n        continue\n    c = json.load(open(f))\n    h, m = c.get(\"host_decode_s\") or {}, c.get(\"host_mem\") or {}\n    rd = h.get(\"reads\") or {}\n    at = lambda k: (m.get(k) or {})                                   # noqa: E731\n    pw = c.get(\"pool_warm\") or {}\n    print(f\"  {f[len(r) + 1:]}: tok/s {c['tok_s_wall']}, misses/token \"\n          f\"{c['misses_per_token_decode']}, stage {h.get('stage')} s (wait {h.get('stage_wait')}), \"\n          f\"poll {h.get('poll')}, dma {h.get('dma_s')}; reads cached {rd.get('cached')} disk \"\n          f\"{rd.get('disk')}; rss {at('at_decode').get('rss')} -> {at('at_end').get('rss')} \"\n          f\"(file {at('at_decode').get('rss_file')}, children {at('at_decode').get('children_rss')}),\"\n          f\" available {at('at_decode').get('available')} -> {at('at_end').get('available')}; \"\n          f\"pool resident {(pw.get('at_decode') or {}).get('resident_gb')} -> \"\n          f\"{(pw.get('at_end') or {}).get('resident_gb')} GB\")\nPY\ndate > $R/DONE\n", "tools/offload/sessions/session12.sh": "#!/bin/bash\n# offload card sessions 11 + 12 (production build, no reload), d29bfe9's programs (session 9's\n# references, refs-d29bfe9) in two trees: A = tree-s11 (session 10's host code + Layout.pitch +\n# DROPOTHER's guard), B = this one (A + PoolFile's mapped reads, offload-mglru).\n#   11: A's g26r twice (the 26B's slots whole RUN blocks apart: every expert read in place;\n#       session 10: 2.39-2.42 tok/s, direct 5618 of 11276), the other files dropped (DROPOTHER)\n#   12: q35e128r A B A B on a host whose other checkpoints a process mapped and touched (HOG:\n#       the Qwen3.5 0.8B / 2B / 4B, session 10's 13.6 GB; DROPOTHER=\"\"): the pool read through\n#       read() (A) against touched through its map (B; docs/offload.md 10.7). Session 10:\n#       3.05 tok/s with them in the page cache, 3.79 without.\n# About 20 min (2026-10-01 21:30-21:50, results: docs/offload.md 10.6 and 10.7). It stops at a\n# mismatch, a timeout or an error (a FAIL, a selftest's).\n# Run: otpu-lock --wait 10800 -- tools/offload/sessions/session12.sh   (log: O/s12/session.log)\nset -u\nSESSION=${SESSION:-s12}; RF=${RF:-${O:-$HOME/otpu-build/offload/card2}/refs-d29bfe9}\nsource \"$(dirname \"$0\")/env.sh\"             # (its RF defaults to O: set before)\nexec > >(tee -a $R/session.log) 2>&1\nTB=$T; TA=${TA:-$O/../tree-s11}\nDIRS=\"$HOME/openTPU/models:$O:$O/../g26\"\nHOGS=\"$HOME/openTPU/models/Qwen3.5-0.8B:$HOME/openTPU/models/Qwen3.5-2B:$HOME/openTPU/models/Qwen3.5-4B\"\necho \"session12 start $(date +%T) tree B $rev, A $(cat $TA/COMMIT 2>/dev/null) mem $(mem) GB\"\nbad() { sleep 1; grep -c -E \"\\[FAIL\\]|exit 124|Traceback|STOP\" $R/session.log; }\nb0=$(bad)\nstop() { [ $(bad) -gt $b0 ] && { echo \"STOP $(date +%T): a mismatch, a timeout or an error\"; return 0; }; return 1; }\nrun() {   # tree, its name, runs, then card_moe.sh's environment\n  local tt=$1 out=$2 runs=$3; shift 3\n  echo \"--- $out: tree $tt, $runs, $*\"\n  env \"$@\" T=$tt RF=$RF R=$R/$out RUNS=\"$runs\" bash \"$here/card_moe.sh\"\n}\ngo=1\nrun $TA s11 \"g26r g26r\" DROPOTHER=$DIRS HOG=\nstop && go=0\nif [ $go = 1 ]; then\n  for k in 1 2; do\n    for t in A B; do\n      if [ $t = A ]; then tt=$TA; else tt=$TB; fi\n      run $tt $t$k q35e128r DROPOTHER= HOG=$HOGS\n      stop && { go=0; break 2; }\n    done\n  done\nfi\necho \"session12 end $(date +%T)\"\npython - $R <<'PY'\nimport glob, json, sys\nr = sys.argv[1]\nfor f in sorted(glob.glob(f\"{r}/*/*.json\")):\n    if f.endswith(\".trace.json\"):\n        continue\n    c = json.load(open(f))\n    h, m = c.get(\"host_decode_s\") or {}, c.get(\"host_mem\") or {}\n    rd = h.get(\"reads\") or {}\n    pw = c.get(\"pool_warm\") or {}\n    print(f\"  {f[len(r) + 1:]}: tok/s {c['tok_s_wall']}, stage {h.get('stage')} s, poll \"\n          f\"{h.get('poll')}, dma {h.get('dma_s')}, direct {h.get('direct')}; reads cached \"\n          f\"{rd.get('cached')} disk {rd.get('disk')}; pool resident \"\n          f\"{(pw.get('at_decode') or {}).get('resident_gb')} -> \"\n          f\"{(pw.get('at_end') or {}).get('resident_gb')} GB; cached \"\n          f\"{(m.get('at_decode') or {}).get('cached')} GB\")\nPY\ndate > $R/DONE\n", "tools/offload/sessions/session13.sh": "#!/bin/bash\n# offload card session 13 (production build, no reload), d29bfe9's programs (session 9's\n# references, refs-d29bfe9) in one tree: session 12's host code + docs/offload.md 10.8's serving\n# (preadv_iov, a request's first miss a fifth first, the victims' clears after its experts, the\n# poll loop spinning), against the same tree's --legacy-serve (as session 12 served), A B A B:\n#   q35e128sl / q35e128s: the 35B at 128 tokens (session 12's B2: 3.76 tok/s, windows 21.5 s,\n#     DMA 16.6; predicted about 4.0 now);\n#   g26sl / g26s: the 26B at 128 tokens (session 11: 2.65 / 2.69, windows 32.0 s, DMA 27.2;\n#     predicted about 2.8).\n# Each with its timeline and BoardDram's DMA calls (--hint-trace: <run>.trace.json and\n# <run>.trace.calls.json). The other big files dropped before each run (DROPOTHER's default).\n# About 14 min (2026-10-01 22:48-23:02; results: docs/offload.md 10.8). It stops at a mismatch,\n# a timeout or an error (a FAIL, a selftest's).\n# Run: otpu-lock --wait 10800 -- tools/offload/sessions/session13.sh   (log: O/s13/session.log)\nset -u\nSESSION=${SESSION:-s13}; RF=${RF:-${O:-$HOME/otpu-build/offload/card2}/refs-d29bfe9}\nsource \"$(dirname \"$0\")/env.sh\"             # (its RF defaults to O: set before)\nexec > >(tee -a $R/session.log) 2>&1\necho \"session13 start $(date +%T) tree $rev mem $(mem) GB\"\nbad() { sleep 1; grep -c -E \"\\[FAIL\\]|exit 124|Traceback|STOP\" $R/session.log; }\nb0=$(bad)\nstop() { [ $(bad) -gt $b0 ] && { echo \"STOP $(date +%T): a mismatch, a timeout or an error\"; return 0; }; return 1; }\nrun() {   # its name, runs\n  local out=$1 runs=$2\n  echo \"--- $out: $runs\"\n  env T=$T RF=$RF R=$R/$out RUNS=\"$runs\" bash \"$here/card_moe.sh\"\n}\ngo=1\nfor k in 1 2; do\n  run L$k q35e128sl; stop && { go=0; break; }\n  run N$k q35e128s; stop && { go=0; break; }\ndone\nif [ $go = 1 ]; then\n  run gL1 g26sl\n  stop || run gN1 g26s\nfi\necho \"session13 end $(date +%T)\"\npython - $R <<'PY'\nimport glob, json, sys\nr = sys.argv[1]\nfor f in sorted(glob.glob(f\"{r}/*/*.json\")):\n    if \".trace.\" in f:\n        continue\n    c = json.load(open(f))\n    h = c.get(\"host_decode_s\") or {}\n    rd = h.get(\"reads\") or {}\n    print(f\"  {f[len(r) + 1:]}: legacy {c.get('legacy_serve')} tok/s {c['tok_s_wall']} \"\n          f\"(device {c['tok_s_device']}), poll {h.get('poll')}, dma {h.get('dma_s')}, stage \"\n          f\"{h.get('stage')}, flush {h.get('flush')}, reads cached {rd.get('cached')} disk \"\n          f\"{rd.get('disk')}, polls {h.get('polls_reads')}, match {c.get('match')}\")\nPY\ndate > $R/DONE\n", "tools/offload/sessions/session14.sh": "#!/bin/bash\n# offload card session 14 (production: Gen2 x8, deploy_g2fix_0885d436; no reload), session 13's\n# programs (d29bfe9's, refs-d29bfe9) in session 13's tree with PollPacer (docs/offload.md 10.10):\n#   q35e128s, q35e128sp: the 35B spinning (Gen2, 10.9: 5.07 / 5.10 tok/s), then with the\n#     decode's polls paced;\n#   g26s, g26s50, g26sp, g26s, g26sp: the 26B's poll A/B (spinning on Gen2: 3.54 tok/s, 561k\n#     poll reads; its compute rose 0.086 G cycles over Gen1's, 10.9): spinning, a 50 us sleep,\n#     paced.\n# Each with its timeline and DMA calls (--hint-trace). The other big files dropped before each\n# run (DROPOTHER's default). About 19 min. It stops at a mismatch, a timeout or an error.\n# Run: otpu-lock --wait 10800 -- tools/offload/sessions/session14.sh   (log: O/s14/session.log)\nset -u\nSESSION=${SESSION:-s14}; RF=${RF:-${O:-$HOME/otpu-build/offload/card2}/refs-d29bfe9}\nsource \"$(dirname \"$0\")/env.sh\"             # (its RF defaults to O: set before)\nexec > >(tee -a $R/session.log) 2>&1\necho \"session14 start $(date +%T) tree $rev mem $(mem) GB\"\nbad() { sleep 1; grep -c -E \"\\[FAIL\\]|exit 124|Traceback|STOP\" $R/session.log; }\nb0=$(bad)\nstop() { [ $(bad) -gt $b0 ] && { echo \"STOP $(date +%T): a mismatch, a timeout or an error\"; return 0; }; return 1; }\nrun() {   # its name, runs\n  echo \"--- $1: $2\"\n  env T=$T RF=$RF R=$R/$1 RUNS=\"$2\" bash \"$here/card_moe.sh\"\n}\nfor x in \"N1 q35e128s\" \"P1 q35e128sp\" \"gS1 g26s\" \"gF1 g26s50\" \"gP1 g26sp\" \"gS2 g26s\" \"gP2 g26sp\"; do\n  run $x\n  stop && break\ndone\necho \"session14 end $(date +%T)\"\npython - $R <<'PY'\nimport glob, json, sys\nr = sys.argv[1]\nfor f in sorted(glob.glob(f\"{r}/*/*.json\")):\n    if \".trace.\" in f:\n        continue\n    c = json.load(open(f))\n    h, d = c.get(\"host_decode_s\") or {}, c.get(\"device_counters\") or {}\n    g = {k: round(d.get(k, 0) / 1e9, 3) for k in (\"RUNNING\", \"MXU_STARVE\", \"DMA_BUSY\", \"DRAM_WAIT\")}\n    print(f\"  {f[len(r) + 1:]}: poll_idle {c.get('poll_idle')} tok/s {c['tok_s_wall']} (device \"\n          f\"{c['tok_s_device']}), poll {h.get('poll')}, dma {h.get('dma_s')} ({h.get('dma_gbs')} \"\n          f\"GB/s), polls {h.get('polls_reads')}, pacer {c.get('pacer')}, G cycles {g}, \"\n          f\"match {c.get('match')}\")\nPY\ndate > $R/DONE\n", "tools/offload/sessions/session15.sh": "#!/bin/bash\n# offload card session 15 (docs/offload.md 10.11, design A), on the bitstream as loaded:\n# - the tag's order on it first (tools/qual/waitw.py --tag-rounds 2000: an expert's 1-4 MiB with\n#   the tag in its DMA's last beat while the card waits on it; it stops on a FAIL);\n# - then A against each miss's entry on the same bitstream, A B A B: A's parent (OLD: main\n#   cb3dce5, every other change the same) and this tree (the answer and the tags), q35e128s and\n#   g26s with their timelines and DMA calls, against refs-d29bfe9 (the math is unchanged: the\n#   same tokens and prefill sha; refs-f725c2b confirms it on the ISA simulator). Predicted: the\n#   35B -0.6 to -0.8 s per 128 tokens (+2.4-3.3%), the 26B -0.4 to -0.9 s (+1-2.5%); the 35B's\n#   64-byte calls 31,346 -> about 10,000.\n#   OLD     A's parent's tree (default O/../tree-cb3dce5: git archive of main cb3dce5)\n#   RF_OLD  its references (default RF; refs-cb3dce5 if its ISA runs had differed)\n# About 22 min. It stops at a mismatch, a timeout or an error.\n# Run: otpu-lock --wait 10800 -- tools/offload/sessions/session15.sh   (log: O/s15/session.log)\nset -u\nSESSION=${SESSION:-s15}; RF=${RF:-${O:-$HOME/otpu-build/offload/card2}/refs-d29bfe9}\nsource \"$(dirname \"$0\")/env.sh\"             # (its RF defaults to O: set before)\nOLD=${OLD:-$(dirname \"$O\")/tree-cb3dce5}; RF_OLD=${RF_OLD:-$RF}\nexec > >(tee -a $R/session.log) 2>&1\necho \"session15 start $(date +%T) tree $rev old $(cat $OLD/COMMIT) mem $(mem) GB\"\nbad() { sleep 1; grep -c -E \"\\[FAIL\\]|exit 124|Traceback|STOP\" $R/session.log; }\nb0=$(bad)\nstop() { [ $(bad) -gt $b0 ] && { echo \"STOP $(date +%T): a mismatch, a timeout or an error\"; return 0; }; return 1; }\necho \"--- waitw: the tag in the data's last beat\"\ntimeout 900 python tools/qual/waitw.py --rounds 50 --tag-rounds 2000; echo \"waitw exit $?\"\nrun() {   # its name, runs, tree\n  local rf=$RF; [ \"$3\" = \"$OLD\" ] && rf=$RF_OLD\n  echo \"--- $1: $2 ($(cat $3/COMMIT 2>/dev/null || echo $3), RF $rf)\"\n  env T=$3 RF=$rf R=$R/$1 RUNS=\"$2\" bash \"$3/tools/offload/sessions/card_moe.sh\"\n}\nstop || for x in \"L1 q35e128s $OLD\" \"A1 q35e128s $T\" \"L2 q35e128s $OLD\" \"A2 q35e128s $T\" \\\n                 \"gL1 g26s $OLD\" \"gA1 g26s $T\" \"gL2 g26s $OLD\" \"gA2 g26s $T\"; do\n  run $x\n  stop && break\ndone\necho \"session15 end $(date +%T)\"\npython - $R <<'PY'\nimport glob, json, sys\nr = sys.argv[1]\nfor f in sorted(glob.glob(f\"{r}/*/*.json\")):\n    if \".trace.\" in f:\n        continue\n    c = json.load(open(f))\n    h, d = c.get(\"host_decode_s\") or {}, c.get(\"device_counters\") or {}\n    g = {k: round(d.get(k, 0) / 1e9, 3) for k in (\"RUNNING\", \"MXU_STARVE\", \"DMA_BUSY\", \"DRAM_WAIT\")}\n    print(f\"  {f[len(r) + 1:]}: tok/s {c['tok_s_wall']} (device {c['tok_s_device']}), poll \"\n          f\"{h.get('poll')}, dma {h.get('dma_s')} ({h.get('dma_gbs')} GB/s), polls \"\n          f\"{h.get('polls_reads')}, G {g}, match {c.get('match')} sha {c.get('prefill_logits_sha')}\")\nPY\ndate > $R/DONE\n", "tools/offload/sessions/session16.sh": "#!/bin/bash\n# offload card session 16 (docs/offload.md 10.13, the request's head), on the bitstream as loaded:\n# main (OLD: design A, the answer first) against this tree (the answer after the first expert's\n# first part, the other misses' willneed after it, touches deferred, a reused mincore vector,\n# the DMA lock reentrant), A B A B, q35e128s and g26s with their timelines and DMA calls. Host\n# only: the same programs, so both match RF bit for bit (main's 35B programs changed since\n# f725c2b: refs-8100ffb; the 26B's did not: refs-f725c2b). Predicted (serve_emu): the head -0.5\n# to -0.6 s per 128 tokens; the 35B 5.08-5.16 -> 5.20-5.27 tok/s, the 26B 3.58 -> 3.63-3.65.\n#   OLD     main's tree (default O/../tree-main: git archive of main with COMMIT)\n#   RF      the references (default O/refs-s16: q35ref16.json from refs-8100ffb, q26ref16.json\n#           from refs-f725c2b)\n# Then the 35B's layer-major prefill (pooled, R = 2, lmtime's 134-token prompt PF_HF, its sha\n# PF_SHA and tokens), main against this tree: onecall's prefill serve rose 6.56 -> 7.10 s.\n#   EXPECT  the card's build (default e4db91c9: production pa); another one stops it\n# About 26 min. It stops at a mismatch, a timeout or an error.\n# Run: otpu-lock --wait 10800 -- tools/offload/sessions/session16.sh   (log: O/s16/session.log)\nset -u\nSESSION=${SESSION:-s16}; RF=${RF:-${O:-$HOME/otpu-build/offload/card2}/refs-s16}\nsource \"$(dirname \"$0\")/env.sh\"             # (its RF defaults to O: set before)\nOLD=${OLD:-$(dirname \"$O\")/tree-main}\nexec > >(tee -a $R/session.log) 2>&1\necho \"session16 start $(date +%T) tree $rev old $(cat $OLD/COMMIT) mem $(mem) GB\"\nbad() { sleep 1; grep -c -E \"\\[FAIL\\]|exit 124|Traceback|STOP\" $R/session.log; }\nb0=$(bad)\nstop() { [ $(bad) -gt $b0 ] && { echo \"STOP $(date +%T): a mismatch, a timeout or an error\"; return 0; }; return 1; }\nrun() {   # its name, runs, tree\n  echo \"--- $1: $2 ($(cat $3/COMMIT 2>/dev/null || echo $3), RF $RF)\"\n  env T=$3 RF=$RF R=$R/$1 RUNS=\"$2\" bash \"$3/tools/offload/sessions/card_moe.sh\"\n}\nEXPECT=${EXPECT:-e4db91c9}\nPF_HF=${PF_HF:-$HOME/otpu-build/moepf/lmtime/q35w-hf.json} PF_SHA=${PF_SHA:-95426ebacc3b40a9}\nPF_TOK=\"[8160, 579, 264, 7047, 1817, 421]\"\npf() {    # its name, tree: the 35B's prompt layer-major, R = 2, pooled, with its timeline\n  echo \"--- $1: 35B layer-major prefill ($(cat $2/COMMIT))\"\n  t0=$SECONDS; cat $O/pool-q35-fp4.split.bin > /dev/null; echo \"  pool read in $((SECONDS - t0)) s\"\n  (cd $2 && PYTHONPATH=$2 timeout 1800 python tools/offload/moe_card.py $O/Qwen3.5-35B-A3B \\\n    --check $PF_HF -n 16 --pool $O/pool-q35-fp4.split.bin --cfg $R/cfg-dev.pkl --experts 0 --card \\\n    --policy lfu --embed-table host --hints off --layer-major 2 --prefill-trace $R/$1.trace.json \\\n    --out $R/$1.json > $R/$1.log 2>&1)\n  echo \"  exit $? $(date +%T)\"; grep -E \"Error|Traceback\" $R/$1.log | tail -3\n  python - $R/$1.json $PF_SHA \"$PF_TOK\" <<'PY' || echo \"STOP: $1 differs\"\nimport json, sys\nd = json.load(open(sys.argv[1]))\ntok = json.loads(sys.argv[3])\nok = d[\"prefill_logits_sha\"] == sys.argv[2] and d[\"tokens\"][:len(tok)] == tok\nprint(f\"  [{'PASS' if ok else 'FAIL'}] prefill sha {d['prefill_logits_sha']} vs {sys.argv[2]}, tokens \"\n      f\"{'same' if d['tokens'][:len(tok)] == tok else 'DIFFER'}; prefill {d['prefill_s']} s, \"\n      f\"requests {d.get('prefill_requests')} misses {d.get('prefill_misses')}\")\npt = d[\"prefill_time\"]\nprint(\"  prefill_time \" + json.dumps({k: pt.get(k) for k in (\"wall_s\", \"runs\", \"device_s\", \"between_s\", \"requests\", \"serve_s\")}))\nsys.exit(0 if ok else 1)\nPY\n}\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|build\" | tail -14\necho \"$st\" | grep -q \"build $EXPECT\" || echo \"STOP: the card's build is not $EXPECT\"\ntimeout 300 python tools/qual/refs.py cfg $R/cfg-dev.pkl > /dev/null 2>&1; echo \"cfg exit $?\"\nstop || for x in \"M1 q35e128s $OLD\" \"H1 q35e128s $T\" \"M2 q35e128s $OLD\" \"H2 q35e128s $T\"; do\n  run $x\n  stop && break\ndone\nstop || for x in \"pfM $OLD\" \"pfH $T\"; do\n  pf $x\n  stop && break\ndone\nstop || for x in \"gM1 g26s $OLD\" \"gH1 g26s $T\" \"gM2 g26s $OLD\" \"gH2 g26s $T\"; do\n  run $x\n  stop && break\ndone\necho \"session16 end $(date +%T)\"\npython - $R <<'PY'\nimport glob, json, sys\nr = sys.argv[1]\nfor f in sorted(glob.glob(f\"{r}/*/*.json\")):\n    if \".trace.\" in f:\n        continue\n    c = json.load(open(f))\n    h, d = c.get(\"host_decode_s\") or {}, c.get(\"device_counters\") or {}\n    g = {k: round(d.get(k, 0) / 1e9, 3) for k in (\"RUNNING\", \"MXU_STARVE\", \"DMA_BUSY\", \"DRAM_WAIT\")}\n    print(f\"  {f[len(r) + 1:]}: tok/s {c['tok_s_wall']} (device {c['tok_s_device']}), poll \"\n          f\"{h.get('poll')}, dma {h.get('dma_s')} ({h.get('dma_gbs')} GB/s), polls \"\n          f\"{h.get('polls_reads')}, G {g}, match {c.get('match')} sha {c.get('prefill_logits_sha')}\")\nPY\ndate > $R/DONE\n", "tools/offload/sessions/session17.sh": "#!/bin/bash\n# offload card session 17, on the bitstream as loaded (EXPECT: production fmvf 542fc43a), in one\n# lock, this tree throughout:\n# (b) LFM2.5-8B-A1B token-exact (design A owes it, docs/offload.md 10.11): 8b16, and 8b160 with\n#     LFM160=1. Its pool is in /dev/shm (LFMPOOL, copied before the lock: the host's disk is at\n#     its floor) behind links in O, all deleted right after (b). Skipped if LFMPOOL is missing.\n# (a) the decode's re-baseline on the fused build: q35e128s twice (the A runs of (c)), g26s twice.\n# (c) the 35B's capped hints (docs/offload.md 12.7): q35e128s (A), q35e128hn (B: pre, top 4, n 1)\n#     and with TOP8=1 q35e128hn8 (C: top 8) in a palindrome, A B C C B A (A B B A without C), so\n#     a linear drift cancels for each. Predicted for B: about +5% tok/s over A (contention\n#     0.13-0.17 s a GB: +5 to +6%; at 0.34: +1.6%); top 8 about +7%. Rule: hints on by default\n#     for the 35B only if B gains >= 2% over A with every run bit for bit.\n# Each model's first run after the others' pools leave the page cache runs slower (gemma4's\n# pfhint2: 35B 13.16 against 12.46 s, demand serve 6.83 -> 5.93 s), so a discarded warm-up run\n# of the base config (W, gW: checked, not compared) comes before the 35B's and the 26B's; the\n# summary gives each pair's difference. LFM2's runs are a token-exact check, not compared.\n# RF holds the ISA simulator's references: q35ref16 and q26ref16 (refs-s16: the programs are\n# unchanged since), q35ref16h (the hint programs with the caps, refs-hintcap), ref16 and ref160\n# (LFM2's, refs-lfm-3ef23f6). Without q35ref16h, HREF=q35ref16 links it to q35ref16 (hints\n# change no logit; logged), else the B runs are skipped.\n# About 35 min. It stops at a mismatch, a timeout or an error.\n# Run: otpu-lock --wait 10800 -- tools/offload/sessions/session17.sh   (log: O/s17/session.log)\nset -u\nSESSION=${SESSION:-s17}; RF=${RF:-${O:-$HOME/otpu-build/offload/card2}/refs-s17}\nsource \"$(dirname \"$0\")/env.sh\"             # (its RF defaults to O: set before)\nLFMPOOL=${LFMPOOL:-/dev/shm/offload-lfm/pool-lfm25-8b-fp4.split.bin}\nEXPECT=${EXPECT:-542fc43a}\nexec > >(tee -a $R/session.log) 2>&1\necho \"session17 start $(date +%T) tree $rev RF $RF mem $(mem) GB\"\nbad() { sleep 1; grep -c -E \"\\[FAIL\\]|exit 124|Traceback|STOP\" $R/session.log; }\nb0=$(bad)\nstop() { [ $(bad) -gt $b0 ] && { echo \"STOP $(date +%T): a mismatch, a timeout or an error\"; return 0; }; return 1; }\nrun() {   # its name, runs\n  echo \"--- $1: $2 ($rev, RF $RF)\"\n  env RF=$RF R=$R/$1 RUNS=\"$2\" bash \"$T/tools/offload/sessions/card_moe.sh\"\n}\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL|build\" | tail -14\necho \"$st\" | grep -q \"build $EXPECT\" || echo \"STOP: the card's build is not $EXPECT\"\nif [ ! -f $RF/q35ref16h.json ] && [ -n \"${HREF:-}\" ]; then\n  ln -s $HREF.json $RF/q35ref16h.json && echo \"q35ref16h: $HREF's (no ISA run of the hint programs)\"\nfi\nP=$O/pool-lfm25-8b-fp4.split.bin\nlfm_gone() { rm -f $P $P.packed $P.format; rm -rf \"$(dirname $LFMPOOL)\"; echo \"  LFM2 pool deleted $(date +%T); /dev/shm: $(df -h /dev/shm | tail -1)\"; }\nif ! stop && [ -f $LFMPOOL ] && [ ! -e $P ]; then\n  ln -s $LFMPOOL $P && cp $LFMPOOL.packed $LFMPOOL.format $O/\n  run b8 \"8b16${LFM160:+ 8b160}\"\n  lfm_gone\nelse\n  echo \"(b) skipped: $([ -f $LFMPOOL ] || echo \"no $LFMPOOL\")$([ -e $P ] && echo \" $P exists\")\"\nfi\nstop || for x in \"W q35e128s\" \"A1 q35e128s\" \"B1 q35e128hn\" ${TOP8:+\"C1 q35e128hn8\"} \\\n                 ${TOP8:+\"C2 q35e128hn8\"} \"B2 q35e128hn\" \"A2 q35e128s\" \"gW g26s\" \"gA1 g26s\" \\\n                 \"gA2 g26s\"; do\n  run $x\n  stop && break\ndone\necho \"session17 end $(date +%T)\"\npython - $R <<'PY'\nimport glob, json, sys\nimport numpy as np\nr = sys.argv[1]\nby = {}\nfor f in sorted(glob.glob(f\"{r}/*/*.json\")):\n    if \".trace.\" in f:\n        continue\n    c = json.load(open(f))\n    h, d = c.get(\"host_decode_s\") or {}, c.get(\"device_counters\") or {}\n    hi = c.get(\"hints\") or {}\n    run = f[len(r) + 1:].split(\"/\")[0]\n    by.setdefault(run.rstrip(\"0123456789\"), []).append(c)\n    print(f\"  {f[len(r) + 1:]}: tok/s {c['tok_s_wall']} (device {c['tok_s_device']}), generate \"\n          f\"{c.get('generate_s')} s, misses {c.get('misses_per_token_decode')} a decode token, MB \"\n          f\"{(c.get('bytes_per_token_decode') or 0) / 1e6:.0f}, serve {h.get('serve')}, hints \"\n          f\"{ {k: hi.get(k) for k in ('served', 'prefetched', 'promoted', 'dropped', 'withdrawn')} }, \"\n          f\"match {c.get('match')} sha {c.get('prefill_logits_sha')}\")\na = by.get(\"A\")                             # (the warm-up runs W, gW not compared)\nfor k in (\"B\", \"C\"):\n    if a and by.get(k):\n        ta, tb = (np.mean([c[\"tok_s_wall\"] for c in x]) for x in (a, by[k]))\n        pairs = \", \".join(f\"{y['tok_s_wall'] / x['tok_s_wall'] - 1:+.1%}\" for x, y in zip(a, by[k]))\n        print(f\"  {k} against A: tok/s {tb:.3f} against {ta:.3f} ({tb / ta - 1:+.1%}); by pair \"\n              f\"({k}1 / A1, {k}2 / A2): {pairs}\")\nPY\ndate > $R/DONE\n", "tools/offload/sessions/session18.sh": "#!/bin/bash\n# Session 18 (offload, docs/offload.md 13.12): the halt-aware hold re-measured with its fix\n# (offload-hold: run_clock during a run's serve; pfv2 had holds 0), and the 35B decode hints'\n# confirm against the default parts (ra since pfv2). One otpu-lock; per pair one discarded\n# warm-up run, then A B B A, each pair's difference reported.\n# (1) the 35B's layer-major prefill (R = 2, pooled, lmtime's 134-token prompt, 16 tokens) with\n#     the layer-ahead predictor and whole-expert parts (--layer-ahead hint --ahead-part 4096):\n#     A = --idle-parts ra, B = --idle-parts v2. Pass: lmtime's sha 95426ebacc3b40a9 and tokens.\n#     B must show holds > 0.\n# (2) the 35B decode, 128 tokens, A B C C B A: A = q35e128s (no hints; ref q35ref16), B = the\n#     hints (pre, top 4, n 1, whole-expert parts, --hint-drop; ref q35ref16h) with --idle-parts\n#     ra, C = the same with v2; hint traces kept. Hints become the default only at >= 2% with\n#     both pairs positive, on the parts mode (1) makes the default.\n# Host only against main's programs, so session 17's references hold (RF: card2/refs-s17). A\n# build other than EXPECT, a failed selftest, a failed or timed-out run or a mismatch stops it;\n# no retries. About 25 min.\n# Run: setsid -f otpu-lock --wait 3600 -- bash tools/offload/sessions/session18.sh   (no pipe)\nset -u\nSESSION=s18\nRF=${RF:-$HOME/otpu-build/offload/card2/refs-s17}\nsource \"$(dirname \"$0\")/env.sh\"\nexec > >(tee -a $R/session.log) 2>&1\nEXPECT=${EXPECT:-542fc43a}\nDROPOTHER=$HOME/openTPU/models:$O:$O/../g26\nLM=${LM:-$HOME/otpu-build/moepf/lmtime/q35w-hf.json}\nP=\"--embed-table host --hints off --layer-major 2 --layer-ahead hint --ahead-part 4096\"\nHN=\"--embed-table host --hints on --hint-drop --hint-n 1 --hint-top 4 --hint-part 1632\"\nQ=Qwen3.5-35B-A3B; QP=pool-q35-fp4.split.bin\ndeclare -A RUN=(         # checkpoint, pool, HF's, tokens, reference, moe_card's other options\n  [pW]=\"$Q $QP $LM 16 sha:95426ebacc3b40a9 $P --idle-parts ra\"\n  [pA1]=\"$Q $QP $LM 16 sha:95426ebacc3b40a9 $P --idle-parts ra\"\n  [pB1]=\"$Q $QP $LM 16 sha:95426ebacc3b40a9 $P --idle-parts v2\"\n  [pB2]=\"$Q $QP $LM 16 sha:95426ebacc3b40a9 $P --idle-parts v2\"\n  [pA2]=\"$Q $QP $LM 16 sha:95426ebacc3b40a9 $P --idle-parts ra\"\n  [dW]=\"$Q $QP $O/q35-hf.json 128 $RF/q35ref16.json --embed-table host --hints off\"\n  [dA1]=\"$Q $QP $O/q35-hf.json 128 $RF/q35ref16.json --embed-table host --hints off --hint-trace TRACE\"\n  [dB1]=\"$Q $QP $O/q35-hf.json 128 $RF/q35ref16h.json $HN --idle-parts ra --hint-trace TRACE\"\n  [dC1]=\"$Q $QP $O/q35-hf.json 128 $RF/q35ref16h.json $HN --idle-parts v2 --hint-trace TRACE\"\n  [dC2]=\"$Q $QP $O/q35-hf.json 128 $RF/q35ref16h.json $HN --idle-parts v2 --hint-trace TRACE\"\n  [dB2]=\"$Q $QP $O/q35-hf.json 128 $RF/q35ref16h.json $HN --idle-parts ra --hint-trace TRACE\"\n  [dA2]=\"$Q $QP $O/q35-hf.json 128 $RF/q35ref16.json --embed-table host --hints off --hint-trace TRACE\")\nQ35TOK=\"[8160, 579, 264, 7047, 1817, 421]\"        # (lmtime's first tokens)\necho \"session18 start $(date +%T) tree $rev mem $(mem) GB; $(uptime)\"\nst=$(timeout 600 python -m opentpu.host.selftest 2>&1)\necho \"$st\" | grep -E \"\\[(PASS|FAIL)\\]|ALL\" | tail -14\necho \"$st\" | grep -q \"build $EXPECT\" || { echo \"STOP: the card's build is not $EXPECT\"; exit 2; }\necho \"$st\" | grep -q \"ALL PASS\" || { echo \"STOP: selftest\"; exit 2; }\ntimeout 300 python tools/qual/refs.py cfg $R/cfg-dev.pkl > /dev/null 2>&1; echo \"cfg exit $?\"\nfor run in pW pA1 pB1 pB2 pA2 dW dA1 dB1 dC1 dC2 dB2 dA2; do\n  read -r md pool hf n ref extra <<< \"${RUN[$run]}\"\n  extra=${extra//TRACE/$R/$run.hint.json}\n  ptr=\"\"; [ $n = 16 ] && ptr=\"--prefill-trace $R/$run.trace.json\"\n  echo \"=== $run $(date +%T) ($extra)\"\n  python - $O/$md $O/$pool $DROPOTHER <<'PY'\nimport os, sys                      # every other file of 100 MB or more out of the page cache\nkeep = {os.path.realpath(sys.argv[1]), os.path.realpath(sys.argv[2])}  # (card_moe.sh's DROPOTHER)\nours = tuple(os.path.realpath(os.path.expanduser(d)) + os.sep for d in (\"~/openTPU\", \"~/otpu-build\"))\ngb = n = 0\nseen = set()\nfor d in sys.argv[3].split(\":\"):\n    for root, _, files in os.walk(os.path.expanduser(d)):\n        for f in files:\n            r = os.path.realpath(os.path.join(root, f))\n            if r in seen or not r.startswith(ours) or not os.path.isfile(r) \\\n                    or os.path.getsize(r) < 100 << 20 or r in keep or os.path.dirname(r) in keep:\n                continue\n            seen.add(r)\n            fd = os.open(r, os.O_RDONLY)\n            os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n            os.close(fd)\n            gb, n = gb + os.path.getsize(r) / 1e9, n + 1\nprint(f\"  dropped from the page cache: {n} other files of {gb:.1f} GB\")\nPY\n  t0=$SECONDS; cat $O/$pool > /dev/null; echo \"  pool read in $((SECONDS - t0)) s, mem $(mem) GB\"\n  timeout 900 python tools/offload/moe_card.py $O/$md --check $hf -n $n --pool $O/$pool \\\n    --cfg $R/cfg-dev.pkl --experts 0 --card --policy lfu $extra $ptr \\\n    --out $R/$run.json > $R/$run.log 2>&1\n  rc=$?; echo \"  exit $rc $(date +%T)\"; grep -E \"Error|Traceback\" $R/$run.log | tail -3\n  [ $rc -eq 0 ] && [ -f $R/$run.json ] || { echo \"STOP: $run\"; break; }\n  python - $R/$run.json $ref \"$Q35TOK\" <<'PY' || { echo \"STOP: $run differs\"; break; }\nimport json, sys\nd = json.load(open(sys.argv[1]))\nif sys.argv[2].startswith(\"sha:\"):\n    sha, tok = sys.argv[2][4:], json.loads(sys.argv[3])\nelse:\n    r = json.load(open(sys.argv[2]))\n    sha, tok = r[\"prefill_logits_sha\"], r[\"tokens\"]\nok = d[\"prefill_logits_sha\"] == sha and d[\"tokens\"][:len(tok)] == tok\nprint(f\"  [{'PASS' if ok else 'FAIL'}] prefill sha {d['prefill_logits_sha']} vs {sha}, tokens \"\n      f\"{'same' if d['tokens'][:len(tok)] == tok else 'DIFFER'}; prefill {d['prefill_s']} s, \"\n      f\"decode {d['tok_s_wall']} tok/s (device {d.get('tok_s_device')}), misses/token \"\n      f\"{d.get('misses_per_token_decode')}\")\nprint(\"  idle_parts \" + json.dumps(d.get(\"idle_parts\")) + \" hints \" + json.dumps(d.get(\"hints\")))\npt = d.get(\"prefill_time\")\nif pt:\n    print(\"  prefill_time \" + json.dumps({k: pt.get(k) for k in (\"wall_s\", \"runs\", \"device_s\",\n                                                                \"between_s\", \"requests\", \"serve_s\")}))\nsys.exit(0 if ok else 1)\nPY\ndone\necho \"=== final selftest $(date +%T)\"\ntimeout 600 python -m opentpu.host.selftest 2>&1 | grep -E \"\\[(PASS|FAIL)\\]|ALL\" | tail -14\necho \"session18 end $(date +%T)\"\npython - $R <<'PY'\nimport json, os, sys\nr = sys.argv[1]\ndef get(run):\n    f = f\"{r}/{run}.json\"\n    return json.load(open(f)) if os.path.exists(f) else None\nfor name, runs, b, key in ((\"35B prefill, ra -> v2\", \"p\", \"B\", \"prefill_s\"),\n                           (\"35B decode, hints top 4 + ra\", \"d\", \"B\", \"tok_s_wall\"),\n                           (\"35B decode, hints top 4 + v2\", \"d\", \"C\", \"tok_s_wall\")):\n    a1, b1, b2, a2 = (get(runs + x) for x in (\"A1\", b + \"1\", b + \"2\", \"A2\"))\n    if None in (a1, b1, b2, a2):\n        print(f\"  {name}: incomplete\"); continue\n    v = lambda c: c[key] if key != \"prefill_s\" else c[\"prefill_time\"][\"wall_s\"]   # noqa: E731\n    d1, d2 = v(b1) - v(a1), v(b2) - v(a2)\n    ma, mb = (v(a1) + v(a2)) / 2, (v(b1) + v(b2)) / 2\n    rel = f\" ({mb / ma - 1:+.2%})\" if key == \"tok_s_wall\" else \"\"\n    print(f\"  {name} ({key}): A {v(a1):.3f} {v(a2):.3f}, {b} {v(b1):.3f} {v(b2):.3f}; pairs \"\n          f\"{b}-A {d1:+.3f} {d2:+.3f}; means {b}-A {mb - ma:+.3f}{rel}\")\n    for x, c in ((b + \"1\", b1), (b + \"2\", b2)):\n        print(f\"    {x} idle_parts {json.dumps(c.get('idle_parts'))}\")\nPY\ndate > $R/DONE\n", "tools/offload/sessions/session5.sh": "#!/bin/bash\n# offload card session 5 (2026-10-01, production build B, Gen1, no reload; tree 7a048e5,\n# offload-hint): Qwen3.5-35B-A3B, 16 tokens, slots by decayed use filling the DRAM (--experts 0):\n#   q35c   the embedding table on the card, no hints (34-35 slots a layer)\n#   q35e   the table on the host (42 slots a layer), no hints\n#   q35eh  the table on the host, hints on\n# each token-exact against the ISA simulator's q35ref16. The pool must hold all 10240 experts\n# (the card host's checkpoint has none: pack_pool.py's send / recv). Results: docs/offload.md\n# 10.4, 12.5. About 35 min (3 image builds).\n# Run: otpu-lock --wait 10800 -- tools/offload/sessions/session5.sh   (log: O/s5/session.log)\nset -u\nSESSION=s5; source \"$(dirname \"$0\")/env.sh\"\nexec > >(tee -a $R/session.log) 2>&1\necho \"session5 start $(date +%T) tree $rev mem $(mem) GB\"\nRUNS=\"${RUNS:-q35c q35e q35eh}\" bash \"$here/card_moe.sh\"\necho \"session5 end $(date +%T)\"\ndate > $R/DONE\n", "tools/offload/sessions/session6.sh": "#!/bin/bash\n# offload card session 6 (2026-10-01, production build B, Gen1, no reload; tree d0835eb: main\n# ee7fa64 + ExpertServer's drop and timeline): session 5's follow-up on the router hints, which\n# lost 5%. The full 35B pool, its page cache warm:\n#   q35e    table on the host, no hints (session 5's noise)\n#   q35eht  + hints (512 KiB parts), with the decode's timeline\n#   q35ehd  + a request withdrawing its layer's unnamed hints\n#   q35ehs  + 128 KiB parts\n#   q35ehds + both\n#   q35c    table on the card, no hints\n# each token-exact against q35ref16. Results: docs/offload.md 12.6. About 12 min.\n# Run: otpu-lock --wait 10800 -- tools/offload/sessions/session6.sh   (log: O/s6/session.log)\nset -u\nSESSION=s6; source \"$(dirname \"$0\")/env.sh\"\nexec > >(tee -a $R/session.log) 2>&1\necho \"session6 start $(date +%T) tree $rev mem $(mem) GB\"\nRUNS=\"${RUNS:-q35e q35eht q35ehd q35ehs q35ehds q35c}\" bash \"$here/card_moe.sh\"\necho \"session6 end $(date +%T)\"\ndate > $R/DONE\n", "tools/offload/sessions/session7.sh": "#!/bin/bash\n# offload card session 7 (2026-10-01, production build B, Gen1, no reload; tree 91e17ec,\n# hint-tune): the embedding table on the host against on the card at 128 tokens, each twice and\n# interleaved (16 tokens vary by ~6% on the host), the pool read into the page cache before each\n# run, the polls' beat read. Each run's first 16 tokens and prefill against q35ref16, the four\n# runs' 128 tokens against each other. Results: docs/offload.md 10.4. About 12 min.\n# Run: otpu-lock --wait 10800 -- tools/offload/sessions/session7.sh   (log: O/s7/session.log)\nset -u\nSESSION=s7; source \"$(dirname \"$0\")/env.sh\"\nexec > >(tee -a $R/session.log) 2>&1\necho \"session7 start $(date +%T) tree $rev mem $(mem) GB\"\nRUNS=\"${RUNS:-q35e128a q35c128a q35e128b q35c128b}\" bash \"$here/card_moe.sh\"\necho \"session7 end $(date +%T)\"\npython - $R <<'PY'\nimport json, sys\nr = {n: json.load(open(f\"{sys.argv[1]}/q35card128{n}.json\")) for n in (\"ea\", \"ca\", \"eb\", \"cb\")}\nprint(\"  128 tokens the same in all four runs:\", len({tuple(x[\"tokens\"]) for x in r.values()}) == 1)\nPY\ndate > $R/DONE\n", "tools/offload/sessions/session8.sh": "#!/bin/bash\n# offload card session 8 (2026-10-01, production build B, Gen1, no reload; tree 2a0b962, the DMA\n# guard): Gemma 4 26B-A4B with its experts streamed (docs/offload.md 11): int8 layers, fp4\n# experts (the split pool, G26POOL) and fp4 head, 18 slots a layer by decayed use, 128 tokens\n# after wiki.txt's first paragraph, twice. Then one 35B run as session 7's q35e128a: the guard's\n# cost against O/s7's. Each run's first 16 tokens and prefill against the ISA simulator's\n# reference (q26ref16: reference.sh), the two 26B runs' 128 tokens against each other.\n# Results: docs/offload.md 11.5. About 35 min.\n# Run: otpu-lock --wait 10800 -- tools/offload/sessions/session8.sh   (log: O/s8/session.log)\nset -u\nSESSION=s8; source \"$(dirname \"$0\")/env.sh\"\nexec > >(tee -a $R/session.log) 2>&1\n[ -e $O/gemma-4-26B-A4B ] || ln -s ${G26:-$HOME/openTPU/models/gemma-4-26B-A4B} $O/gemma-4-26B-A4B\necho \"session8 start $(date +%T) tree $rev mem $(mem) GB\"\nRUNS=\"${RUNS:-g26a g26b q35e128a}\" bash \"$here/card_moe.sh\"\necho \"session8 end $(date +%T)\"\npython - $R $O/s7 <<'PY'\nimport json, os, sys\no, s7 = sys.argv[1:]\nr = {n: json.load(open(f\"{o}/g26card128{n}.json\")) for n in (\"a\", \"b\")\n     if os.path.exists(f\"{o}/g26card128{n}.json\")}\nprint(\"  26B: 128 tokens the same in both runs:\",\n      len(r) == 2 and len({tuple(x[\"tokens\"]) for x in r.values()}) == 1)\ndef polls(x):\n    h = x[\"host_decode_s\"]\n    return f\"polls' reads {1e6 * h['polls_read_s'] / max(h['polls_reads'], 1):.1f} us x {h['polls_reads']}\"\nfor n, x in r.items():\n    print(f\"  g26{n}: {x['tok_s_wall']} tok/s, {polls(x)}\")\nif os.path.exists(f\"{o}/q35card128ea.json\") and os.path.exists(f\"{s7}/q35card128ea.json\"):\n    c, s = (json.load(open(f\"{d}/q35card128ea.json\")) for d in (o, s7))\n    print(f\"  35B: tokens as session 7's: {c['tokens'] == s['tokens']}; tok/s {c['tok_s_wall']} \"\n          f\"(s7 {s['tok_s_wall']}); {polls(c)} (s7 {polls(s)})\")\nPY\ndate > $R/DONE\n", "tools/offload/sessions/session9.sh": "#!/bin/bash\n# offload card session 9 (production build B, Gen1, no reload): the experts' MMs paired (main\n# d29bfe9, moe-pair) against unpaired, in one session. Tree B is this one (d29bfe9 + this\n# script; its ISA-simulator references in RFB, made by reference.sh at d29bfe9), tree A main\n# 7d879e6, before moe-pair (TA; its references in RFA: sessions 7 and 8's, and LFM2.5-8B's\n# 160 tokens made at 7d879e6). A B A B, each with:\n#   q35e128a  Qwen3.5-35B-A3B, the table on the host, 128 tokens (session 7: 3.84, 3.87 tok/s)\n#   g26a      gemma-4-26B-A4B, int8 / fp4 experts / fp4 head, 128 tokens (session 8: 2.77, 2.77)\n#   8b160     LFM2.5-8B-A1B, 160 tokens (session 3: 10.64), when its pool is staged\n# each run against its own tree's reference (tokens, prefill sha). The co-simulation projects\n# +3-4% for the 35B and the 26B (link-bound at Gen1) and +35-40% for LFM2.5-8B. The first live\n# run of the repo's card_moe.sh; results: docs/offload.md 10.5. About 35 min (AB=B: tree B\n# alone, about 18). It stops at a mismatch, a timeout or an error (a FAIL, a selftest's).\n# WAITPOOL=s: LFM2.5-8B's pool is streamed in while this holds the lock (opentpu's disk keeps it\n# only for the session): the sparse file made here, then pack_pool.py send | recv from a host\n# with the whole checkpoint, ending with POOL.done; up to s seconds, a pool not whole removed.\n# DROPPOOL=1: the pool removed at the end.\n# Run: otpu-lock --wait 10800 -- tools/offload/sessions/session9.sh   (log: O/s9/session.log)\nset -u\nSESSION=s9; source \"$(dirname \"$0\")/env.sh\"\nexec > >(tee -a $R/session.log) 2>&1\nTB=$T; TA=${TA:-$O/../tree-7d879e6}; RFA=${RFA:-$O/refs-7d879e6} RFB=${RFB:-$O/refs-d29bfe9}\necho \"session9 start $(date +%T) tree B $rev, A $(cat $TA/COMMIT 2>/dev/null) mem $(mem) GB\"\nP=$O/pool-lfm25-8b-fp4.split.bin\nif [ -n \"${WAITPOOL:-}\" ]; then\n  [ -f $P ] || python tools/offload/pack_pool.py $O/LFM2.5-8B-A1B $P init\n  t0=$SECONDS; until [ -f $P.done ] || [ $((SECONDS - t0)) -gt $WAITPOOL ]; do sleep 10; done\n  if python -c \"import numpy, sys; sys.exit(not numpy.fromfile('$P.packed', numpy.uint8).all())\"; then\n    echo \"  LFM2.5-8B's pool whole after $((SECONDS - t0)) s\"\n  else\n    echo \"  LFM2.5-8B's pool not whole: removed, 8b160 skipped\"; rm -f $P $P.packed $P.format $P.done\n  fi\nfi\nbad() { sleep 1; grep -c -E \"\\[FAIL\\]|exit 124|Traceback|STOP\" $R/session.log; }\nb0=$(bad)\nfor k in 1 2; do\n  for t in ${AB:-A B}; do\n    if [ $t = A ]; then tt=$TA rf=$RFA; else tt=$TB rf=$RFB; fi\n    echo \"--- tree $t ($tt), round $k\"\n    T=$tt RF=$rf R=$R/$t$k RUNS=\"${RUNS:-q35e128a g26a 8b160}\" bash \"$here/card_moe.sh\"\n    [ $(bad) -gt $b0 ] && { echo \"STOP $(date +%T): a mismatch, a timeout or an error\"; break 2; }\n  done\ndone\necho \"session9 end $(date +%T)\"\n[ -n \"${DROPPOOL:-}\" ] && rm -f $P $P.packed $P.format $P.done && echo \"  LFM2.5-8B's pool removed\"\npython - $R <<'PY'\nimport glob, json, os, sys\nr = sys.argv[1]\nfor name in (\"q35card128ea\", \"g26card128a\", \"card160\"):\n    v = {t: [json.load(open(f)) for f in sorted(glob.glob(f\"{r}/{t}[12]/{name}.json\"))]\n         for t in (\"A\", \"B\")}\n    if not v[\"B\"]:\n        continue\n    s = {t: [x[\"tok_s_wall\"] for x in v[t]] for t in v}\n    same = len({tuple(x[\"tokens\"]) for x in v[\"B\"]}) == 1\n    gain = (f\", B/A {sum(s['B']) / len(s['B']) / (sum(s['A']) / len(s['A'])) - 1:+.1%}\"\n            if s[\"A\"] else \"\")\n    print(f\"  {name}: tok/s A {s['A']} B {s['B']}{gain}; B's runs the same tokens: {same}\")\nPY\ndate > $R/DONE\n", "tools/offload/sessions/wiki1.txt": "The Roman Empire was a state that dominated the Mediterranean and much of Europe, Western Asia, and North Africa during the classical period. The Roman Republic had previously conquered most of these territories, which later came under permanent single-person rule following Octavian's rise to power and the establishment of the Augustan Principate in 27 BC. By the late 3rd century AD, the empire had been divided many times. The Western Roman Empire collapsed in 476 AD, whereas the Eastern Roman Empire (also known as the Byzantine Empire) persisted until the fall of Constantinople in 1453.\n", "tools/offload/slot_bench.py": "\"\"\"The expert server's write rate on the card, without a model (docs/offload.md section 10):\nrequests of k missing experts served into DRAM slots, through BackendDram (Board.write) and\nBoardDram (one-pass channel runs, a DMA thread, the host's words from a shadow). The script plays\nthe card's side of the mailbox itself (it posts each request's ids and seq), so no program runs.\nIt writes whole 64-byte beats only, into a scratch layout at --base, after zeroing its mailbox\nand directory (a scrubbed card: no read of a beat never written).\n\n    python3 tools/offload/slot_bench.py                 # the card (/dev/xdma0), under its lock\n    python3 tools/offload/slot_bench.py --null          # host only: a transport that drops\n                                                        # the DMA (the staging's CPU cost)\n\nThe experts come from host RAM (the page cache's case, warm), 1.67 MB (Qwen3.5-35B-A3B) and\n5.85 MB (LFM2.5-8B-A1B) by default.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport time\nfrom types import SimpleNamespace\n\nimport numpy as np\n\nSIZES = {\"q35\": 1671168, \"lfm8b\": 5849088}      # bytes per expert slot (ExpertFormat, fp4)\n\n\ndef bench(board, slot: int, k: int, reqs: int, base: int, kind: str, pool_file=None,\n          reader=\"pread\", warm=False, pieces=2) -> dict:\n    from pathlib import Path\n\n    from opentpu.host.offload import (LINE, SPLIT, BackendDram, BoardDram, ExpertServer, Layout,\n                                      PoolFile)\n    E = k * (reqs + 1)                          # every id new: k misses per request\n    lay = Layout.build(base, E, k, (E,), slot)\n    if pool_file:                   # a real pool file's packed experts, each memory its own E\n        done = np.fromfile(str(pool_file) + \".packed\", np.uint8)\n        if Path(pool_file).stat().st_size != len(done) * slot:\n            raise ValueError(f\"{pool_file}: not {len(done)} slots of {slot} bytes\")\n        gids = np.nonzero(done)[0][(kind == \"board\") * E:][:E]\n        if len(gids) < E:\n            raise ValueError(f\"{pool_file}: fewer than {2 * E} packed experts\")\n        fmt = Path(str(pool_file) + \".format\")\n        split = fmt.exists() and fmt.read_text().strip() == SPLIT\n        if reader == \"mmap\":        # the memmap's rows (its pages; the split format's bytes\n            mm = np.memmap(pool_file, np.uint8, \"r\")         # as if the slot's: a rate only)\n            mm = mm[:len(mm) // slot * slot].reshape(-1, slot)\n            pool = [mm[g] for g in gids]\n        else:                       # MO.serve's reader, its warm thread first with --warm\n            pf = PoolFile(pool_file, slot, split)\n            if warm:\n                pf.warm(gids).join()\n            pool = None\n    else:\n        pool = np.random.default_rng(0).integers(0, 256, (E, slot), dtype=np.uint8)\n    if kind == \"board\":\n        mem = BoardDram(SimpleNamespace(board=board), lay, pieces=pieces)\n    else:\n        mem = BackendDram(SimpleNamespace(write=lambda s, a, d: board.write(a, d),\n                                          read=lambda s, a, n: board.read(a, n)))\n    srv = ExpertServer(mem, lay, (lambda g: pool[g]) if pool is not None else\n                       (lambda g: pf.get(int(gids[g]))))\n    srv.load(())\n    t_serve, tm = 0.0, {\"stage\": 0.0, \"flush\": 0.0}\n    for name in tm:                             # BoardDram: the staging, the waits for the DMA\n        f = getattr(mem, \"write_slot\" if name == \"stage\" else \"flush\", None)\n        if f is not None:\n            def timed(*a, _f=f, _n=name):\n                t0 = time.perf_counter()\n                try:\n                    return _f(*a)\n                finally:\n                    tm[_n] += time.perf_counter() - t0\n            setattr(mem, \"write_slot\" if name == \"stage\" else \"flush\", timed)\n    for seq in range(1, reqs + 1):\n        ids = [(seq - 1) * k + i for i in range(k)]\n        board.write(lay.row, np.array(ids + [0] * (LINE // 4 - k), np.float32))\n        board.write(lay.mbox, np.float32(seq).tobytes())\n        t0 = time.perf_counter()\n        assert srv.poll() == 1\n        t_serve += time.perf_counter() - t0\n    mb = srv.bytes / 1e6\n    r = dict(memory=type(mem).__name__, slot_mb=round(slot / 1e6, 3), k=k, requests=reqs,\n             ms_per_expert=round(1e3 * t_serve / (reqs * k), 3),\n             ms_per_request=round(1e3 * t_serve / reqs, 3), mb_s=round(mb / t_serve))\n    if kind == \"board\":\n        r[\"dma_gb_s\"] = round(mem.dma_bytes / mem.dma_s / 1e9, 3) if mem.dma_s else None\n        r[\"direct\"] = mem.direct                # read from the file into the runs\n        r[\"pieces\"] = mem.pieces\n        r.update({f\"{x}_ms_per_expert\": round(1e3 * v / (reqs * k), 3) for x, v in tm.items()})\n    return r\n\n\ndef main():\n    ap = argparse.ArgumentParser(description=__doc__.split(\"\\n\")[0])\n    ap.add_argument(\"--null\", action=\"store_true\", help=\"no card: a transport that drops DMA\")\n    ap.add_argument(\"--base\", type=lambda x: int(x, 0), default=0x8000_0000,\n                    help=\"the scratch layout's logical DRAM address\")\n    ap.add_argument(\"--reqs\", type=int, default=40, help=\"requests per size and memory\")\n    ap.add_argument(\"-k\", type=int, default=3, help=\"missing experts per request\")\n    ap.add_argument(\"--sizes\", nargs=\"*\", default=list(SIZES))\n    ap.add_argument(\"--pool\", help=\"read the experts from this pool file (one --sizes entry: \"\n                                   \"its slot size), not host RAM\")\n    ap.add_argument(\"--reader\", choices=(\"pread\", \"mmap\"), default=\"pread\",\n                    help=\"--pool: MO.serve's reader (os.preadv; a split-format file straight \"\n                         \"into the channel runs), or the memmap's rows\")\n    ap.add_argument(\"--pieces\", type=int, default=2,\n                    help=\"BoardDram: the parts of an expert read when no DMA is in flight\")\n    ap.add_argument(\"--warm\", action=\"store_true\", help=\"--pool pread: read the experts into \"\n                                                        \"the page cache first (the warm thread)\")\n    a = ap.parse_args()\n    from opentpu.host.board import Board\n    if a.null:\n        from opentpu.host.fake import FakeTransport\n\n        class Null(FakeTransport):\n            \"\"\"Keeps the mailbox and the directory (its first MiB), drops the slots' DMA.\"\"\"\n            threaded = True\n\n            def mem_write(self, ch, off, data):\n                if off + len(data) <= len(self.ch[ch]):\n                    super().mem_write(ch, off, data)\n        board = Board(Null(ch_bytes=1 << 20, devname=None))\n        board.info()[\"caps\"][\"chash\"] = True            # the production map's swaps\n        a.base = 0\n    else:\n        from opentpu.host.board import XdmaTransport\n        board = Board(XdmaTransport(\"/dev/xdma0\"))\n    try:\n        for s in a.sizes:\n            for kind in (\"backend\", \"board\"):\n                print(json.dumps(dict(size=s, chash=board.chash,\n                                      **bench(board, SIZES[s], a.k, a.reqs, a.base, kind,\n                                              a.pool, a.reader, a.warm, a.pieces))),\n                      flush=True)\n    finally:\n        board.close()\n\n\nif __name__ == \"__main__\":\n    main()\n", "tools/offload/strip_experts.py": "\"\"\"A MoE checkpoint without its routed experts, for the card's host (docs/offload.md 10.4, 11.4):\nthe card run reads the experts from the packed pool file only (pack_pool.py), so the host keeps\nevery other tensor, in its own dtype, in one safetensors file, with the checkpoint's other files.\n\n    python3 tools/offload/strip_experts.py SRC DST                   # Qwen3.5-35B-A3B: 4.6 GiB\n    python3 tools/offload/strip_experts.py SRC DST --only model.language_model.   # Gemma 4 26B\n    python3 tools/offload/strip_experts.py SRC DST --mtp --only mtp. --out mtp.safetensors\n\nDropped: the routed experts (`.experts.`; a shared expert is `shared_expert`), the vision tower\nand the MTP head (`model.visual.`, `mtp.`: LazyWeights skips them), and with --only every tensor\noutside that prefix (the 26B's vision and audio towers). --mtp keeps the MTP head but its routed\nexperts (an MTP image's: they stream from its pool, docs/offload.md 15.6): with --only mtp. and\n--out mtp.safetensors (the file's name), the file that turns the card host's checkpoint into\nan MTP image's beside the other's files (Qwen3.5-35B-A3B: 0.1 GiB).\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport shutil\nfrom pathlib import Path\n\n\ndef main():\n    ap = argparse.ArgumentParser(description=__doc__.split(\"\\n\")[0])\n    ap.add_argument(\"src\")\n    ap.add_argument(\"dst\")\n    ap.add_argument(\"--only\", help=\"keep only the tensors under this prefix\")\n    ap.add_argument(\"--mtp\", action=\"store_true\", help=\"keep the MTP head (mtp.*) but its experts\")\n    ap.add_argument(\"--out\", default=\"model.safetensors\", help=\"the tensors' file in DST\")\n    a = ap.parse_args()\n    from safetensors import safe_open\n    from safetensors.torch import save_file\n\n    src, dst = Path(a.src), Path(a.dst)\n    dst.mkdir(parents=True, exist_ok=True)\n    for f in src.iterdir():\n        if f.is_file() and f.suffix != \".safetensors\" and f.name != \"model.safetensors.index.json\":\n            shutil.copy2(f, dst / f.name)\n    keep, skipped, nb = {}, 0, 0\n    drop = (\"model.visual.\",) if a.mtp else (\"model.visual.\", \"mtp.\")\n    for f in sorted(src.glob(\"*.safetensors\")):\n        with safe_open(str(f), \"pt\") as h:\n            for k in h.keys():\n                if (\".experts.\" in k or k.startswith(drop)\n                        or (a.only and not k.startswith(a.only))):\n                    skipped += 1\n                    continue\n                t = h.get_tensor(k)\n                keep[k] = t.contiguous()\n                nb += t.numel() * t.element_size()\n    save_file(keep, str(dst / a.out), metadata={\"format\": \"pt\"})\n    print(f\"kept {len(keep)} tensors ({nb / 2**30:.2f} GiB), skipped {skipped}\")\n\n\nif __name__ == \"__main__\":\n    main()\n", "tools/offload/survey.py": "\"\"\"Survey of MoE (and too-big dense) checkpoints for expert offloading (docs/offload.md).\n\n    python3 tools/offload/survey.py [--json out.json] [repo ...]\n\nReads each checkpoint's safetensors headers over HTTP (two range requests per shard, no weights\ndownloaded) and the config, sorts every text-decoder tensor into experts, shared experts,\ndense (attention, norms, routers, dense MLPs), embedding, LM head and per-layer embeddings (PLE),\nand prints per model:\n\n- the expert shape: routed experts per MoE layer, top-k, shared experts, one expert's parameters\n  and its bytes in our 4-bit format (fp4 with two-level scales, 4.25 bits per weight);\n- total and active parameters (active: dense + shared + top-k experts per MoE layer + LM head);\n- the bytes a decode token streams on the card: dense + shared + top-k experts in fp4, the LM\n  head in int8 (8.25 bits), the embedding row not counted (one row is looked up);\n- the footprint in fp4 / int8 head: the part that must stay on the card (dense, shared, head,\n  embedding table in int8 when untied) and the expert pool (what an expert cache holds).\n\nVision, audio and multi-token-prediction weights are left out: the card decodes text.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport re\nimport struct\nimport sys\nimport urllib.request\nfrom concurrent.futures import ThreadPoolExecutor\nfrom collections import defaultdict\n\nHF = \"https://huggingface.co\"\nFP4_BITS = 4.25          # fp4 elements + one 32-bit two-level scale word per 128 (docs/quant.md)\nINT8_BITS = 8.25         # int8 + an fp32 scale per 128\n\nMODELS = [\n    \"google/gemma-4-26B-A4B\",\n    \"google/gemma-4-E4B\",\n    \"LiquidAI/LFM2-8B-A1B\",\n    \"LiquidAI/LFM2.5-8B-A1B\",\n    \"LiquidAI/LFM2-24B-A2B\",\n    \"Qwen/Qwen3-30B-A3B\",\n    \"Qwen/Qwen3.5-35B-A3B\",\n    \"Qwen/Qwen3-Next-80B-A3B-Instruct\",\n    \"Qwen/Qwen3.5-122B-A10B\",\n    \"allenai/OLMoE-1B-7B-0125\",\n    \"ibm-granite/granite-3.1-3b-a800m-instruct\",\n    \"ibm-granite/granite-4.0-h-tiny\",\n    \"ibm-granite/granite-4.0-h-small\",\n    \"openai/gpt-oss-20b\",\n    \"openai/gpt-oss-120b\",\n    \"deepseek-ai/DeepSeek-V2-Lite\",\n    \"moonshotai/Moonlight-16B-A3B-Instruct\",\n    \"PowerInfer/SmallThinker-21BA3B-Instruct\",\n    \"PowerInfer/SmallThinker-4BA0.6B-Instruct\",\n    \"microsoft/Phi-mini-MoE-instruct\",\n    \"mistralai/Mixtral-8x7B-v0.1\",\n]\n\nSKIP = re.compile(r\"(^|\\.)(visual|vision_tower|vision_model|audio_tower|audio_model|embed_vision|\"\n                  r\"embed_audio|multi_modal_projector|mtp|vision|audio)(\\.|_)\")\nEXPERT = re.compile(r\"(\\.experts\\.|\\.experts_|block_sparse_moe\\.(input|output)_linear)\")\nSHARED = re.compile(r\"(shared_expert\\.|shared_experts\\.|shared_mlp\\.)\")\nLAYER = re.compile(r\"layers\\.(\\d+)\\.\")\nEXPERT_ID = re.compile(r\"experts\\.(\\d+)\\.\")\n\n\ndef _get(url, rng=None):\n    req = urllib.request.Request(url, headers={\"Range\": f\"bytes={rng[0]}-{rng[1]}\"} if rng else {})\n    with urllib.request.urlopen(req, timeout=60) as r:\n        return r.read()\n\n\ndef header(repo, fname):\n    url = f\"{HF}/{repo}/resolve/main/{fname}\"\n    n = struct.unpack(\"<Q\", _get(url, (0, 7)))[0]\n    h = json.loads(_get(url, (8, 8 + n - 1)))\n    h.pop(\"__metadata__\", None)\n    return h\n\n\ndef text_config(cfg):\n    for k in (\"text_config\", \"llm_config\", \"language_config\"):\n        if isinstance(cfg.get(k), dict):\n            return cfg[k]\n    return cfg\n\n\ndef first(c, *keys, default=None):\n    for k in keys:\n        if c.get(k) is not None:\n            return c[k]\n    return default\n\n\ndef numel(t):\n    n = 1\n    for d in t[\"shape\"]:\n        n *= d\n    return n\n\n\ndef survey(repo):\n    info = json.loads(_get(f\"{HF}/api/models/{repo}\"))\n    files = [s[\"rfilename\"] for s in info[\"siblings\"]\n             if s[\"rfilename\"].endswith(\".safetensors\") and \"/\" not in s[\"rfilename\"]\n             and not s[\"rfilename\"].startswith(\"consolidated\")]\n    cfg = json.loads(_get(f\"{HF}/{repo}/resolve/main/config.json\"))\n    tc = text_config(cfg)\n    E = first(tc, \"num_experts\", \"num_local_experts\", \"n_routed_experts\", \"moe_num_experts\",\n              \"moe_num_primary_experts\")\n    k = first(tc, \"num_experts_per_tok\", \"top_k_experts\", \"moe_topk\", \"num_experts_per_token\",\n              \"moe_top_k\", \"moe_num_active_primary_experts\")\n    groups = defaultdict(int)\n    with ThreadPoolExecutor(8) as ex:\n        headers = list(ex.map(lambda f: header(repo, f), files))\n    moe_layers, expert_params = set(), defaultdict(int)   # per (layer): params of all experts\n    for h in headers:\n        for name, t in h.items():\n            if SKIP.search(name):\n                continue\n            n = numel(t)\n            if name.endswith(\"_blocks\"):          # MXFP4 (gpt-oss): two elements per byte\n                n *= 2\n            elif name.endswith(\"_scales\"):        # its E8M0 scales: part of the 4-bit format\n                continue\n            m = LAYER.search(name)\n            if EXPERT.search(name) and not SHARED.search(name):\n                layer = int(m.group(1))\n                moe_layers.add(layer)\n                expert_params[layer] += n\n                groups[\"experts\"] += n\n            elif SHARED.search(name) and \"shared_expert_gate\" not in name:\n                groups[\"shared\"] += n\n            elif \"per_layer\" in name and (\"embed\" in name):\n                groups[\"ple\"] += n               # Gemma per-layer embeddings (a row per token)\n            elif \"embed_tokens\" in name or name.endswith(\"wte.weight\") or \"word_embeddings\" in name:\n                groups[\"embed\"] += n\n            elif name.startswith(\"lm_head\") or \".lm_head\" in name or name == \"output.weight\":\n                groups[\"head\"] += n\n            else:\n                groups[\"dense\"] += n\n    L = first(tc, \"num_hidden_layers\", \"n_layers\")\n    tied = groups[\"head\"] == 0                    # no LM head tensor: the embedding is the head\n    nm = len(moe_layers)\n    per_expert = (groups[\"experts\"] / (nm * E)) if nm and E else 0\n    head = groups[\"head\"] or groups[\"embed\"]\n    active_exp = (k or 0) * per_expert * nm\n    total = groups[\"dense\"] + groups[\"shared\"] + groups[\"experts\"] + groups[\"embed\"] \\\n        + groups[\"head\"] + groups[\"ple\"]\n    active = groups[\"dense\"] + groups[\"shared\"] + active_exp + head\n    b4 = FP4_BITS / 8\n    b8 = INT8_BITS / 8\n    return {\n        \"repo\": repo, \"arch\": first(tc, \"model_type\", default=cfg.get(\"model_type\")),\n        \"layers\": L, \"moe_layers\": nm, \"experts\": E, \"top_k\": k,\n        \"shared\": groups[\"shared\"], \"hidden\": first(tc, \"hidden_size\", \"d_model\"),\n        \"expert_ffn\": first(tc, \"moe_intermediate_size\", \"expert_intermediate_size\",\n                            \"intermediate_size\"),\n        \"vocab\": first(tc, \"vocab_size\"), \"tied\": tied,\n        \"per_expert\": per_expert, \"experts_total\": groups[\"experts\"],\n        \"dense\": groups[\"dense\"], \"embed\": groups[\"embed\"], \"head\": groups[\"head\"],\n        \"ple\": groups[\"ple\"], \"total\": total, \"active\": active,\n        # bytes: fp4 blocks, int8 head; the embedding table in int8 on the card when untied\n        \"expert_bytes\": per_expert * b4,\n        \"tok_expert_bytes\": active_exp * b4,\n        \"tok_bytes\": (groups[\"dense\"] + groups[\"shared\"] + active_exp) * b4 + head * b8,\n        \"resident_bytes\": (groups[\"dense\"] + groups[\"shared\"]) * b4 + head * b8\n        + (0 if tied else groups[\"embed\"] * b8),\n        \"pool_bytes\": groups[\"experts\"] * b4,\n        \"ple_bytes\": groups[\"ple\"] * b4,\n    }\n\n\ndef main():\n    ap = argparse.ArgumentParser(description=__doc__.split(\"\\n\")[0])\n    ap.add_argument(\"repos\", nargs=\"*\", default=MODELS)\n    ap.add_argument(\"--json\")\n    a = ap.parse_args()\n    rows = []\n    for r in a.repos:\n        try:\n            rows.append(survey(r))\n        except Exception as e:  # noqa: BLE001 - a missing / gated repo is reported, not fatal\n            print(f\"{r}: {type(e).__name__}: {e}\", file=sys.stderr)\n    G = 1e9\n    print(f\"{'model':42} {'L':>3} {'moe':>3} {'E':>4} {'k':>2} {'exp MB':>6} {'total B':>7} \"\n          f\"{'active B':>8} {'tok MB':>7} {'exp/tok MB':>10} {'resident GB':>11} {'pool GB':>7}\")\n    for d in rows:\n        print(f\"{d['repo']:42} {d['layers']:>3} {d['moe_layers']:>3} {d['experts'] or 0:>4} \"\n              f\"{d['top_k'] or 0:>2} {d['expert_bytes'] / 1e6:6.2f} {d['total'] / G:7.2f} \"\n              f\"{d['active'] / G:8.2f} {d['tok_bytes'] / 1e6:7.0f} \"\n              f\"{d['tok_expert_bytes'] / 1e6:10.0f} {d['resident_bytes'] / G:11.2f} \"\n              f\"{d['pool_bytes'] / G:7.2f}\")\n    if a.json:\n        with open(a.json, \"w\") as f:\n            json.dump(rows, f, indent=1)\n\n\nif __name__ == \"__main__\":\n    main()\n", "tools/omarchy_test.sh": "#!/usr/bin/env bash\n# Run pytest for this script's worktree on the omarchy box instead of this machine.\n#\n#   tools/omarchy_test.sh [pytest args...]        e.g. tools/omarchy_test.sh -q tests/test_rtl.py -k fuzz\n#   tools/omarchy_test.sh --exec CMD [args...]    any command in the tree instead of pytest (with\n#                                                 the venv and Verilator on PATH), e.g.\n#                                                 --exec env OTPU_AXI=1 python -m pytest -q tests/test_board.py\n#\n# Optional: OTPU_REMOTE_NAME=<name> names the tree (~/otpu-test/<name>, default: the worktree's\n# directory name + a hash of its path); OTPU_REMOTE_BUILD=<dir under ~> links the tree's build/\n# (the Verilator cache, keyed by source hash) to a shared directory, so fresh trees reuse it.\n#\n# Ships the worktree the script is in (not the current directory's: `bash /path/to/tree/tools/\n# omarchy_test.sh` tests that tree), its tracked files with their uncommitted edits, to\n# ~/otpu-test/<name> on omarchy and says which tree and commit on stderr; files there that the\n# worktree no longer tracks are deleted (build/, models and __pycache__ stay), so a module\n# removed here is gone there too. Links the model checkpoints and runs pytest there with\n# ~/.local/bin/verilator and ~/otpu-venv.\n# At most OTPU_REMOTE_JOBS (default 2) test runs share omarchy at once; a run waits for a free\n# slot, so Vivado builds keep most of the CPU and memory (two builds plus three test runs\n# thrashed 32 GB). The Verilator cache (build/) stays per tree on omarchy between runs of the\n# same worktree. Exit status is pytest's.\nset -euo pipefail\nHOST=${OTPU_REMOTE:-omarchy.tail5bd214.ts.net}\nJOBS=${OTPU_REMOTE_JOBS:-2}\nEXTRA_KB=${OTPU_REMOTE_EXTRA_KB:-16000000}   # the extra slot's MemAvailable floor (16 GB)\nmode=pytest\nif [[ ${1:-} == --exec ]]; then mode=exec; shift; fi\ntop=$(cd \"$(dirname \"${BASH_SOURCE[0]}\")/..\" && git rev-parse --show-toplevel)\nname=${OTPU_REMOTE_NAME:-$(basename \"$top\")-$(printf '%s' \"$top\" | shasum | cut -c1-6)}\ndir=\"otpu-test/$name\"\nbuild=${OTPU_REMOTE_BUILD:-}\nmark=${OTPU_REMOTE_SLOT_MARK:-}   # set: say on stderr when the run holds its slot (the tournament's\n                                 # gate timeouts count from there)\nedits=$(git -C \"$top\" status --porcelain --untracked-files=no | wc -l | tr -d ' ')\necho \"omarchy_test: $top at $(git -C \"$top\" rev-parse --short HEAD)$([[ $edits == 0 ]] ||\n  echo \" + $edits uncommitted\") -> $HOST:~/$dir\" >&2\n\n# the tree as it is now: tracked files, including uncommitted edits; then the files it no longer\n# tracks go (the list inline, then the pruning script)\nssh \"$HOST\" \"mkdir -p ~/$dir\"\n(cd \"$top\" && git ls-files -z | COPYFILE_DISABLE=1 tar --no-mac-metadata --no-xattrs --null -T - -cf -) | ssh \"$HOST\" \"tar -xf - -C ~/$dir\"\n{ printf 'cd ~/%s\\ncat > .otpu-files <<\"OTPU_FILES_END\"\\n' \"$dir\"\n  git -C \"$top\" -c core.quotePath=false ls-files\n  printf 'OTPU_FILES_END\\n'; cat <<'PRUNE'\nLC_ALL=C sort -o .otpu-files .otpu-files\nfind . \\( -path ./build -o -path ./models -o -path ./obj_dir -o -name __pycache__ \\\n  -o -name .pytest_cache \\) -prune -o \\( -type f -o -type l \\) -print | sed 's|^\\./||' \\\n  | grep -vx .otpu-files | LC_ALL=C sort | LC_ALL=C comm -23 - .otpu-files \\\n  | while IFS= read -r f; do rm -f -- \"$f\"; done\n# a package whose sources all went: its __pycache__ too (else it imports as a namespace\n# package), then the empty directories\nfind . \\( -path ./build -o -path ./obj_dir \\) -prune -o -name __pycache__ -type d -print \\\n  | while IFS= read -r d; do [ -n \"$(ls -A \"$(dirname \"$d\")\" | grep -vx __pycache__)\" ] || rm -rf \"$d\"; done\nfind . -mindepth 1 \\( -path ./build -o -path ./obj_dir \\) -prune -o -type d -empty -print \\\n  | while IFS= read -r d; do rmdir -p \"$d\" 2> /dev/null || true; done\nPRUNE\n} | ssh \"$HOST\" \"bash -s\"\n\nargs=$(printf '%q ' \"$@\")\nssh \"$HOST\" \"bash -s\" <<EOF\nset -e\ncd ~/$dir\nln -sfn ~/openTPU/models models\nif [[ -n \"$build\" ]]; then mkdir -p ~/$build; rm -rf build; ln -sfn ~/$build build; fi\n# one of JOBS slots (flock on per-slot lock files), plus one more while omarchy has memory to spare\n# (MemAvailable above EXTRA_KB, i.e. no second full build placing)\nmkdir -p ~/otpu-test/.slots\nfor i in \\$(seq 1 3600); do\n  n=$JOBS\n  (( \\$(awk '/MemAvailable/{print \\$2}' /proc/meminfo 2> /dev/null || echo 0) > $EXTRA_KB )) && n=\\$((n + 1))\n  for s in \\$(seq 1 \\$n); do\n    exec 9>~/otpu-test/.slots/\\$s\n    if flock -n 9; then\n      if [[ -n \"$mark\" ]]; then echo \"omarchy_test: slot \\$s\" >&2; fi\n      export PATH=\\$HOME/.local/bin:\\$PATH\n      if [[ $mode == exec ]]; then\n        export PATH=\\$HOME/otpu-venv/bin:\\$PATH PYTHONPATH=\\$PWD\n        nice -n 5 $args\n      else\n        nice -n 5 ~/otpu-venv/bin/python -m pytest -p no:cacheprovider $args\n      fi\n      exit \\$?\n    fi\n  done\n  sleep 2\ndone\necho \"no free test slot on $HOST after 2 h\" >&2; exit 2\nEOF\n", "tools/perf_ddr.py": "\"\"\"Decode speed over core clocks on the RTL: one decode token (the resident decode program at\n--pos, as the card runs it) per core clock (and DDR3 rate: 1066 only, the board's DDR3 never runs\nfaster), through the board's memory path with either the card's controller (--mem ldc: LiteDRAM's\nown, co-simulated, rtlsim.MEMORY's LDC) or the calibrated bank model (--mem model:\notpu_native_mem, profile.ddr3_plusargs, 300 ns read latency).\n\n    python3 tools/perf_ddr.py CACHE.json IMGDIR --model qwen3 --format fp4 [--mem ldc]\n                              [--mhz 100,133.33,150,200] [--ddr 1066] [--prefixes]\n    python3 tools/perf_ddr.py CACHE.json IMGDIR --table [--models qwen3,qwen35,lfm2]\n                              [--formats fp4,int8] [--mem ldc] [--mhz ...] [--ddr ...]\n                              [--prefixes]\n\nA point is the whole model's token, simulated (2-3 minutes per point for these models on the\nco-simulated controller). --prefixes builds it from layer prefixes instead, as\ntools/perf_prefill.py builds prefill: the first layer, then per layer kind the difference of two\nprefixes (a run is one or two layers plus the LM head). That is faster but wrong on the card's\ntwo-port controller: there the second layer costs less than the layers after it (Qwen3 fp4 at\n133.33 MHz: 83.9k cycles, against 91.8k for every layer from the third on), and Qwen3's token\ncomes out 5.4% short (3.691 against 3.903 Mcycles; the card: 3.939). The whole model is within\n1.1% of the card (docs/litedram.md section 11). Each image (whole model or prefix) is built\nonce, streamed to IMGDIR as tb_top loads it (the image, then the program at the boot address,\nand after it the program's wait entries, opentpu.waits, as rtlsim writes them when the board's\notpu_seq runs WAITC: the target's SEQ_WC), and every point then runs the simulator on that file\n(the DRAM dump goes nowhere). Points are\ncached in CACHE.json (one entry per layer count and point, with the DRAM commands), so a stopped\nrun resumes. --table prints Mcycles/token, tokens/s, the\nDRAM bytes read and written per token and GB/s. The configuration comes from the environment\n(the board's: OTPU_MCOLS=4 OTPU_MXU=systolic OTPU_PAIR=1 OTPU_DSTEP=1 OTPU_STREAM=1). The KV cache\nholds --cap positions (default 2048), the LM head is int8 (--head). OTPU_LDC_BREAK=1 (--mem ldc)\nadds each channel's cycle breakdown (BRK lines: sim/verilator/otpu_ldc_mem.sv +ldc_break; cached\nunder the point's key + \"|brk\"; docs/litedram.md section 11, \"What is left after memeff\").\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport dataclasses\nimport json\nimport os\nimport re\nimport resource\nimport sys\nimport time\nfrom pathlib import Path\n\nimport numpy as np\n\nROOT = Path(__file__).resolve().parent.parent\nsys.path[:0] = [str(ROOT), str(ROOT / \"tools\")]\n\nfrom opentpu import isa as I  # noqa: E402\nfrom opentpu import rtlsim, simtmp  # noqa: E402\nfrom opentpu.waits import wait_counts  # noqa: E402\nfrom opentpu.compiler import arg_words  # noqa: E402\nfrom opentpu.isasim import board_config  # noqa: E402\nfrom opentpu.llm import load_spec, model_dir  # noqa: E402\nfrom opentpu.llm.qwen3 import ATTN_BLOCK, RunPos  # noqa: E402\nfrom opentpu.profile import ddr3_plusargs  # noqa: E402\nfrom perf_prefill import _kinds, _prefix, _proxies  # noqa: E402\n\nMTS = {1066: 3200 / 3}                 # the board's DDR3 never runs faster (its HR banks' rate)\nMIB = 1 << 20\nMAX_CYCLES = 1 << 26                   # a prefix's decode token is a few million cycles\n\n\ndef peak_mb() -> float:\n    r = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss\n    return r / MIB if sys.platform == \"darwin\" else r / 1024\n\n\nclass LazyW:\n    \"\"\"The checkpoint's tensors (load_weights' names, fp32), each read when indexed.\"\"\"\n\n    def __init__(self, path):\n        from safetensors import safe_open\n        self.at = {}\n        for f in sorted(Path(path).glob(\"*.safetensors\")):\n            with safe_open(str(f), \"pt\") as h:\n                for k in h.keys():\n                    if not k.startswith((\"model.visual.\", \"mtp.\")):\n                        self.at[k.replace(\"model.language_model.\", \"model.\", 1)] = (str(f), k)\n\n    def __contains__(self, k):\n        return k in self.at\n\n    def __getitem__(self, k):\n        import torch\n        from safetensors import safe_open\n        f, name = self.at[k]\n        with safe_open(f, \"pt\") as h:\n            return h.get_tensor(name).to(torch.float32).numpy()\n\n\ndef boot_program(prog: list, cfg) -> tuple[np.ndarray, int]:\n    \"\"\"The program's words as rtlsim._run boots it, and its instructions (the loader's boot_n):\n    when the board's otpu_seq runs WAITC (rtlsim.BOARD_UARCH's SEQ_WC, the card's since\n    release-2), the compiler's wait entries (opentpu.waits) follow its last chunk, 64 bits each;\n    without them the loader leaves the sidecar empty and the first dependency stops the run.\"\"\"\n    words = np.asarray(I.assemble(prog), \"<u4\")\n    n = len(words) // 8\n    if rtlsim.BOARD_UARCH.get(\"SEQ_WC\"):\n        ww = wait_counts(prog, cfg.D, cfg.S)\n        words = np.concatenate([words, np.zeros(-len(words) % (cfg.D // 4), \"<u4\"),\n                                ww.astype(\"<u8\").view(\"<u4\")])\n    return words, n\n\n\nclass Grid:\n    def __init__(self, cache: Path, imgdir: Path, mem: str, pos: int, cap: int, head: str,\n                 plus: list | None = None, prefixes: bool = False):\n        self.cache_p, self.imgdir, self.mem = cache, imgdir, mem\n        self.pos, self.cap, self.head = pos, cap, head\n        self.use_prefixes = prefixes\n        self.plus = list(plus or [])\n        self.cache = json.loads(cache.read_text()) if cache.exists() else {}\n\n    def key(self, name, n, wf, mhz, ddr) -> str:\n        env = \"|\".join(os.environ.get(k, \"-\") for k in\n                       (\"OTPU_MCOLS\", \"OTPU_MXU\", \"OTPU_PAIR\", \"OTPU_DSTEP\", \"OTPU_STREAM\"))\n        return (f\"{name}|{env}|{wf}|{self.head}|{mhz}|{ddr}|{n}|step|{self.pos}|{self.cap}|\"\n                f\"resident\" + (\"|ldc\" if self.mem == \"ldc\" else \"\") +\n                (\"|wc\" if rtlsim.BOARD_UARCH.get(\"SEQ_WC\") else \"\") +\n                \"\".join(f\"|{x}\" for x in self.plus))\n\n    @staticmethod\n    def prefixes(spec):\n        kinds = _kinds(spec)\n        _, diff = _proxies(kinds)\n        return kinds, diff, sorted({1} | {x for p in diff.values() for x in p})\n\n    def image(self, name, spec, W, n, wf) -> dict:\n        \"\"\"The prefix's DRAM file, program and run metadata in imgdir (built once).\"\"\"\n        wc = bool(rtlsim.BOARD_UARCH.get(\"SEQ_WC\"))\n        stem = self.imgdir.resolve() / (f\"{name}_{wf}_{self.head}_{self.pos}_{self.cap}_{n}\"\n                                         + (\"_wc\" if wc else \"\"))\n        meta_p = stem.with_suffix(\".json\")\n        if meta_p.exists():\n            return json.loads(meta_p.read_text())\n        t = time.time()\n        sp = _prefix(spec, n)\n        kw = dict(wformat=wf, head_format=self.head, lookup=True)\n        need = sp.image(board_config(DRAM_BYTES=1 << 40), self.cap, **kw).nbytes\n        # the simulated DRAM: a power of two up to 1 GiB, else in 256 MiB steps\n        size = 1 << max(20, (need - 1).bit_length())\n        if size > 1 << 30:\n            size = -(-(need + 16 * MIB) // (256 * MIB)) * 256 * MIB\n        img = sp.image(board_config(DRAM_BYTES=size), self.cap, **kw)\n        K = getattr(img.spec, \"conv_k\", 1)\n        b = self.pos // ATTN_BLOCK + 1\n        progs, ra = img.compile_decode(b, max((b - 1) * ATTN_BLOCK, K - 1), ATTN_BLOCK)\n        args = arg_words(ra, RunPos.values(791, self.pos, K, ATTN_BLOCK))\n        cfg = img.cfg\n        if 8 * len(progs[0]) > cfg.IMEM_WORDS:\n            cfg = dataclasses.replace(cfg, IMEM_WORDS=1 << (8 * len(progs[0]) - 1).bit_length())\n        prog, boot_n = boot_program(progs[0], cfg)\n        dram = img.build(W)[0]\n        n4 = -(-len(dram) // 4) * 4\n        at = -(-n4 // cfg.D) * cfg.D\n        grow = at + 4 * len(prog) > size          # rtlsim._run: the program above the DRAM\n        if grow:\n            at = size\n        tmp = stem.with_suffix(\".bin.tmp\")\n        with open(tmp, \"wb\") as f:                # rtlsim._run's image file, in pieces\n            step = 64 * MIB\n            for i in range(0, len(dram), step):\n                c = dram[i:i + step]\n                if len(c) % 4:\n                    c = np.concatenate([c, np.zeros(-len(c) % 4, np.uint8)])\n                c.view(\"<u4\").astype(\">u4\").tofile(f)\n            z = at - n4\n            while z > 0:\n                np.zeros(min(z, step) // 4, \">u4\").tofile(f)\n                z -= min(z, step)\n            prog.astype(\">u4\").tofile(f)\n        tmp.rename(stem.with_suffix(\".bin\"))\n        rtlsim._write_hex(stem.with_suffix(\".hex\"), prog[:8 * boot_n])\n        meta = {\"DRAM_BYTES\": size, \"IMEM_WORDS\": cfg.IMEM_WORDS, \"at\": at, \"grow\": grow,\n                \"boot_n\": boot_n, \"args\": [int(a) for a in args],\n                \"nbytes\": int(len(dram)), \"bin\": str(stem.with_suffix(\".bin\")),\n                \"hex\": str(stem.with_suffix(\".hex\"))}\n        meta_p.write_text(json.dumps(meta))\n        print(f\"  {name} {wf} {n} layers: image {meta['nbytes'] / MIB:.0f} MiB, DRAM \"\n              f\"{size / MIB:.0f} MiB, program {len(prog)} words ({time.time() - t:.0f} s, \"\n              f\"driver peak {peak_mb():.0f} MB)\", flush=True)\n        return meta\n\n    def simulate(self, meta, mhz, ddr) -> tuple[int, list]:\n        \"\"\"One token: cycles and the DRAM commands (reads, writes, row changes, partial).\"\"\"\n        size = meta[\"DRAM_BYTES\"]\n        cfg = dataclasses.replace(board_config(DRAM_BYTES=size), IMEM_WORDS=meta[\"IMEM_WORDS\"])\n        ldc = ddr if self.mem == \"ldc\" else 0\n        exe = rtlsim.build_top(cfg, 20, rtlsim.BOARD_UARCH, True,\n                               2 * size if meta[\"grow\"] else None, ldc)\n        with simtmp.tempdir(\"otpu_ddr_\") as d:\n            (d / \"dram_0.bin\").symlink_to(meta[\"bin\"])\n            (d / \"prog_0.hex\").symlink_to(meta[\"hex\"])\n            (d / \"dram_out_0.bin\").symlink_to(\"/dev/null\")\n            args = [str(exe), f\"+dir={d}\", f\"+max_cycles={MAX_CYCLES}\"] + self.plus\n            args += rtlsim.ldc_plusargs(ddr, mhz) if ldc else ddr3_plusargs(MTS[ddr], mhz)\n            args += [f\"+arg{k}={int(v) & 0xFFFFFFFF}\" for k, v in enumerate(meta[\"args\"])]\n            args += [\"+axi_stall=0\", f\"+axi_seed={rtlsim.MEMORY['SEED']}\", \"+axi_bw=100\",\n                     f\"+axi_lat={round(0.3 * mhz)}\"]\n            args += [\"+boot\", f\"+boot_addr={meta['at']}\", f\"+boot_n={meta['boot_n']}\"]\n            if ldc and os.environ.get(\"OTPU_LDC_BREAK\"):\n                args += [\"+ldc_break\"]     # the controller's cycle breakdown (otpu_ldc_mem.sv)\n            r = rtlsim.run_sim(args, timeout=3600)\n        out = r.stdout + r.stderr\n        self.brk = re.findall(r\"^BRK .*$\", out, re.M)\n        m = re.search(r\"RESULT cycles=(\\d+) halted=(\\d+) error=(\\d+)\", out)\n        if not m or m.group(2) != \"1\" or m.group(3) != \"0\":\n            raise RuntimeError(f\"RTL simulation failed:\\n{out[-3000:]}\")\n        mem = [tuple(map(int, x)) for x in\n               re.findall(r\"MEM ch\\d rd=(\\d+) wr=(\\d+) row_miss=(\\d+) rmw=(\\d+)\", out)]\n        return int(m.group(1)), [sum(x[i] for x in mem) for i in range(4)]\n\n    def layer_counts(self, spec) -> list:\n        \"\"\"The layer counts a point simulates: the whole model's, or its prefixes'.\"\"\"\n        return self.prefixes(spec)[2] if self.use_prefixes else [len(_kinds(spec))]\n\n    def full(self, name, spec, wf, mhz, ddr):\n        \"\"\"The whole model's token cycles and DRAM commands (None if not simulated yet): the\n        whole model's run, or (--prefixes) built from its prefixes.\"\"\"\n        if not self.use_prefixes:\n            k = self.key(name, len(_kinds(spec)), wf, mhz, ddr)\n            return self.cache.get(k), self.cache.get(k + \"|mem\")\n        kinds, diff, ns = self.prefixes(spec)\n        c = {n: self.cache.get(self.key(name, n, wf, mhz, ddr)) for n in ns}\n        m = {n: self.cache.get(self.key(name, n, wf, mhz, ddr) + \"|mem\") for n in ns}\n        if None in c.values():\n            return None, None\n        cyc = c[1] + sum(c[diff[k][1]] - c[diff[k][0]] for k in kinds[1:])\n        mm = None if None in m.values() else [\n            m[1][i] + sum(m[diff[k][1]][i] - m[diff[k][0]][i] for k in kinds[1:])\n            for i in range(4)]\n        return cyc, mm\n\n    def run(self, name, wf, mhzs, ddrs):\n        spec = load_spec(model_dir(name))\n        ns = self.layer_counts(spec)\n        self.imgdir.mkdir(parents=True, exist_ok=True)\n        W = LazyW(model_dir(name))\n        metas = {n: self.image(name, spec, W, n, wf) for n in ns}\n        del W\n        for ddr in ddrs:\n            for mhz in mhzs:\n                for n in ns:\n                    k = self.key(name, n, wf, mhz, ddr)\n                    if k in self.cache:\n                        continue\n                    t = time.time()\n                    cyc, mem = self.simulate(metas[n], mhz, ddr)\n                    self.cache[k], self.cache[k + \"|mem\"] = cyc, mem\n                    if getattr(self, \"brk\", None):\n                        self.cache[k + \"|brk\"] = self.brk\n                        print(\"\\n\".join(self.brk), flush=True)\n                    self.cache_p.write_text(json.dumps(self.cache, indent=1))\n                    print(f\"  {name} {wf} {mhz} MHz DDR3-{ddr}: {n} layers: {cyc} cycles \"\n                          f\"({time.time() - t:.0f} s) rd/wr/row_miss/rmw {mem}\", flush=True)\n                cyc, mm = self.full(name, spec, wf, mhz, ddr)\n                print(f\"{name} {wf} DDR3-{ddr} {mhz} MHz: {cyc} cycles, rd {mm[0]} wr {mm[1]} \"\n                      f\"(native commands; driver peak {peak_mb():.0f} MB)\", flush=True)\n\n    def table(self, names, wfs, mhzs, ddrs):\n        print(f\"{'model':7} {'fmt':4} {'DDR3':>5} {'MHz':>7} {'Mcyc/token':>10} {'tok/s':>6} \"\n              f\"{'MB read':>8} {'MB written':>10} {'GB/s':>6}\")\n        for name in names:\n            spec = load_spec(model_dir(name))\n            for wf in wfs:\n                for ddr in ddrs:\n                    for mhz in mhzs:\n                        cyc, mm = self.full(name, spec, wf, mhz, ddr)\n                        if cyc is None:\n                            continue\n                        rd, wr = (mm[0] * 64 / 1e6, mm[1] * 64 / 1e6) if mm else (0, 0)\n                        print(f\"{name:7} {wf:4} {ddr:5d} {mhz:7g} {cyc / 1e6:10.3f} \"\n                              f\"{mhz * 1e6 / cyc:6.1f} {rd:8.1f} {wr:10.1f} \"\n                              f\"{(rd + wr) * mhz / cyc * 1e3:6.2f}\")\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"cache\", type=Path)\n    ap.add_argument(\"imgdir\", type=Path)\n    ap.add_argument(\"--model\", help=\"run this model's points\")\n    ap.add_argument(\"--format\", default=\"fp4\", choices=[\"int8\", \"int4\", \"fp4\"])\n    ap.add_argument(\"--table\", action=\"store_true\", help=\"print the cached points\")\n    ap.add_argument(\"--models\", default=\"qwen3,qwen35,lfm2\")\n    ap.add_argument(\"--formats\", default=\"fp4,int8\")\n    ap.add_argument(\"--mem\", default=\"ldc\", choices=[\"ldc\", \"model\"])\n    ap.add_argument(\"--mhz\", default=\"100,133.33,150,200\")\n    ap.add_argument(\"--ddr\", default=\"1066\")\n    ap.add_argument(\"--pos\", type=int, default=544)\n    ap.add_argument(\"--cap\", type=int, default=2048)\n    ap.add_argument(\"--head\", default=\"int8\", choices=[\"int8\", \"int4\", \"fp4\"])\n    ap.add_argument(\"--plus\", action=\"append\", default=[],\n                    help=\"extra simulator argument (repeatable; part of the cache key)\")\n    ap.add_argument(\"--prefixes\", action=\"store_true\",\n                    help=\"build the token from layer prefixes (fast; short on two ports)\")\n    a = ap.parse_args()\n    g = Grid(a.cache, a.imgdir, a.mem, a.pos, a.cap, a.head, a.plus, a.prefixes)\n    mhzs = [float(x) for x in a.mhz.split(\",\")]\n    ddrs = [int(x) for x in a.ddr.split(\",\")]\n    if a.table:\n        g.table(a.models.split(\",\"), a.formats.split(\",\"), mhzs, ddrs)\n    elif a.model:\n        g.run(a.model, a.format, mhzs, ddrs)\n    else:\n        ap.error(\"--model or --table\")\n\n\nif __name__ == \"__main__\":\n    main()\n", "tools/perf_deltanet.py": "\"\"\"Measure the Gated DeltaNet recurrence on the RTL at the board configuration (AXI memory path).\n\n    python3 tools/perf_deltanet.py [--heads 1 8 16] [--bw 80] [--cl 2]\n\nRuns `kernels/deltanet.gated_deltanet_step` (128 x 128 fp32 states streamed through TMEM by LD\nand ST) with the new VOPs (RDOT, OUTER: 3 state passes per head) and on the older ISA (7\npasses), checks the RTL against the ISA simulator bit for bit, and prints the cycles. The\nold-ISA kernel does not compile for 16 heads (its 16K-word temporaries and the per-head tiles\nfragment the 64K-word TMEM): use the per-head slope between 1 and 8 heads.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport sys\nfrom pathlib import Path\n\nimport numpy as np\n\nROOT = Path(__file__).resolve().parent.parent\nsys.path.insert(0, str(ROOT))\nsys.path.insert(0, str(ROOT / \"tests\"))\n\nfrom opentpu import isa as I, rtlsim  # noqa: E402\nfrom opentpu.isasim import Machine, board_config  # noqa: E402\nfrom opentpu.compiler import CompileError  # noqa: E402\nfrom opentpu.kernels.deltanet import gated_deltanet_step  # noqa: E402\nfrom opentpu.runtime import collect, compile_kernel  # noqa: E402\nfrom test_vops import deltanet_args  # noqa: E402\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"--heads\", type=int, nargs=\"+\", default=[1, 8, 16])\n    ap.add_argument(\"--bw\", type=int, default=80)\n    ap.add_argument(\"--lat\", type=int, default=30)\n    ap.add_argument(\"--cl\", type=int, default=2, help=\"VPU composite lanes (VPU_CL)\")\n    a = ap.parse_args()\n    cfg = board_config(DRAM_BYTES=1 << 24)\n    uarch = dict(rtlsim.BOARD_UARCH, VPU_CL=a.cl)\n    for H in a.heads:\n        args, (Sw, ow) = deltanet_args(np.random.default_rng(H), H=H)\n        for fused in (True, False):\n            try:\n                comp, imgs = compile_kernel(gated_deltanet_step, cfg, **args, fused=fused)\n            except CompileError as e:\n                print(f\"H={H:2d} {'old ISA':22s} does not compile: {e}\")\n                continue\n            prog = comp.programs[0]\n            passes = sum(1 for i in prog if i.op == I.VOP and i.w[3] == 128 | (128 << 16))\n            m = Machine(cfg, comp.programs, [imgs[0].copy()]).run()\n            drams, tmems, st = rtlsim.run(cfg, comp.programs, [imgs[0].copy()], uarch=uarch,\n                                          axi=True, boot=True, bw=a.bw, lat=a.lat, stall=0)\n            exact = np.array_equal(drams[0], m.slices[0].dram) and \\\n                np.array_equal(tmems[0], m.slices[0].tmem)\n            out = collect(comp, drams, tmems, st).outputs\n            err = np.max(np.abs(out[\"state_out\"].transpose(0, 2, 1) - Sw)) / np.abs(Sw).max()\n            print(f\"H={H:2d} {'new ISA (RDOT, OUTER)' if fused else 'old ISA':22s} \"\n                  f\"CL={a.cl} bw={a.bw}%: {st['cycles']:8d} cycles  {len(prog):4d} instrs  \"\n                  f\"{passes:3d} state passes  bit-exact vs ISA sim: {exact}  \"\n                  f\"state rel err vs float64 {err:.1e}\", flush=True)\n\n\nif __name__ == \"__main__\":\n    main()\n", "tools/perf_prefill.py": "\"\"\"Prefill vs decode cycles per token on the RTL at the board configuration (simulated).\n\n    python3 tools/perf_prefill.py [--model qwen3|lfm2|qwen35|DIR] [--prompts 16,64,256]\n                                  [--bw 100] [--lat 30] [--cache FILE] [--validate]\n\nA prompt of P tokens from an empty cache, fed as the Engine does it: token by token with the\ndecode kernel (P steps; before chunked prefill) or in chunked prefill runs (qwen3.fit_chunk\npicks each run's rows: PREFILL_ROWS, fewer where TMEM or IMEM do not hold them; only the last\nrun computes logits, for its last row). Reported: device cycles per prompt token, both ways,\nthe speedup, and TTFT at an assumed 100 MHz (device time only, no host time).\n\nA full-model run takes minutes of RTL simulation per token, so the cost is built from proxies\nwith the real layer shapes and the full LM head (the timing does not depend on the data): the\nfirst 1, 2, ... layers of the model (enough to contain one layer of each kind). A layer's cost\nis the difference between consecutive prefixes, measured at a few positions and interpolated\nlinearly in the position (contexts below 256 are one attention block); the full model is the\nfirst prefix plus the cost of every further layer by kind. --validate also runs the whole\nmodel for one prefill run and one decode step and prints the extrapolation error.\n\nConfiguration: board_config() (OTPU_MCOLS / OTPU_LANES select the MXU columns and VPU lanes),\nrtlsim.BOARD_UARCH, the AXI memory path with the program booted from DRAM, `lat` cycles of AXI\nlatency, `bw` percent of the peak DRAM bandwidth (one D-byte chunk per cycle).\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport dataclasses\nimport json\nimport os\nimport sys\nimport time\nfrom pathlib import Path\n\nimport numpy as np\n\nROOT = Path(__file__).resolve().parent.parent\nsys.path.insert(0, str(ROOT))\n\nfrom opentpu import rtlsim, simtmp  # noqa: E402\nfrom opentpu.isasim import board_config  # noqa: E402\nfrom opentpu.llm import MODELS, load_spec, model_dir  # noqa: E402\nfrom opentpu.llm.qwen3 import PREFILL_ROWS, fit_chunk, load_weights, rope_tables  # noqa: E402\n\nSAMPLES = (0, 120, 240)          # positions where a layer's cost is measured\n\n\ndef _kinds(spec) -> tuple:\n    return spec.kinds if hasattr(spec, \"kinds\") else (\"attn\",) * spec.layers\n\n\ndef _prefix(spec, n: int):\n    \"\"\"The model cut to its first n layers.\"\"\"\n    if hasattr(spec, \"kinds\"):\n        return dataclasses.replace(spec, kinds=spec.kinds[:n])\n    return dataclasses.replace(spec, layers=n)\n\n\ndef _proxies(kinds) -> tuple[int, dict]:\n    \"\"\"The prefix lengths to measure and, per layer kind, (n, n + 1): the kind's cost is\n    c(n + 1) - c(n).\"\"\"\n    diff = {}\n    for i in range(1, len(kinds)):\n        diff.setdefault(kinds[i], (i, i + 1))\n    return sorted({1} | {n for p in diff.values() for n in p}), diff\n\n\nclass Bench:\n    def __init__(self, model: str, bw: int, lat: int, cache: Path | None):\n        self.path = model_dir(model)\n        self.spec = load_spec(self.path)\n        self.W = load_weights(self.path)\n        self.bw, self.lat, self.cache = bw, lat, cache\n        self.cap = 512\n        self.results = json.loads(cache.read_text()) if cache and cache.exists() else {}\n        self.images = {}\n\n    def image(self, n: int):\n        if n not in self.images:\n            spec = _prefix(self.spec, n)\n            probe = spec.image(board_config(DRAM_BYTES=1 << 40), self.cap, 1, PREFILL_ROWS)\n            cfg = board_config(DRAM_BYTES=1 << max(20, (probe.nbytes - 1).bit_length()))\n            img = spec.image(cfg, self.cap, 1, PREFILL_ROWS)\n            dram = img.build(self.W)[0]\n            x = np.asarray(self.W[\"model.embed_tokens.weight\"][791:791 + PREFILL_ROWS],\n                           np.float32)\n            b = np.ascontiguousarray(x).view(np.uint8).reshape(-1)\n            dram[img.io[\"x\"]:img.io[\"x\"] + b.size] = b\n            self.images[n] = (img, dram)\n        return self.images[n]\n\n    def cycles(self, n: int, kind: str, p0: int, rows: int = 1, head: bool = True) -> int:\n        \"\"\"Cycles of one run of the n-layer prefix: a decode step at p0 (\"step\") or `rows`\n        prompt rows at p0 .. (\"rows\"; logits for the last one with `head`).\"\"\"\n        key = f\"{self.path.name}|{board_config().MCOLS}|\" \\\n              f\"{os.environ.get('OTPU_ACT_ROWS', '0')}|{self.bw}|\" \\\n              f\"{self.lat}|{n}|{kind}|{p0}|{rows}|{head}\"\n        if key in self.results:\n            return self.results[key]\n        img, dram = self.image(n)\n        if kind == \"step\":\n            progs = img.compile_step(p0)\n        else:\n            progs = img.compile_rows([(0, p0 + j) for j in range(rows)],\n                                     [rows - 1] if head else [])\n        dram = dram.copy()\n        cs = [rope_tables(img.spec, p0 + j) for j in range(rows)]\n        for k, v in ((\"cos\", np.stack([c for c, _ in cs])), (\"sin\", np.stack([s for _, s in cs]))):\n            b = np.ascontiguousarray(v, np.float32).view(np.uint8).reshape(-1)\n            dram[img.io[k]:img.io[k] + b.size] = b\n        cfg = img.cfg\n        if 8 * len(progs[0]) > cfg.IMEM_WORDS:      # a proxy of the long program: time it\n            cfg = dataclasses.replace(cfg, IMEM_WORDS=1 << (8 * len(progs[0]) - 1).bit_length())\n        t = time.time()\n        with simtmp.tempdir(\"otpu_prefill_\") as d:\n            _, _, st = rtlsim.run(cfg, progs, [dram], uarch=rtlsim.BOARD_UARCH, axi=True,\n                                  boot=True, stall=0, bw=self.bw, lat=self.lat, keep=d,\n                                  max_cycles=1 << 40)\n        print(f\"  {n} layers {kind} p0={p0} rows={rows} head={head}: {st['cycles']} cycles \"\n              f\"({time.time() - t:.0f} s)\", flush=True)\n        self.results[key] = int(st[\"cycles\"])\n        if self.cache:\n            self.cache.write_text(json.dumps(self.results, indent=1))\n        return self.results[key]\n\n    def model_cost(self, kind: str, p0: int, rows: int, head: bool) -> float:\n        \"\"\"The full model's cycles for one run, from the prefixes (layer costs interpolated\n        between the SAMPLES positions for full-size runs).\"\"\"\n        kinds = _kinds(self.spec)\n        ns, diff = _proxies(kinds)\n\n        def c(n):\n            if kind == \"rows\" and (rows, head) != (self.R, False):\n                return self.cycles(n, kind, p0, rows, head)     # a run of its own: measured\n            lo = max(s for s in SAMPLES if s <= p0) if p0 < SAMPLES[-1] else SAMPLES[-2]\n            hi = SAMPLES[SAMPLES.index(lo) + 1]\n            a, b = self.cycles(n, kind, lo, rows, head), self.cycles(n, kind, hi, rows, head)\n            return a + (b - a) * (p0 - lo) / (hi - lo)\n\n        total = c(1)\n        for k in kinds[1:]:\n            i, j = diff[k]\n            total += c(j) - c(i)\n        return total\n\n    def plan(self, P: int) -> list:\n        \"\"\"The Engine's prefill runs for a P-token prompt: [(p0, rows)].\"\"\"\n        img = self.spec.image(board_config(), self.cap, 1, PREFILL_ROWS)\n        out, p0, fit = [], 0, PREFILL_ROWS\n        while p0 < P:\n            n, _, fit = fit_chunk(img, 256, 0, p0, PREFILL_ROWS, P - p0, fit)\n            out.append((p0, n))\n            p0 += n\n        return out\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"--model\", default=\"qwen3\",\n                    help=f\"{' or '.join(MODELS)} (models/<name>), or a checkpoint directory\")\n    ap.add_argument(\"--prompts\", default=\"16,64,256\")\n    ap.add_argument(\"--bw\", type=int, default=100)\n    ap.add_argument(\"--lat\", type=int, default=30)\n    ap.add_argument(\"--cache\", type=Path, help=\"keep RTL results between invocations\")\n    ap.add_argument(\"--validate\", action=\"store_true\")\n    a = ap.parse_args()\n    bench = Bench(a.model, a.bw, a.lat, a.cache)\n    prompts = [int(x) for x in a.prompts.split(\",\")]\n    plans = {P: bench.plan(P) for P in prompts}\n    ns = [n for pl in plans.values() for _, n in pl]\n    bench.R = max(set(ns), key=ns.count)       # the usual run: interpolated; others measured\n    print(f\"{bench.path.name}: {len(_kinds(bench.spec))} layers, prefill rows {bench.R} \"\n          f\"(MCOLS={board_config().MCOLS}, ACT_ROWS={board_config().act_rows}), bw {a.bw}%, \"\n          f\"lat {a.lat}; simulated RTL cycles\")\n    rows = []\n    for P in prompts:\n        dec = sum(bench.model_cost(\"step\", p, 1, True) for p in range(P))\n        pre = 0.0\n        for i, (p0, n) in enumerate(plans[P]):\n            last = i + 1 == len(plans[P])\n            pre += bench.model_cost(\"step\", p0, 1, True) if n == 1 else \\\n                bench.model_cost(\"rows\", p0, n, last)\n        rows.append((P, dec, pre, plans[P]))\n    print(f\"\\n{'prompt':>6} {'runs':>5} {'decode cyc/tok':>15} {'prefill cyc/tok':>16} \"\n          f\"{'speedup':>8} {'TTFT before':>12} {'TTFT after':>11}  (100 MHz, device only)\")\n    for P, dec, pre, pl in rows:\n        print(f\"{P:6d} {len(pl):5d} {dec / P:15,.0f} {pre / P:16,.0f} {dec / pre:7.2f}x \"\n              f\"{dec / 1e8:11.2f}s {pre / 1e8:10.2f}s\")\n    if a.validate:\n        n = len(_kinds(bench.spec))\n        for kind, p0, r, head in ((\"rows\", SAMPLES[1], bench.R, False), (\"step\", SAMPLES[1], 1,\n                                                                          True)):\n            want = bench.model_cost(kind, p0, r, head)\n            got = bench.cycles(n, kind, p0, r, head)\n            print(f\"validate {kind} p0={p0} rows={r}: full model {got}, extrapolated \"\n                  f\"{want:.0f} ({100 * (want - got) / got:+.3f}%)\")\n\n\nif __name__ == \"__main__\":\n    main()\n", "tools/perf_prompt.py": "\"\"\"Prompt-run prefill cycles per row, today's runs against tiled ones (docs/tiled_prefill.md):\nRTL co-simulation of one prompt run (docs/prefill.md: a P run at a run-time position, its state\nwords and tokens from DRAM) of R rows over the first L layers of a model.\n\n    python3 tools/perf_prompt.py --model qwen3.5-0.8b [--layers 4] [--blocks 2]\n        [--kernel prompt|tile] [--rows 4,8,16] [--mcols 4] [--act-rows 16] [--tmem 65536]\n        [--wformat fp4] [--head-format int8] [--mem ldc|port] [--depth 2] [--ranges]\n        [--imem 131072] [--phases] [--compile-only]\n\n--kernel prompt: today's prompt run (the image's compile_prompt_run, R rows); tile: the tiled\nprompt run (tiled.compile_tile_run, T rows). The run sits at the start of bucket --blocks\n(position (blocks - 1) * 256, tpos 0: it attends over blocks - 1 whole blocks and its own\nmasked one). ACT_ROWS: --act-rows, at least MCOLS (0: MCOLS, the card's). --depth: the tile's\nattention pipeline depth (0: compile_tile_run's choice, at the virtual IMEM ATTN_DEPTH);\n--ranges: the tile's range forms (tiled.ranges: W_o's operand a QACT range a part). IMEM\nis virtual (--imem words, default 1 << 17: 16K instructions; 1 << 19 holds every tile TMEM\ndoes) so a run that would not fit still measures; \"imem_fits\" says\nwhether it fits the card's (4096 instructions). --layers: the model's first L layers (Gemma 4:\nSpec.truncated).\n\nThe images are zeros (timing does not depend on the data). One JSON line per run: cycles,\ncycles per row, the core-port roofline (port-B chunks, the MXU's own cycles), with --phases the\ncycles per phase. --mem as tools/perf_tiled.py's.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport dataclasses\nimport json\nimport sys\nimport time\nfrom pathlib import Path\n\nimport numpy as np\n\nROOT = Path(__file__).resolve().parent.parent\nsys.path.insert(0, str(ROOT))\nsys.path.insert(0, str(ROOT / \"tools\"))\n\nfrom opentpu import isa as I  # noqa: E402\nfrom opentpu import rtlsim  # noqa: E402\nfrom opentpu.isasim import board_config  # noqa: E402\nfrom opentpu.llm import load_spec, model_dir  # noqa: E402\nfrom opentpu.profile import ddr3_plusargs, parse  # noqa: E402\n\nfrom perf_tiled import MHZ, phase  # noqa: E402\n\nCARD_IMEM = 4096 * 8\n\n\ndef cut(spec, n):\n    if hasattr(spec, \"truncated\"):\n        return spec.truncated(range(n))\n    if hasattr(spec, \"kinds\"):\n        return dataclasses.replace(spec, kinds=spec.kinds[:n])\n    return dataclasses.replace(spec, layers=n)\n\n\ndef compile_run(img, kernel, blocks, R, block=256, depth=0, ranges=False):\n    if kernel == \"prompt\":\n        return img.compile_prompt_run(blocks, R, \"P\", block)[0]\n    from opentpu.llm import tiled\n    if not depth and not ranges:\n        return tiled.compile_tile_run(img, blocks, R, \"P\", block)[0]\n    forms = tiled.variants\n    extra = dict(({\"depth\": depth} if depth else {}), **({\"whole\": False} if ranges else {}))\n    try:                                    # the forms at this attention depth / in ranges only\n        tiled.variants = lambda *a: [dict(v, **extra) for v in forms(*a)]\n        return tiled.compile_tile_run(img, blocks, R, \"P\", block)[0]\n    finally:\n        tiled.variants = forms\n\n\ndef one(a, spec, R):\n    act = max(a.act_rows or a.mcols, a.mcols)\n    kw = dict(MCOLS=a.mcols, ACT_ROWS=act, TMEM_WORDS=a.tmem, IMEM_WORDS=a.imem, PAIR=True,\n              DSTEP=True, STREAM=True)\n    cap = 256 * (a.blocks + 1)\n    rec = dict(model=a.model, layers=a.layers, blocks=a.blocks, R=R, mcols=a.mcols,\n               act_rows=act, tmem=a.tmem, wformat=a.wformat, mem=a.mem, kernel=a.kernel,\n               depth=getattr(a, \"depth\", 0), ranges=getattr(a, \"ranges\", False))\n    ikw = dict(rows=max(R, 8), wformat=a.wformat, head_format=a.head_format, lookup=True)\n    probe = spec.image(board_config(DRAM_BYTES=1 << 40, **kw), cap, **ikw)\n    cfg = board_config(DRAM_BYTES=1 << max(20, (probe.nbytes - 1).bit_length()), **kw)\n    img = spec.image(cfg, cap, **ikw)\n    t = time.time()\n    try:\n        progs = compile_run(img, a.kernel, a.blocks, R, depth=getattr(a, \"depth\", 0),\n                            ranges=getattr(a, \"ranges\", False))\n    except Exception as e:                  # TMEM / ACT RAM / rows: the fit answer\n        rec[\"error\"] = f\"{type(e).__name__}: {e}\"[:300]\n        return rec\n    rec[\"instructions\"] = max(len(p) for p in progs)\n    rec[\"imem_fits\"] = rec[\"instructions\"] * 8 <= CARD_IMEM\n    rec[\"mms\"] = sum(1 for i in progs[0] if i.op == I.MM)\n    rec[\"compile_s\"] = round(time.time() - t, 1)\n    if a.compile_only:\n        return rec\n    dram = np.zeros(img.nbytes, np.uint8)\n    if a.mem == \"ldc\":\n        plus = rtlsim.ldc_plusargs(1066, MHZ) + ddr3_plusargs(3200 / 3, MHZ)[2:]\n        mem = dict(ldc=1066, bw=100, lat=round(0.3 * MHZ),\n                   plusargs=[\"+axi_dram=1\", \"+axi_map=1\"] + plus)\n    else:\n        mem = dict(ldc=0, bw=100, lat=a.lat, plusargs=[])\n    t = time.time()\n    _, _, st = rtlsim.run(cfg, progs, [dram], trace=True, uarch=rtlsim.BOARD_UARCH, axi=True,\n                          boot=True, stall=0, max_cycles=1 << 40, **mem)\n    rec[\"sim_s\"] = round(time.time() - t)\n    p = parse(st[\"trace\"], cfg, progs, \"prompt\")\n    p.cycles = st[\"cycles\"]\n    ps = p.roofline()[\"per_slice\"][0]\n    rec.update(cycles=p.cycles, per_row=round(p.cycles / R), portb=ps[\"portb\"],\n               porta=ps[\"porta_cycles\"], mxu=ps[\"mxu\"],\n               busy={k: v for k, v in p.unit_busy(0).items() if v})\n    if a.phases:\n        ph = p.phases(lambda r: phase(progs[0][r.pc]))\n        rec[\"phases\"] = {k: dict(cycles=v[\"cycles\"], portb=v[\"portb\"], VPU=v[\"VPU\"],\n                                 MXU=v[\"MXU\"]) for k, v in ph.items()}\n    return rec\n\n\ndef main():\n    ap = argparse.ArgumentParser(description=__doc__.split(\"\\n\")[0])\n    ap.add_argument(\"--model\", required=True)\n    ap.add_argument(\"--layers\", type=int, default=4)\n    ap.add_argument(\"--blocks\", type=int, default=2)\n    ap.add_argument(\"--kernel\", choices=[\"prompt\", \"tile\"], default=\"prompt\")\n    ap.add_argument(\"--rows\", default=\"4,8,16\")\n    ap.add_argument(\"--mcols\", type=int, default=4)\n    ap.add_argument(\"--act-rows\", type=int, default=0)\n    ap.add_argument(\"--tmem\", type=int, default=1 << 16)\n    ap.add_argument(\"--wformat\", default=\"fp4\")\n    ap.add_argument(\"--head-format\", default=\"int8\")\n    ap.add_argument(\"--mem\", choices=[\"ldc\", \"port\"], default=\"ldc\")\n    ap.add_argument(\"--lat\", type=int, default=40)\n    ap.add_argument(\"--depth\", type=int, default=0)\n    ap.add_argument(\"--imem\", type=int, default=1 << 17, help=\"IMEM words (virtual)\")\n    ap.add_argument(\"--ranges\", action=\"store_true\")\n    ap.add_argument(\"--phases\", action=\"store_true\")\n    ap.add_argument(\"--compile-only\", action=\"store_true\")\n    a = ap.parse_args()\n    spec = cut(load_spec(model_dir(a.model)), a.layers)\n    for R in [int(x) for x in a.rows.split(\",\")]:\n        print(json.dumps(one(a, spec, R)), flush=True)\n\n\nif __name__ == \"__main__\":\n    main()\n", "tools/perf_qwen.py": "\"\"\"Profile one decode token on the RTL at the board configuration (the board's memory path:\notpu_native_dram in front of the native memory model, sim/verilator/otpu_native_mem.sv).\n\n    python3 tools/perf_qwen.py [--model qwen3|lfm2|qwen35|gemma4|DIR] [--layers N] [--pos P]\n                               [--bw 100] [--check] [--wformat int8|int4|fp4]\n                               [--head-format int8|int4|fp4] [--ddr 1066 [--mhz 100] [--ldc]]\n\nUses the real weights (models/Qwen3-0.6B, or --model lfm2: models/LFM2.5-230M, --model qwen35:\nmodels/Qwen3.5-0.8B, --model gemma4: models/gemma-4-E2B-it), optionally only the first N layers\n(Gemma 4: or a list of checkpoint layers, e.g. 0,1,2,3,4,15,19, its KV-shared layers attending\nto the last own layer of their kind in the list; the LM head is always complete).\nPrints cycles, the core-port roofline (port-B chunk transfers: weights, KV, LD/ST chunks; port\nA; the MXU's own rate), the useful-bytes roofline, the DRAM efficiency, tokens/s at --mhz, the\ncycles per phase of the token (DeltaNet, attention, MLP, LM head) with their bytes, MM time per\nkernel source line, and the MXU idle gaps with their causes.\n\n--ddr MTS: the DDR3 bank model calibrated on the card (opentpu.profile.ddr3_plusargs; ROW_BANK_\nCOLUMN, 300 ns latency) at DDR3-MTS with the core at --mhz (the controller clock, LiteDRAM's sys,\nis MTS / 8). --ldc: the card's channels instead of the bank model -- the board's bridge and\nLiteDRAM's own controller with the production core's settings (DDR3-1066 only, the board's\nrate; rtlsim.MEMORY's LDC). DRAM efficiency = the token's DRAM bytes (weights, scales, KV,\nI/O, reads and writes) / (its time x the DDR3 peak, 16 bytes x MTS: 17.07 GB/s at 1066).\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport dataclasses\nimport re\nimport sys\nimport time\nfrom collections import defaultdict\nfrom pathlib import Path\n\nimport numpy as np\n\nROOT = Path(__file__).resolve().parent.parent\nsys.path.insert(0, str(ROOT))\n\nfrom opentpu import isa as I  # noqa: E402\nfrom opentpu import rtlsim  # noqa: E402\nfrom opentpu.isasim import Machine, board_config  # noqa: E402\nfrom opentpu.llm import MODELS, load_spec, model_dir  # noqa: E402\nfrom opentpu.llm.qwen3 import load_weights, rope_tables  # noqa: E402\nfrom opentpu.profile import ddr3_peak, ddr3_plusargs, dram_efficiency, parse  # noqa: E402\n\n\n# kernel functions that name a phase of the token (the innermost one on an instruction's source\n# stack wins)\nPHASE_NAMES = {\"head_step\": \"DeltaNet\", \"_deltanet\": \"DeltaNet\", \"_pair_segment\": \"DeltaNet\",\n               \"_deltanet_dstep\": \"DeltaNet\", \"_deltanet_rows\": \"DeltaNet\",\n               \"_attention\": \"attention\", \"_attend_heads\": \"attention\", \"_conv\": \"conv\",\n               \"_mlp\": \"MLP\", \"swiglu_down\": \"MLP\", \"_lm_head\": \"LM head\",\n               \"_attention_rows\": \"attention\", \"qwen3_rows\": \"LM head\",\n               \"_ple\": \"PLE\", \"_ple_inputs\": \"PLE\", \"_gathered\": \"gather\",\n               \"qwen35_mtp\": \"MTP\"}\n\n\ndef _phase(ins):\n    for _, _, fn in ins.src:\n        if fn in PHASE_NAMES:\n            return PHASE_NAMES[fn]\n    return \"other\"\n\n\ndef _src(ins, depth=1):\n    s = ins.src[depth] if len(ins.src) > depth else (ins.src[0] if ins.src else (\"?\", 0, \"?\"))\n    return f\"{Path(s[0]).name}:{s[1]} {s[2]}\"\n\n\ndef _gap_table(p, progs, pbytes, bpc):\n    \"\"\"Per phase: cycles, roofline (useful bytes at bpc bytes per cycle) and the excess, and the\n    phase's cycles split by the MXU's state (MAC / starved: chunk FIFO empty / blocked: chunks\n    but no MAC (scales or the drain) / no MM streaming) and port B's idle cycles. A 64-cycle\n    counter window goes to the phase whose run (as Profile.phases charges them) holds its end.\"\"\"\n    runs, done = [], 0\n    for r in sorted(p.slice_recs(0), key=lambda r: r.idx):\n        if r.end > done:\n            ph = _phase(progs[0][r.pc])\n            if runs and runs[-1][2] == ph:\n                runs[-1][1] = r.end\n            else:\n                runs.append([done, r.end, ph])\n            done = r.end\n    b = p.buckets[0]\n    acc = defaultdict(lambda: defaultdict(int))\n    k = 0\n    for i, c in enumerate(b[\"c\"]):\n        while k + 1 < len(runs) and runs[k][1] < c:\n            k += 1\n        t = acc[runs[k][2] if runs else \"other\"]\n        n = b[\"n\"][i]\n        t[\"n\"] += n\n        t[\"mac\"] += b[\"mx\"][i]\n        t[\"starve\"] += b[\"ms\"][i]\n        t[\"block\"] += b[\"mb\"][i]\n        t[\"bidle\"] += n - b[\"bm\"][i] - b[\"bd\"][i]\n    cyc = p.phases(lambda r: _phase(progs[0][r.pc]))\n    print(\"gap table: cycles, roofline, excess; MXU MAC / starved / blocked / no MM; \"\n          \"port B idle\")\n    rows = []\n    for ph, v in cyc.items():\n        rl = pbytes[ph] / bpc\n        t = acc[ph]\n        idle = t[\"n\"] - t[\"mac\"] - t[\"starve\"] - t[\"block\"]\n        rows.append((v[\"cycles\"] - rl, ph, v[\"cycles\"], rl, t, idle))\n    for ex, ph, cy, rl, t, idle in sorted(rows, key=lambda x: -x[0]):\n        print(f\"  {ph:12s} {cy:9d} {rl:9.0f} {ex:+9.0f}   MAC {t['mac']:8d}  starved \"\n              f\"{t['starve']:7d}  blocked {t['block']:7d}  no MM {idle:7d}   B idle {t['bidle']:8d}\")\n    # the MXU's starved / blocked windows by MM source line (the MM consuming at the window's end)\n    mms = sorted((r for r in p.slice_recs(0) if r.op == I.MM and r.end >= 0),\n                 key=lambda r: max(r.start, r.release))\n    by = defaultdict(lambda: [0, 0, 0])\n    k = 0\n    for i, c in enumerate(b[\"c\"]):\n        while k + 1 < len(mms) and max(mms[k + 1].start, mms[k + 1].release) <= c:\n            k += 1\n        if mms and max(mms[k].start, mms[k].release) <= c <= mms[k].end + b[\"n\"][i]:\n            t = by[_src(progs[0][mms[k].pc], 0)]\n            t[0] += b[\"ms\"][i]\n            t[1] += b[\"mb\"][i]\n            t[2] += b[\"mx\"][i]\n    print(\"  MXU starved / blocked / MAC by MM source (top 8 by starved + blocked)\")\n    for src, (ms, mb, mx) in sorted(by.items(), key=lambda x: -(x[1][0] + x[1][1]))[:8]:\n        print(f\"    {src:50s} starved {ms:7d}  blocked {mb:7d}  MAC {mx:8d}\")\n\n\ndef _union(iv) -> int:\n    tot, cs, ce = 0, None, None\n    for x, y in sorted(iv):\n        if ce is None or x > ce:\n            tot += 0 if ce is None else ce - cs\n            cs, ce = x, y\n        else:\n            ce = max(ce, y)\n    return tot + (0 if ce is None else ce - cs)\n\n\ndef _json_line(a, p, progs, cfg, R, hacked, pbytes, D):\n    \"\"\"One JSON line of the run (--json): cycles, units' busy, the stream engine's busy (its\n    DSTEP / STREAM intervals: the profile counts them on the DMA), per VOP function the\n    instructions and busy cycles, per phase cycles / VPU / MXU / SE, and the MXU gaps' blame\n    by the class of the instruction they waited on.\"\"\"\n    import json\n    recs = p.slice_recs(0)\n    from opentpu import isa as II\n    se = _union([(r.start, r.end) for r in recs if r.op in (II.DSTEP, II.STREAM) and r.start >= 0])\n    sys.path.insert(0, str(ROOT / \"tools\"))\n    import vpu_hack\n    vf = defaultdict(lambda: [0, 0, 0])     # per function: count, busy, issue cycles (model)\n    for r in recs:\n        ins = progs[0][r.pc]\n        if r.op in (II.VOP, II.DSTEP, II.STREAM) and r.start >= 0:\n            f = II.VFUNCS.get((ins.w[5] >> 16) & 0xFF, \"?\") if r.op == II.VOP else r.name\n            vf[f][0] += 1\n            vf[f][1] += r.end - r.start\n            vf[f][2] += vpu_hack.issue_cycles(ins, cfg.LANES)\n    ph = p.phases(lambda r: _phase(progs[0][r.pc]))\n    for k, v in ph.items():\n        v[\"SE\"] = _union([(r.start, r.end) for r in recs if r.op in (II.DSTEP, II.STREAM)\n                          and r.start >= 0 and _phase(progs[0][r.pc]) == k])\n        v[\"bytes\"] = pbytes.get(k, 0)\n    g = p.mxu_gaps(0)\n    blame = defaultdict(int)\n    for (name, _), v in g[\"blame\"].items():\n        blame[name] += v\n    out = {\"model\": Path(str(a.model)).name, \"wformat\": a.wformat, \"head\": a.head_format,\n           \"rows\": a.rows, \"batch\": a.batch, \"pos\": a.pos, \"layers\": a.layers,\n           \"mcols\": cfg.MCOLS, \"hack\": a.hack, \"hacked\": hacked, \"cycles\": p.cycles,\n           \"instructions\": len(progs[0]), \"busy\": p.unit_busy(0), \"se_busy\": se,\n           \"vop\": {k: v for k, v in sorted(vf.items())}, \"phases\": ph,\n           \"mxu_gaps\": {\"prologue\": g[\"prologue\"], \"epilogue\": g[\"epilogue\"],\n                        \"gaps\": sum(y - x for x, y, _ in g[\"gaps\"]), \"blame\": dict(blame)},\n           \"roofline\": p.roofline()[\"bound\"]}\n    with open(a.json, \"a\") as f:\n        f.write(json.dumps(out) + \"\\n\")\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"--model\", default=\"qwen3\",\n                    help=f\"{' or '.join(MODELS)} (models/<name>), or a checkpoint directory\")\n    ap.add_argument(\"--layers\", default=\"2\", help=\"0: all; Gemma 4: or a comma list of \"\n                    \"checkpoint layers\")\n    ap.add_argument(\"--pos\", type=int, default=9)\n    ap.add_argument(\"--cap\", type=int, default=None,\n                    help=\"KV cache capacity (tokens); default: the multiple of 256 above pos\")\n    ap.add_argument(\"--bw\", type=int, default=100)\n    ap.add_argument(\"--lat\", type=int, default=None, help=\"read latency, core cycles \"\n                    \"(default 30; with --ddr 300 ns)\")\n    ap.add_argument(\"--stall\", type=int, default=0)\n    ap.add_argument(\"--dram\", choices=[\"off\", \"brc\", \"rbc\"], default=\"off\",\n                    help=\"DDR3 bank / row timing (otpu_native_mem.sv) with the address map \"\n                         \"BANK_ROW_COLUMN or ROW_BANK_COLUMN (LiteDRAM's; replaces --bw)\")\n    ap.add_argument(\"--ddr\", type=float, default=None,\n                    help=\"DDR3 MT/s of the calibrated bank model (800, 1066, 1300; sets \"\n                         \"--dram rbc and the timings)\")\n    ap.add_argument(\"--mhz\", type=float, default=100.0, help=\"core clock (tokens/s; --ddr)\")\n    ap.add_argument(\"--ldc\", action=\"store_true\",\n                    help=\"--ddr: LiteDRAM's controller co-simulated instead of the bank model\")\n    ap.add_argument(\"--plus\", action=\"append\", default=[],\n                    help=\"extra simulator argument, e.g. --plus +axi_trfc=26 (repeatable)\")\n    ap.add_argument(\"--rows\", type=int, default=0,\n                    help=\"R token rows at positions pos .. pos+R-1 of one sequence in one program \"\n                         \"(qwen3_rows: a prefill chunk or a speculative verify pass); 0: the \"\n                         \"decode step\")\n    ap.add_argument(\"--logits\", choices=[\"last\", \"all\", \"none\"], default=\"last\",\n                    help=\"--rows: which rows get logits (prefill: last or none; verify: all)\")\n    ap.add_argument(\"--mcols\", type=int, default=None, help=\"MXU columns (default OTPU_MCOLS or 4)\")\n    ap.add_argument(\"--block\", type=int, default=None, help=\"attention block (tokens)\")\n    ap.add_argument(\"--depth\", type=int, default=None, help=\"attention score blocks in flight\")\n    ap.add_argument(\"--check\", action=\"store_true\", help=\"compare with the ISA simulator\")\n    ap.add_argument(\"--dump\", help=\"write the run's Lens profile data (lens.to_data) as JSON\")\n    ap.add_argument(\"--resident\", action=\"store_true\",\n                    help=\"the resident decode program of pos's bucket (run arguments, inputs \"\n                         \"from the image's tables; qwen3.compile_decode); with --rows the \"\n                         \"resident engine's prefill run, its inputs from the tables too \"\n                         \"(compile_rows tokens)\")\n    ap.add_argument(\"--generate\", type=int, default=0, metavar=\"N\",\n                    help=\"with --resident: the decode loop on the device (generate.py), N \"\n                         \"tokens from pos in one run (greedy, or --sample); cycles per token\")\n    ap.add_argument(\"--sample\", default=None, metavar=\"T,K,P,PEN\",\n                    help=\"--generate sampled: temperature, top-k, top-p, repetition penalty\")\n    ap.add_argument(\"--mtp\", choices=[\"verify\", \"draft\"], default=None,\n                    help=\"Qwen3.5 MTP decoding (opentpu/llm/mtp.py, docs/mtp.md 9): the k = 1 \"\n                         \"verify run (2 rows, logits of both, the hidden rows stored, the \"\n                         \"DeltaNet steps of row 1 into the other state slot) or the MTP \"\n                         \"drafter's run over 2 rows\")\n    ap.add_argument(\"--timeline\", help=\"print the instructions of dynamic index range A:B\")\n    ap.add_argument(\"--idle\", action=\"store_true\", help=\"list DRAM-idle stretches (64-cycle windows)\")\n    ap.add_argument(\"--wformat\", default=\"int8\", choices=[\"int8\", \"int4\", \"fp4\", \"mix\"],\n                    help=\"weight format of the layers (opentpu/quant.py)\")\n    ap.add_argument(\"--head-format\", default=None, choices=[\"int8\", \"int4\", \"fp4\"],\n                    help=\"weight format of the LM head (default: --wformat)\")\n    ap.add_argument(\"--batch\", type=int, default=0, metavar=\"B\",\n                    help=\"a batched decode step: B sequences (KV slots) at --pos each, one row a \"\n                         \"slot, every row's logits (Qwen3 family: opentpu/llm/batch.py's step, \"\n                         \"the pick on the device; other models: compile_rows over the slots)\")\n    ap.add_argument(\"--hack\", default=\"\",\n                    help=\"timing-only program transforms, comma list (tools/vpu_hack.py: novop, \"\n                         \"nocomp, comp1, half, halfcomp, halfew, nose, halfse); results wrong\")\n    ap.add_argument(\"--json\", help=\"append the run's numbers as one JSON line to this file\")\n    ap.add_argument(\"--gaps\", action=\"store_true\",\n                    help=\"per phase: the cycles above its roofline, split by what the MXU and \"\n                         \"port B did (64-cycle windows)\")\n    a = ap.parse_args()\n    plus = list(a.plus)\n    ldc = 0\n    if a.ldc:\n        if not a.ddr or int(a.ddr) not in rtlsim.LDC_MODELS:\n            ap.error(f\"--ldc needs --ddr {' / '.join(map(str, rtlsim.LDC_MODELS))}\")\n        ldc = int(a.ddr)\n        plus = plus + rtlsim.ldc_plusargs(ldc, a.mhz)\n    if a.ddr:\n        a.ddr = {1066: 3200 / 3, 1333: 4000 / 3}.get(int(a.ddr), a.ddr)\n        plus = plus + ddr3_plusargs(a.ddr, a.mhz)[2:]   # the first of a plusarg wins\n        a.dram = \"rbc\" if a.dram == \"off\" else a.dram\n        a.lat = a.lat if a.lat is not None else round(0.3 * a.mhz)\n    a.lat = 30 if a.lat is None else a.lat\n    path = model_dir(a.model)\n    spec = load_spec(path)\n    layers = [int(x) for x in a.layers.split(\",\")]\n    if hasattr(spec, \"truncated\") and layers != [0]:\n        spec = spec.truncated(layers if len(layers) > 1 else range(layers[0]))\n    elif len(layers) > 1:\n        ap.error(\"--layers: a list of layers needs a Gemma 4 checkpoint\")\n    elif layers[0]:\n        spec = dataclasses.replace(spec, **({\"kinds\": spec.kinds[:layers[0]]}\n                                            if hasattr(spec, \"kinds\") else {\"layers\": layers[0]}))\n    if a.mtp:\n        spec = dataclasses.replace(spec, mtp=True)\n        a.rows, a.logits = 2, \"all\"\n    R = max(1, a.rows, a.batch)\n    if a.batch and (a.rows or a.mtp or a.resident):\n        ap.error(\"--batch is a decode step of its own (no --rows, --mtp, --resident)\")\n    if a.cap is None:\n        a.cap = 256 * ((a.pos + R - 1) // 256 + 1)\n    if a.pos + (1 if a.batch else R) - 1 >= a.cap:\n        ap.error(f\"--pos {a.pos} needs --cap above it (the KV write would land past the cache)\")\n    W = load_weights(path, mtp=bool(a.mtp))\n    wkw = dict(wformat=a.wformat, head_format=a.head_format, rows=R,\n               **({\"lookup\": True} if a.resident else {}))\n    qwen3_batch = bool(a.batch) and type(spec).__module__.endswith(\".qwen3\")\n    if a.batch:\n        wkw.update(batch=a.batch, **({\"lookup\": True} if qwen3_batch else {}))\n    mk = {\"MCOLS\": a.mcols} if a.mcols else {}\n    need = spec.image(board_config(DRAM_BYTES=1 << 40, **mk), a.cap, **wkw).nbytes\n    need += (64 << 20) if qwen3_batch else 0           # the batch area (batch.alloc)\n    cfg = board_config(DRAM_BYTES=1 << max(20, (need - 1).bit_length()), **mk)\n    img = spec.image(cfg, a.cap, **wkw)\n    dram = img.build(W)[0]\n    # the rows' (slot, position): a batched step's slots at pos, or one sequence's positions\n    rows = [(s, a.pos) for s in range(a.batch)] if a.batch else [(0, a.pos + r) for r in range(R)]\n    # the rows' inputs (the KV cache before pos stays zero: timing does not depend on it)\n    if hasattr(img, \"host_inputs\"):         # Gemma 4: the gathered rows, the RoPE rows\n        parts = img.host_inputs([791 + r for r in range(R)], [p for _, p in rows])\n    else:\n        emb = np.stack([np.asarray(W[\"model.embed_tokens.weight\"][791 + r], np.float32)\n                        for r in range(R)])\n        tabs = [rope_tables(spec, p) for _, p in rows]\n        c, s = np.stack([t[0] for t in tabs]), np.stack([t[1] for t in tabs])\n        parts = [(img.io[k], v) for k, v in ((\"x\", emb), (\"cos\", c), (\"sin\", s))]\n    for addr, v in parts:\n        b = np.ascontiguousarray(v, np.float32).view(np.uint8).ravel()\n        dram[addr:addr + b.size] = b\n    # rows of tables the host keeps (Gemma 4 E4B's PLE records), as the Engine writes them\n    for addr, v in getattr(img, \"host_rows\", lambda t: [])([791 + r for r in range(R)]):\n        b = np.ascontiguousarray(v).view(np.uint8).ravel()\n        dram[addr:addr + b.size] = b\n    if a.depth:\n        import opentpu.llm.qwen3 as Q\n        Q.ATTN_DEPTH = a.depth\n    args = None\n    if qwen3_batch:\n        from opentpu.llm import batch as BA\n        from opentpu.llm.qwen3 import ATTN_BLOCK\n        area = BA.alloc(img, cfg, a.batch, -(-img.nbytes // 4096) * 4096)\n        if area[\"end\"] > cfg.DRAM_BYTES:\n            ap.error(\"--batch: no room for the batch area\")\n        dram = np.concatenate([dram, np.zeros(max(0, area[\"end\"] - len(dram)), np.uint8)])\n        BA.build([dram], area, spec, cfg)\n        tin = np.asarray([791 + s for s in range(a.batch)], np.float32).view(np.uint8)\n        dram[area[\"tin\"]:area[\"tin\"] + tin.size] = tin\n        progs = BA.compile_step(img, area, rows, [None] * a.batch, a.block or ATTN_BLOCK)\n    elif a.batch:\n        progs = img.compile_rows(rows, list(range(R)), *([a.block] if a.block else []))\n    elif a.mtp == \"draft\":\n        progs = img.compile_mtp(a.pos, R, None, *([a.block] if a.block else []))\n    elif a.mtp == \"verify\":\n        progs = img.compile_rows([(0, a.pos + r) for r in range(R)], list(range(R)),\n                                 *([a.block] if a.block else []), fork=True, hidden=True)\n    elif a.rows:\n        lr = {\"last\": [R - 1], \"all\": list(range(R)), \"none\": []}[a.logits]\n        progs = img.compile_rows([(0, a.pos + r) for r in range(R)], lr,\n                                 *([a.block] if a.block else []),\n                                 **({\"tokens\": [791 + r for r in range(R)]} if a.resident\n                                    else {}))\n    elif a.resident and a.generate:\n        from opentpu.llm import generate as G\n        from opentpu.llm.qwen3 import ATTN_BLOCK\n        blk, K = a.block or ATTN_BLOCK, getattr(spec, \"conv_k\", 1)\n        b = a.pos // blk + 1\n        if a.pos + a.generate > b * blk:\n            ap.error(f\"--generate {a.generate} from --pos {a.pos} leaves the bucket\")\n        samp = None\n        if a.sample:\n            tt, kk, pp, pen = a.sample.split(\",\")\n            samp = G.Sampling(float(tt), int(kk), float(pp), float(pen))\n        progs = img.compile_generate(b, max((b - 1) * blk, K - 1), blk, chain=False, samp=samp)\n        g = img.lookup[\"gen\"]\n        put = [(g[\"state\"], G.state_words(spec, 791, a.pos, a.generate, [], blk, samp)),\n               (g[\"out\"] + 4 * (a.pos + 1), np.full(a.generate, G.OUT_MARK, np.uint32))]\n        if samp is not None:\n            u = np.random.default_rng(0).random(a.generate).astype(np.float32)\n            put.append((g[\"uni\"] + 4 * (a.pos + 1), np.minimum(u, np.float32(1 - 2.0 ** -24))))\n            if samp.pen:\n                pa, pb = np.ones(G._vpad(spec), np.float32), np.ones(G._vpad(spec), np.float32)\n                pa[[791, 1000, 2000]] = np.float32(1.0) / np.float32(samp.penalty)\n                pb[[791, 1000, 2000]] = samp.penalty            # a context of three ids\n                put += [(g[\"pa\"], pa), (g[\"pb\"], pb)]\n        for at, v in put:\n            v = np.ascontiguousarray(v).view(np.uint8).ravel()\n            dram[at:at + v.size] = v\n    elif a.resident:\n        from opentpu.compiler import arg_words\n        from opentpu.llm.qwen3 import ATTN_BLOCK, RunPos\n        blk, K = a.block or ATTN_BLOCK, getattr(spec, \"conv_k\", 1)\n        b = a.pos // blk + 1\n        progs, ra = img.compile_decode(b, max((b - 1) * blk, K - 1), blk)\n        args = arg_words(ra, RunPos.values(791, a.pos, K, blk))\n    else:\n        progs = img.compile_step(a.pos, *([a.block] if a.block else []))\n    hacked = {}\n    if a.hack:\n        sys.path.insert(0, str(ROOT / \"tools\"))\n        import vpu_hack\n        res = [vpu_hack.apply(p, a.hack) for p in progs]\n        progs, hacked = [p for p, _ in res], res[0][1]\n        print(f\"hack {a.hack}: {hacked}\")\n    if 8 * len(progs[0]) > cfg.IMEM_WORDS:      # a proxy of a longer program: time it\n        cfg = dataclasses.replace(cfg, IMEM_WORDS=1 << (8 * len(progs[0]) - 1).bit_length())\n        print(f\"(IMEM grown to {cfg.IMEM_WORDS} words for {len(progs[0])} instructions)\")\n    t = time.time()\n    drams, _, st = rtlsim.run(cfg, progs, [dram], trace=True,\n                              uarch=rtlsim.BOARD_UARCH,\n                              axi=True, boot=True, stall=a.stall, bw=a.bw, lat=a.lat,\n                              max_cycles=1 << 40, args=args, ldc=ldc,\n                              plusargs=([] if a.dram == \"off\" else\n                                        [\"+axi_dram=1\", f\"+axi_map={int(a.dram == 'rbc')}\"])\n                              + plus)\n    wall = time.time() - t\n    if a.resident and a.generate:\n        w = drams[0][g[\"out\"] + 4 * (a.pos + 1):g[\"out\"] + 4 * (a.pos + 1 + a.generate)]\n        got = [int(x) for x in w.view(np.float32)]\n        print(f\"generate {a.generate} tokens ({'sampled ' + a.sample if samp else 'greedy'}): \"\n              f\"{st['cycles']} cycles, {st['cycles'] / a.generate:.0f} per token, \"\n              f\"{len(progs[0])} instructions; tokens {got}\")\n    p = parse(st[\"trace\"], cfg, progs, path.name)\n    p.cycles = st[\"cycles\"]\n    rl = p.roofline()\n    # port B (chunks) runs at bw; port A (one scale word per block, from buffered beats) and the\n    # MXU (one block per cycle) do not: 4-bit weights stream two blocks per chunk\n    ps = rl[\"per_slice\"][0]\n    ideal = max(ps[\"portb\"] * 100 / a.bw, ps[\"porta_cycles\"], ps[\"mxu\"])\n    if a.rows:\n        print(f\"rows={R} (positions {a.pos}..{a.pos + R - 1}, logits {a.logits}) \"\n              f\"MCOLS={cfg.MCOLS}: {p.cycles / R:.0f} cycles per row\")\n    print(f\"layers={spec.layers} pos={a.pos} bw={a.bw}% lat={a.lat}: {p.cycles} cycles \"\n          f\"({wall:.0f}s sim), core-port roofline {ideal:.0f} cycles (port B {ps['portb']} \"\n          f\"chunks, port A {ps['porta_cycles']}, MXU {ps['mxu']}), \"\n          f\"efficiency {100 * ideal / p.cycles:.1f}%\")\n    ar = st.get(\"axi_reads\", [])\n    if ar:\n        print(\"DRAM read / write beats per channel: \" +\n              \", \".join(f\"{r} / {w}\" for (r, _), (w, _) in zip(ar, st[\"axi_writes\"])) +\n              f\"; dram={a.dram}\")\n    b = p.buckets[0]\n    if b.get(\"ms\") is not None:\n        mxb = sum(b.get(\"mx\", []))\n        print(f\"MXU starved (chunk FIFO empty while streaming, the card's MXU_STARVE) \"\n              f\"{sum(b['ms'])} cycles = {100 * sum(b['ms']) / p.cycles:.1f}%; blocked (chunks \"\n              f\"but no MAC) {100 * sum(b.get('mb', [])) / p.cycles:.1f}%; MAC \"\n              f\"{100 * mxb / p.cycles:.1f}%; DRAM read beats/cycle/channel \"\n              f\"{sum(n for _, n in ar) / 2 / p.cycles:.3f}\")\n    for c, d in enumerate(st.get(\"axi_detail\", [])):\n        print(f\"  ch{c}: port A reads {d['ar_a']}, DDR3 row opens {d['row_miss']}, \"\n              f\"read-modify-writes {d['rmw']} (port A / QST {d['rmw_a']})\")\n    # the MXU's scale reads (otpu_mxu): 32-byte line requests, and those for a row's Sw alone\n    # (its Sw in neither its first advance's line nor the previous row's last); per MM from the\n    # MXS lines (in issue order = the MMs' dispatch order)\n    xs = st.get(\"mxu_scale\") or []\n    if xs:\n        nmm = sum(1 for r in p.recs if r.op == I.MM and r.slice == 0)\n        print(f\"MXU scale lines: {xs[0]['areq']} requests ({xs[0]['areq'] / max(1, nmm):.1f} per \"\n              f\"MM), {xs[0]['sw']} for a row's Sw alone \"\n              f\"({100 * xs[0]['sw'] / max(1, xs[0]['areq']):.1f}%)\")\n    mxs = [tuple(map(int, m)) for m in re.findall(r\"^MXS0 a=(\\d+) sw=(\\d+)\", st[\"trace\"], re.M)]\n    mms = sorted((r for r in p.recs if r.op == I.MM and r.slice == 0), key=lambda r: r.idx)\n    per_mm = dict(zip((r.idx for r in mms), mxs)) if len(mxs) == len(mms) else {}\n    # useful-bytes roofline: weights + their fp32 block scales + KV + activations, at D bytes\n    # per cycle (both channels at 100%)\n    D = cfg.D\n\n    def nbytes(r):\n        if r.op == I.MM:\n            return r.portb * D + r.porta * 4\n        if r.op in (I.LD, I.ST):\n            return 4 * progs[0][r.pc].w[2]\n        if r.op in (I.DSTEP, I.STREAM):\n            return r.portb * D\n        return r.porta if r.op == I.QST else 0\n\n    useful = sum(nbytes(r) for r in p.recs)\n    ub = useful / D * 100 / a.bw\n    print(f\"useful bytes {useful} -> {ub:.0f} cycles at {D} B/cycle x {a.bw}% (the core's \"\n          f\"port): efficiency {100 * ub / p.cycles:.1f}%\")\n    if a.ddr:\n        print(f\"DRAM efficiency {100 * dram_efficiency(useful, p.cycles, a.ddr, a.mhz):.1f}% \"\n              f\"(DDR3-{a.ddr:.0f} peak {ddr3_peak(a.ddr) / 1e9:.2f} GB/s = \"\n              f\"{ddr3_peak(a.ddr) / a.mhz / 1e6:.1f} B per core cycle at {a.mhz:g} MHz; \"\n              f\"{useful / p.cycles * a.mhz / 1e3:.2f} GB/s moved)\")\n    print(f\"at {a.mhz:g} MHz: {p.cycles / a.mhz / 1e3:.2f} ms/token, \"\n          f\"{a.mhz * 1e6 / p.cycles:.1f} tok/s (simulated cycles, no host time)\")\n    print(p.summary())\n    print(f\"phases: cycles, share, useful bytes -> cycles at {a.bw}% (their roofline), \"\n          f\"VPU busy, MXU busy\")\n    pb = defaultdict(int)\n    for r in p.recs:\n        pb[_phase(progs[0][r.pc])] += nbytes(r)\n    for k, v in sorted(p.phases(lambda r: _phase(progs[0][r.pc])).items(),\n                       key=lambda x: -x[1][\"cycles\"]):\n        rl_ph = pb[k] / D * 100 / a.bw\n        print(f\"  {k:12s} {v['cycles']:9d} {100 * v['cycles'] / p.cycles:5.1f}%  \"\n              f\"{pb[k]:10d} B -> {rl_ph:9.0f} ({100 * rl_ph / max(1, v['cycles']):5.1f}%)  \"\n              f\"VPU {v['VPU']:9d}  MXU {v['MXU']:9d}\")\n    if a.gaps:\n        _gap_table(p, progs, pb, D * a.bw / 100)\n    ph = defaultdict(lambda: [0, 0, 0, 0, 0])\n    for r in p.recs:\n        if r.op != I.MM or r.end < 0:\n            continue\n        k = _src(progs[0][r.pc])\n        ph[k][0] += 1\n        ph[k][1] += r.portb\n        ph[k][2] += r.end - max(r.start, r.release)\n        if r.slice == 0 and r.idx in per_mm:\n            ph[k][3] += per_mm[r.idx][0]\n            ph[k][4] += per_mm[r.idx][1]\n    print(\"MM by source: count, chunks, release->end cycles\"\n          + (\", scale lines, of them Sw alone\" if per_mm else \"\"))\n    for k, v in sorted(ph.items(), key=lambda x: -x[1][1])[:20]:\n        print(f\"  {k:50s} {v[0]:6d} {v[1]:9d} {v[2]:9d}\"\n              + (f\" {v[3]:9d} {v[4]:9d}\" if per_mm else \"\"))\n    g = p.mxu_gaps(0)\n    print(f\"MXU prologue {g['prologue']} epilogue {g['epilogue']} \"\n          f\"gaps {sum(b - a for a, b, _ in g['gaps'])}\")\n    for key, v in sorted(g[\"blame\"].items(), key=lambda x: -x[1])[:15]:\n        src = _src(progs[0][key[1]], 0) if key[1] >= 0 else \"?\"\n        print(f\"  gap {v:8d}  after {key[0]:6s} pc={key[1]:5d} {src}\")\n    for k, v in sorted(p.by_class(0).items(), key=lambda x: -x[1][\"busy\"]):\n        print(f\"  {k:7s} n={v['count']:6d} busy={v['busy']:9d} work={v['work']:9d} \"\n              f\"wait_dep={v['wait_dep']:9d} wait_unit={v['wait_unit']:9d}\")\n    if a.timeline:\n        lo, hi = (int(x) for x in a.timeline.split(\":\"))\n        for r in p.slice_recs(0)[lo:hi]:\n            print(f\"  #{r.idx:5d} pc={r.pc:4d} {r.name:9s} {r.detail:28s} disp={r.dispatch:8d} \"\n                  f\"rdy={r.ready:8d} st={r.start:8d} rel={r.release:8d} end={r.end:8d}  \"\n                  f\"{_src(progs[0][r.pc], 0)}\")\n    if a.idle:\n        b = p.buckets[0]\n        util = [(c, n, bm + bd) for c, n, bm, bd in zip(b[\"c\"], b[\"n\"], b[\"bm\"], b[\"bd\"])]\n        tot, run = 0, None\n        for c, n, u in util:\n            lost = n - u\n            tot += max(0, lost)\n            if lost > n // 8:\n                if run and c - n <= run[1] + 1:\n                    run = (run[0], c, run[2] + lost)\n                else:\n                    if run and run[2] > 300:\n                        print(f\"  idle {run[2]:6d} in [{run[0]}, {run[1]}]\")\n                    run = (c - n, c, lost)\n        if run and run[2] > 300:\n            print(f\"  idle {run[2]:6d} in [{run[0]}, {run[1]}]\")\n        print(f\"  port-B idle cycles total {tot}\")\n    if a.json:\n        _json_line(a, p, progs, cfg, R, hacked, pb, D)\n    if a.dump:\n        import json\n        from opentpu import lens as L\n        Path(a.dump).write_text(json.dumps(L.to_data(p)))\n    if a.check:\n        m = Machine(cfg, [progs[0]], [dram.copy()], args)\n        m.run()\n        ok = np.array_equal(m.slices[0].dram[:img.nbytes], drams[0][:img.nbytes])\n        print(\"bit-exact vs ISA:\", ok)\n\n\nif __name__ == \"__main__\":\n    main()\n", "tools/perf_tiled.py": "\"\"\"Prefill cycles per token against the rows a weight pass serves (docs/tiled_prefill.md): RTL\nco-simulation of one prefill run of T rows, the first L layers of a model, no logits.\n\n    python3 tools/perf_tiled.py [--model qwen3|qwen35|DIR | --shape qwen3-4b] [--layers 2]\n        [--pos 256] [--rows 4,8,16] [--mcols 4] [--act-rows 32] [--tmem 65536]\n        [--imem 131072] [--wformat fp4] [--mem ldc|port] [--lat 40] [--kernel rows|tile]\n        [--phases] [--compile-only]\n\n--kernel rows: today's prefill run (qwen3_rows / qwen35_rows, compile_rows) with every MM over\nthe run's T rows at once: the ACT RAM holds max(--act-rows, MCOLS, T) rows, so each weight\nchunk is streamed once and replayed for ceil(T / MCOLS) groups (docs/isa.md, MM). TMEM and IMEM\nmay be virtual (--tmem, --imem words; the card's TMEM is 64K words): today's kernel holds every\nrow's activations at once, so more than 8 rows of Qwen3-0.6B need more. A TMEM over 64K words\nneeds otpu_seq's TMEM hazard ranges to follow TMEM_WORDS (without it every instruction past\nword 65,535 waits for everything: docs/tiled_prefill.md 3.5).\n--kernel tile: the tiled prefill run (opentpu/llm/tiled.py): the same, with the projections\nsplit by KV head and the MLP's down projection by output columns (TMEM independent of H), and\nthe attention's rows packed MCOLS / G to an MM (K / V streamed once per group of rows).\n\n--mem ldc: the card's memory path (LiteDRAM's controllers co-simulated, DDR3-1066, the core at\n133.33 MHz); --mem port: the board's adapter in front of a memory at the core port's full rate\n(one 128-byte chunk a cycle on two channels, --lat cycles of latency): the BCU1525's DDR4 or the\nF2's HBM, whose bandwidth exceeds what one slice's port takes.\n\nThe images are zeros (timing does not depend on the data). One JSON line per run: cycles,\ncycles per row, the core-port roofline (port-B chunks, the MXU's own cycles), and with\n--phases the cycles per phase (projections, attention, MLP, DeltaNet, other) with their port-B\nchunks and MXU / VPU busy cycles.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport dataclasses\nimport json\nimport sys\nimport time\nfrom pathlib import Path\n\nimport numpy as np\n\nROOT = Path(__file__).resolve().parent.parent\nsys.path.insert(0, str(ROOT))\n\nfrom opentpu import isa as I  # noqa: E402\nfrom opentpu import rtlsim  # noqa: E402\nfrom opentpu.isasim import board_config  # noqa: E402\nfrom opentpu.llm import load_spec, model_dir  # noqa: E402\nfrom opentpu.profile import ddr3_plusargs, parse  # noqa: E402\n\nMHZ = 133.33\nSHAPES = {   # dense shapes whose checkpoints are not needed (timing does not depend on data)\n    \"qwen3-4b\": dict(hidden=2560, layers=36, n_q=32, n_kv=8, head_dim=128, ffn=9728,\n                     vocab=151936),\n}\nATTN_CORE = {\"scores\", \"finish\", \"prime\", \"_attend_heads\", \"_attend_tile\", \"_tile_scores\",\n             \"_tile_finish\"}\nPHASES = {\"_deltanet_rows\": \"deltanet\", \"_deltanet_dstep\": \"deltanet\",\n          \"_mlp\": \"mlp\", \"swiglu_down\": \"mlp\", \"_mlp_tile\": \"mlp\", \"_down_split\": \"mlp\",\n          \"_attention_rows\": \"attn-proj\", \"_attention_tile\": \"attn-proj\"}\n\n\ndef phase(ins) -> str:\n    fns = [fn for _, _, fn in ins.src]\n    if any(f in ATTN_CORE for f in fns):\n        return \"attn-core\"\n    for f in fns:\n        if f in PHASES:\n            return PHASES[f]\n    return \"other\"\n\n\ndef spec_of(a):\n    if a.shape:\n        from opentpu.llm.qwen3 import Spec\n        return Spec(**SHAPES[a.shape])\n    return load_spec(model_dir(a.model))\n\n\ndef cut(spec, n):\n    if hasattr(spec, \"kinds\"):\n        return dataclasses.replace(spec, kinds=spec.kinds[:n])\n    return dataclasses.replace(spec, layers=n)\n\n\ndef compile_run(img, kernel, pos, T, block=256):\n    rows = [(0, pos + r) for r in range(T)]\n    if kernel == \"rows\":\n        return img.compile_rows(rows, [], block)\n    from opentpu.llm import tiled\n    return tiled.compile_tile(img, pos, T, block)\n\n\ndef one(a, spec, T):\n    act = max(a.act_rows or 0, a.mcols, T)\n    kw = dict(MCOLS=a.mcols, ACT_ROWS=act, TMEM_WORDS=a.tmem, IMEM_WORDS=a.imem, PAIR=True,\n              DSTEP=True, STREAM=True)\n    cap = 256 * ((a.pos + T - 1) // 256 + 1)\n    rec = dict(model=a.shape or Path(str(model_dir(a.model))).name, layers=a.layers,\n               pos=a.pos, T=T, mcols=a.mcols, act_rows=act, tmem=a.tmem, wformat=a.wformat,\n               mem=a.mem, kernel=a.kernel)\n    probe = spec.image(board_config(DRAM_BYTES=1 << 40, **kw), cap, rows=T,\n                       wformat=a.wformat, head_format=\"int8\")\n    cfg = board_config(DRAM_BYTES=1 << max(20, (probe.nbytes - 1).bit_length()), **kw)\n    img = spec.image(cfg, cap, rows=T, wformat=a.wformat, head_format=\"int8\")\n    t = time.time()\n    try:\n        progs = compile_run(img, a.kernel, a.pos, T)\n    except Exception as e:                  # TMEM / IMEM / ACT RAM: the fit answer\n        rec[\"error\"] = f\"{type(e).__name__}: {e}\"[:300]\n        return rec\n    rec[\"instructions\"] = max(len(p) for p in progs)\n    mm = [i for i in progs[0] if i.op == I.MM]\n    rec[\"mms\"] = len(mm)\n    rec[\"compile_s\"] = round(time.time() - t, 1)\n    if a.compile_only:\n        return rec\n    dram = np.zeros(img.nbytes, np.uint8)\n    if a.mem == \"ldc\":\n        plus = rtlsim.ldc_plusargs(1066, MHZ) + ddr3_plusargs(3200 / 3, MHZ)[2:]\n        mem = dict(ldc=1066, bw=100, lat=round(0.3 * MHZ),\n                   plusargs=[\"+axi_dram=1\", \"+axi_map=1\"] + plus)\n    else:\n        mem = dict(ldc=0, bw=100, lat=a.lat, plusargs=[])\n    t = time.time()\n    _, _, st = rtlsim.run(cfg, progs, [dram], trace=True, uarch=rtlsim.BOARD_UARCH, axi=True,\n                          boot=True, stall=0, max_cycles=1 << 40, **mem)\n    rec[\"sim_s\"] = round(time.time() - t)\n    p = parse(st[\"trace\"], cfg, progs, \"tiled\")\n    p.cycles = st[\"cycles\"]\n    ps = p.roofline()[\"per_slice\"][0]\n    rec.update(cycles=p.cycles, per_row=round(p.cycles / T), portb=ps[\"portb\"],\n               porta=ps[\"porta_cycles\"], mxu=ps[\"mxu\"],\n               busy={k: v for k, v in p.unit_busy(0).items() if v})\n    if a.phases:\n        ph = p.phases(lambda r: phase(progs[0][r.pc]))\n        rec[\"phases\"] = {k: dict(cycles=v[\"cycles\"], portb=v[\"portb\"], VPU=v[\"VPU\"],\n                                 MXU=v[\"MXU\"]) for k, v in ph.items()}\n    return rec\n\n\ndef main():\n    ap = argparse.ArgumentParser(description=__doc__.split(\"\\n\")[0])\n    ap.add_argument(\"--model\", default=\"qwen3\")\n    ap.add_argument(\"--shape\", choices=sorted(SHAPES), default=None)\n    ap.add_argument(\"--layers\", type=int, default=2)\n    ap.add_argument(\"--pos\", type=int, default=256)\n    ap.add_argument(\"--rows\", default=\"4,8,16\")\n    ap.add_argument(\"--mcols\", type=int, default=4)\n    ap.add_argument(\"--act-rows\", type=int, default=0,\n                    help=\"ACT RAM rows (at least max(MCOLS, T), the default)\")\n    ap.add_argument(\"--tmem\", type=int, default=1 << 16, help=\"TMEM words (the card's: 64K)\")\n    ap.add_argument(\"--imem\", type=int, default=1 << 17)\n    ap.add_argument(\"--wformat\", default=\"fp4\", choices=[\"int8\", \"int4\", \"fp4\"])\n    ap.add_argument(\"--mem\", choices=[\"ldc\", \"port\"], default=\"ldc\")\n    ap.add_argument(\"--lat\", type=int, default=40, help=\"--mem port: latency, core cycles\")\n    ap.add_argument(\"--kernel\", choices=[\"rows\", \"tile\"], default=\"rows\")\n    ap.add_argument(\"--phases\", action=\"store_true\")\n    ap.add_argument(\"--compile-only\", action=\"store_true\")\n    a = ap.parse_args()\n    spec = cut(spec_of(a), a.layers)\n    for T in [int(x) for x in a.rows.split(\",\")]:\n        print(json.dumps(one(a, spec, T)), flush=True)\n\n\nif __name__ == \"__main__\":\n    main()\n", "tools/prefill_routes.py": "\"\"\"The route and rows of a dense model's prompt on the card, bucket by bucket (docs/prefill.md,\ndocs/tiled_prefill.md): what Engine.prefill takes with resident prompt runs (otpu-chat's), from\nprefill.py's own rules on a zero image of the whole model.\n\n    python3 tools/prefill_routes.py --model DIR [--wformat auto] [--head-format F] [--cap 2048]\n        [--buckets 1-8] [--imem 4096,8192,16384,0]\n\nFor each bucket (positions (b - 1) x 256 ..): the tile's rows (prefill._tile_fit), today's prompt\nruns' rows and whether they cover the bucket (prefill._fit), the kind the bucket's runs take\n(prefill.tiled: \"tile\" or \"prompt\") and r_max, whether a prompt reaching the bucket takes prompt\nruns at all (prefill.covers: every bucket it touches covered; else the whole prompt takes\ncompile_rows' route, Engine.prefill_chunks), and the rows of that route's run at the bucket's\nstart (qwen3.fit_chunk: up to the image's rows, whole passes of MCOLS, what fits TMEM and IMEM).\nWith --imem, the tile's rows at each IMEM size in instructions (0: unbounded): what a bigger IMEM\nor the looped attention would let the tile take (TMEM and ACT RAM still bound it).\n\nThe configuration is the card's bitstream (the target's: OTPU_TARGET, default ypcb-00338 m4;\nPAIR, DSTEP, STREAM, SEQ_WC), the engine's rows grown to ACT_ROWS (Engine with tiled prompt\nruns), lookup tables (resident). --wformat auto is otpu-chat's default (the model's mix, else\nint8). OTPU_TILE must be unset (the default: tiled prompt runs on). One JSON line a bucket.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport dataclasses\nimport json\nimport os\nimport sys\nimport threading\nimport time\nfrom pathlib import Path\nfrom types import SimpleNamespace\n\nROOT = Path(__file__).resolve().parent.parent\nsys.path.insert(0, str(ROOT))\n\nfrom opentpu.isasim import board_config  # noqa: E402\nfrom opentpu.llm import formats as FM  # noqa: E402\nfrom opentpu.llm import load_spec, model_dir  # noqa: E402\nfrom opentpu.llm import prefill as PF  # noqa: E402\nfrom opentpu.llm.qwen3 import ATTN_BLOCK, PREFILL_ROWS, Engine, fit_chunk  # noqa: E402\n\n\ndef stub_engine(spec, cfg, cap: int, wformat: str, head_format):\n    \"\"\"An Engine as otpu-chat makes it (resident, prompt runs, the program cache off) for\n    prefill.py's choices only: its image, no weights and no backend.\"\"\"\n    eng = object.__new__(Engine)\n    rows = max(PREFILL_ROWS, cfg.act_rows) if cfg.S == 1 else PREFILL_ROWS\n    img = spec.image(cfg, cap, 1, rows, wformat=wformat, head_format=head_format, lookup=True)\n    eng.__dict__.update(\n        spec=spec, cfg=cfg, cap=cap, block=ATTN_BLOCK, image=img, rows=rows, batch=1,\n        prog_cache=False, prompt_runs=True, tile_runs=None, device_inputs=True, poss=[0],\n        backend=SimpleNamespace(), row_server=None,\n        _host_rows=getattr(img, \"host_rows\", None), _prompt_lock=threading.RLock())\n    return eng\n\n\ndef bucket(eng, b: int) -> dict:\n    p = max((b - 1) * eng.block, PF.conv_k(eng) - 1)\n    rec = dict(bucket=b, pos=p)\n    t = time.time()\n    try:\n        R, covered = PF._fit(eng, b)\n    except Exception as e:                      # noqa: BLE001 (no prompt run fits the bucket)\n        R, covered = 0, False\n        rec[\"prompt_error\"] = f\"{type(e).__name__}: {e}\"[:160]\n    T = PF._tile_fit(eng, b)\n    tiled = PF.tiled(eng, b)\n    rec.update(tile_T=T, today_R=R, today_covered=covered, kind=\"tile\" if tiled else \"prompt\",\n               r_max=PF.r_max(eng, b) if (tiled or R) else 0, covered=tiled or covered)\n    # compile_rows' route (the prompt goes there when any bucket it touches is not covered)\n    n, _, _ = fit_chunk(eng.image, eng.block, 0, p, eng.rows, 1 << 20, eng.rows,\n                        tokens=[0] * eng.rows)\n    rec[\"rows_route_R\"] = n\n    rec[\"s\"] = round(time.time() - t)\n    return rec\n\n\ndef main():\n    ap = argparse.ArgumentParser(description=__doc__.split(\"\\n\")[0])\n    ap.add_argument(\"--model\", required=True)\n    ap.add_argument(\"--wformat\", default=FM.AUTO)\n    ap.add_argument(\"--head-format\", default=None)\n    ap.add_argument(\"--cap\", type=int, default=2048)\n    ap.add_argument(\"--buckets\", default=\"\", help=\"a-b or a list (default: every bucket)\")\n    ap.add_argument(\"--imem\", default=\"\", help=\"the tile's rows at these IMEM sizes, in \"\n                    \"instructions (0: unbounded), e.g. 4096,8192,16384,0\")\n    a = ap.parse_args()\n    if os.environ.get(\"OTPU_TILE\", \"\").strip() not in (\"\", \"1\"):\n        raise SystemExit(\"prefill_routes: OTPU_TILE=0 turns the tile off; unset it\")\n    spec = load_spec(model_dir(a.model))\n    wf = FM.auto(spec, a.wformat)\n    cfg = board_config(PAIR=True, DSTEP=True, STREAM=True, SEQ_WC=True)\n    nb = -(-a.cap // ATTN_BLOCK)\n    if not a.buckets:\n        bs = list(range(1, nb + 1))\n    elif \"-\" in a.buckets:\n        lo, hi = map(int, a.buckets.split(\"-\"))\n        bs = list(range(lo, hi + 1))\n    else:\n        bs = [int(x) for x in a.buckets.split(\",\")]\n    eng = stub_engine(spec, cfg, a.cap, wf, a.head_format)\n    imems = [int(x) for x in a.imem.split(\",\")] if a.imem else []\n    alt = {n: stub_engine(spec, dataclasses.replace(cfg, IMEM_WORDS=8 * (n or 1 << 16)),\n                          a.cap, wf, a.head_format) for n in imems}\n    for b in bs:\n        rec = dict(model=Path(a.model).name, wformat=wf, cap=a.cap, **bucket(eng, b))\n        for n, e in alt.items():\n            rec[f\"tile_T_imem{n or 'inf'}\"] = PF._probe_tile(e, b)\n        print(json.dumps(rec), flush=True)\n\n\nif __name__ == \"__main__\":\n    main()\n", "tools/q35_split.py": "\"\"\"Decode-step cost of a model's first N layers on the card, from the free-running counters:\nwhere a token's cycles go, layer kind by layer kind, to set against tools/perf_qwen.py's\nsimulated cycles for the same --layers.\n\n    python3 tools/q35_split.py [--model qwen35] [--layers 1,3,4,0] [--pos 60] [--reps 3]\n                               [--wformat fp4] [--head-format int8] [--json out.json]\n\nFor each N (0: every layer) the model is cut to its first N layers (the LM head stays whole),\nits image written to the card, and --reps decode steps run at position --pos (per-position\nprograms, the KV cache before --pos empty: the timing does not depend on it). Prints per N the\nstep's cycles (the min over the reps) and the counters over one step: DRAM read / write bytes,\nMXU busy / MAC / starved, VPU, DMA, TMEM_DENY and DRAM_WAIT cycles.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport dataclasses\nimport json\nimport sys\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parent.parent\nsys.path.insert(0, str(ROOT))\n\nfrom opentpu.host import chat as C  # noqa: E402\nfrom opentpu.host import regs as R  # noqa: E402\nfrom opentpu.llm import load_spec, model_dir  # noqa: E402\nfrom opentpu.llm import qwen3 as Q  # noqa: E402\n\nKEYS = (\"RUNNING\", \"MXU_BUSY\", \"MXU_MAC\", \"MXU_STARVE\", \"VPU_BUSY\", \"QNT_BUSY\", \"DMA_BUSY\",\n        \"TMEM_DENY\", \"DRAM_RD\", \"DRAM_WR\", \"DRAM_WAIT\", \"INSTR\")\n\n\ndef main(argv=None) -> int:\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"--model\", default=\"qwen35\")\n    ap.add_argument(\"--layers\", default=\"1,3,4,0\")\n    ap.add_argument(\"--pos\", type=int, default=60)\n    ap.add_argument(\"--reps\", type=int, default=3)\n    ap.add_argument(\"--wformat\", default=\"fp4\")\n    ap.add_argument(\"--head-format\", default=\"int8\")\n    ap.add_argument(\"--backend\", default=\"board\", choices=[\"board\", \"board-sim\"])\n    ap.add_argument(\"--dev\", default=\"/dev/xdma0\")\n    ap.add_argument(\"--json\")\n    a = ap.parse_args(argv)\n    path = model_dir(a.model)\n    full = load_spec(path)\n    W = Q.load_weights(path)\n    cap = 256 * (a.pos // 256 + 1)\n    out = []\n    for n in (int(x) for x in a.layers.split(\",\")):\n        spec = dataclasses.replace(full, **({\"kinds\": full.kinds[:n]} if hasattr(full, \"kinds\")\n                                            else {\"layers\": n})) if n else full\n        backend, cfg = C.make_backend(a.backend, spec, cap, a.dev, path.name)\n        eng = Q.Engine(spec, W, cap=cap, cfg=cfg, backend=backend, wformat=a.wformat,\n                       head_format=a.head_format, pipeline=False)\n        board = eng.backend.board\n        steps = []\n        try:\n            for _ in range(a.reps):\n                eng.pos = a.pos\n                s0 = board.snapshot()\n                eng.step(791)\n                s1 = board.snapshot()\n                d = {k: s1[k] - s0[k] for k in KEYS if k in s0}\n                d[\"cycles\"] = eng.stats[-1][\"cycles\"]\n                steps.append(d)\n        finally:\n            eng.backend.close()\n        best = min(steps, key=lambda d: d[\"cycles\"])\n        best[\"layers\"] = spec.layers if hasattr(spec, \"layers\") else n\n        best[\"kinds\"] = list(getattr(spec, \"kinds\", []))\n        best[\"all_cycles\"] = [d[\"cycles\"] for d in steps]\n        out.append(best)\n        run = max(1, best.get(\"RUNNING\", best[\"cycles\"]))\n        print(f\"N={n or 'all'} ({best['layers']} layers): {best['cycles']} cycles \"\n              f\"(reps {best['all_cycles']}); DRAM read {best['DRAM_RD'] * R.DRAM_BEAT / 1e6:.2f} MB,\"\n              f\" write {best['DRAM_WR'] * R.DRAM_BEAT / 1e6:.2f} MB; \" + \", \".join(\n                  f\"{k} {100 * best[k] / run:.1f}%\" for k in\n                  (\"MXU_BUSY\", \"MXU_MAC\", \"MXU_STARVE\", \"VPU_BUSY\", \"DMA_BUSY\", \"TMEM_DENY\",\n                   \"DRAM_WAIT\") if k in best), flush=True)\n    if a.json:\n        Path(a.json).write_text(json.dumps(out, indent=1))\n    return 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n", "tools/q35_trace.py": "\"\"\"One decode step of a model cut to its first N layers, instruction by instruction, on the card\n(the hardware trace, keep first) or on the RTL simulator (DDR3-1066 bank model, as\ntools/perf_qwen.py --ddr 1066): dumps every traced instruction's timing to JSON, to set the\ntwo side by side (where the card's cycles go that the model does not charge).\n\n    python3 tools/q35_trace.py card|sim --out f.json [--model qwen35] [--layers 1] [--pos 60]\n                                        [--wformat fp4] [--head-format int8] [--mhz 120.755]\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport dataclasses\nimport json\nimport sys\nfrom pathlib import Path\n\nimport numpy as np\n\nROOT = Path(__file__).resolve().parent.parent\nsys.path.insert(0, str(ROOT))\n\nfrom opentpu import isa as I  # noqa: E402\nfrom opentpu import rtlsim  # noqa: E402\nfrom opentpu.llm import load_spec, model_dir  # noqa: E402\nfrom opentpu.llm import qwen3 as Q  # noqa: E402\nfrom opentpu.profile import ddr3_plusargs, parse  # noqa: E402\n\n\ndef _dump(p, progs, cycles, out, extra):\n    recs = []\n    for r in sorted(p.slice_recs(0), key=lambda r: r.idx):\n        ins = progs[0][r.pc]\n        src = ins.src[1] if len(ins.src) > 1 else (ins.src[0] if ins.src else (\"?\", 0, \"?\"))\n        recs.append({\"idx\": r.idx, \"pc\": r.pc, \"op\": r.op, \"name\": r.name, \"detail\": r.detail,\n                     \"dispatch\": r.dispatch, \"ready\": r.ready, \"start\": r.start,\n                     \"release\": r.release, \"end\": r.end, \"portb\": getattr(r, \"portb\", 0),\n                     \"src\": f\"{Path(src[0]).name}:{src[1]} {src[2]}\"})\n    Path(out).write_text(json.dumps({\"cycles\": cycles, \"recs\": recs, **extra}))\n    print(f\"{out}: {cycles} cycles, {len(recs)} instructions traced\", flush=True)\n\n\ndef main(argv=None) -> int:\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"where\", choices=[\"card\", \"sim\"])\n    ap.add_argument(\"--out\", required=True)\n    ap.add_argument(\"--model\", default=\"qwen35\")\n    ap.add_argument(\"--layers\", type=int, default=1)\n    ap.add_argument(\"--pos\", type=int, default=60)\n    ap.add_argument(\"--wformat\", default=\"fp4\")\n    ap.add_argument(\"--head-format\", default=\"int8\")\n    ap.add_argument(\"--mhz\", type=float, default=120.755)\n    ap.add_argument(\"--dev\", default=\"/dev/xdma0\")\n    a = ap.parse_args(argv)\n    path = model_dir(a.model)\n    spec = load_spec(path)\n    if a.layers:\n        spec = dataclasses.replace(spec, **({\"kinds\": spec.kinds[:a.layers]}\n                                            if hasattr(spec, \"kinds\") else {\"layers\": a.layers}))\n    W = Q.load_weights(path)\n    cap = 256 * (a.pos // 256 + 1)\n    if a.where == \"card\":\n        from opentpu.host import chat as C\n        from opentpu.host.hwlens import records_to_trace\n        backend, cfg = C.make_backend(\"board\", spec, cap, a.dev, path.name)\n        eng = Q.Engine(spec, W, cap=cap, cfg=cfg, backend=backend, wformat=a.wformat,\n                       head_format=a.head_format, pipeline=False)\n        try:\n            eng.pos = a.pos\n            eng.step(791)                   # warm: the same run untraced\n            eng.pos = a.pos\n            progs = eng.image.compile_step(a.pos)\n            eng.backend.trace = {\"keep\": \"first\"}\n            eng._program = lambda pos: progs        # the traced run's programs, for parse\n            eng.step(791)\n            st = eng.stats[-1]\n        finally:\n            eng.backend.close()\n        tr = st[\"trace\"]\n        p = parse(records_to_trace(tr[\"records\"], progs), cfg, progs, \"card\")\n        _dump(p, progs, st[\"cycles\"], a.out,\n              {\"trace\": {k: tr[k] for k in (\"count\", \"drop\", \"depth\", \"lost\")}})\n        return 0\n    from opentpu.isasim import board_config\n    wkw = dict(wformat=a.wformat, head_format=a.head_format, rows=Q.PREFILL_ROWS)\n    need = spec.image(board_config(DRAM_BYTES=1 << 40), cap, **wkw).nbytes\n    cfg = board_config(DRAM_BYTES=1 << max(20, (need - 1).bit_length()))\n    img = spec.image(cfg, cap, **wkw)\n    dram = img.build(W)[0]\n    x = np.asarray(W[\"model.embed_tokens.weight\"][791], np.float32)\n    c, s = Q.rope_tables(spec, a.pos)\n    for key, v in ((\"x\", x), (\"cos\", c), (\"sin\", s)):\n        b = np.ascontiguousarray(v, np.float32).view(np.uint8).ravel()\n        dram[img.io[key]:img.io[key] + b.size] = b\n    progs = img.compile_step(a.pos)\n    mts = 3200 / 3\n    _, _, st = rtlsim.run(cfg, progs, [dram], trace=True, uarch=rtlsim.BOARD_UARCH,\n                          axi=True, boot=True, stall=0, bw=100, lat=round(0.3 * a.mhz),\n                          max_cycles=1 << 40, plusargs=ddr3_plusargs(mts, a.mhz))\n    p = parse(st[\"trace\"], cfg, progs, \"sim\")\n    _dump(p, progs, st[\"cycles\"], a.out, {})\n    return 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n", "tools/qual/chatkv.py": "\"\"\"Card check of a chat's KV cache across turns (docs/host.md, \"The KV cache across turns\"): a\nscripted conversation through otpu-chat's Chat on --backend board, greedy, each turn rolled\nback to where its rendering parts from what the device holds (Engine.rollback; Qwen3.5, LFM2,\nGemma 4 past its rings' slack: from the snapshot of their state each turn takes at its reply's\nstart, copied on the device) and fed the rest; then each turn's rendering again from position\n0, as the chat fed it before (the restart), whose logits must equal the turn's first logits bit\nfor bit (int8 weights: any split of a prompt into runs gives the same rows), and whose greedy\nreply the turn's. Per turn: the rendering's tokens, the tokens reused and fed, the prefill's\nruns, where a restore took the context (restored at), device Mcycles and wall seconds against\nthe restart's, the snapshot's and the restore's device cycles (the ISA simulator counts no\ncycles: tokens and runs). --mtp: the turns' prefill is MTP's (its rows and\nthe MTP layer's runs), the restart a plain prefill of the rows.\n\n    otpu-lock -- python3 tools/qual/chatkv.py --model qwen35 [--mtp] [--dev /dev/xdma0]\n    otpu-lock -- python3 tools/qual/chatkv.py --model gemma4 --think --max-new 300 --turns 3\n    python3 tools/qual/chatkv.py --model qwen3 --backend isa --turns 3 --max-new 8   (dry run)\n\nGemma 4 E2B-it (int8 layers, the fp4 PLE table) continues each turn's context thinking off; with\n--think the template drops a reply's thinking channel (a reply cut at --max-new, its channel\nopen, entirely), so the turn rolls back to the reply's start, through the snapshot (restored)\nonce that is more than its rings' slack (257) back.\n\nPrints one line per turn and \"CHATKV PASS\" (exit 0) or \"CHATKV FAIL\" (exit 1).\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport sys\nimport time\nfrom pathlib import Path\n\nimport numpy as np\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[2]))\n\nfrom opentpu.host.chat import SNAPSHOTS, Chat, make_backend, sampler   # noqa: E402\nfrom opentpu.llm import MODELS, load_spec, model_dir                  # noqa: E402\nfrom opentpu.llm import snapshot as SN                                # noqa: E402\nfrom opentpu.llm.qwen3 import PREFILL_ROWS, Engine, load_weights      # noqa: E402\n\nMESSAGES = [\"What is 1 + 32 * 9?\",\n            \"And why is the ocean blue?\",\n            \"Give me three facts about it as a short list.\",\n            \"Shorter, please.\",\n            \"Thanks! Summarize this chat in one sentence.\"]\n\n\ndef recording(rec: list, eng=None):\n    \"\"\"A greedy chat.sampler that keeps the logits of its picks (each turn's first token), and\n    the engine's runs so far (len(eng.stats): the prefill's runs end there). Gemma 4's: with its\n    soft cap, as Chat takes (the same argmax).\"\"\"\n    base = sampler(0, 0, 1.0, None, softcap=getattr(getattr(eng, \"spec\", None), \"softcap\", None))\n\n    def pick(logits, context=()):\n        rec.append((np.array(logits, np.float32), len(eng.stats) if eng is not None else 0))\n        return base(logits, context)\n    for k in (\"stream\", \"warm\", \"greedy\", \"params\", \"softcap\", \"rng\"):\n        setattr(pick, k, getattr(base, k))\n    return pick\n\n\ndef sim_config(spec, cap: int, wformat: str, head_format: str | None):\n    \"\"\"The simulators' configuration: the card's (one slice, MCOLS 4, PAIR, DSTEP, STREAM), its\n    DRAM cut to the image and the program area (board.sim_config), doubled where the\n    snapshots' area does not fit beside them.\"\"\"\n    from dataclasses import replace\n\n    from opentpu.host.board import sim_config as cut\n    from opentpu.isasim import board_config\n    cfg = cut(spec, cap, board_config(PAIR=True, DSTEP=True, STREAM=True), lookup=True,\n              wformat=wformat, head_format=head_format)\n    img = spec.image(replace(cfg, DRAM_BYTES=1 << 40), cap, 1, PREFILL_ROWS, wformat,\n                     head_format, lookup=True)\n    if SN.stateful(img) and SN.Snapshots.area(img, cfg, SNAPSHOTS) is None:\n        cfg = replace(cfg, DRAM_BYTES=2 * cfg.DRAM_BYTES)\n    return cfg\n\n\ndef _cycles(stats) -> int:\n    return sum((s or {}).get(\"cycles\", 0) for s in stats)\n\n\ndef _mc(c: int, on: bool) -> str:\n    return f\" {c / 1e6:.1f} Mcycles\" if on else \"\"\n\n\ndef main(argv=None) -> int:\n    ap = argparse.ArgumentParser(description=__doc__.split(\"\\n\")[0])\n    ap.add_argument(\"--model\", default=\"qwen35\",\n                    help=f\"{' or '.join(MODELS)} (models/<name>), or a checkpoint directory\")\n    ap.add_argument(\"--backend\", default=\"board\", choices=[\"board\", \"board-sim\", \"isa\"])\n    ap.add_argument(\"--dev\", default=\"/dev/xdma0\")\n    ap.add_argument(\"--cap\", type=int, default=1024)\n    ap.add_argument(\"--wformat\", default=\"int8\", choices=[\"int8\", \"fp4\", \"int4\", \"nvfp4\", \"mix\"],\n                    help=\"int8 (default): bit-exact in any split; with PAIR a 4-bit run of \"\n                         \"more than MCOLS / 2 rows sums in another order (docs/prefill.md)\")\n    ap.add_argument(\"--head-format\", default=None, choices=[\"int8\", \"fp4\", \"int4\", \"nvfp4\"])\n    ap.add_argument(\"--turns\", type=int, default=len(MESSAGES))\n    ap.add_argument(\"--max-new\", type=int, default=24)\n    ap.add_argument(\"--think\", action=\"store_true\")\n    ap.add_argument(\"--mtp\", action=\"store_true\", help=\"Qwen3.5: the MTP decoder\")\n    a = ap.parse_args(argv)\n    from transformers import AutoTokenizer\n    path = model_dir(a.model)\n    tok, spec = AutoTokenizer.from_pretrained(path), load_spec(path)\n    if a.mtp:\n        from dataclasses import replace\n        spec = replace(spec, mtp=True)\n    if a.backend == \"board\":\n        backend, cfg = make_backend(a.backend, spec, a.cap, a.dev, path.name, lookup=True,\n                                    wformat=a.wformat, head_format=a.head_format)\n    else:\n        backend, cfg = \"isa\", sim_config(spec, a.cap, a.wformat, a.head_format)\n        if a.backend == \"board-sim\":\n            from opentpu.host.board import BoardBackend, SimTransport\n            tr = SimTransport(ch_bytes=cfg.DRAM_BYTES // 2)\n            backend = (lambda c, imgs: BoardBackend(c, imgs, transport=tr, model=path.name))\n    kw = dict(cap=a.cap, cfg=cfg, backend=backend, wformat=a.wformat,\n              head_format=a.head_format, prompt_runs=True, snapshots=SNAPSHOTS)\n    if a.mtp:\n        from opentpu.llm.mtp import mtp_engine\n        eng = mtp_engine(spec, load_weights(path, mtp=True), **kw)\n    else:\n        eng = Engine(spec, load_weights(path), resident=True, **kw)\n    khz = (getattr(eng.backend, \"info\", None) or {}).get(\"core_khz\")\n    mhz = khz / 1e3 if khz else 0.0\n    cyc_on = a.backend != \"isa\"            # the ISA simulator counts no cycles\n    rec: list = []\n    chat = Chat(eng, tok, a.think, recording(rec, eng), a.max_new, clock_mhz=mhz)\n    print(f\"{path.name} {eng.image.wformat} head {eng.image.head_format}, {a.backend}\"\n          f\"{f' {mhz:g} MHz' if mhz else ''}, cap {a.cap}, think {a.think}, mtp {chat.use_mtp}, \"\n          f\"stateful {eng.stateful}, snapshots \"\n          f\"{'none' if eng._snaps is None else 'device' if eng.snapshot_bytes else 'host'}\"\n          f\" ({0 if eng._snaps is None else eng._snaps.nbytes / 2**20:.2f} MiB)\", flush=True)\n    turns = []\n    for msg in MESSAGES[:a.turns]:\n        k0, s0 = len(eng.stats), len(eng.snap_stats)\n        reply, t = chat.ask(msg)\n        ids = chat._template(history=chat.history[:-1])\n        ops = {op: _cycles(x for x in eng.snap_stats[s0:] if x[\"op\"] == op)\n               for op in (\"snapshot\", \"restore\")}\n        runs = rec[-1][1] - k0 if not chat.use_mtp else None\n        turns.append(dict(ids=ids, t=t, logits=rec[-1][0], reply=list(chat._reply), ops=ops,\n                          runs=runs))\n        back = [s[\"pos\"] for s in eng.snap_stats[s0:] if s[\"op\"] == \"restore\"]\n        print(f\"turn {len(turns)}: {len(ids)} tokens, reused {t.reused}, fed {t.prefill_tokens}\"\n              f\"{'' if runs is None else f' in {runs} runs'}\"\n              f\"{' (restarted)' if t.restarted else ''}\"\n              f\"{f' (restored at {back[0]})' if back else ''}; prefill {t.prefill_s:.3f} s\"\n              f\"{_mc(t.prefill_cycles, cyc_on)}, TTFT {t.ttft_s or 0:.3f} s; \"\n              + (f\"snapshot {ops['snapshot'] / 1e6:.2f} restore {ops['restore'] / 1e6:.2f} \"\n                 f\"Mcycles; \" if cyc_on else \"\")\n              + f\"reply {t.gen_tokens} tokens ({t.end})\", flush=True)\n    ok, tot = True, np.zeros(6)\n    for i, x in enumerate(turns):                   # the restart: the rendering from 0\n        eng.reset()\n        k0, w0 = len(eng.stats), time.perf_counter()\n        lg = eng.prefill(x[\"ids\"])\n        wall, cyc, runs = time.perf_counter() - w0, _cycles(eng.stats[k0:]), len(eng.stats) - k0\n        same = np.array_equal(lg.view(np.uint32), x[\"logits\"].view(np.uint32))\n        diff = float(np.max(np.abs(lg - x[\"logits\"]))) if not same else 0.0\n        out, want = [], x[\"reply\"]\n        while len(out) < len(want):                 # the greedy reply after it\n            out.append(int(np.argmax(lg)))\n            if len(out) < len(want):\n                lg = eng.step(out[-1])\n        t = x[\"t\"]\n        good = same and out == want and not (i and t.restarted)\n        ok &= good\n        cyc_rb = t.prefill_cycles + sum(x[\"ops\"].values())\n        tot += [len(x[\"ids\"]), t.prefill_tokens, cyc, cyc_rb, runs, x[\"runs\"] or 0]\n        lgs = \"equal\" if same else f\"differ (max {diff:.3g})\"\n        rb_runs = \"\" if x[\"runs\"] is None else f\" in {x['runs']} runs\"\n        print(f\"[{'PASS' if good else 'FAIL'}] turn {i + 1}: logits {lgs}, reply \"\n              f\"{'equal' if out == want else 'differs'}; restart: {len(x['ids'])} tokens in \"\n              f\"{runs} runs {wall:.3f} s{_mc(cyc, cyc_on)}, rollback: {t.prefill_tokens} \"\n              f\"tokens{rb_runs} {t.prefill_s:.3f} s{_mc(cyc_rb, cyc_on)}\", flush=True)\n    runs = \"\" if chat.use_mtp else f\"{int(tot[5])} \"       # MTP: its rows and layer runs\n    print(f\"tokens fed {int(tot[1])} (restart {int(tot[0])}), runs {runs}(restart \"\n          f\"{int(tot[4])})\" + (f\", device Mcycles {tot[3] / 1e6:.1f} (restart \"\n                               f\"{tot[2] / 1e6:.1f})\" if cyc_on else \"\"))\n    print(\"CHATKV PASS\" if ok else \"CHATKV FAIL\")\n    return 0 if ok else 1\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n", "tools/qual/chatmoe.py": "\"\"\"otpu-chat with a mixture-of-experts model streamed from its pool (docs/offload.md 14), scripted:\na few turns of one conversation through otpu-chat's own Chat, engine and sampler, on the ISA\nsimulator or the card, each turn's tokens and numbers as JSON. The run on the simulator with the\ncard's configuration (tools/qual/refs.py cfg) is the card's reference bit for bit: --check\ncompares every turn's tokens with it.\n\n    python3 tools/qual/chatmoe.py MODEL --cfg cfg.pkl --out ref.json              # ISA simulator\n    python3 tools/qual/chatmoe.py MODEL --backend board --check ref.json --out card.json\n\nMODEL: a short name of opentpu.llm.MODELS (lfm2-8b, qwen35-35b, gemma4-26b) or a checkpoint\ndirectory. The turns default to TURNS (two: a question, then one about the answer), greedy\n(--sample: the model's sampling defaults, the uniforms from --seed's generator: the card's loop\npicks the same tokens as the simulator's), --max-new tokens each. The pool, slots and prompt\nsettings are otpu-chat's (opentpu/host/streamed.py; --em-rows: expert-major's least rows a\ncall, docs/offload.md 13.16). Each turn lists its prompt's calls (a layer-major prompt's\nprefill_layers: a model with state has two, up to the snapshot at the reply's start and after):\nrows, expert-major or not, wall and device seconds, the expert server's counts over it and the\nhost's time on its requests and idle parts (--trace: each call's runs and the server's timeline\ntoo, and each turn's host phases up to its first token, _Phases). On a tree whose\nstreamed.engine has no em_rows (production's) it runs without --em-rows.\nThe pool's page cache is recorded with them: the fraction of its packed experts in it (mincore,\nPoolFile.resident, as tools/offload/pool_disk.py checks its arms) after the load and before and\nafter each turn (--pool-calls: each call too; a 17.5 GB pool's check takes 60-90 ms, which\nthe turn's wall times then include), and each call's and turn's pool reads by where they came\nfrom (PoolFile.io: \"cached\", \"disk\"); a turn that read from the disk or began under 95% is\nmarked \"cold\" (its prompt's misses waited on the disk: session r2m8's 35B, 2026-10-13, 2,966\nmisses served in 40.2 s against production's 2.9 s, the same calls, read from the SSD at\n~13.5 ms each).\n--mtp (Qwen3.5-MoE): the MTP drafter's image (streamed.engine(mtp=): its pool the -mtp one,\npack_pool.py extend), each reply by the MTP loop on the device as otpu-chat --mtp decodes it\n(docs/offload.md 15.6), greedy or sampled: the same tokens as plain decode's (--check against a\nplain run's JSON), with each turn's iterations and accepted drafts; --mtp-from: the drafter's\ncheckpoint when not the model's (MiniCPM-V 4.7: its base Qwen3.5-35B-A3B). Exit 1 when --check\nfinds another token.\n\nImages (a model with a vision side: MiniCPM-V, docs/minicpmv.md): --image N:PATH attaches PATH\nto turn N (1-based; repeated), --max-slices bounds an image's slices; each turn reports its\nimages and their crops' wall seconds through the card's tower (vision_s), and the JSON keeps\neach image's sha256 (the reference's must be the same bytes).\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport json\nimport pickle\nimport sys\nimport time\nfrom pathlib import Path\n\nTURNS = (\"What is the capital of France? Answer in one sentence.\",\n         \"And what is it famous for? Two sentences.\")\nDATE = (2026, 9, 29)        # \"today\" for a chat template that states it (refs.py's DATE)\n\n\nclass _Pinned:\n    \"\"\"The tokenizer with its chat template's date pinned (a reference must not expire).\"\"\"\n\n    def __init__(self, tok):\n        self.tok = tok\n\n    def __getattr__(self, k):\n        return getattr(self.tok, k)\n\n    def __call__(self, *a, **kw):\n        return self.tok(*a, **kw)\n\n    def apply_chat_template(self, *a, **kw):\n        import datetime\n        day = datetime.date(*DATE)\n        return self.tok.apply_chat_template(*a, strftime_now=lambda fmt: day.strftime(fmt), **kw)\n\n\n# the expert server's counts a prompt's call reports (their change over it): its requests'\n# hits and misses, expert-major's need lines, their ids queued (not in a slot), already in\n# one and landed, the needs end_prefill sent, idle parts landed whole (prefetched) and the\n# polls that held one back near a run's end (holds, stage_holds), the bytes sent\nCALL_COUNTS = (\"hits\", \"misses\", \"need_lines\", \"needs_queued\", \"need_hits\", \"needs_landed\",\n               \"drained\", \"prefetched\", \"holds\", \"stage_holds\", \"bytes\")\n\n\ndef _pool(eng):\n    \"\"\"The engine's pool file (offload.PoolFile) and its packed experts' bytes; (None, 0) for a\n    pool in host RAM.\"\"\"\n    pf = getattr(getattr(eng, \"server\", None), \"pool_file\", None)\n    if pf is None or pf.ids is None or not len(pf.ids):\n        return None, 0\n    return pf, len(pf.ids) * pf.slot\n\n\ndef _resident(pf, total: int) -> float | None:\n    \"\"\"The fraction of the pool's packed experts in the page cache now (PoolFile.resident), or\n    None where the host cannot tell.\"\"\"\n    res = None if pf is None else pf.resident(pf.ids)\n    return None if res is None else round(res / total, 4)\n\n\ndef _io(pf) -> dict:\n    \"\"\"PoolFile.io's counts now (a copy): {cached | disk | unknown: [reads, s, bytes, absent]}.\"\"\"\n    return {k: list(v) for k, v in ((pf.io or {}) if pf is not None else {}).items()}\n\n\ndef _reads(io0: dict, io1: dict) -> dict:\n    \"\"\"The pool's reads between two _io copies by where they came from: [reads, s, MB].\"\"\"\n    out = {}\n    for k, v in io1.items():\n        d = [x - y for x, y in zip(v, io0.get(k, [0] * len(v)))]\n        if d[0]:\n            out[k] = [d[0], round(d[1], 3), round(d[2] / 1e6, 1)]\n    return out\n\n\ndef _calls(eng, calls: list, trace: list | None = None, pool_calls: bool = False) -> None:\n    \"\"\"Each prefill_layers call of eng appended to `calls`: its rows, expert-major or not (the\n    gate's choice, streamed.gate_expert_major, else the Engine's), wall and device seconds,\n    runs, the server's CALL_COUNTS over it, and from the server's events its requests and the\n    host's seconds on them (serve_s: each seen to served, while the card waits) and on idle\n    parts (parts_s); with `trace` (a list) also its runs (key, start, end, cycles; s from the\n    call's start) and those events (seen, done, kind, layer or expert, misses or bytes).\"\"\"\n    base, srv = eng.prefill_layers, eng.server\n    pf, total = _pool(eng)\n    res = (lambda: _resident(pf, total)) if pool_calls else (lambda: None)  # noqa: E731\n    khz = (getattr(eng.backend, \"info\", None) or {}).get(\"core_khz\")\n    runs, t0 = [], [None]\n    if trace is not None:\n        lr, b, key = eng._layer_run, eng.backend, [None]\n\n        def layer_run(k):\n            key[0] = k\n            return lr(k)\n        eng._layer_run = layer_run\n        if hasattr(b, \"start\"):                 # (the card's: start, then wait)\n            start, wait = b.start, b.wait\n\n            def started(*a, **kw):\n                if t0[0] is not None:\n                    runs.append([key[0], time.perf_counter() - t0[0]])\n                return start(*a, **kw)\n\n            def waited(*a, **kw):\n                st = wait(*a, **kw)\n                if t0[0] is not None and runs and len(runs[-1]) == 2:\n                    runs[-1] += [time.perf_counter() - t0[0], (st or {}).get(\"cycles\")]\n                return st\n            b.start, b.wait = started, waited\n\n    def prefill_layers(tokens, logits: bool = True, **kw):     # (kw: an MTP image's, vis)\n        c0 = {k: getattr(srv, k, 0) for k in CALL_COUNTS}\n        res0, io0 = res(), _io(pf)              # (the pool's page cache: outside the timing)\n        k, t = len(eng.stats), time.perf_counter()\n        srv.events = []                         # (the server's timeline: each poll that did work)\n        if trace is not None:\n            runs.clear()\n            t0[0] = t\n        try:\n            return base(tokens, logits, **kw)\n        finally:\n            dt = time.perf_counter() - t\n            cyc = sum((x or {}).get(\"cycles\") or 0 for x in eng.stats[k:])\n            last = getattr(eng, \"em_last\", None)\n            em = last[1] if last is not None and last[0] == len(tokens) else eng.expert_major\n            ev, srv.events = srv.events or [], None\n            req = [e for e in ev if e[2] == \"d\"]\n            calls.append(dict(rows=len(tokens), em=bool(em), s=round(dt, 3),\n                              device_s=round(cyc / (khz * 1e3), 3) if khz else None,\n                              runs=len(eng.stats) - k, requests=len(req),\n                              serve_s=round(sum(e[1] - e[0] for e in req), 3),\n                              parts_s=round(sum(e[1] - e[0] for e in ev if e[2] == \"p\"), 3),\n                              **{c: getattr(srv, c, 0) - c0[c] for c in CALL_COUNTS},\n                              pool_before=res0, pool_after=res(),\n                              reads=_reads(io0, _io(pf))))\n            if trace is not None:\n                t0[0] = None\n                trace.append(dict(rows=len(tokens), em=bool(em), runs=[list(r) for r in runs],\n                                  events=[[round(e[0] - t, 6), round(e[1] - t, 6)] +\n                                          list(e[2:]) for e in ev]))\n    eng.prefill_layers = prefill_layers\n\n\n# the host's phases of a turn up to its first token (--trace, _Phases), and the ones that\n# hold others (left out of _Phases.line's sum: their parts are phases of their own)\nPHASES = (\"template\", \"rollback\", \"mtp prefill\", \"prefill_layers\", \"end_prefill\", \"mtp snapshot\",\n          \"snapshot\", \"a0\", \"run\")\nHOLDERS = (\"mtp prefill\", \"mtp snapshot\")\n\n\nclass _Phases:\n    \"\"\"--trace: each turn's host phases from its start (before Chat.ask) to its first token,\n    [phase, start, end, cycles] (s from the turn's start; a device run's cycles, else None),\n    in the order they end: \"template\" (Chat._template: the conversation rendered, the prompt's\n    and reply_start's), \"rollback\" (Chat._rollback: to a snapshot, its restore's runs in it),\n    \"mtp prefill\" (MTPDecoder.prefill: the MTP decoder's prompt, a nested one for its first\n    conv_k - 1 rows), \"prefill_layers\" (each call, as `calls`), \"end_prefill\" (the expert\n    server's slots back to decode's, in a call), \"snapshot\" (Engine.snapshot: the state's\n    copy), \"mtp snapshot\" (MTPDecoder.snapshot: the snapshot and the held row's read), \"a0\"\n    (the first pick: the first token from the prompt's logits; none starts after it) and \"run\"\n    (each device run outside the calls: a snapshot's copies, MTP's first rows, a draft). Host\n    bookkeeping: the same calls, runs and tokens.\"\"\"\n\n    def __init__(self, chat, eng):\n        self.t0, self.done, self.out, self.depth = None, False, [], 0\n        self.wrap(chat, \"_template\", \"template\")\n        self.wrap(chat, \"_rollback\", \"rollback\")\n        self.wrap(eng, \"snapshot\", \"snapshot\")\n        self.wrap(eng, \"prefill_layers\", \"prefill_layers\", call=True)\n        srv = getattr(eng, \"server\", None)\n        if srv is not None and hasattr(srv, \"end_prefill\"):\n            self.wrap(srv, \"end_prefill\", \"end_prefill\")\n        if chat.mtp is not None:\n            self.wrap(chat.mtp, \"prefill\", \"mtp prefill\")\n            self.wrap(chat.mtp, \"snapshot\", \"mtp snapshot\")\n        chat.pick = _FirstPick(chat.pick, self)\n        b = eng.backend\n        if hasattr(b, \"start\"):                 # (the card's: run is start, then wait)\n            start, wait, t = b.start, b.wait, [None]\n\n            def started(*a, **kw):\n                t[0] = time.perf_counter() if self.live and not self.depth else None\n                return start(*a, **kw)\n\n            def waited(*a, **kw):\n                st = wait(*a, **kw)\n                if t[0] is not None:\n                    self.add(\"run\", t[0], time.perf_counter(), (st or {}).get(\"cycles\"))\n                    t[0] = None\n                return st\n            b.start, b.wait = started, waited\n        else:\n            self.wrap(b, \"run\", \"run\", run=True)\n\n    @property\n    def live(self) -> bool:\n        return self.t0 is not None and not self.done\n\n    def add(self, name: str, t: float, t1: float, cycles=None) -> None:\n        self.out.append([name, round(t - self.t0, 6), round(t1 - self.t0, 6), cycles])\n\n    def wrap(self, obj, attr: str, name: str, call: bool = False, run: bool = False) -> None:\n        \"\"\"obj.attr stamped `name` (call: a prefill_layers call, whose runs are its own; run:\n        a device run, outside the calls only, its cycles too).\"\"\"\n        fn = getattr(obj, attr)\n\n        def timed(*a, **kw):\n            if not self.live or (run and self.depth):\n                return fn(*a, **kw)\n            t, r = time.perf_counter(), None\n            self.depth += call\n            try:\n                r = fn(*a, **kw)\n                return r\n            finally:\n                self.depth -= call\n                self.add(name, t, time.perf_counter(),\n                         r.get(\"cycles\") if run and isinstance(r, dict) else None)\n        setattr(obj, attr, timed)\n\n    def begin(self) -> None:\n        self.t0, self.done, self.out = time.perf_counter(), False, []\n\n    def end(self) -> list:\n        self.t0 = None\n        return self.out\n\n    @staticmethod\n    def line(phases: list, ttft: float | None) -> str:\n        \"\"\"A turn's phases summed by name, and the rest of its TTFT outside them (the union of\n        the phases' spans but HOLDERS').\"\"\"\n        tot: dict = {}\n        for p, a, b, _ in phases:\n            n, s = tot.get(p, (0, 0.0))\n            tot[p] = (n + 1, s + b - a)\n        spans = sorted((a, b) for p, a, b, _ in phases if p not in HOLDERS)\n        cov, end = 0.0, 0.0\n        for a, b in spans:\n            cov += max(0.0, b - max(a, end))\n            end = max(end, b)\n        rest = \"\" if ttft is None else f\"; the rest of TTFT {max(0.0, ttft - cov):.3f} s\"\n        return \", \".join(f\"{p} {tot[p][1]:.3f} s\" + (f\" ({tot[p][0]})\" if tot[p][0] > 1 else \"\")\n                         for p in PHASES if p in tot) + rest\n\n\nclass _FirstPick:\n    \"\"\"The chat's sampler (its attributes as they are), its first call in a turn stamped \"a0\"\n    (_Phases): the turn's first token.\"\"\"\n\n    def __init__(self, pick, ph: _Phases):\n        self._pick, self._ph = pick, ph\n\n    def __getattr__(self, k):\n        return getattr(self._pick, k)\n\n    def __call__(self, *a, **kw):\n        ph = self._ph\n        if not ph.live:\n            return self._pick(*a, **kw)\n        t = time.perf_counter()\n        try:\n            return self._pick(*a, **kw)\n        finally:\n            ph.add(\"a0\", t, time.perf_counter())\n            ph.done = True\n\n\ndef run(model, backend: str = \"isa\", cfg_file: str | None = None, dev: str = \"/dev/xdma0\",\n        turns=TURNS, max_new: int = 16, cap: int = 2048, pool: str | None = None,\n        experts: int = 0, layer_major: int | None = None, sample: bool = False,\n        seed: int = 0, create: bool = False, tok=None, em_rows: int | None = None,\n        trace: list | None = None, em_pass: int | None = None, mtp: bool = False,\n        mtp_from: str | None = None, images=(), max_slices: int | None = None,\n        vision_staged: bool | None = None, pool_calls: bool = False,\n        tile_rows: int | None = None, phases: list | None = None) -> dict:\n    from opentpu.host import chat as C\n    from opentpu.host import streamed as ST\n    from opentpu.isasim import board_config\n    from opentpu.llm import load_spec, model_dir\n    path = model_dir(model)\n    if tok is None:\n        from transformers import AutoTokenizer\n        tok = _Pinned(AutoTokenizer.from_pretrained(path))\n    spec = load_spec(path)\n    wformat, head, formats = ST.defaults(spec)\n    be, cfg = C.make_backend(backend, spec, cap, dev, path.name)\n    if cfg_file is not None:                    # (the card's: refs.py cfg)\n        want = pickle.loads(Path(cfg_file).read_bytes())\n        if cfg is not None and cfg != want:\n            raise SystemExit(f\"the device's configuration is not {cfg_file}'s: {cfg} / {want}\")\n        cfg = want\n    t = time.time()\n    eng = ST.engine(path, cfg or board_config(), be, cap, pool or ST.DEFAULT, experts=experts,\n                    wformat=wformat, head_format=head, formats=formats, layer_major=layer_major,\n                    create=create, snapshots=C.SNAPSHOTS,     # (otpu-chat's: its turns roll back)\n                    vision_staged=vision_staged,              # (MiniCPM-V: None, the Spec's)\n                    **({} if em_rows is None else {\"em_rows\": em_rows}),    # (13.16)\n                    **({} if em_pass is None else {\"em_pass\": em_pass}),    # (13.18)\n                    **({\"mtp\": True, \"mtp_from\": mtp_from} if mtp else {}),    # (15.6)\n                    **({} if tile_rows is None else {\"tile_rows\": tile_rows, \"tile_runs\": True}))\n    load_s = time.time() - t\n    if tile_rows is not None and not getattr(eng, \"layer_tile\", False):\n        raise SystemExit(\"--tile-rows: no tiled expert-major runs on this engine (their mask \"\n                         \"tiles: an image built without OTPU_TILE=0; expert-major prefill)\")\n    pf, total = _pool(eng)\n    if pf is not None and pf.io is None:        # (the reads by where they came from)\n        pf.io = {}\n    calls: list = []\n    if eng.layer_major:                         # (the prompt's calls, each turn's)\n        _calls(eng, calls, trace, pool_calls)\n    sp = C.sampling(spec, argparse.Namespace(), path)\n    pick = C.sampler(sp[\"temperature\"] if sample else 0, sp[\"top_k\"], sp[\"top_p\"], seed,\n                     sp[\"repetition_penalty\"], getattr(spec, \"softcap\", None))\n    khz = (getattr(eng.backend, \"info\", None) or {}).get(\"core_khz\")\n    chat = C.Chat(eng, tok, False, pick, max_new, clock_mhz=khz / 1e3 if khz else 0.0)\n    chat.max_slices = max_slices\n    ph = None if phases is None else _Phases(chat, eng)     # (--trace: each turn's phases)\n    out = dict(model=path.name, backend=backend, cfg=cfg_file, sample=sample, seed=seed,\n               weights=C.weights_label(eng.image, wformat),\n               experts=ST.describe(eng, eng.pool_path), layer_major=eng.layer_major,\n               expert_major=eng.expert_major, em_rows=getattr(eng, \"em_rows\", 0),\n               em_pass=getattr(eng, \"em_pass\", None),\n               tile_rows=getattr(eng, \"tile_rows\", None) if getattr(eng, \"layer_tile\", False)\n               else None, on_card=chat.on_card, load_s=round(load_s, 1), max_slices=max_slices,\n               vision_staged=getattr(getattr(eng.image, \"vision\", None), \"resident\", True) is False,\n               images=[dict(turn=i, path=str(f), sha256=hashlib.sha256(\n                   Path(f).read_bytes()).hexdigest()) for i, f in images],\n               pool_gb=round(total / 1e9, 2), pool_at_load=_resident(pf, total), turns=[])\n    if mtp:\n        if not chat.use_mtp:\n            raise SystemExit(\"--mtp: these sampling settings stay on the host (no MTP loop)\")\n        out.update(mtp=True, mtp_from=mtp_from)\n    for k, text in enumerate(turns, 1):\n        for i, f in images:\n            if i == k:\n                chat.attach(str(f))\n        n0, c0 = len(chat.fed), len(calls)\n        res0, io0 = _resident(pf, total), _io(pf)\n        k0 = None if trace is None else len(trace)\n        if ph is not None:\n            ph.begin()\n        reply, tr = chat.ask(text)\n        if ph is not None:\n            phases.append(dict(ttft_s=tr.ttft_s, calls=[k0, len(trace)] if trace is not None\n                               else None, phases=ph.end()))\n        res1, reads = _resident(pf, total), _reads(io0, _io(pf))\n        r = lambda x, k=3: None if x is None else round(x, k)      # noqa: E731\n        out[\"turns\"].append(dict(\n            text=text, reply=reply, tokens=list(chat._reply), end=tr.end, fed_before=n0,\n            fed=[int(t) for t in chat.fed],\n            prompt_tokens=tr.prefill_tokens, reused=tr.reused, restarted=tr.restarted,\n            context=tr.context, ttft_s=r(tr.ttft_s),\n            prefill_s=r(tr.prefill_s), prefill_tok_s=r(tr.prefill_tok_s, 2),\n            prefill_dev_tok_s=r(tr.prefill_dev_tok_s, 2), gen_tokens=tr.gen_tokens,\n            decode_tok_s=r(tr.decode_tok_s, 2), decode_dev_tok_s=r(tr.decode_dev_tok_s, 2),\n            hits=tr.expert_hits, misses=tr.expert_misses,\n            hit_rate=r(tr.expert_hit_rate, 4), mb_per_token=r(tr.streamed_mb_per_token, 2),\n            prefill_misses=tr.prefill_misses, images=tr.images, vision_s=r(tr.vision_s),\n            calls=calls[c0:], line=tr.line(),\n            pool_before=res0, pool_after=res1, reads=reads,\n            cold=bool(reads.get(\"disk\")) or any(c[\"pool_before\"] is not None and\n                                                c[\"pool_before\"] < 0.95 for c in calls[c0:])\n            or (res0 is not None and res0 < 0.95),\n            **({\"mtp_iters\": tr.mtp_iters, \"mtp_accepted\": tr.mtp_accepted} if mtp else {})))\n    out[\"host_mem\"] = ST.host_mem()\n    return out\n\n\ndef check(got: dict, ref: dict) -> list:\n    \"\"\"The turns whose tokens differ from the reference's: (turn, first different index).\"\"\"\n    bad = []\n    for i, (a, b) in enumerate(zip(got[\"turns\"], ref[\"turns\"])):\n        if a[\"tokens\"] != b[\"tokens\"]:\n            bad.append((i, next((j for j, (x, y) in enumerate(zip(a[\"tokens\"], b[\"tokens\"]))\n                                 if x != y), min(len(a[\"tokens\"]), len(b[\"tokens\"])))))\n    if len(got[\"turns\"]) != len(ref[\"turns\"]):\n        bad.append((min(len(got[\"turns\"]), len(ref[\"turns\"])), None))\n    if [x[\"sha256\"] for x in got.get(\"images\", [])] != \\\n            [x[\"sha256\"] for x in ref.get(\"images\", [])]:\n        bad.append((None, \"images\"))\n    return bad\n\n\ndef _pct(x) -> str:\n    return \"?\" if x is None else f\"{100 * x:.1f}%\"\n\n\ndef _rd(reads: dict) -> str:\n    return \", \".join(f\"{k} {v[0]} ({v[1]} s, {v[2]} MB)\"\n                     for k, v in sorted(reads.items())) or \"none\"\n\n\ndef main(argv=None) -> int:\n    ap = argparse.ArgumentParser(description=__doc__.split(\"\\n\")[0])\n    ap.add_argument(\"model\")\n    ap.add_argument(\"--backend\", choices=(\"isa\", \"board\"), default=\"isa\")\n    ap.add_argument(\"--dev\", default=\"/dev/xdma0\")\n    ap.add_argument(\"--cfg\", help=\"the card's configuration, pickled (tools/qual/refs.py cfg); \"\n                                  \"on the card it must be the device's\")\n    ap.add_argument(\"--turn\", action=\"append\", help=\"a user turn (repeated; default TURNS)\")\n    ap.add_argument(\"--max-new\", type=int, default=16, help=\"tokens a reply at most\")\n    ap.add_argument(\"--cap\", type=int, default=2048)\n    ap.add_argument(\"--pool\", help=\"the expert pool (default: the checkpoint's, as otpu-chat)\")\n    ap.add_argument(\"--pool-create\", action=\"store_true\",\n                    help=\"a missing pool is made, each expert packed on its first use (a \"\n                         \"reference on a host with the whole checkpoint and no pool)\")\n    ap.add_argument(\"--experts\", type=int, default=0, help=\"slots a MoE layer (0: fill)\")\n    ap.add_argument(\"--layer-major\", type=int, metavar=\"R\")\n    ap.add_argument(\"--em-rows\", type=int, metavar=\"N\",\n                    help=\"expert-major from N new rows a call on (default: the family's, \"\n                         \"streamed.EM_ROWS; 0: every call)\")\n    ap.add_argument(\"--em-pass\", type=int, metavar=\"C\",\n                    help=\"expert-major's entries a pass (default: the configuration's, \"\n                         \"moe.em_pass_rows)\")\n    ap.add_argument(\"--tile-rows\", type=int, metavar=\"T\",\n                    help=\"expert-major runs tiled, T rows a run (Engine.tile_rows: the layer's \"\n                         \"weights once for T rows; default 8 for Qwen3.5-MoE, off with \"\n                         \"OTPU_TILE=0)\")\n    ap.add_argument(\"--trace\", help=\"each turn's calls' runs and the server's timeline, and its \"\n                                    \"host phases up to the first token (PHASES), JSON\")\n    ap.add_argument(\"--mtp\", action=\"store_true\",\n                    help=\"Qwen3.5-MoE: decode with the MTP drafter, the loop on the device \"\n                         \"(its pool: the -mtp one, pack_pool.py extend)\")\n    ap.add_argument(\"--mtp-from\", metavar=\"DIR\",\n                    help=\"the MTP drafter's checkpoint when not the model's (--mtp)\")\n    ap.add_argument(\"--image\", action=\"append\", default=[], metavar=\"N:PATH\",\n                    help=\"an image for turn N (1-based; repeated): a model with a vision side\")\n    ap.add_argument(\"--max-slices\", type=int, help=\"an image's slices at most (default the \"\n                                                   \"processor's)\")\n    vis = ap.add_mutually_exclusive_group()\n    vis.add_argument(\"--vision-staged\", action=\"store_true\",\n                     help=\"MiniCPM-V's tower weights staged through the expert slots \"\n                          \"(minicpmv.Spec.vision_staged, the default; the pool grows by their \"\n                          \"entries)\")\n    vis.add_argument(\"--vision-resident\", action=\"store_true\",\n                     help=\"MiniCPM-V's tower weights resident in the image\")\n    ap.add_argument(\"--pool-calls\", action=\"store_true\",\n                    help=\"the pool's page cache before and after each call too (mincore: \"\n                         \"60-90 ms a check of a 17.5 GB pool, in the turn's wall times)\")\n    ap.add_argument(\"--sample\", action=\"store_true\", help=\"the model's sampling defaults\")\n    ap.add_argument(\"--seed\", type=int, default=0)\n    ap.add_argument(\"--check\", help=\"a reference run's JSON: its tokens, turn by turn\")\n    ap.add_argument(\"--out\", help=\"this run's JSON\")\n    a = ap.parse_args(argv)\n    tr, ph = ([], []) if a.trace else (None, None)\n    images = []\n    for x in a.image:\n        n, _, f = x.partition(\":\")\n        if not n.isdigit() or not Path(f).is_file():\n            ap.error(f\"--image {x}: N:PATH, PATH a file\")\n        images.append((int(n), Path(f)))\n    r = run(a.model, a.backend, a.cfg, a.dev, a.turn or TURNS, a.max_new, a.cap, a.pool,\n            a.experts, a.layer_major, a.sample, a.seed, a.pool_create, em_rows=a.em_rows,\n            trace=tr, em_pass=a.em_pass, mtp=a.mtp or a.mtp_from is not None,\n            mtp_from=a.mtp_from, images=images, max_slices=a.max_slices,\n            vision_staged=True if a.vision_staged else False if a.vision_resident else None,\n            pool_calls=a.pool_calls, tile_rows=a.tile_rows, phases=ph)\n    for i, t in enumerate(r[\"turns\"]):\n        print(f\"turn {i + 1}: {t['reply']!r}\\n  {t['line']}\", flush=True)\n        print(f\"  pool: {_pct(t['pool_before'])} -> {_pct(t['pool_after'])} of its \"\n              f\"{r['pool_gb']} GB in the page cache; reads {_rd(t['reads'])}\"\n              + (\"; COLD (misses read from the disk)\" if t[\"cold\"] else \"\"), flush=True)\n        for c in t[\"calls\"]:\n            print(f\"    call: {c['rows']} rows {'expert' if c['em'] else 'layer'}-major, \"\n                  f\"{c['s']} s (device {c['device_s']}), {c['runs']} runs; misses \"\n                  f\"{c['misses']} ({c['requests']} requests, served in {c['serve_s']} s), needs \"\n                  f\"{c['needs_queued']} ({c['need_lines']} lines), parts {c['prefetched']} \"\n                  f\"({c['parts_s']} s), holds {c['holds']}; pool {_pct(c['pool_before'])} -> \"\n                  f\"{_pct(c['pool_after'])} in the page cache, reads {_rd(c['reads'])}\",\n                  flush=True)\n        if ph is not None:\n            print(f\"    phases: {_Phases.line(ph[i]['phases'], t['ttft_s'])}\", flush=True)\n    if a.trace:\n        Path(a.trace).write_text(json.dumps(dict(\n            run_fields=[\"key\", \"start\", \"end\", \"cycles\"],\n            event_fields=[\"seen\", \"done\", \"kind\", \"layer or expert\", \"misses or bytes\"],\n            calls=tr, phase_fields=[\"phase\", \"start\", \"end\", \"cycles\"], turns=ph)))\n    rc = 0\n    if a.check:\n        ref = json.loads(Path(a.check).read_text())\n        bad = check(r, ref)\n        r[\"check\"] = dict(ref=a.check, ok=not bad, differ=bad)\n        print(f\"[{'FAIL' if bad else 'PASS'}] {r['model']} against {a.check}: \" +\n              (\", \".join(\"other images\" if i is None else f\"turn {i + 1} from token {j}\"\n                         for i, j in bad) if bad else\n               f\"{len(r['turns'])} turns' tokens the same\"), flush=True)\n        rc = 1 if bad else 0\n    if a.out:\n        Path(a.out).write_text(json.dumps(r, indent=1))\n    return rc\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n", "tools/qual/chatmoe.sh": "#!/bin/bash\n# otpu-chat's streamed MoE models on the card (docs/offload.md 14): for each model a scripted chat\n# of two greedy turns (tools/qual/chatmoe.py: otpu-chat's Chat, engine and settings, the card's\n# decode loop picking every token), checked turn by turn against the ISA simulator's run with\n# the card's configuration, with each turn's TTFT, prefill and decode tok/s and the slots' hits.\n#   lfm2-8b      LFM2.5-8B-A1B: nvfp4 with an int8 head, its prompt token by token\n#   qwen35-35b   Qwen3.5-35B-A3B: nvfp4 layers, fp4 experts, int8 head, the embedding table on\n#                the host, its prompt layer by layer (R = 2, pooled slots)\n#   gemma4-26b   gemma-4-26B-A4B-it (the instruct checkpoint): int8 layers, nvfp4 experts, fp4\n#                head, its prompt layer by layer\n# (streamed.FORMATS, the MX formats). The pools are the MX MXU's (key 2, numerics mx1:\n# pool-*-mx.split.bin); the pools before MX (pool-*-fp4.split.bin, key 1) are refused.\n# The checkpoints and pools are the offload sessions' (tools/offload/sessions/env.sh: O), each\n# pool stamped with its key (pack_pool.py MODEL POOL stamp); the references are\n# RF/chatmoe-<model>.json. A model whose files are not staged is skipped. Before each model\n# every file of 100 MB or more under ~/openTPU, ~/otpu-build and /data/otpu but its checkpoint's\n# (the files in its directory, and where its links lead) and its pool leaves the page cache (as\n# card_moe.sh's DROPOTHER; a link out of the three is skipped, never opened) and its pool is read\n# into it. /data/otpu: MiniCPM-V's pool (18 GB) stayed in the page cache after session hostr21\n# (2026-10-14), and the card host's 31 GB then held 63% of the 35B's pool; the three roots: the\n# 26B's pool (offload/g26it, outside O) stayed after its run in E3's window (2026-10-14), and the\n# 35B's run after it found 78% of its pool there. Selftest before and after.\n# The references, on a host with the whole checkpoints (CFG: the card's refs.py cfg, REFCFG):\n#   python3 tools/qual/chatmoe.py CHECKPOINT --cfg CFG --pool POOL --out chatmoe-<model>.json\n#   (--pool-create where the host has no pool: the experts packed as they are asked for)\n# Run (the card's lock for the whole session; no pipe):\n#   setsid -f otpu-lock --wait 3600 -- bash tools/qual/chatmoe.sh > /dev/null 2>&1\n#   (the log: R/session.log, R = O/SESSION; RUNS=\"lfm2-8b qwen35-35b gemma4-26b\"; POOL_CALLS=1:\n#   chatmoe.py --pool-calls, the pool's page cache around each call; env.sh's T,\n#   O, RF, REFCFG; G26POOL relative to O)\nset -u\nSESSION=${SESSION:-chatmoe-$(date +%m%d-%H%M)}\nsource \"$(dirname \"$0\")/../offload/sessions/env.sh\"\nexec > >(tee -a $R/session.log) 2>&1\nG26POOL=${G26POOL:-../g26it/pool-g26it-mx.split.bin}\ndeclare -A RUN=(        # checkpoint, pool (in O)\n  [lfm2-8b]=\"LFM2.5-8B-A1B pool-lfm25-8b-mx.split.bin\"\n  [qwen35-35b]=\"Qwen3.5-35B-A3B pool-q35-mx.split.bin\"\n  [gemma4-26b]=\"gemma-4-26B-A4B-it $G26POOL\")\necho \"chatmoe start $(date +%T) tree $rev mem $(mem) GB\"\ntimeout 1800 python -m opentpu.host.selftest 2>&1 | grep -E \"\\[(PASS|FAIL)\\]|config\" | tail -12\ntimeout 300 python tools/qual/refs.py cfg $R/cfg-dev.pkl > /dev/null 2>&1; echo \"cfg exit $?\"\npython - $R/cfg-dev.pkl $REFCFG <<'PY'\nimport dataclasses, pickle, sys\na, b = (pickle.load(open(f, \"rb\")) for f in sys.argv[1:])\nd = {f.name: (getattr(a, f.name), getattr(b, f.name)) for f in dataclasses.fields(a)\n     if getattr(a, f.name) != getattr(b, f.name)}\nprint(\"  cfg: the references' configuration\" if not d else f\"  cfg DIFFERS from the references' (device, ref): {d}\")\nsys.exit(1 if d else 0)\nPY\n[ $? = 0 ] || { echo \"STOP: the device configuration is not the references'\"; exit 2; }\nfor m in ${RUNS:-lfm2-8b qwen35-35b gemma4-26b}; do\n  read -r md pool <<< \"${RUN[$m]}\"\n  ref=$RF/chatmoe-$m.json\n  if [ ! -f $O/$md/config.json ] || [ ! -f $O/$pool ] || [ ! -f $ref ]; then\n    echo \"  [SKIP] $m: not staged ($O/$md, $O/$pool, $ref)\"; continue; fi\n  echo \"=== $m $(date +%T)\"\n  python - $O/$md $O/$pool $HOME/openTPU:$HOME/otpu-build:/data/otpu <<'PY'\nimport os, sys                                # every other file of 100 MB or more out of the\nkeep = {os.path.realpath(sys.argv[1]), os.path.realpath(sys.argv[2])}    # page cache: the pair's\nkeep |= {os.path.realpath(os.path.join(sys.argv[1], f)) for f in os.listdir(sys.argv[1])}  # (links)\nours = tuple(os.path.realpath(os.path.expanduser(d)) + os.sep\n             for d in (\"~/openTPU\", \"~/otpu-build\", \"/data/otpu\"))\ngb = n = 0\nseen = set()\nfor d in sys.argv[3].split(\":\"):\n    for root, _, files in os.walk(d):\n        for f in files:\n            r = os.path.realpath(os.path.join(root, f))\n            if r in seen or not r.startswith(ours) or not os.path.isfile(r) or \\\n                    os.path.getsize(r) < 100 << 20 or r in keep or os.path.dirname(r) in keep:\n                seen.add(r)\n                continue\n            seen.add(r)\n            fd = os.open(r, os.O_RDONLY)\n            os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n            os.close(fd)\n            gb, n = gb + os.path.getsize(r) / 1e9, n + 1\nprint(f\"  dropped from the page cache: {n} other files of {gb:.1f} GB\")\nPY\n  t0=$SECONDS; cat $O/$pool > /dev/null       # the pool in the page cache (the RAM tier)\n  python - $O/$pool <<'PY'\nimport os, sys\nfrom opentpu.host.offload import PoolFile\np = os.path.realpath(sys.argv[1])\nn = os.path.getsize(p + \".packed\")\nprint(f\"  pool: {PoolFile(p, os.path.getsize(p) // n, True, False).resident(range(n)) / 1e9:.2f} of \"\n      f\"{os.path.getsize(p) / 1e9:.2f} GB in the page cache, {sum(open(p + '.packed', 'rb').read())} \"\n      f\"of {n} experts packed, key {'yes' if os.path.exists(p + '.key') else 'NO (not stamped)'}\")\nPY\n  echo \"  (read in $((SECONDS - t0)) s, mem $(mem) GB)\"\n  timeout 3600 python tools/qual/chatmoe.py $O/$md --pool $O/$pool --backend board \\\n    --cfg $R/cfg-dev.pkl --check $ref --out $R/chatmoe-$m.json ${POOL_CALLS:+--pool-calls} \\\n    > $R/chatmoe-$m.log 2>&1\n  echo \"  exit $? $(date +%T)\"; grep -E \"\\[(PASS|FAIL)\\]|Error|Traceback\" $R/chatmoe-$m.log | tail -3\n  [ -f $R/chatmoe-$m.json ] || continue\n  python - $R/chatmoe-$m.json <<'PY'\nimport json, sys\nr = json.load(open(sys.argv[1]))\nprint(f\"  {r['weights']}; {r['experts']}; layer-major {r['layer_major']}, loop on the card \"\n      f\"{r['on_card']}, load {r['load_s']} s, host {r['host_mem']}\")\nfor i, t in enumerate(r[\"turns\"]):\n    print(f\"  turn {i + 1}: prompt {t['prompt_tokens']} tokens (reused {t['reused']}\"\n          f\"{', restarted' if t['restarted'] else ''}) in {t['prefill_s']} s \"\n          f\"({t['prefill_tok_s']} tok/s, device {t['prefill_dev_tok_s']}), {t['prefill_misses']} \"\n          f\"misses; TTFT {t['ttft_s']} s; decode {t['gen_tokens']} tokens at {t['decode_tok_s']} \"\n          f\"tok/s (device {t['decode_dev_tok_s']}), hits {t['hit_rate']}, \"\n          f\"{t['mb_per_token']} MB/token; end {t['end']}\")\n    if \"cold\" in t:                             # (the pool's page cache: chatmoe.py's record)\n        print(f\"    pool {t['pool_before']} -> {t['pool_after']} in the page cache, reads \"\n              f\"{t['reads']}\" + (\"; COLD: misses read from the disk\" if t[\"cold\"] else \"\")\n              + \"\".join(f\"; call {c['rows']} rows {c['pool_before']} -> {c['pool_after']}\"\n                        for c in t[\"calls\"]))\nPY\ndone\necho \"=== final selftest $(date +%T)\"\ntimeout 1800 python -m opentpu.host.selftest 2>&1 | grep -E \"\\[(PASS|FAIL)\\]|config\" | tail -12\necho \"CHATMOE DONE $(date +%T)\"\n", "tools/qual/fpcard.py": "\"\"\"The fp32 corners on the card against the ISA simulator (tests/test_fp_rtl.py's programs at the\nboard's configuration): multiplies and adds at the flush boundary, the composite functions on\ntheir scaled ranges, powers of two, exp2's limits and NaN words (otpu_se_comp on a DSTEP build),\nthe quantizer's recip on huge and tiny amax and on every exponent (QST, rows and blocks), an MM\nwhose partial sums flush to -0, and ARGMAX ties inside a chunk of lanes. Each program runs on the\ncard and on the ISA simulator from the same DRAM image; the DRAM below checks.PROG_AT must be\nequal, bit for bit.\n\n    python3 tools/qual/fpcard.py [--dev /dev/xdma0]   the card (run it under otpu-lock)\n    python3 tools/qual/fpcard.py --rtl                 the same programs on the RTL (Verilator)\n\nPrints one line per program and \"FPCARD PASS\" (exit 0) or \"FPCARD FAIL\" (exit 1).\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport dataclasses\nimport sys\nfrom pathlib import Path\n\nimport numpy as np\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[2]))\n\nfrom opentpu import fp32 as F, isa as I                          # noqa: E402\nfrom opentpu.host.checks import PROG_AT, ZERO_AT                 # noqa: E402\nfrom opentpu.isasim import Machine, board_config                 # noqa: E402\n\nOUT = 0x100000                  # DRAM: the programs' stored TMEM results\n\n\ndef _image(*parts) -> np.ndarray:\n    img = np.zeros(PROG_AT, np.uint8)\n    for at, a in parts:\n        b = np.ascontiguousarray(a).view(np.uint8).reshape(-1)\n        img[at:at + len(b)] = b\n    return img\n\n\ndef _corner_words(rng, n):\n    \"\"\"n words: rsqrt's scaled ranges (exponent fields 0..5 and 246..255, both signs), random\n    words of every field, every power of two and its neighbours (recip's significand edges,\n    rsqrt's powers of four), exp2 near its range limits and where x + 1 rounds to 1, NaNs.\"\"\"\n    p = np.arange(1, 255, dtype=np.int64) << 23\n    p = np.concatenate([p, p - 1, p + 1])\n    k = np.float32([-127, -126, -125, -1, 0, 1, 126, 127, 128])\n    t = np.exp2(-np.arange(20, 31))\n    ex = np.concatenate([np.nextafter(k, np.float32(-np.inf)), np.nextafter(k, np.float32(np.inf)),\n                         -t, t]).astype(np.float32)\n    extra = np.concatenate([\n        np.uint32([0x7FC00000, 0xFFC00000, 0x7F800001, 0xFFBFFFFF, 0x7F800000, 0xFF800000,\n                   0x7E800000, 0x7E7311C3, 0x7E7311C4, 0x7E7FFFFF, 0x00800000, 0x00FFFFFF,\n                   0x3F800000]),\n        np.concatenate([p, p | (1 << 31)]).astype(np.uint32), ex.view(np.uint32)])\n    n = n - len(extra)\n    e = np.where(rng.random(n) < 0.5, rng.choice(list(range(6)) + list(range(246, 255)), n),\n                 rng.integers(1, 255, n)).astype(np.uint32)\n    m = rng.integers(0, 1 << 23, n, dtype=np.uint32)\n    m[rng.random(n) < 0.1] = 0\n    m[rng.random(n) < 0.1] = 0x7FFFFF\n    s = rng.integers(0, 2, n, dtype=np.uint32)\n    w = (s << 31) | (e << 23) | m\n    return F.from_bits(np.concatenate([w, extra])).copy()\n\n\ndef mul_add(cfg):\n    \"\"\"MUL / ADD / SUB with results at the flush boundary: products of a power of two and an\n    all-ones mantissa, on 2^-126 - 2^-150 or near it (IEEE rounds the tie up to 2^-126 on the\n    subnormal grid), and sums of normals that land below 2^-126.\"\"\"\n    rng = np.random.default_rng(5)\n    n = 2048\n    e1 = rng.integers(1, 127, n).astype(np.int64)        # e1 + e2 = 127: 2^-126 (1 - 2^-24)\n    e2 = np.clip(127 - e1 + rng.integers(-1, 2, n), 1, 254)\n    s1, s2 = (rng.integers(0, 2, n).astype(np.int64) << 31 for _ in range(2))\n    m2 = np.where(rng.random(n) < 0.7, 0x7FFFFF, rng.integers(0x7FFFF0, 0x800000, n))\n    a = F.from_bits((s1 | (e1 << 23)).astype(np.uint32)).copy()\n    b = F.from_bits((s2 | (e2 << 23) | m2).astype(np.uint32)).copy()\n    c = F.from_bits(np.uint32(0x00800000) + rng.integers(0, 64, n).astype(np.uint32)).copy()\n    d = F.from_bits((np.uint32(0x00800000) + rng.integers(0, 64, n).astype(np.uint32))\n                    | np.uint32(0x80000000)).copy()\n    x = np.concatenate([a, b, c, d])\n    cols = 64\n    rows = n // cols\n    A, B, C, Dd, o = 0, n, 2 * n, 3 * n, 4 * n\n    prog = [I.ld(0, 0, 4 * n),\n            I.vop(I.V_MUL, o, A, B, rows, cols, cols, cols, cols),\n            I.vop(I.V_MUL, o + n, B, A, rows, cols, cols, cols, cols),\n            I.vop(I.V_ADD, o + 2 * n, C, Dd, rows, cols, cols, cols, cols),\n            I.vop(I.V_SUB, o + 3 * n, C, Dd, rows, cols, cols, cols, cols),\n            I.vop(I.V_RSUB, o + 4 * n, Dd, C, rows, cols, cols, cols, cols),\n            I.st(OUT, o, 5 * n), I.halt()]\n    return prog, _image((0, x))\n\n\ndef composites(cfg):\n    \"\"\"RECIP / RSQRT / EXP2 / LOG2 / ABS / COPY / EXP2SUB / MAX / MIN on the corner words.\"\"\"\n    rng = np.random.default_rng(19)\n    cols = 64\n    x = _corner_words(rng, 40 * cols)\n    n = len(x)\n    rows = n // cols\n    prog = [I.ld(0, 0, n)]\n    out = n\n    for func in (I.V_RECIP, I.V_RSQRT, I.V_EXP2, I.V_LOG2, I.V_ABS, I.V_COPY):\n        prog.append(I.vop(func, out, 0, 0, rows, cols, cols, cols, 0))\n        out += n\n    for func in (I.V_EXP2SUB, I.V_MAX, I.V_MIN):\n        prog.append(I.vop(func, out, 0, cols, rows - 1, cols, cols, cols, cols))\n        out += n\n    prog += [I.st(OUT, n, out - n), I.halt()]\n    return prog, _image((0, x))\n\n\ndef quantizer(cfg):\n    \"\"\"QST (row groups and blocks): amax in [2^123, 2^126) (once recip's scaled range), at 2^126\n    (inv = 0), tiny ones (inv = +inf: zeros give 0 * inf, q 0) and an inf element.\"\"\"\n    D, KB = cfg.D, 2\n    rng = np.random.default_rng(3)\n    rows = []\n    for amax in (2.0 ** 123, 1.5 * 2.0 ** 125, 0x7E7311C4, 2.0 ** 126, 2.0 ** -126, 1e-37,\n                 3.7e-37, 3.8e-37, np.inf, 1.0):\n        a = F.from_bits(np.uint32(amax)) if isinstance(amax, int) else F.f32(amax)\n        r = (rng.standard_normal(KB * D) * 0.3).astype(np.float32) * a\n        r[rng.random(KB * D) < 0.4] = 0.0\n        r[rng.random(KB * D) < 0.1] = -0.0\n        r[0] = a\n        rows.append(np.where(np.isfinite(r) | np.isinf(a), r, 0).astype(np.float32))\n    x = np.stack(rows)\n    R = len(rows)\n    prog = [I.ld(0, 0, x.size),\n            I.qst(0, OUT, OUT + 0x8000, R, KB, KB * D, KB * D, 1),\n            I.qst(0, OUT + 0x10000, OUT + 0x18000, R, KB, KB * D, KB * D, 1, row=True),\n            I.halt()]\n    return prog, _image((0, x))\n\n\ndef quantizer_recip(cfg):\n    \"\"\"QST (blocks and rows): amax at every power of two (recip on the significand 1.0, the\n    result's exponent field 127 - field away), its neighbours, random ones of every field, the\n    largest below 2^126, and across the point where inv = 127 * recip(amax) overflows to +inf\n    (a neighbour and a random one of every few fields: KB * D = 256 words a row at D = 128).\"\"\"\n    D, KB = cfg.D, 2\n    rng = np.random.default_rng(4)\n    p = np.arange(1, 253, dtype=np.int64) << 23\n    am = np.concatenate([p, p[::4] + 1, p[::2] | rng.integers(0, 1 << 23, 126),\n                         (5 << 23) + np.arange(8257526, 8257546), [0x7E7FFFFF, 0x7E800000]])\n    am = F.from_bits(am.astype(np.uint32))\n    am = np.resize(am, -(-len(am) // KB) * KB)\n    R = len(am) // KB\n    r = (rng.standard_normal((R * KB, D)) * 0.3).astype(np.float32) * am[:, None]\n    r[rng.random(r.shape) < 0.3] = 0.0\n    r[:, 0] = am\n    x = r.reshape(R, KB * D)\n    prog = [I.ld(0, 0, x.size),\n            I.qst(0, OUT, OUT + 0x10000, R, KB, KB * D, KB * D, 1),\n            I.qst(0, OUT + 0x20000, OUT + 0x30000, R, KB, KB * D, KB * D, 1, row=True),\n            I.halt()]\n    return prog, _image((0, x))\n\n\ndef mm_negzero(cfg):\n    \"\"\"KB = 10: each block's term (i2f(127) * ws_k) * (1/127); blocks 0..3 and 4..7 are\n    -(2^-126 + 3 ulp) and 2^-126, so every partial of two real terms flushes to -0, and t8, t9\n    are -0. The MXU adds no pad terms: the row sum is -0.\"\"\"\n    D, KB = cfg.D, 10\n    s = F.mul(F.f32(1.0), F.INV127)\n    t_of = lambda ws: F.mul(F.mul(F.f32(127.0), F.f32(ws)), s)   # noqa: E731\n    ws_b = F.from_bits(np.uint32(0x00800000))\n    while F.bits(t_of(ws_b)) < 0x00800000:\n        ws_b = F.from_bits(F.bits(ws_b) + np.uint32(1))\n    ws_a = F.from_bits((F.bits(ws_b) + np.uint32(3)) | np.uint32(0x80000000))\n    ws = np.array([ws_a] * 4 + [ws_b] * 4 + [F.f32(-0.0)] * 2, np.float32)\n    x = np.zeros(KB * D, np.float32)\n    x[np.arange(KB) * D] = 1.0\n    W = np.zeros(KB * D, np.int8)\n    W[np.arange(KB) * D] = 1\n    out = 2 * KB * D\n    prog = [I.ld(0, 0, KB * D), I.qact(0, 1, 0, KB, KB * D),\n            I.mm(0x10000, 0x20000, out, 1, KB, KB * D, 1, 1, 0, 4 * KB),\n            I.st(OUT, out, 16), I.halt()]\n    return prog, _image((0, x), (0x10000, W), (0x20000, ws))\n\n\ndef argmax_ties(cfg):\n    \"\"\"ARGMAX ties at the row's maximum inside one chunk of lanes go to the first column: every\n    pair of tied lanes in the row's first chunk and in a later one, and rows over {0, 1, 2}.\"\"\"\n    lanes = cfg.LANES\n    rng = np.random.default_rng(6)\n    pairs = [(p, q) for p in range(lanes) for q in range(p + 1, lanes)]\n    t = np.full((2 * len(pairs), 2 * lanes), -1.0, np.float32)\n    for k, (p, q) in enumerate(pairs):\n        t[k, [p, q]] = 5.0\n        t[len(pairs) + k, [lanes + p, lanes + q]] = 5.0\n    r = rng.integers(0, 3, (64, lanes)).astype(np.float32)\n    data = np.concatenate([t.reshape(-1), r.reshape(-1)])\n    o = len(data) + 64\n    nout = 2 * t.shape[0] + 2 * 64\n    prog = [I.ld(0, 0, len(data)),\n            I.argmax(o, 0, t.shape[0], t.shape[1], 2, t.shape[1]),\n            I.argmax(o + 2 * t.shape[0], t.size, 64, lanes, 2, lanes),\n            I.st(OUT, o, nout), I.halt()]\n    return prog, _image((0, data))\n\n\nCHECKS = [mul_add, composites, quantizer, quantizer_recip, mm_negzero, argmax_ties]\n\n\ndef rtl_check(cfg, prog, img) -> tuple[bool, str]:\n    \"\"\"run_demo's comparison on the RTL instead of the card.\"\"\"\n    from opentpu import rtlsim\n    prog = [I.ld(ZERO_AT, 0, cfg.TMEM_WORDS)] + prog\n    ref = np.zeros(cfg.DRAM_BYTES, np.uint8)\n    ref[:len(img)] = img\n    sl = Machine(cfg, [prog], [ref.copy()]).run().slices[0]\n    drams, _, _ = rtlsim.run(cfg, [prog], [ref.copy()], uarch=dict(rtlsim.BOARD_UARCH,\n                                                                    MXU_IMPL=2))\n    bad = np.nonzero(drams[0][:PROG_AT] != sl.dram[:PROG_AT])[0]\n    if len(bad):\n        return False, f\"{len(bad)} DRAM bytes differ, first at {[hex(int(b)) for b in bad[:6]]}\"\n    return True, \"equal\"\n\n\ndef main(argv=None) -> int:\n    ap = argparse.ArgumentParser(description=__doc__.split(\"\\n\")[0])\n    ap.add_argument(\"--dev\", default=\"/dev/xdma0\")\n    ap.add_argument(\"--rtl\", action=\"store_true\", help=\"the RTL (Verilator), not the card\")\n    a = ap.parse_args(argv)\n    if a.rtl:\n        cfg = board_config(PAIR=True, DSTEP=True, STREAM=True, DRAM_BYTES=1 << 22)\n        board = None\n        print(f\"fpcard on the RTL: {cfg}\")\n    else:\n        from opentpu.host.board import CH_BYTES, Board, XdmaTransport, device_config\n        board = Board(XdmaTransport(a.dev), check=False)\n        # the DRAM's ECC check bits once per configuration first (a read of a beat not written\n        # since counts as an uncorrectable error): run on a bitstream just loaded, it read some\n        board.scrub()\n        info = board.info()\n        cfg = device_config(info, DRAM_BYTES=2 * CH_BYTES)\n        bid = info.get(\"build_id\")\n        print(f\"fpcard on {a.dev}: build {bid:08x}\" if bid is not None else\n              f\"fpcard on {a.dev}: no build id\", f\"LANES={cfg.LANES} DSTEP={cfg.DSTEP}\")\n    fails = 0\n    for chk in CHECKS:\n        prog, img = chk(cfg)\n        if board is None:\n            ok, msg = rtl_check(cfg, prog, img)\n        else:\n            from opentpu.host.checks import run_demo\n            ok, msg, _ = run_demo(board, cfg, prog, img)\n        fails += not ok\n        print(f\"  [{'PASS' if ok else 'FAIL'}] {chk.__name__}: {msg}\", flush=True)\n    if board is not None:\n        board.close()\n    print(\"FPCARD PASS\" if fails == 0 else f\"FPCARD FAIL ({fails} of {len(CHECKS)})\")\n    return 0 if fails == 0 else 1\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n", "tools/qual/perf.py": "\"\"\"Card qualification: prefill tok/s on a long prompt, then decode with the card's free-running\ncounters (device cycles, DRAM traffic and efficiency, MXU starvation) and wall time.\n\n    python3 tools/qual/perf.py MODEL WFORMAT [HEAD_FORMAT] [--prompt 512] [--tokens 64]\n\nRun from a host tree (the repo root). One engine per call, with resident decode where the model\nhas it (the check that resident decode computes the ISA simulator's tokens is refs.py card\n--resident, after the warm soak).\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport sys\nimport time\nfrom pathlib import Path\n\nimport numpy as np\n\nROOT = Path(__file__).resolve().parents[2]\nsys.path.insert(0, str(ROOT))\n\nfrom transformers import AutoTokenizer  # noqa: E402\n\nfrom opentpu.host import chat as C  # noqa: E402\nfrom opentpu.llm import gemma4 as G4  # noqa: E402\nfrom opentpu.llm import load_spec, model_dir  # noqa: E402\nfrom opentpu.llm import qwen3 as Q  # noqa: E402\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"model\")\n    ap.add_argument(\"wformat\")\n    ap.add_argument(\"head_format\", nargs=\"?\")\n    ap.add_argument(\"--prompt\", type=int, default=512, help=\"prefill tokens\")\n    ap.add_argument(\"--tokens\", type=int, default=64, help=\"decode tokens\")\n    a = ap.parse_args()\n    m, wf, hf = a.model, a.wformat, (a.head_format if a.head_format not in (None, \"-\") else None)\n    path = model_dir(m)\n    spec, tok = load_spec(path), AutoTokenizer.from_pretrained(path)\n    backend, cfg = C.make_backend(\"board\", spec, 2048, \"/dev/xdma0\", path.name)\n    eng = Q.Engine(spec, Q.load_weights(path), cap=2048, cfg=cfg, backend=backend,\n                   wformat=wf, head_format=hf, resident=True)\n    board, info = eng.backend.board, eng.backend.info\n    khz = info[\"core_khz\"]\n    text = (ROOT / \"tools/data/austen_pp_ch1.txt\").read_text()\n    if isinstance(spec, G4.Spec):         # after <bos> (an instruct tokenizer adds none)\n        ids = G4.text_ids(tok, text, spec.bos)[:a.prompt]\n    else:\n        ids = tok(text)[\"input_ids\"][:a.prompt]\n    t0, n0 = time.perf_counter(), len(eng.stats)\n    logits = eng.prefill(ids)\n    wall = time.perf_counter() - t0\n    pcyc = sum(s[\"cycles\"] for s in eng.stats[n0:])\n    print(f\"{path.name} ({wf}{', head ' + hf if hf else ''}): prefill {len(ids)} tokens in \"\n          f\"{len(eng.stats) - n0} runs: device {len(ids) * khz * 1e3 / pcyc:.1f} tok/s, \"\n          f\"wall {len(ids) / wall:.1f} tok/s (compile included); resident={eng.resident}\")\n    t = int(np.argmax(logits))\n    n, s0 = a.tokens, board.snapshot()\n    n0 = len(eng.stats)\n    t0 = time.perf_counter()\n    for _ in range(n):\n        t = int(np.argmax(eng.step(t)))\n    eng._drain()\n    wall = time.perf_counter() - t0\n    s1 = board.snapshot()\n    dev = sum(s[\"cycles\"] for s in eng.stats[n0:])\n    d = {k: s1[k] - s0[k] for k in (\"DRAM_RD\", \"DRAM_WR\", \"RUNNING\", \"MXU_STARVE\", \"DRAM_WAIT\")\n         if k in s0}\n    run_s = d[\"RUNNING\"] / (khz * 1e3)\n    peak = 2 * 8 * info[\"ddr_mts\"] * 1e6 / 1e9 if info.get(\"ddr_mts\") else 17.06\n    gbs = (d[\"DRAM_RD\"] + d[\"DRAM_WR\"]) * 64 / run_s / 1e9\n    print(f\"  decode {n} tokens: {dev / n / 1e6:.3f} Mcycles/token, device \"\n          f\"{n * khz * 1e3 / dev:.2f} tok/s, wall {n / wall:.2f} tok/s (argmax loop, not \"\n          f\"streamed); DRAM read {d['DRAM_RD'] * 64 / n / 1e6:.1f} MB/token, write \"\n          f\"{d['DRAM_WR'] * 64 / n / 1e6:.2f} MB/token; while running {gbs:.2f} GB/s \"\n          f\"(read {d['DRAM_RD'] * 64 / run_s / 1e9:.2f}) = {100 * gbs / peak:.0f}% of \"\n          f\"{peak:.1f} GB/s\"\n          + (f\"; MXU_STARVE {100 * d['MXU_STARVE'] / d['RUNNING']:.0f}%\" if \"MXU_STARVE\" in d else \"\")\n          + (f\"; DRAM_WAIT {100 * d['DRAM_WAIT'] / d['RUNNING']:.0f}%\" if \"DRAM_WAIT\" in d else \"\"))\n    eng.backend.close()\n\n\nif __name__ == \"__main__\":\n    main()\n", "tools/qual/qual.sh": "#!/bin/bash\n# Card qualification of a candidate bitstream (docs/board.md, \"Qualifying a bitstream\").\n#\n#   bash tools/qual/qual.sh DEPLOY_DIR [fast|full]\n#\n# Started without the card lock, it quantizes the 4-bit runs' weights into the image cache\n# first (opentpu.host.prebuild, at nice 19), then takes the lock (otpu-lock, waiting up to\n# LOCK_WAIT seconds, default 3600) and runs under it; started under `otpu-lock -- ...` it runs\n# at once, and the tools quantize what the cache does not hold under the lock.\n# DEPLOY_DIR holds otpu.bit (a path, or a name under ~/otpu-build). Runs from the host tree the\n# script is in. Environment: REST (the bitstream to leave on the card; default the candidate),\n# OUT (results; default /tmp/qual-<deploy>), REFCACHE (tools/qual/refs.py), LOAD=0 (no JTAG load:\n# qualify the bitstream the card runs, e.g. on opentpu, whose root port once did not bring the\n# link back on a hot rescan after a reload), RUNS (the model runs MODEL:WF:HF, default the six\n# of Qwen3, LFM2.5 and Qwen3.5 in int8 and 4-bit; e.g. RUNS=\"lfm2-2.6b:int8:- lfm2-2.6b:fp4:int8\"\n# for the other models of opentpu.llm.MODELS), LONG (the long prompt's run, MODEL:WF:HF, default\n# lfm2:int8:-; empty: none), XL (the xl prompt's runs, MODEL:WF:HF ..., default none: ~1,400\n# tokens in prompt runs, buckets 1-6; refs.py's MODEL:WF:HF:xl,pr), NTOK (the token-exact runs'\n# tokens, default 32), ECC_EACH=1 (both channels' ECC counters after every step, into\n# $OUT/ecc.tsv, and a NOTE line in checks.txt when they changed: a corrected word placed to the\n# step that read it; r2.1's m8 2343d61e counted 2 on channel 0 somewhere in qual fast's 20\n# minutes between its first selftest and the turnarounds).\n#\n# The card must run the candidate: its BUILD_ID (Board.info) must be EXPECT, else the last 8\n# hex digits of the deploy's name (deploy_fpfix_e776703a -> e776703a), checked after the JTAG\n# load (with LOAD=0 at the start) and again at the end; after REST's load, REST's build\n# (REST_EXPECT, else its directory's name's, the link resolved). A failed JTAG load, another\n# build on the card or a probe of BUILD_ID and CAPS that fails is a FAIL line and stops the\n# qual (REST is loaded back if the candidate was).\n#\n# fast (~25 min with cached references): selftest (with the RDOT/OUTER/LOG2 op checks), the ISA\n#   references in the background, prefill + DRAM efficiency for the six configurations, the\n#   streamed decode (decode_profile) of the three 4-bit ones, a 3 min warm soak, diag with the\n#   quick memory test, then after the soak token-exact against the ISA simulator: for all six,\n#   per-position and resident, NTOK greedy tokens past EOS with every logits vector bit for bit,\n#   and LONG's long prompt (240 tokens, the decode across position 256: a run per attention\n#   bucket) per-position, resident and resident in prompt runs (docs/prefill.md), and each XL\n#   run's xl prompt resident in prompt runs (docs/tiled_prefill.md 13); then a final\n#   selftest. A bitstream with the decode loop (CAPS bit30) also runs it for all six, LONG's\n#   two (plain and in prompt runs) and the XL runs (in prompt runs), token-exact against the\n#   same references, and\n#   decode_profile --card-loop, greedy and sampled, for the 4-bit ones (wall against device\n#   tok/s); GEN=0 / 1 overrides the bitstream's bit. A bitstream with WAITW (CAPS bit31;\n#   WAITW=0 / 1 overrides it) runs tools/qual/waitw.py after the warm diag: 200 rounds of the\n#   host writing data, then a flag, while the card waits on the flag and then reads the data,\n#   and a WAITW timeout. Before the final selftest, tools/qual/turnaround.py: TURN seconds\n#   (default 30) of fp4 weight reads beside 64 KiB stores and loads (the DRAM's read / write\n#   turnarounds; fastmux's rtw 3), the data against the ISA simulator, and both channels' ECC\n#   counters, which must be 0 then; and the kernel's xdma errors since the load (dmesg), each a\n#   FAIL line.\n# full (~45 min): also a cold diag with the full march C- (2 x 2.6 min), decode_profile for all\n#   six, rw_bench, a 5 min soak and the full march in the warm diag.\n# Every phase prints its duration; the table is at the end and in $OUT/phases.tsv.\n#\n# A check that crashes counts: every step's output goes to $OUT/logs/, and a step that exits\n# non-zero (a timeout too) or prints a Python exception is a FAIL line in $OUT/checks.txt, as is\n# a token-exact run that did not pass (or did not test what it says: resident decode not\n# engaged, prompt runs not taken). The model phases need the tree's checkpoints (models/, as\n# opentpu.llm.model_dir finds them: a staged tree needs its models link); without them they are\n# skipped and that is a FAIL line. The references' job gets REFS_WAIT seconds (default 900)\n# after the last token-exact run, then it is killed and that is a FAIL line. SOAK (seconds)\n# overrides the profile's warm soak; PREBUILD=0 skips the prebuild. The exit status is 0 only\n# when the qual ran to its end with no FAIL line.\nset -u\nDEP=${1:?deploy dir}; PROFILE=${2:-fast}\ncase $DEP in /*) BIT=$DEP/otpu.bit ;; *) BIT=~/otpu-build/$DEP/otpu.bit ;; esac\nNAME=$(basename \"$DEP\")\nH=$(cd \"$(dirname \"$0\")/../..\" && pwd); P=${PYTHON:-~/otpu-venv/bin/python}\nREST=${REST:-$BIT}; OUT=${OUT:-/tmp/qual-$NAME}; mkdir -p \"$OUT\"\ncd \"$H\" || exit 1; export PYTHONPATH=$H\nRUNS=${RUNS:-\"qwen3:int8:- lfm2:int8:- qwen35:int8:- qwen3:fp4:int8 lfm2:fp4:int8 qwen35:fp4:int8\"}\nLONG=${LONG-lfm2:int8:-}; XL=${XL-}; NTOK=${NTOK:-32}\n# Started without the card lock: first the 4-bit runs' weights into the image cache\n# (opentpu.host.prebuild at nice 19, outside the lock; opentpu/qcache.py), so the session\n# quantizes nothing under the lock; then this script again, under it. PREBUILD=0: no prebuild.\nif [ -z \"${OTPU_LOCK_HELD:-}\" ]; then\n  PB=\"\"\n  if [ \"${PREBUILD:-1}\" != 0 ]; then\n    for r in $RUNS $LONG $XL; do case \":${r#*:}:\" in *:fp4:*|*:int4:*|*:mix:*) PB=\"$PB --prebuild $r\" ;; esac; done\n    kept=${REFCACHE:-$HOME/otpu-build/refcache}/configs/$NAME.pkl\n    [ -n \"$PB\" ] && [ -f \"$kept\" ] && PB=\"$PB --prebuild-cfg $kept\"\n  fi\n  echo \"=== prebuild outside the card lock${PB:+:$PB}; then the lock (up to ${LOCK_WAIT:-3600} s) $(date +%T)\"\n  exec $P -m opentpu.host.runstate --wait \"${LOCK_WAIT:-3600}\" $PB -- bash \"$H/tools/qual/qual.sh\" \"$@\"\nfi\nif [ \"$PROFILE\" = full ]; then\n  SOAK=${SOAK:-300}; COLD=1; WARM_MEM=full; DP_RUNS=$RUNS; RW=1\nelse\n  SOAK=${SOAK:-180}; COLD=0; WARM_MEM=quick; RW=0\n  DP_RUNS=\"\"; for r in $RUNS; do [[ $r == *:fp4:* ]] && DP_RUNS=\"$DP_RUNS $r\"; done\nfi\n: > \"$OUT/phases.tsv\"; : > \"$OUT/checks.txt\"; mkdir -p \"$OUT/logs\"\nPH=\"\"; PT=0; T00=$(date +%s)\nREFS=\"\"; STOPPED=\"\"; LOADED=0; RESTORED=\"\"; K0=0; GENC=0; WAITWC=0\nmemgb() { awk '/MemAvailable/ {printf \"%.1f\", $2 / 1048576}' /proc/meminfo 2>/dev/null; }\nphase() {\n  local now; now=$(date +%s)\n  if [ -n \"$PH\" ]; then printf '%s\\t%d\\n' \"$PH\" $((now - PT)) >> \"$OUT/phases.tsv\"\n    echo \"--- $PH: $((now - PT)) s\"; fi\n  PH=$1; PT=$now\n  [ -n \"$PH\" ] && echo \"=== $PH $(date +%T)  load $(cut -d' ' -f1 /proc/loadavg 2>/dev/null), MemAvailable $(memgb) GiB\"\n}\n# root helpers: opentpu has narrow sudo rules (/etc/sudoers.d/60-otpu-card) for these exact commands\nrescan() { if [ -x /usr/local/sbin/otpu-rescan ]; then sudo -n /usr/local/sbin/otpu-rescan; else sudo ~/otpu-venv/bin/otpu-setup --rescan; fi; }\nothers() { sudo -n lsof -t /dev/xdma0_* 2>/dev/null | head -1; }\nquiet() { for _ in $(seq 120); do [ -z \"$(others)\" ] && return 0; sleep 5; done\n  echo \"device open by pid $(others)\"; return 1; }\n# load BIT: JTAG (openFPGALoader's exit status counts; its output in $OUT/jtag.log), then the\n# rescan until the card answers; 1, and why, on a failure. Which build the card then runs is\n# check_build's to say: every openTPU bitstream answers the rescan with the same ID.\nload() {\n  quiet || return 1\n  echo \"=== $1 $(date +%T)\" >> \"$OUT/jtag.log\"\n  openFPGALoader -c digilent_hs2 --freq 10000000 \"$1\" >> \"$OUT/jtag.log\" 2>&1; local rc=$?\n  tail -1 \"$OUT/jtag.log\"\n  [ $rc = 0 ] || { echo \"openFPGALoader exit $rc ($OUT/jtag.log)\"; return 1; }\n  for _ in $(seq 60); do\n    rescan 2>&1 | tee -a \"$OUT/rescan.log\" | tail -1 | tee \"$OUT/rescan\"   # rescan.log: every step (relink)\n    grep -q \"ID 0x4f545055\" \"$OUT/rescan\" && return 0; sleep 10; done\n  echo \"rescan failed for 10 minutes\"; return 1; }\n# FAIL and PASS lines into checks.txt; a FAIL line on stderr too (not into the callers' filters\n# and tees)\nfail() { echo \"  [FAIL] $PH: $*\" >> \"$OUT/checks.txt\"; echo \"  [FAIL] $PH: $*\" >&2; }\npass() { echo \"  [PASS] $PH: $*\" | tee -a \"$OUT/checks.txt\"; }\n# stop [WHY]: the qual ends here (finish: REST back, the summary, exit status 1)\nstop() { [ $# -gt 0 ] && fail \"$*\"; STOPPED=1; echo \"the qual stops here\"; exit 1; }\n# run LABEL CMD...: CMD's output (stdout and stderr) into $OUT/logs/NNN-LABEL.txt, then printed\n# for the caller's filter. A non-zero exit (timeout's 124 too) or a Python exception is a FAIL\n# line: a crash never passes silently through the filters below. Returns 1 when it is one.\nEXC='^Traceback \\(most recent call last\\)|^([A-Za-z_][A-Za-z0-9_]*\\.)*[A-Za-z_][A-Za-z0-9_]*(Error|Exception)(: |$)'\n# ecc_each STEP (ECC_EACH=1): the ECC counters now (memcal.ecc: corrected / uncorrectable words\n# per channel since the last scrub, not cleared) as a line of $OUT/ecc.tsv; a NOTE when they differ\n# from the line before (the file, not a variable: run may be in a subshell)\necc_each() {\n  [ \"${ECC_EACH:-0}\" = 1 ] || return 0\n  local c prev\n  c=$(timeout 60 $P -c \"from opentpu.host.board import XdmaTransport\nfrom opentpu.host import memcal\ne = memcal.ecc(XdmaTransport('/dev/xdma0', dma=False))\nprint('ECC', 'none' if e is None else ' '.join('%d/%d' % x for x in e))\" 2>/dev/null | sed -n 's/^ECC //p' | tail -1)\n  prev=$(awk -F'\\t' '$3 != \"?\" {v = $3} END {print v}' \"$OUT/ecc.tsv\" 2>/dev/null)   # (the last read)\n  printf '%s\\t%s\\t%s\\n' \"$(date +%T)\" \"$1\" \"${c:-?}\" >> \"$OUT/ecc.tsv\"\n  if [ -n \"$prev\" ] && [ -n \"$c\" ] && [ \"$c\" != \"$prev\" ]; then\n    echo \"  [NOTE] ECC (ch0 ch1, corrected/uncorrectable) $prev -> $c after $1\" | tee -a \"$OUT/checks.txt\" >&2\n  fi\n}\nrun() {\n  local label=$1; shift\n  local n; n=$(( $(ls \"$OUT/logs\" | wc -l) + 1 ))        # counted: run may be in a subshell\n  local log; log=\"$OUT/logs/$(printf %03d $n)-$(printf %s \"$label\" | tr -c 'A-Za-z0-9_.-' _).txt\"\n  \"$@\" > \"$log\" 2>&1; local rc=$?\n  ecc_each \"$(basename \"$log\" .txt)\"\n  local exc; exc=$(grep -E \"$EXC\" \"$log\" | grep -v '^Traceback' | tail -1 | cut -c1-200)\n  local bad=0\n  if [ $rc -ne 0 ] || grep -qE \"$EXC\" \"$log\"; then\n    fail \"$label: exit $rc${exc:+, $exc} ($log)\"; bad=1\n  fi\n  cat \"$log\"\n  return $bad\n}\nhexid() { printf '%s\\n' \"$1\" | sed -n 's/.*_\\([0-9a-f]\\{8\\}\\)$/\\1/p'; }\n# check_build BUILD WHAT: the card's BUILD_ID (and CAPS bits 30 and 31, into GENC and WAITWC)\n# from Board.info: a PASS line when it is BUILD, else a FAIL line and status 1\ncheck_build() {\n  local got=\"\"\n  [ -n \"$1\" ] || { fail \"$2: no build id to check the card against (REST_EXPECT, or a\" \\\n                        \"directory named ..._<8 hex digits>)\"; return 1; }\n  read -r got GENC WAITWC <<< \"$(run \"probe ($2)\" $P -c \"from opentpu.host.board import Board, XdmaTransport\ni = Board(XdmaTransport('/dev/xdma0', dma=False), check=False, lock=False).info()\nc, b = i['caps'] or {}, i['build_id']\nprint('PROBE', 'none' if b is None else '%08x' % b, int(bool(c.get('gen'))), int(bool(c.get('waitw'))))\" \\\n    | sed -n 's/^PROBE //p' | tail -1)\"\n  [ -n \"$got\" ] || { fail \"$2: the probe of BUILD_ID and CAPS failed\"; return 1; }\n  [ \"$got\" = \"$1\" ] || { fail \"$2: the card runs build $got, not $1\"; return 1; }\n  pass \"$2: the card runs build $got\"\n}\n# REST back on the card: its load, then its build\nrestore() {\n  RESTORED=1\n  load \"$REST\" || { fail \"the JTAG load of REST ($REST) failed\"; return 1; }\n  check_build \"${REST_EXPECT:-$(hexid \"$(cd \"$(dirname \"$REST\")\" 2>/dev/null && basename \"$(pwd -P)\")\")}\" \\\n              \"REST ($REST)\"\n}\n# the kernel log's last timestamp (s since boot), then its xdma errors after it: a FAIL line each\nklog_t() { sudo -n dmesg 2>/dev/null | sed -n 's/^\\[ *\\([0-9][0-9]*\\.[0-9]*\\)\\].*/\\1/p' | tail -1; }\nxdma_errors() {\n  local k; k=$(sudo -n dmesg 2>&1) || { fail \"dmesg: not readable ($(printf %s \"$k\" | tail -1))\"; return; }\n  printf '%s\\n' \"$k\" | awk -v t0=\"$K0\" 'match($0, /^\\[ *[0-9]+\\.[0-9]+\\]/) {\n      if (substr($0, 2, RLENGTH - 2) + 0 > t0 + 0) print }' \\\n    | grep -iE \"xdma.*(timed out|error|fail)\" | cut -c1-200 | while IFS= read -r l; do fail \"dmesg: $l\"; done\n}\nselftest() { run selftest timeout 1800 $P -m opentpu.host.selftest \\\n  | grep -E \"\\[(PASS|FAIL)\\]|config|ALL|stopped|hint\" | tee -a \"$OUT/checks.txt\"; }\ndiag() {  # $1 label, $2 quick|full\n  run \"diag $1\" timeout 3600 $P -m opentpu.host.diag --mem \"$2\" --soak 20 > \"$OUT/diag-$1.txt\"\n  grep -E \"\\[(PASS|FAIL)\\].*(RDOT|OUTER|LOG2)\" \"$OUT/diag-$1.txt\"\n  sed -n '/^summary/,$p' \"$OUT/diag-$1.txt\" | tee -a \"$OUT/checks.txt\"\n}\n# exact LABEL MODEL WF HF [refs.py card's flags]: a token-exact run, its line into checks.txt\nexact() { local label=$1; shift\n  run \"$label\" timeout 1800 $P tools/qual/refs.py card \"$OUT/cfg.pkl\" \"$1\" \"$2\" \"$3\" \"$NTOK\" \"${@:4}\" \\\n    | grep -E \"\\] model|Error|Traceback\" | tee -a \"$OUT/checks.txt\"; }\nnpass() { grep -c '\\[PASS\\] model' \"$OUT/checks.txt\"; }\n# the references' job (this shell's, still running); refs_wait: up to REFS_WAIT s more for its\n# end, then killed (refs.py compute kills its jobs); a non-zero exit, an exception in its log\n# or the kill is a FAIL line\nrefs_running() { [ -n \"$REFS\" ] && jobs -p | grep -qx \"$REFS\" && kill -0 \"$REFS\" 2>/dev/null; }\nrefs_wait() {\n  local t0 w=${REFS_WAIT:-900} rc; t0=$(date +%s)\n  while refs_running && [ $(( $(date +%s) - t0 )) -lt \"$w\" ]; do sleep 2; done\n  if refs_running; then\n    kill \"$REFS\"; wait \"$REFS\"; REFS=\"\"\n    fail \"refs compute: still running $w s after the last token-exact run: killed ($OUT/refs.log)\"\n    return\n  fi\n  wait \"$REFS\"; rc=$?; REFS=\"\"\n  echo \"refs exit $rc\" >> \"$OUT/refs.log\"\n  { [ $rc = 0 ] && ! grep -qE \"$EXC\" \"$OUT/refs.log\"; } || fail \"refs compute: exit $rc ($OUT/refs.log)\"\n}\n# the model phases' checkpoints, where the tools look for them (opentpu.llm.model_dir)\nmodels_ok() {\n  local m d bad=\"\"\n  for m in $(for r in $RUNS $LONG $XL; do echo \"${r%%:*}\"; done | sort -u); do\n    d=$($P -c \"from opentpu.llm import model_dir; print(model_dir('$m'))\" 2>/dev/null)\n    [ -n \"$d\" ] && [ -f \"$d/config.json\" ] || bad=\"$bad $m (${d:-model_dir failed})\"\n  done\n  [ -z \"$bad\" ] && return 0\n  fail \"no checkpoint for$bad: $H/models does not hold the models (a staged tree needs its\" \\\n       \"models link, e.g. models -> ~/openTPU/models); the model phases are skipped\"\n  return 1\n}\ntemp() { $P -m opentpu.host.smi 2>&1 | grep -oE \"Temp [^ ]+ [^ │]+\" | head -1; }\nfinish() {\n  local rc=$? nf\n  if refs_running; then kill \"$REFS\"; wait \"$REFS\"; echo \"killed the references' job (pid $REFS)\"; fi\n  [ $rc != 0 ] && [ -z \"$STOPPED\" ] && fail \"qual.sh exited early (status $rc)\"\n  if [ $rc != 0 ] && [ \"$LOADED\" = 1 ] && [ -z \"$RESTORED\" ] && [ \"$REST\" != \"$BIT\" ]; then\n    phase \"REST back on the card\"; restore; fi\n  phase \"\"\n  echo \"=== phases ($PROFILE)\"; column -t -s $'\\t' \"$OUT/phases.tsv\"\n  nf=$(grep -c '\\[FAIL\\]' \"$OUT/checks.txt\")\n  echo \"total $(( ($(date +%s) - T00) / 60 )) min; $nf FAIL lines\" \\\n       \"($(grep -c '\\[PASS\\]' \"$OUT/checks.txt\") PASS); results in $OUT\"\n  if [ \"$nf\" = 0 ] && [ $rc = 0 ]; then echo \"QUAL DONE $NAME $(date +%T): PASS\"; exit 0; fi\n  echo \"QUAL DONE $NAME $(date +%T): FAIL\"; exit 1\n}\ntrap finish EXIT\ntrap 'exit 143' TERM HUP INT    # killed: finish too (the references' job, REST, the summary)\n\n# (a staged copy of the tree has no .git: its COMMIT file, as the deploy kits write it, if any)\nHC=$(git -C \"$H\" rev-parse --short HEAD 2>/dev/null || head -c 7 \"$H/COMMIT\" 2>/dev/null)\necho \"################ $NAME, $PROFILE profile, host tree ${HC:-unknown} $(date +%T)\"\nphase \"load + selftest\"\nEXPECT=${EXPECT:-$(hexid \"$NAME\")}\n[ -n \"$EXPECT\" ] || stop \"no build id to expect: set EXPECT ($NAME does not end in _<8 hex digits>)\"\nif [ \"${LOAD:-1}\" = 0 ]; then echo \"LOAD=0: no JTAG load, the card keeps its bitstream\"\nelse load \"$BIT\" || stop \"the JTAG load of $BIT failed (above; $OUT/jtag.log, $OUT/rescan.log)\"\n  LOADED=1; fi\nK0=$(klog_t); K0=${K0:-0}\ncheck_build \"$EXPECT\" \"the candidate\" || stop\nselftest\nrun \"refs cfg\" $P tools/qual/refs.py cfg \"$OUT/cfg.pkl\" --name \"$NAME\" | cut -c1-200\nMODELS=1; models_ok || MODELS=0\nGEN=${GEN:-$GENC}; WAITW=${WAITW:-$WAITWC}\necho \"decode loop on the card (CAPS bit30): $([ \"$GEN\" = 1 ] && echo yes || echo no),\" \\\n     \"WAITW (CAPS bit31): $([ \"$WAITW\" = 1 ] && echo yes || echo no)\"\nNRUNS=$(set -- $RUNS; echo $#); NLONG=$(set -- $LONG; echo $#); NXL=$(set -- $XL; echo $#)\nXLR=\"\"; for r in $XL; do XLR=\"$XLR $r:xl,pr\"; done     # (refs.py's runs: the keys it computes)\n\nif [ $MODELS = 1 ]; then phase \"references (background)\"\n  $P tools/qual/refs.py compute \"$OUT/cfg.pkl\" --ntok \"$NTOK\" --runs $RUNS \\\n    ${LONG:+$LONG:long $LONG:long,pr} $XLR > \"$OUT/refs.log\" 2>&1 &\n  REFS=$!\n  sleep 3; head -8 \"$OUT/refs.log\"\nfi\n\nif [ $COLD = 1 ]; then phase \"diag cold (full march)\"; temp; diag cold full; fi\n\nif [ $MODELS = 1 ]; then\nphase \"prefill + decode counters ($NRUNS)\"\nfor r in $RUNS; do IFS=: read -r m w h <<< \"$r\"\n  run \"perf $m $w $h\" timeout 1800 $P tools/qual/perf.py \"$m\" \"$w\" \"$h\" | grep -vE \"Warning|warn\\(\"\ndone\n\nphase \"decode_profile ($(set -- $DP_RUNS; echo $#))\"\nfor r in $DP_RUNS; do IFS=: read -r m w h <<< \"$r\"; args=\"--wformat $w\"; [ \"$h\" != \"-\" ] && args=\"$args --head-format $h\"\n  run \"decode_profile $m $w $h\" timeout 1800 $P tools/decode_profile.py --model \"$m\" --greedy \\\n    --tokens 96 $args --json \"$OUT/dp-$m-$w-$h.json\" > \"$OUT/dp-$m-$w-$h.txt\"\n  grep -E \" on board|^host critical|^wall|Error\" \"$OUT/dp-$m-$w-$h.txt\"\ndone\nfi\n\nif [ $RW = 1 ]; then phase \"rw_bench\"\n  run rw_bench timeout 900 $P tools/rw_bench.py card --modes mm,mm+st,mm+dstep,dstep | tail -4; fi\n\nif [ $MODELS = 1 ]; then\nphase \"warm soak ${SOAK} s\"; temp\nt0=$(date +%s); n=0\nwhile [ $(( $(date +%s) - t0 )) -lt $SOAK ]; do\n  run \"soak run $((n + 1))\" timeout 900 $P tools/decode_profile.py --model qwen3 --greedy \\\n    --tokens 256 --prompt \"Write a long essay about the history of France.\" > \"$OUT/soak-run.txt\"\n  ok=$?; grep -E \"^wall|Error|error\" \"$OUT/soak-run.txt\"\n  n=$((n+1))\n  [ $ok = 0 ] || break          # a failed run ends the soak (its FAIL line), not a loop of them\ndone; echo \"warm soak: $n runs in $(( $(date +%s) - t0 )) s\"; temp\nfi\n\nphase \"diag warm ($WARM_MEM memory test)\"; diag warm $WARM_MEM\n\nif [ \"$WAITW\" = 1 ]; then phase \"WAITW on the host's writes\"\n  run waitw timeout 900 $P tools/qual/waitw.py --rounds 200 | grep -E \"\\[(PASS|FAIL)\\]\" \\\n    | tee -a \"$OUT/checks.txt\"\nfi\n\nif [ $MODELS = 1 ]; then\nphase \"token-exact after the soak ($NRUNS x per-position + resident${LONG:+, the long prompt x 3}${XL:+, the xl prompt x $NXL})\"\ngrep -E \"FAILED\" \"$OUT/refs.log\"\np0=$(npass)\nfor r in $RUNS; do IFS=: read -r m w h <<< \"$r\"\n  for res in \"\" --resident; do exact \"token-exact $m $w $h$res\" \"$m\" \"$w\" \"$h\" $res; done\ndone\nif [ -n \"$LONG\" ]; then IFS=: read -r m w h <<< \"$LONG\"\n  for res in \"\" --resident \"--resident --prompt-runs\"; do\n    exact \"token-exact long $m $w $h${res:+ $res}\" \"$m\" \"$w\" \"$h\" --long $res; done\nfi\nfor r in $XL; do IFS=: read -r m w h <<< \"$r\"\n  exact \"token-exact xl $m $w $h --resident --prompt-runs\" \"$m\" \"$w\" \"$h\" --xl --resident \\\n    --prompt-runs\ndone\nwant=$(( NRUNS * 2 + NLONG * 3 + NXL )); got=$(( $(npass) - p0 ))\n[ \"$got\" -eq \"$want\" ] || fail \"$got of $want token-exact runs passed\"\nif [ \"$GEN\" = 1 ]; then\nphase \"decode loop on the card ($NRUNS${LONG:+ + 2 long}${XL:+ + $NXL xl} token-exact + $(set -- $DP_RUNS; echo $#) x 2 decode_profile)\"\np0=$(npass)\nfor r in $RUNS; do IFS=: read -r m w h <<< \"$r\"\n  exact \"card loop $m $w $h\" \"$m\" \"$w\" \"$h\" --card-loop\ndone\nif [ -n \"$LONG\" ]; then IFS=: read -r m w h <<< \"$LONG\"\n  for pr in \"\" --prompt-runs; do\n    exact \"card loop long $m $w $h${pr:+ $pr}\" \"$m\" \"$w\" \"$h\" --long --card-loop $pr; done\nfi\nfor r in $XL; do IFS=: read -r m w h <<< \"$r\"\n  exact \"card loop xl $m $w $h --prompt-runs\" \"$m\" \"$w\" \"$h\" --xl --card-loop --prompt-runs\ndone\nwant=$(( NRUNS + NLONG * 2 + NXL )); got=$(( $(npass) - p0 ))\n[ \"$got\" -eq \"$want\" ] || fail \"$got of $want card-loop token-exact runs passed\"\nfor r in $DP_RUNS; do IFS=: read -r m w h <<< \"$r\"; args=\"--wformat $w\"; [ \"$h\" != \"-\" ] && args=\"$args --head-format $h\"\n  for mode in greedy sampled; do         # sampled: the model's chat defaults (chat.SAMPLING)\n    run \"decode_profile card loop $m $w $h $mode\" timeout 1800 $P tools/decode_profile.py --model \"$m\" \\\n      $([ $mode = greedy ] && echo --greedy) --tokens 96 $args --card-loop \\\n      --json \"$OUT/dpl-$m-$w-$h-$mode.json\" > \"$OUT/dpl-$m-$w-$h-$mode.txt\"\n    grep -E \"decode loop on the card|Error\" \"$OUT/dpl-$m-$w-$h-$mode.txt\"\n  done\ndone\nfi\nrefs_wait                       # (refs.py card waited for each reference it needed)\nfi\n\nphase \"DRAM turnarounds + ECC (${TURN:-30} s)\"\nrun turnaround timeout 900 $P tools/qual/turnaround.py --seconds \"${TURN:-30}\" \\\n  | grep -E \"\\[(PASS|FAIL)\\]\" | tee -a \"$OUT/checks.txt\"\nxdma_errors                     # since the load (before REST's, which brings its own)\n\nphase \"final selftest\"\nif [ \"$REST\" != \"$BIT\" ] && [ \"${LOAD:-1}\" != 0 ]; then restore || stop\nelse check_build \"$EXPECT\" \"the candidate, at the end\" || stop; fi\nselftest\n", "tools/qual/refs.py": "\"\"\"ISA-simulator references for the card qualification's token-exact checks, cached by content.\n\n    python3 tools/qual/refs.py cfg OUT.pkl [--name NAME]    the card's configuration (registers)\n    python3 tools/qual/refs.py compute CFG.pkl [--runs R ...] [--jobs N] [--ntok 32]\n                                         references for the runs (default all eight), in\n                                         parallel as memory allows; exit 1 if any job failed or\n                                         died\n    python3 tools/qual/refs.py card CFG.pkl MODEL WF HF NTOK [--long | --xl]\n                                         [--resident [--card-loop]] [--prompt-runs]\n                                         the card's greedy tokens and logits against the cached\n                                         reference (--card-loop: after the prompt's token, the\n                                         decode loop on the card, Engine.generate_card, CAPS\n                                         bit30; --prompt-runs: the prompt in prompt runs,\n                                         docs/prefill.md, resident; --long: the long prompt;\n                                         --xl: the xl prompt)\n    python3 tools/qual/refs.py key CFG.pkl MODEL WF HF NTOK [--long | --xl] [--prompt-runs]\n                                         the cache file of one reference\n    python3 tools/qual/refs.py one CFG.pkl MODEL WF HF NTOK [--long | --xl] [--prompt-runs]\n                                         (worker: one reference)\n\nRun from a host tree (the repo root; PYTHONPATH set). A run is MODEL:WF[:HF[:FLAGS]], HF '-' =\nthe LM head in WF; FLAGS, comma-separated: long (the long prompt) or xl (the xl prompt), pr\n(prompt runs).\n\nA reference is the ISA simulator's NTOK greedy tokens after the prompt, past EOS (no stop ids:\na model's one-sentence answer ends after about 8 tokens, and the decode goes on), and a digest\nof every logits vector a token was picked from (the prefill's last row's, then each step's: the\nfp32 bits' sha256, with the top 5 for the FAIL line). The card check compares the tokens and,\nbit for bit, the logits: all NTOK per position and in resident decode (which gives per-position\ndecoding's logits bit for bit, tests/test_lfm2.py), the prefill's on the card's decode loop\n(whose logits stay on the device). The prompts:\n- short: otpu-selftest's model check (\"What is the capital of France?\"), about 22 tokens;\n- long: LONG_TEXT cut to at most LONG_TOKENS tokens, so that NTOK = 32 tokens decode across\n  position 256, the attention bucket's end (a run per bucket, the decode loop's HALT CHAIN);\n- xl: LONG_TEXT repeated (XL_TEXT), cut to at most XL_TOKENS tokens, at a KV capacity of CAP_XL:\n  the prompt fills buckets 1 to XL_BUCKET and the decode stays in its last, so that with pr the\n  prefill takes the prompt runs of every bucket up to it (docs/tiled_prefill.md 13: the looped\n  attention's tiles, Phi-4-mini's 12 rows a run from bucket 6 where it took 1).\nWith pr (--prompt-runs) the reference prefills in prompt runs too (resident, at run-time\npositions: their split can round a 4-bit MM's sums in another order than compile_rows' runs).\n\nThe cache ($REFCACHE, default ~/otpu-build/refcache) is keyed by what decides the ISA\nsimulator's tokens and logits: the sources of the opentpu package minus the card's host code\n(opentpu/host, which only drives the card; the simulator configuration it derives, sim_config,\nis hashed as a value) but with the host code the models import (HOST_IN_REF), the ISA\nconfiguration, the model checkpoint (config and file sizes), the formats (WF, HF), the OTPU_*\nenvironment those sources read (env_key: OTPU_FORMATS, OTPU_PLE_FORMAT, ...; not the runtime\nones), the prompt, its token ids (the chat template's output, with the date pinned), the token\ncount, prompt runs and the reference's format (VERSION). A host-only change (a poll fix) reuses\nthe references; any compiler, kernel or simulator change recomputes them. The key has no\nmachine or path in it, so references computed on another box (omarchy, or the Mac under its\nload rules) can be copied into the cache directory: `rsync -a ~/otpu-build/refcache/ ...`.\n\nHang-proofing: a reference being computed has a `.pending` file (host, pid, a heartbeat every\n15 s); a failure leaves a `.failed` file. The card check waits only while a live job is\ncomputing the reference, and fails at once when none is (never started, died, OOM-killed).\n`compute` starts jobs only while /proc/meminfo's MemAvailable covers them (their recorded peak\nRSS, with a reserve) and runs one fewer per Vivado process on the box; killed (SIGTERM), it\nkills its jobs and marks their references failed.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport datetime\nimport hashlib\nimport json\nimport os\nimport pickle\nimport re\nimport signal\nimport socket\nimport subprocess\nimport sys\nimport threading\nimport time\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[2]\nsys.path.insert(0, str(ROOT))\n\nVERSION = 2                                   # the reference's format: tokens past EOS, logits\nCAP = 512                                     # KV positions: the long prompt decodes past 256\nNTOK = 32\nRUNS = [\"qwen35:fp4:int8\", \"qwen3:fp4:int8\", \"qwen35:int8:-\", \"lfm2:fp4:int8\", \"qwen3:int8:-\",\n        \"lfm2:int8:-\", \"lfm2:int8:-:long\", \"lfm2:int8:-:long,pr\"]      # longest first\nPROMPT = \"What is the capital of France? Answer in one sentence.\"\nLONG_TEXT = (\n    \"Read this history of timekeeping, then summarize it in three sentences and name the \"\n    \"invention you consider the most important. Mechanical clocks first appeared in the \"\n    \"towers of European cathedrals and town halls near the end of the thirteenth century. They \"\n    \"had no faces at first: a falling weight turned a train of gears, a verge and foliot \"\n    \"escapement let the train advance in small steps, and a bell struck the hours for the \"\n    \"people below. Such clocks could drift by a quarter of an hour in a day, so their keepers \"\n    \"set them each noon against a sundial. The pendulum changed that. In 1656 Christiaan \"\n    \"Huygens built a clock whose escapement was governed by a swinging pendulum, and its error \"\n    \"fell to under a minute a day. Minute hands became worth having, and soon the anchor \"\n    \"escapement allowed long pendulums with small swings, which kept even better time. At sea, \"\n    \"though, a pendulum is useless, and navigators needed the time at their home port to find \"\n    \"their longitude: every four minutes of error in the clock meant a degree of error in the \"\n    \"position. After a prize was offered in 1714, John Harrison spent decades building a series \"\n    \"of marine timekeepers, the last of them a large watch that kept time to within a few \"\n    \"seconds on a voyage to Jamaica. In the nineteenth century the railways spread standard \"\n    \"time across whole countries, and telegraph signals carried the time from observatories to \"\n    \"stations. Quartz crystals, which vibrate at a steady frequency in an electric field, \"\n    \"replaced pendulums in the best clocks of the 1930s, and cheap quartz watches reached \"\n    \"everyone in the 1970s. Atomic clocks, which count the oscillations of caesium atoms, have \"\n    \"defined the second since 1967; the best of them would neither gain nor lose a second in \"\n    \"many millions of years. Today satellites carry such clocks, and a phone finds its place on \"\n    \"Earth by comparing the times at which their signals arrive.\")\nLONG_TOKENS = 240                             # the long prompt's tokens, at most\nXL_TEXT = \"\\n\\n\".join([LONG_TEXT] * 4)        # (about 2,200 tokens before the cut)\nXL_TOKENS = 1400                              # the xl prompt's tokens, at most\nXL_BUCKET = 6                                 # the bucket the xl prompt ends in (from 1281)\nCAP_XL = 2048                                 # an xl run's KV positions\nATTN_BLOCK = 256                              # the attention bucket (opentpu.llm.qwen3's)\nDATE = datetime.date(2026, 9, 29)             # \"today\" for chat templates that state it\nEXCLUDE = (\"host/\", \"serve/\", \"lens.py\", \"lens_app.html\", \"rtlsim.py\", \"hwtrace.py\")\n# host code the models import into the reference's path (opentpu.llm.*, kernels/mailbox.py:\n# LINE, Layout, RowLayout, ExpertServer: the mailbox, PLE rows, MoE serving)\nHOST_IN_REF = (\"host/offload.py\",)\n# OTPU_* variables the hashed sources read that do not change a reference: the caches' and the\n# card tools' (opentpu.progcache.RUNTIME_ENV), the simulators' scratch space and build jobs, and\n# board_config's defaults (the card's configuration is in the key by value)\nRUNTIME_ENV = (\"OTPU_SIM_TMP\", \"OTPU_BUILD_JOBS\", \"OTPU_MCOLS\", \"OTPU_LANES\", \"OTPU_PAIR\",\n               \"OTPU_DSTEP\", \"OTPU_STREAM\", \"OTPU_ACT_ROWS\")\nHEARTBEAT = 15                                # s between .pending updates\nSTALE = 120                                   # s without a heartbeat: the job is dead\nRESERVE = 4 << 30                             # bytes of MemAvailable kept free\nMEM_GUESS = {\"lfm2\": 2.0, \"qwen3\": 3.0, \"qwen35\": 4.0, \"lfm2-2.6b\": 12.0, \"smollm3\": 13.0,\n             \"phi4-mini\": 16.0, \"qwen35-2b\": 10.0, \"qwen35-4b\": 14.0,\n             \"gemma4\": 9.0}  # GiB, before a peak\n\n\ndef cache_root() -> Path:\n    return Path(os.environ.get(\"REFCACHE\", Path.home() / \"otpu-build/refcache\"))\n\n\ndef sources(pkg: Path | None = None):\n    \"\"\"(name, path) of the files the key hashes, in order.\"\"\"\n    pkg = pkg or ROOT / \"opentpu\"\n    for p in sorted(pkg.rglob(\"*\")):\n        rel = p.relative_to(pkg).as_posix()\n        if not p.is_file() or \"__pycache__\" in rel or p.suffix not in (\".py\", \".json\", \".txt\",\n                                                                         \".html\"):\n            continue\n        if rel.startswith(EXCLUDE) and rel not in HOST_IN_REF:\n            continue\n        yield rel, p\n\n\ndef source_hash(pkg: Path | None = None) -> str:\n    h = hashlib.sha256()\n    for rel, p in sources(pkg):\n        h.update(rel.encode() + b\"\\0\" + p.read_bytes() + b\"\\0\")\n    return h.hexdigest()[:16]\n\n\ndef env_key(pkg: Path | None = None) -> dict:\n    \"\"\"The OTPU_* variables set in the environment that the hashed sources read (lfm2's\n    OTPU_MLP_UNROLL_BODIES, gemma4's OTPU_PLE_FORMAT and OTPU_PLE_HOST, OTPU_FORMATS), but not\n    the runtime ones (RUNTIME_ENV): {name: value}; set to \"\" is not unset.\"\"\"\n    from opentpu.progcache import RUNTIME_ENV as PC_RUNTIME\n    names = set()\n    for _, p in sources(pkg):\n        names |= {m.decode() for m in re.findall(rb\"OTPU_[A-Z0-9_]+\", p.read_bytes())}\n    skip = set(PC_RUNTIME) | set(RUNTIME_ENV)\n    return {k: os.environ[k] for k in sorted(names - skip) if k in os.environ}\n\n\ndef model_fingerprint(path: Path) -> str:\n    h = hashlib.sha256()\n    for p in sorted(path.iterdir()):\n        if p.suffix == \".json\":\n            h.update(p.name.encode() + p.read_bytes())\n        elif p.suffix == \".safetensors\":\n            h.update(f\"{p.name}:{p.stat().st_size}\".encode())\n    return h.hexdigest()[:16]\n\n\ndef parse_run(r: str) -> tuple:\n    \"\"\"MODEL:WF[:HF[:FLAGS]] -> (model, wf, hf, long, pr, xl).\"\"\"\n    f = r.split(\":\")\n    if not 2 <= len(f) <= 4:\n        raise ValueError(f\"{r}: a run is MODEL:WF[:HF[:FLAGS]]\")\n    flags = set(filter(None, f[3].split(\",\"))) if len(f) > 3 else set()\n    if flags - {\"long\", \"xl\", \"pr\"} or {\"long\", \"xl\"} <= flags:\n        raise ValueError(f\"{r}: the flags are long or xl, and pr\")\n    return (f[0], f[1], f[2] if len(f) > 2 else \"-\", \"long\" in flags, \"pr\" in flags,\n            \"xl\" in flags)\n\n\ndef cap(xl: bool = False) -> int:\n    \"\"\"A reference's KV positions (the card check's too): CAP_XL for the xl prompt, else CAP.\"\"\"\n    return CAP_XL if xl else CAP\n\n\ndef key(cfg, model: str, wf: str, hf: str, n: int, long: bool = False,\n        pr: bool = False, xl: bool = False) -> tuple[Path, dict]:\n    from opentpu.host.board import sim_config\n    from opentpu.llm import load_spec, model_dir\n    path = model_dir(model)\n    spec = load_spec(path)\n    from transformers import AutoTokenizer\n    ids = prompt_ids(AutoTokenizer.from_pretrained(path), long, xl)\n    fmt = {\"wformat\": wf, \"head_format\": None if hf == \"-\" else hf}\n    prompt = f\"{XL_TOKENS}: {XL_TEXT}\" if xl else f\"{LONG_TOKENS}: {LONG_TEXT}\" if long \\\n        else PROMPT\n    parts = {\"v\": VERSION, \"src\": source_hash(),\n             \"sim_cfg\": repr(sim_config(spec, cap(xl), cfg, lookup=pr, **fmt)),\n             \"model\": path.name, \"ckpt\": model_fingerprint(path), \"wf\": wf, \"hf\": hf,\n             \"ntok\": n, \"cap\": cap(xl), \"prompt\": prompt,\n             \"ids\": hashlib.sha256(json.dumps(ids).encode()).hexdigest()[:16], \"pr\": pr,\n             \"env\": env_key()}\n    k = hashlib.sha256(json.dumps(parts, sort_keys=True).encode()).hexdigest()[:20]\n    tag = (\"_long\" if long else \"\") + (\"_xl\" if xl else \"\") + (\"_pr\" if pr else \"\")\n    return cache_root() / f\"{model}_{wf}_{hf}_{n}{tag}_{k}.pkl\", parts\n\n\ndef _chat(tok, text: str) -> list:\n    \"\"\"`text` as a user turn of the model's chat template, with today's date pinned (DATE:\n    SmolLM3's system header states the date, and a reference must not expire); a base model\n    without a template gets the plain text.\"\"\"\n    if not tok.chat_template:\n        return list(tok(text)[\"input_ids\"])\n    msgs = [{\"role\": \"user\", \"content\": text}]\n    ids = tok.apply_chat_template(msgs, add_generation_prompt=True, enable_thinking=False,\n                                  tokenize=True, strftime_now=lambda fmt: DATE.strftime(fmt))\n    return list(ids[\"input_ids\"] if hasattr(ids, \"keys\") else ids)\n\n\ndef prompt_ids(tok, long: bool = False, xl: bool = False) -> list:\n    \"\"\"The prompt's token ids: PROMPT's, or (long) those of the most words of LONG_TEXT that\n    make a prompt of at most LONG_TOKENS tokens, or (xl) of XL_TEXT, at most XL_TOKENS.\"\"\"\n    if not (long or xl):\n        return _chat(tok, PROMPT)\n    text, most = (XL_TEXT, XL_TOKENS) if xl else (LONG_TEXT, LONG_TOKENS)\n    words = text.split(\" \")\n    lo, hi = 1, len(words)\n    while lo < hi:\n        mid = (lo + hi + 1) // 2\n        if len(_chat(tok, \" \".join(words[:mid]))) <= most:\n            lo = mid\n        else:\n            hi = mid - 1\n    return _chat(tok, \" \".join(words[:lo]))\n\n\ndef xl_fits(prompt: int, n: int) -> bool:\n    \"\"\"An xl prompt of `prompt` tokens reaches bucket XL_BUCKET and its n tokens' decode\n    (positions prompt .. prompt + n - 2) ends in it, within CAP_XL.\"\"\"\n    return (XL_BUCKET - 1) * ATTN_BLOCK < prompt and \\\n        prompt + n - 2 < min(XL_BUCKET * ATTN_BLOCK, CAP_XL)\n\n\ndef load(model):\n    from transformers import AutoTokenizer\n\n    from opentpu.llm import load_spec, model_dir\n    from opentpu.llm.qwen3 import load_weights\n    path = model_dir(model)\n    return path, load_spec(path), load_weights(path), AutoTokenizer.from_pretrained(path)\n\n\ndef side(kp: Path, ext: str) -> Path:\n    return kp.with_suffix(ext)\n\n\ndef digest(lg) -> tuple[str, list]:\n    \"\"\"A logits vector's fp32 bits' sha256 (16 hex digits) and its top 5 [(id, value)].\"\"\"\n    import numpy as np\n    lg = np.ascontiguousarray(lg, np.float32)\n    top = np.argsort(-lg, kind=\"stable\")[:5]\n    return (hashlib.sha256(lg.view(np.uint32).tobytes()).hexdigest()[:16],\n            [(int(i), float(lg[i])) for i in top])\n\n\ndef greedy(eng, ids, n: int, loop: bool = False) -> tuple[list, list]:\n    \"\"\"n greedy tokens after the prompt, past EOS (no stop ids), and the digests of the logits\n    each was picked from: the prefill's last row's, then each step's; with loop (the decode\n    loop on the card, Engine.generate_card) only the prefill's (the loop's stay on the\n    device).\"\"\"\n    import numpy as np\n    lg = eng.prefill(ids)\n    toks, digs = [int(np.argmax(lg))], [digest(lg)]\n    if loop:\n        return toks + [int(t) for t in eng.generate_card(toks[0], n - 1, stop_ids=[])], digs\n    while len(toks) < n:\n        lg = eng.step(toks[-1])\n        toks.append(int(np.argmax(lg)))\n        digs.append(digest(lg))\n    return toks, digs\n\n\ndef prompt_runs_taken(eng, ids) -> bool:\n    \"\"\"The engine prefills `ids` in prompt runs (prefill.supported and covers).\"\"\"\n    from opentpu.llm import prefill as PF\n    return PF.supported(eng) and PF.covers(eng, 0, len(ids))\n\n\n# ---- one reference (the worker)\ndef one(cfg, model, wf, hf, n, long: bool = False, pr: bool = False, xl: bool = False) -> int:\n    kp, parts = key(cfg, model, wf, hf, n, long, pr, xl)\n    pend = side(kp, \".pending\")\n    if kp.exists():\n        pend.unlink(missing_ok=True)            # (compute's mark of a queued job)\n        print(f\"ref {model} {wf}/{hf}: cached ({kp.name})\")\n        return 0\n    kp.parent.mkdir(parents=True, exist_ok=True)\n    side(kp, \".failed\").unlink(missing_ok=True)\n    me = {\"host\": socket.gethostname(), \"pid\": os.getpid()}\n    stop = threading.Event()\n\n    def beat():\n        while not stop.is_set():\n            pend.write_text(json.dumps({**me, \"t\": time.time()}))\n            stop.wait(HEARTBEAT)\n    th = threading.Thread(target=beat, daemon=True)\n    th.start()\n    try:\n        from opentpu.host.board import sim_config\n        from opentpu.llm.qwen3 import Engine\n        path, spec, W, tok = load(model)\n        t0 = time.time()\n        hf_ = None if hf == \"-\" else hf\n        c = cap(xl)\n        ref = Engine(spec, W, cap=c, cfg=sim_config(spec, c, cfg, lookup=pr, wformat=wf,\n                                                   head_format=hf_),\n                     wformat=wf, head_format=hf_, resident=pr, prompt_runs=pr)\n        ids = prompt_ids(tok, long, xl)\n        if pr and not (ref.resident and prompt_runs_taken(ref, ids)):\n            raise RuntimeError(f\"{model} {wf}/{hf}: the ISA simulator's engine takes no prompt \"\n                               \"runs (prefill.supported, covers)\")\n        toks, digs = greedy(ref, ids, n)\n        want = {\"v\": VERSION, \"tokens\": toks, \"logits\": [d for d, _ in digs],\n                \"top\": [t for _, t in digs], \"prompt\": len(ids), \"pr\": pr}\n        tmp = kp.with_name(f\"{kp.name}.{me['host']}.{me['pid']}.tmp\")   # this writer's own\n        tmp.write_bytes(pickle.dumps(want))\n        tmp.rename(kp)\n        side(kp, \".json\").write_text(json.dumps({**parts, \"tokens\": len(toks),\n                                                 \"prompt_tokens\": len(ids),\n                                                 \"seconds\": round(time.time() - t0),\n                                                 \"host\": me[\"host\"]}, indent=1))\n        print(f\"ref {model} {wf}/{hf}: {len(toks)} tokens in {time.time() - t0:.0f} s\")\n        return 0\n    except BaseException as e:                  # noqa: BLE001 (recorded, then re-raised)\n        side(kp, \".failed\").write_text(f\"{type(e).__name__}: {e}\")\n        raise\n    finally:\n        stop.set()\n        th.join()\n        pend.unlink(missing_ok=True)\n\n\n# ---- many references, memory-aware\ndef mem_available() -> int | None:\n    try:\n        for line in Path(\"/proc/meminfo\").read_text().splitlines():\n            if line.startswith(\"MemAvailable:\"):\n                return int(line.split()[1]) * 1024\n    except OSError:\n        return None\n    return None\n\n\ndef vivado_count() -> int:\n    \"\"\"Vivado builds on this box: the top-level process run_vivado.sh starts (-nojournal); the\n    synthesis and implementation runs it spawns belong to the same build.\"\"\"\n    n = 0\n    for d in Path(\"/proc\").glob(\"[0-9]*\"):\n        try:\n            c = (d / \"cmdline\").read_bytes()\n            if b\"unwrapped/lnx64.o/vivado\" in c and b\"-nojournal\" in c:\n                n += 1\n        except OSError:\n            pass\n    return n\n\n\ndef peak_rss(pid: int) -> int:\n    try:\n        for line in Path(f\"/proc/{pid}/status\").read_text().splitlines():\n            if line.startswith(\"VmHWM:\"):\n                return int(line.split()[1]) * 1024\n    except OSError:\n        pass\n    return 0\n\n\ndef mem_db() -> dict:\n    p = cache_root() / \"mem.json\"\n    try:\n        return json.loads(p.read_text())\n    except (OSError, ValueError):\n        return {}\n\n\ndef run_key(cfg, r: str, n: int) -> Path:\n    m, wf, hf, long, pr, xl = parse_run(r)\n    return key(cfg, m, wf, hf, n, long, pr, xl)[0]\n\n\ndef compute(cfgf: Path, runs: list[str], jobs: int | None, n: int) -> int:\n    cfg = pickle.loads(cfgf.read_bytes())\n    todo = []\n    for r in runs:\n        kp = run_key(cfg, r, n)\n        if kp.exists():\n            print(f\"ref {r}: cached ({kp.name})\", flush=True)\n        else:\n            todo.append((r, kp))\n    host = socket.gethostname()\n\n    def mark_queued():                          # queued jobs count as being computed\n        for _, kp in todo:\n            kp.parent.mkdir(parents=True, exist_ok=True)\n            side(kp, \".failed\").unlink(missing_ok=True)\n            side(kp, \".pending\").write_text(json.dumps(\n                {\"host\": host, \"pid\": os.getpid(), \"t\": time.time(), \"queued\": True}))\n    mark_queued()\n    linux = mem_available() is not None\n    maxj = jobs or (3 if linux else 1)\n    db = mem_db()\n    env = {**os.environ, \"OMP_NUM_THREADS\": \"2\", \"OPENBLAS_NUM_THREADS\": \"2\",\n           \"MKL_NUM_THREADS\": \"2\"}\n    running: dict = {}                          # pid -> (run, Popen, kp, t0, peak)\n    failed = 0\n    # killed (qual.sh: its bounded wait, an early exit): the jobs go too, and say so below\n    signal.signal(signal.SIGTERM, lambda *_: sys.exit(128 + signal.SIGTERM))\n    try:\n        while todo or running:\n            for pid, (r, pr, kp, t0, peak) in list(running.items()):\n                running[pid] = (r, pr, kp, t0, max(peak, peak_rss(pid)))\n                rc = pr.poll()\n                if rc is None:\n                    continue\n                peak = running.pop(pid)[4]\n                if peak:\n                    db[r] = max(peak, db.get(r, 0))\n                if rc == 0 and kp.exists():\n                    continue\n                failed += 1\n                why = (f\"killed by signal {-rc}\" + (\" (the OOM killer?)\" if rc == -signal.SIGKILL\n                                                     else \"\")) if rc < 0 else f\"exit {rc}\"\n                side(kp, \".pending\").unlink(missing_ok=True)\n                if not side(kp, \".failed\").exists():\n                    side(kp, \".failed\").write_text(why)\n                print(f\"ref {r}: FAILED, {why}; see {kp.with_suffix('.log')}\", flush=True)\n            cap = max(1, maxj - (vivado_count() if linux else 0))\n            while todo and len(running) < cap:\n                r, kp = todo[0]\n                need = db.get(r) or int(MEM_GUESS.get(r.split(\":\")[0], 16.0) * (1 << 30))\n                avail = mem_available()\n                if running and avail is not None and avail - RESERVE < need:\n                    break                               # wait for memory (always start one)\n                todo.pop(0)\n                m, wf, hf, long, pr, xl = parse_run(r)\n                kp.parent.mkdir(parents=True, exist_ok=True)\n                log = open(kp.with_suffix(\".log\"), \"w\")\n                p = subprocess.Popen(\n                    [\"nice\", \"-n\", \"5\", sys.executable, __file__, \"one\", str(cfgf), m, wf, hf,\n                     str(n)] + [\"--long\"] * long + [\"--xl\"] * xl + [\"--prompt-runs\"] * pr,\n                    stdout=log, stderr=subprocess.STDOUT, env=env, cwd=ROOT)\n                running[p.pid] = (r, p, kp, time.time(), 0)\n                mem = \"\" if avail is None else (f\", MemAvailable {avail / 2**30:.1f} GiB, \"\n                                                f\"needs ~{need / 2**30:.1f}\")\n                print(f\"ref {r}: started (pid {p.pid}, {len(running)} running{mem})\",\n                      flush=True)\n            mark_queued()\n            time.sleep(2)\n    finally:                                    # stopped early: no job left behind\n        for r, p, kp, _, _ in running.values():\n            p.kill()\n            p.wait()\n            side(kp, \".pending\").unlink(missing_ok=True)\n            side(kp, \".failed\").write_text(\"killed: refs.py compute stopped before it ended\")\n            print(f\"ref {r}: killed, refs.py compute stopped\", flush=True)\n        for r, kp in todo:\n            side(kp, \".pending\").unlink(missing_ok=True)\n            side(kp, \".failed\").write_text(\"never started: refs.py compute stopped\")\n    (cache_root() / \"mem.json\").write_text(json.dumps(db, indent=1))\n    for r in runs:\n        kp = run_key(cfg, r, n)\n        meta = side(kp, \".json\")\n        if kp.exists() and meta.exists():\n            s = json.loads(meta.read_text()).get(\"seconds\")\n            print(f\"ref {r}: ok ({s} s when computed)\")\n    return 1 if failed else 0\n\n\n# ---- the card check\ndef wait_ref(kp: Path) -> str | None:\n    \"\"\"None when the reference exists; otherwise why it never will (fails fast).\"\"\"\n    while not kp.exists():\n        fail = side(kp, \".failed\")\n        if fail.exists():\n            return f\"the reference job failed: {fail.read_text()[:300]}\"\n        pend = side(kp, \".pending\")\n        if not pend.exists():\n            return (\"no reference and no job computing it: run tools/qual/refs.py compute \"\n                    f\"(or copy {kp.name} into {kp.parent})\")\n        try:\n            p = json.loads(pend.read_text())\n        except ValueError:\n            time.sleep(1)\n            continue\n        age = time.time() - p[\"t\"]\n        alive = True\n        if p[\"host\"] == socket.gethostname():\n            try:\n                os.kill(p[\"pid\"], 0)\n            except ProcessLookupError:\n                alive = False\n            except PermissionError:\n                pass\n        if not alive or age > STALE:\n            return (f\"the reference job (pid {p['pid']} on {p['host']}) died: last heartbeat \"\n                    f\"{age:.0f} s ago\")\n        time.sleep(5)\n    return None\n\n\ndef compare(toks: list, digs: list, want, tok=None) -> str | None:\n    \"\"\"None when the card's tokens and logits digests are the reference's (all its tokens; the\n    logits the card gave: the card loop's prefill's only), else the first difference.\"\"\"\n    if not isinstance(want, dict) or want.get(\"v\") != VERSION:\n        return f\"the reference is not of format {VERSION} (an older refs.py's token list)\"\n    name = (lambda t: f\"{t} {tok.decode([t])!r}\") if tok is not None else str\n    for i, (a, b) in enumerate(zip(toks, want[\"tokens\"])):\n        if a != b:\n            return f\"token {i} is {name(a)}, the ISA simulator's {name(b)}\"\n    if len(toks) != len(want[\"tokens\"]):\n        return f\"{len(toks)} tokens, the ISA simulator's {len(want['tokens'])}\"\n    for i, ((d, top), w) in enumerate(zip(digs, want[\"logits\"])):\n        if d != w:\n            return (f\"token {i}'s logits differ (sha {d}, the ISA simulator's {w}); top 5 \"\n                    f\"{top}, the ISA simulator's {want['top'][i]}\")\n    return None\n\n\ndef card(cfgf: Path, model, wf, hf, n, resident: bool, loop: bool = False,\n         prompt_runs: bool = False, long: bool = False, xl: bool = False) -> int:\n    import numpy as np\n\n    from opentpu.host.board import BoardBackend, XdmaTransport\n    from opentpu.llm.qwen3 import Engine\n    resident = resident or loop or prompt_runs\n    cfg = pickle.loads(cfgf.read_bytes())\n    kp, _ = key(cfg, model, wf, hf, n, long, prompt_runs, xl)\n    label = f\"model {model} {wf}/{hf}\" + (\" long\" if long else \"\") + (\" xl\" if xl else \"\") + \\\n        (\" resident\" if resident else \"\") + (\" card loop\" if loop else \"\") + \\\n        (\" prompt runs\" if prompt_runs else \"\")\n    early = None if side(kp, \".pending\").exists() else wait_ref(kp)\n    if early:\n        print(f\"  [FAIL] {label}: {early}\")\n        return 1\n    path, spec, W, tok = load(model)\n    ids = prompt_ids(tok, long, xl)\n    tr = XdmaTransport(\"/dev/xdma0\")\n    hf_ = None if hf == \"-\" else hf\n    dev = Engine(spec, W, cap=cap(xl), cfg=cfg, wformat=wf, head_format=hf_, resident=resident,\n                 backend=lambda c, imgs: BoardBackend(c, imgs, transport=tr, model=path.name),\n                 prompt_runs=prompt_runs)\n    why = None                          # a check that would not test what it says: a FAIL\n    if resident and not dev.resident:\n        why = \"resident decode not engaged (CAPS bit25, the image's lookup tables)\"\n    elif loop and not dev.can_generate:\n        why = \"the card does not run the decode loop (CAPS bit30, resident)\"\n    elif prompt_runs and not prompt_runs_taken(dev, ids):\n        why = \"prompt runs not taken (prefill.supported, covers)\"\n    elif long and not len(ids) < ATTN_BLOCK <= len(ids) + n - 2:\n        why = (f\"the decode, positions {len(ids)} .. {len(ids) + n - 2}, does not cross \"\n               f\"position {ATTN_BLOCK}\")\n    elif xl and not xl_fits(len(ids), n):\n        why = (f\"the xl prompt ({len(ids)} tokens) and its decode do not end in bucket \"\n               f\"{XL_BUCKET}\")\n    if why:\n        print(f\"  [FAIL] {label}: {why}\")\n        dev.backend.close()\n        return 1\n    t0 = time.time()\n    got, digs = greedy(dev, ids, n, loop)\n    dt = time.time() - t0\n    pre = [s for s in dev.stats if \"rows\" in s]\n    pre_cyc = sum(s[\"cycles\"] for s in pre) / max(1, sum(s[\"rows\"] for s in pre))\n    one_ = [s[\"cycles\"] for s in dev.stats if \"rows\" not in s]\n    if loop:                            # a run per bucket reached: cycles per token\n        one_ = [sum(one_) / max(1, len(got) - 1)] * (len(got) - 1)\n    dev._drain()\n    dev.backend.close()\n    why = wait_ref(kp)\n    if why:\n        print(f\"  [FAIL] {label}: {why}\")\n        return 1\n    bad = compare(got, digs, pickle.loads(kp.read_bytes()), tok)\n    print(f\"  [{'FAIL' if bad else 'PASS'}] {label}: \"\n          + (f\"{bad}; \" if bad else f\"{len(got)} tokens and the logits of \"\n             f\"{'the prefill' if loop else f'all {len(digs)}'} bit-exact; \")\n          + f\"{tok.decode(got[:12], skip_special_tokens=True)!r}...; prompt of {len(ids)} \"\n          f\"tokens in {len(pre)} runs, {pre_cyc / 1e6:.2f} Mcycles/token; {len(one_)} \"\n          f\"{'tokens on the card loop' if loop else 'one-token runs'} at positions \"\n          f\"{len(ids)} .. {len(ids) + n - 2}, {np.mean(one_) / 1e6:.2f} Mcycles/token; \"\n          f\"{dt:.1f} s wall\")\n    return 1 if bad else 0\n\n\ndef main():\n    ap = argparse.ArgumentParser(description=__doc__.split(\"\\n\")[0])\n    ap.add_argument(\"mode\", choices=[\"cfg\", \"compute\", \"card\", \"key\", \"one\"])\n    ap.add_argument(\"cfg\")\n    ap.add_argument(\"rest\", nargs=\"*\")\n    ap.add_argument(\"--name\", help=\"cfg: also keep it as $REFCACHE/configs/NAME.pkl\")\n    ap.add_argument(\"--runs\", nargs=\"*\", default=RUNS)\n    ap.add_argument(\"--jobs\", type=int)\n    ap.add_argument(\"--ntok\", type=int, default=NTOK)\n    ap.add_argument(\"--resident\", action=\"store_true\")\n    ap.add_argument(\"--card-loop\", action=\"store_true\")\n    ap.add_argument(\"--prompt-runs\", action=\"store_true\")\n    ap.add_argument(\"--long\", action=\"store_true\", help=\"the long prompt\")\n    ap.add_argument(\"--xl\", action=\"store_true\", help=\"the xl prompt\")\n    a = ap.parse_args()\n    cfgf = Path(a.cfg)\n    if a.mode == \"cfg\":\n        from opentpu.host.board import Board, XdmaTransport, device_config\n        t = XdmaTransport(\"/dev/xdma0\", dma=False)\n        cfg = device_config(Board(t, check=False, lock=False).info())\n        blob = pickle.dumps(cfg)\n        cfgf.write_bytes(blob)\n        if a.name:\n            (cache_root() / \"configs\").mkdir(parents=True, exist_ok=True)\n            (cache_root() / \"configs\" / f\"{a.name}.pkl\").write_bytes(blob)\n        print(f\"config {hashlib.sha1(repr(cfg).encode()).hexdigest()[:12]}: {cfg}\")\n        return 0\n    if a.mode == \"compute\":\n        return compute(cfgf, a.runs, a.jobs, a.ntok)\n    model, wf, hf, n = a.rest[0], a.rest[1], a.rest[2], int(a.rest[3])\n    cfg = pickle.loads(cfgf.read_bytes())\n    if a.mode == \"key\":\n        kp, parts = key(cfg, model, wf, hf, n, a.long, a.prompt_runs, a.xl)\n        print(kp)\n        print(json.dumps(parts, indent=1))\n        return 0\n    if a.mode == \"one\":\n        return one(cfg, model, wf, hf, n, a.long, a.prompt_runs, a.xl)\n    return card(cfgf, model, wf, hf, n, a.resident, a.card_loop, a.prompt_runs, a.long, a.xl)\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n"});
